--- BODY ---
Package Body  Ars_Api_Trns_Pkg
Is
--##-----------------------------------------------------------------------------------------------------##--
   Procedure Insrt_Cst_Rq_Prc (P_Lang_No             In     Number
                              ,P_C_Code              In     Customer.C_Code%Type
                              ,P_C_A_Name            In     Customer.C_A_Name%Type
                              ,P_C_E_Name            In     Customer.C_E_Name%Type Default Null
                              ,P_C_Group_Code        In     Customer.C_Group_Code%Type Default Null
                              ,P_C_Address           In     Customer.C_Address%Type Default Null
                              ,P_C_Class             In     Customer.C_Class%Type Default Null
                              ,P_C_Class_Typ         In     Customer.C_Class_Typ%Type Default Null
                              ,P_Cntry_No            In     Customer.Cntry_No%Type Default Null
                              ,P_Prov_No             In     Customer.Prov_No%Type Default Null
                              ,P_City_No             In     Customer.City_No%Type Default Null
                              ,P_R_Code              In     Customer.R_Code%Type Default Null
                              ,P_Rep_Code            In     Customer.Rep_Code%Type Default Null
                              ,P_Route_No            In     Customer.Route_No%Type Default Null
                              ,P_Sortinroute         In     Customer.Sortinroute%Type Default Null
                              ,P_Gps                 In     Customer.Gps%Type Default Null
                              ,P_C_Phone             In     Customer.C_Phone%Type Default Null
                              ,P_C_Fax               In     Customer.C_Fax%Type Default Null
                              ,P_C_Box               In     Customer.C_Box%Type Default Null
                              ,P_C_Person            In     Customer.C_Person%Type Default Null
                              ,P_C_E_Mail            In     Customer.C_E_Mail%Type Default Null
                              ,P_C_Web_Site          In     Customer.C_Web_Site%Type Default Null
                              ,P_C_Mobile            In     Customer.C_Mobile%Type Default Null
                              ,P_Respons_Person      In     Customer.Respons_Person%Type Default Null
                              ,P_C_Tax_Code          In     Customer.C_Tax_Code%Type Default Null
                              ,P_Clc_Vat_Price_Typ   In     Customer.Clc_Vat_Price_Typ%Type Default Null
                              ,P_Latitude            In     Customer.Latitude%Type Default Null
                              ,P_Longitude           In     Customer.Longitude%Type Default Null
                              ,P_Ad_U_Id             In     Customer.Ad_U_Id%Type
                              ,P_Ad_Trmnl_Nm         In     Customer.Ad_Trmnl_Nm%Type Default Null
                              ,P_LEV_NO_CRDT         In     Number Default Null
                              ,P_LEV_NO_CSH          In     Number Default Null
                              ,P_Cst_Code            Out    Customer.C_Code%Type
                              ,P_Cr_No               In     Customer_Rq.Cr_No%Type Default Null      
                              ,P_Dstrct_Nm           In     Customer_Rq.Dstrct_Nm%Type Default Null  
                              ,P_Building_No         In     Customer_Rq.Building_No%Type Default Null
                              ,P_Street              In     Customer_Rq.Street%Type Default Null     
                              ,P_Add_No              In     Customer_Rq.Add_No%Type Default Null     
                              ,P_C_Box_Code          In     Customer_Rq.C_Box_Code%Type Default Null 
                              ,P_C_Since             In     Customer_Rq.C_Since%Type Default Null    
                              ,P_Shrt_Add            In     Customer_Rq.Shrt_Add%Type Default Null 
                              ,p_CSTMR_IDNTFR        In     Customer_Rq.CSTMR_IDNTFR%Type Default Null 
                              ,p_Sys_No              In     Number Default Null                          
                              )
   Is
      V_Cnt            Number;
      V_Cst_Code       Customer.C_Code%Type;
      V_Cust_D_Type    Ias_Para_Ar.Cust_D_Type%Type;
      V_Cst_Seq_Type   Ias_Para_Ar.Cst_Seq_Type%Type;
      V_C_Acode        Customer.C_A_Code%Type;
      V_Aralt          Ias_Para_Ar.Ar_Ac_Link_Type%Type;
      V_Cst_Seq        Customer.Cst_Seq%Type;
      V_Lang_No        Number;
   Begin
      --------------------------------------------------------------------------------------------

      V_Lang_No := Nvl (P_Lang_No, 1);

      Begin
         Select Cust_D_Type, Cst_Seq_Type, Ar_Ac_Link_Type
           Into V_Cust_D_Type, V_Cst_Seq_Type, V_Aralt
           From Ias_Para_Ar
          Where Rownum <= 1;
      Exception
         When Others Then
            Raise_Application_Error (-20265, 'Err When Get Parameter  ' || Chr (10) || Sqlerrm);
      End;

      --------------------------------------------------------------------------------------------
      If P_C_Code Is Null Then
         Raise_Application_Error (-20266, Ias_Gen_Pkg.Get_Msg (V_Lang_No, 411));
      End If;

      --------------------------------------------------------------------------------------------
      If P_C_Group_Code Is Null And V_Aralt = 2 Then
         Raise_Application_Error (-20267, Ias_Gen_Pkg.Get_Msg (V_Lang_No, 26));
      End If;

      --------------------------------------------------------------------------------------------
      If P_C_Class Is Null And V_Cst_Seq_Type = 3 Then
         Raise_Application_Error (-20268, Ias_Gen_Pkg.Get_Msg (V_Lang_No, 1601) || ' ' || Ias_Gen_Pkg.Get_Prompt (V_Lang_No, 589));
      End If;

      --------------------------------------------------------------------------------------------
      If P_C_Group_Code Is Not Null Then
         Begin
            Select 1
              Into V_Cnt
              From Customer_Group
             Where C_Group_Code = P_C_Group_Code And Rownum <= 1;
         Exception
            When Others Then
               V_Cnt := 0;
         End;

         If Nvl (V_Cnt, 0) = 0 Then
            Raise_Application_Error (-20269, Ias_Gen_Pkg.Get_Msg (V_Lang_No, 43));
         End If;
      End If;

      --------------------------------------------------------------------------------------------
      If P_C_Class Is Not Null Then
         Begin
            Select 1
              Into V_Cnt
              From Customer_Class
             Where C_Class = P_C_Class And Rownum <= 1;
         Exception
            When Others Then
               V_Cnt := 0;
         End;

         If Nvl (V_Cnt, 0) = 0 Then
            Raise_Application_Error (-20270, Ias_Gen_Pkg.Get_Prompt (V_Lang_No, 589) || ' ' || Ias_Gen_Pkg.Get_Msg (V_Lang_No, 312));
         End If;
      End If;

      --------------------------------------------------------------------------------------------
      If P_C_Class_Typ Is Not Null Then
         Begin
            Select 1
              Into V_Cnt
              From Customer_Class_Typ
             Where C_Class_Typ = P_C_Class_Typ And Rownum <= 1;
         Exception
            When Others Then
               V_Cnt := 0;
         End;

         If Nvl (V_Cnt, 0) = 0 Then
            Raise_Application_Error (-20270, Ias_Gen_Pkg.Get_Msg(V_Lang_No, 1526));
         End If;
      End If;

      --------------------------------------------------------------------------------------------
      If P_C_Mobile Is Not Null Then
         Begin
            Select 1
              Into V_Cnt
              From Customer_Rq
             Where Nvl (C_Mobile, 0) = Nvl (P_C_Mobile, 0) And Rownum <= 1;
         Exception
            When Others Then
               V_Cnt := 0;
         End;

         If Nvl (V_Cnt, 0) > 0 Then
            Raise_Application_Error (-20271, Ias_Gen_Pkg.Get_Prompt (V_Lang_No, 6524) || ' ' || Ias_Gen_Pkg.Get_Msg (V_Lang_No, 581) || Chr(10) || 'C_MOBILE=' || P_C_Mobile || Chr(10));
         End If;
      End If;

      --------------------------------------------------------------------------------------------
      Begin
         Select 1
           Into V_Cnt
           From Customer_Rq
          Where C_Code_Trgt = P_C_Code And Rownum <= 1;
      Exception
         When Others Then
            V_Cnt := 0;
      End;
      
      If  Nvl(V_Cnt, 0)<> 0 And Nvl(P_Sys_No,0)= 101  Then 
         V_Cnt := 0;
       End If;  
      --------------------------------------------------------------------------------------------
      If Nvl (V_Cnt, 0) = 0 Then
         If Nvl (V_Cust_D_Type, 0) = 1 Then
            If V_Cst_Seq_Type = 1 Then
               Begin
                  Select Nvl (Max (To_Number (C_Code)), 0) + 1 Into V_Cst_Code From Customer_Rq;
               Exception
                  When No_Data_Found Then
                     Null;
                  When Others Then
                     Raise_Application_Error (-20272, 'Err   ' || Chr (10) || Sqlerrm);
               End;
            Elsif V_Cst_Seq_Type = 2 Then
               Begin
                  Select Nvl (Max (To_Number (C_Code)), 0) + 1
                    Into V_Cst_Code
                    From Customer_Rq
                   Where C_Group_Code = P_C_Group_Code;
               Exception
                  When No_Data_Found Then
                     Null;
                  When Others Then
                     Raise_Application_Error (-20273, 'Err   ' || Chr (10) || Sqlerrm);
               End;
            Elsif V_Cst_Seq_Type = 3 Then
               Begin
                  Select Nvl (Max (To_Number (C_Code)), 0) + 1
                    Into V_Cst_Code
                    From Customer_Rq
                   Where C_Group_Code = P_C_Group_Code And C_Class = P_C_Class;
               Exception
                  When No_Data_Found Then
                     V_Cst_Code := Null;
                  When Others Then
                     Raise_Application_Error (-20274, 'Err   ' || Chr (10) || Sqlerrm);
               End;
            End If;
          
            IF V_Cst_Code IS  NULL THEN 
             V_Cst_Code:= GET_AUTO_INCRMNT_FNC(P_SRC_STR=> V_Cst_Code, P_MX_STR_LNTH=> 1000) ;
            END IF; 
            
         Else
            V_Cst_Code := P_C_Code;
            Null;
         End If;
      Else
         Raise_Application_Error (-20275, Ias_Gen_Pkg.Get_Msg (V_Lang_No, 2057) || '=' || P_C_Code);
      End If;

      --------------------------------------------------------------------------------------------
      Begin
         Select C_A_Code
           Into V_C_Acode
           From Customer_Group
          Where C_Group_Code = P_C_Group_Code And Rownum <= 1;
      Exception
         When Others Then
            Null;
      End;

      --------------------------------------------------------------------------------------------
      Begin
         Select Nvl (Max (Cst_Seq), 0) + 1 Into V_Cst_Seq From Customer_Rq;
      Exception
         When Others Then
            Null;
      End;

      --------------------------------------------------------------------------------------------
      Begin
         Select 1
           Into V_Cnt
           From Customer_Rq
          Where C_Code = V_Cst_Code And Rownum <= 1;
      Exception
         When Others Then
            V_Cnt := 0;
      End;

      If Nvl (V_Cnt, 0) > 0 Then
         Raise_Application_Error (-20277, Ias_Gen_Pkg.Get_Msg (V_Lang_No, 2057) || '=' || V_Cst_Code);
      End If;

      --------------------------------------------------------------------------------------------
         If P_LEV_NO_CRDT Is Not Null Then
             Begin
                Select 1
                  Into V_Cnt
                  From IAS_PRICING_LEVELS
                 Where LEV_NO = P_LEV_NO_CRDT And Rownum <= 1;
             Exception
                When Others Then
                   V_Cnt := 0;
             End;

             If Nvl (V_Cnt, 0) = 0 Then
                Raise_Application_Error (-20298, Ias_Gen_Pkg.Get_Msg (V_Lang_No, 2011) || 'P_LEV_NO_CRDT=' || P_LEV_NO_CRDT);
             End If;
         End If;    

         --------------------------------------------------------------------------------------------
          If P_LEV_NO_CSH Is Not Null Then
             Begin
                Select 1
                  Into V_Cnt
                  From IAS_PRICING_LEVELS
                 Where LEV_NO = P_LEV_NO_CSH And Rownum <= 1;
             Exception
                When Others Then
                   V_Cnt := 0;
             End;

             If Nvl (V_Cnt, 0) = 0 Then
                Raise_Application_Error (-20298, Ias_Gen_Pkg.Get_Msg (V_Lang_No, 2011) || 'P_LEV_NO_CSH=' || P_LEV_NO_CSH);
             End If;
         End If;    

         --------------------------------------------------------------------------------------------
      Begin
         Insert Into Customer_Rq (C_Code
                                 ,C_A_Name
                                 ,C_E_Name
                                 ,C_A_Code
                                 ,Cst_Seq
                                 ,C_Group_Code
                                 ,C_Address
                                 ,C_Class
                                 ,Cntry_No
                                 ,Prov_No
                                 ,City_No
                                 ,R_Code
                                 ,Rep_Code
                                 ,Route_No
                                 ,Sortinroute
                                 ,Gps
                                 ,C_Phone
                                 ,C_Fax
                                 ,C_Box
                                 ,C_Person
                                 ,C_E_Mail
                                 ,C_Web_Site
                                 ,C_Mobile
                                 ,Respons_Person
                                 ,C_Code_Trgt
                                 ,C_Tax_Code
                                 ,Latitude
                                 ,Longitude
                                 ,Ad_U_Id
                                 ,Ad_Date
                                 ,Ad_Trmnl_Nm
                                 ,Cr_No       
                                 ,Dstrct_Nm   
                                 ,Building_No 
                                 ,Street      
                                 ,Add_No      
                                 ,C_Box_Code  
                                 ,C_Since     
                                 ,Shrt_Add
                                 ,CSTMR_IDNTFR
                                 )
              Values (V_Cst_Code
                     ,P_C_A_Name
                     ,P_C_E_Name
                     ,V_C_Acode
                     ,V_Cst_Seq
                     ,P_C_Group_Code
                     ,P_C_Address
                     ,P_C_Class
                     ,P_Cntry_No
                     ,P_Prov_No
                     ,P_City_No
                     ,P_R_Code
                     ,P_Rep_Code
                     ,P_Route_No
                     ,P_Sortinroute
                     ,Decode (P_Gps, Null, (P_Latitude || ',' || P_Longitude), P_Gps)
                     ,P_C_Phone
                     ,P_C_Fax
                     ,P_C_Box
                     ,P_C_Person
                     ,P_C_E_Mail
                     ,P_C_Web_Site
                     ,P_C_Mobile
                     ,P_Respons_Person
                     ,P_C_Code
                     ,P_C_Tax_Code
                     ,P_Latitude
                     ,P_Longitude
                     ,P_Ad_U_Id
                     ,Ys_Gen_Pkg.Get_Curdate
                     ,P_Ad_Trmnl_Nm
                     ,P_Cr_No       
                     ,P_Dstrct_Nm   
                     ,P_Building_No 
                     ,P_Street      
                     ,P_Add_No      
                     ,P_C_Box_Code  
                    ,P_C_Since     
                     ,P_Shrt_Add 
                     ,p_CSTMR_IDNTFR
                     );
      Exception
         When Others Then
            Raise_Application_Error (-20278, 'Err INSERT INTO CUSTOMER_RQ  ' || Chr (10) || Sqlerrm);
      End;

      --------------------------------------------------------------------------------------------
      If Nvl (Ias_Gen_Pkg.Get_Cnt ('Select 1 From CUSTOMER_RQ Where 
                           C_Code_Trgt='' || P_C_Code || '' AND 
                           C_Code='' || V_Cst_Code || ''
                           And RowNum<=1'), 0) <> 0 Then
         For I In (Select A_Cy, Inactive
                     From Account_Curr
                    Where A_Code = V_C_Acode)
         Loop
            Begin
               Insert Into Customer_Curr_Rq (C_Code
                                            ,A_Cy
                                            ,Inactive
                                            ,Ad_U_Id
                                            ,Ad_Date
                                            ,LEV_NO)
                    Values (V_Cst_Code
                           ,I.A_Cy
                           ,I.Inactive
                           ,P_Ad_U_Id
                           ,Ys_Gen_Pkg.Get_Curdate
                           ,P_LEV_NO_CRDT
                             );
            Exception
               When Others Then
                  Rollback;
                  Raise_Application_Error (-20279, 'Err INSERT INTO CUSTOMER_CURR_RQ  ' || Chr (10) || Sqlerrm);
            End;
         End Loop;
      End If;

      Commit;
      P_Cst_Code := V_Cst_Code;
   End Insrt_Cst_Rq_Prc;
 --##------------------------------------------------------------------------------------------------------------------------------##--
  Procedure Insrt_Cst_Prc (P_Lang_No              In     Number
                           ,P_Gnrt_Cst_Flg        In     Number Default 1 --##  1 GENERT NEW CST_CODE ,--##  0 THE SAME CST_CODE SENT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                           ,P_Upd_Flg             In     Number Default 0 --##  0 insert NEW CST_CODE ,--##  1 update customer data                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                           ,P_C_Code              In     Customer.C_Code%Type
                           ,P_C_A_Name            In     Customer.C_A_Name%Type
                           ,P_C_E_Name            In     Customer.C_E_Name%Type Default Null
                           ,P_C_Group_Code        In     Customer.C_Group_Code%Type Default Null
                           ,P_C_Address           In     Customer.C_Address%Type Default Null
                           ,P_C_Class             In     Customer.C_Class%Type Default Null
                           ,P_C_Class_Typ         In     Customer.C_Class_Typ%Type Default Null
                           ,P_Cntry_No            In     Customer.Cntry_No%Type Default Null
                           ,P_Prov_No             In     Customer.Prov_No%Type Default Null
                           ,P_City_No             In     Customer.City_No%Type Default Null
                           ,P_R_Code              In     Customer.R_Code%Type Default Null
                           ,P_Rep_Code            In     Customer.Rep_Code%Type Default Null
                           ,P_Route_No            In     Customer.Route_No%Type Default Null
                           ,P_Sortinroute         In     Customer.Sortinroute%Type Default Null
                           ,P_Gps                 In     Customer.Gps%Type Default Null
                           ,P_C_Phone             In     Customer.C_Phone%Type Default Null
                           ,P_C_Fax               In     Customer.C_Fax%Type Default Null
                           ,P_C_Box               In     Customer.C_Box%Type Default Null
                           ,P_C_Person            In     Customer.C_Person%Type Default Null
                           ,P_C_E_Mail            In     Customer.C_E_Mail%Type Default Null
                           ,P_C_Web_Site          In     Customer.C_Web_Site%Type Default Null
                           ,P_C_Mobile            In     Customer.C_Mobile%Type Default Null
                           ,P_Respons_Person      In     Customer.Respons_Person%Type Default Null
                           ,P_C_Tax_Code          In     Customer.C_Tax_Code%Type Default Null
                           ,P_Clc_Vat_Price_Typ   In     Customer.Clc_Vat_Price_Typ%Type Default Null
                           ,P_Latitude            In     Customer.Latitude%Type Default Null
                           ,P_Longitude           In     Customer.Longitude%Type Default Null
                           ,P_Ad_U_Id             In     Customer.Ad_U_Id%Type
                           ,P_Ad_Trmnl_Nm         In     Customer.Ad_Trmnl_Nm%Type Default Null
                           ,P_Up_U_Id             In     Customer.Up_U_Id%Type Default Null
                           ,P_Up_Trmnl_Nm         In     Customer.Ad_Trmnl_Nm%Type Default Null
                           ,P_Cst_Code            Out    Customer.C_Code%Type
                           ,P_LEV_NO_CRDT         In     Number Default Null
                           ,P_LEV_NO_CSH          In     Number Default Null
                           ,P_Cr_No               In     Customer.Cr_No%Type Default Null      
                           ,P_Dstrct_Nm           In     Customer.Dstrct_Nm%Type Default Null  
                           ,P_Building_No         In     Customer.Building_No%Type Default Null
                           ,P_Street              In     Customer.Street%Type Default Null     
                           ,P_Add_No              In     Customer.Add_No%Type Default Null     
                           ,P_C_Box_Code          In     Customer.C_Box_Code%Type Default Null 
                           ,P_C_Since             In     Customer.C_Since%Type Default Null    
                           ,P_Shrt_Add            In     Customer.Shrt_Add%Type Default Null  
                           ,P_CSTMR_IDNTFR        In     Customer.CSTMR_IDNTFR%Type Default Null
                           ,P_C_CLASS_VAT         In     Customer.C_CLASS_VAT%Type Default Null
                           ,P_C_WHATSAPP_NO       In     Customer.C_WHATSAPP_NO%Type Default Null 
                           ,P_Cur_Xml             In     Clob     Default Null    
                           ,p_Sys_No              In     Number Default Null
                               )
   Is
      V_Cnt            Number;
      V_Cst_Code       Customer.C_Code%Type;
      V_Cust_D_Type    Ias_Para_Ar.Cust_D_Type%Type;
      V_Cst_Seq_Type   Ias_Para_Ar.Cst_Seq_Type%Type;
      V_C_Acode        Customer.C_A_Code%Type;
      V_Aralt          Ias_Para_Ar.Ar_Ac_Link_Type%Type;
      V_Cst_Seq        Customer.Cst_Seq%Type;
      V_Lang_No        Number;
      V_Xml_Type       Xmltype;
   Begin
      --------------------------------------------------------------------------------------------
      V_Lang_No := Nvl (P_Lang_No, 1);
       V_Xml_Type := Xmltype.Createxml (P_Cur_Xml);
      
      If P_AD_U_ID <> 1 And Ias_gen_Pkg.Get_Frm_Prv(P_AD_U_ID,143)=0 Then
         Raise_application_error(-20010,ias_gen_pkg.get_msg(V_Lang_No,592));
      End If;

      Begin
         Select Cust_D_Type, Cst_Seq_Type, Ar_Ac_Link_Type
           Into V_Cust_D_Type, V_Cst_Seq_Type, V_Aralt
           From Ias_Para_Ar
          Where Rownum <= 1;
      Exception
         When Others Then
            Raise_Application_Error (-20280, 'Err When Get Parameter  ' || Chr (10) || Sqlerrm);
      End;

      --------------------------------------------------------------------------------------------
      If P_C_Code Is Null Then
         Raise_Application_Error (-20282, Ias_Gen_Pkg.Get_Msg (V_Lang_No, 411));
      End If;

      --------------------------------------------------------------------------------------------
      If P_C_Group_Code Is Null And V_Aralt = 2 Then
         Raise_Application_Error (-20283, Ias_Gen_Pkg.Get_Msg (V_Lang_No, 26));
      End If;
      --------------------------------------------------------------------------------------------
      If P_C_Class Is Null And V_Cst_Seq_Type = 3 Then
         Raise_Application_Error (-20284, Ias_Gen_Pkg.Get_Msg (V_Lang_No, 1601) || ' ' || Ias_Gen_Pkg.Get_Prompt (V_Lang_No, 589));
      End If;
      --------------------------------------------------------------------------------------------
      If P_C_Group_Code Is Not Null Then
         Begin
            Select 1
              Into V_Cnt
              From Customer_Group
             Where C_Group_Code = P_C_Group_Code And Rownum <= 1;
         Exception
            When Others Then
               V_Cnt := 0;
         End;

         If Nvl (V_Cnt, 0) = 0 Then
            Raise_Application_Error (-20285, Ias_Gen_Pkg.Get_Msg (V_Lang_No, 43));
         End If;
      End If;
      --------------------------------------------------------------------------------------------
      If P_C_Class Is Not Null Then
         Begin
            Select 1
              Into V_Cnt
              From Customer_Class
             Where C_Class = P_C_Class And Rownum <= 1;
         Exception
            When Others Then
               V_Cnt := 0;
         End;

         If Nvl (V_Cnt, 0) = 0 Then
            Raise_Application_Error (-20286, Ias_Gen_Pkg.Get_Prompt (V_Lang_No, 589) || ' ' || Ias_Gen_Pkg.Get_Msg (V_Lang_No, 312));
         End If;
      End If;

      --------------------------------------------------------------------------------------------
      If P_C_Class_Typ Is Not Null Then
         Begin
            Select 1
              Into V_Cnt
              From Customer_Class_Typ
             Where C_Class_Typ = P_C_Class_Typ And Rownum <= 1;
         Exception
            When Others Then
               V_Cnt := 0;
         End;

         If Nvl (V_Cnt, 0) = 0 Then
            Raise_Application_Error (-20287, Ias_Gen_Pkg.Get_Msg (V_Lang_No, 1526));
         End If;
      End If;
      --------------------------------------------------------------------------------------------
      If P_C_Mobile Is Not Null Then
         If Nvl (P_Upd_Flg, 0) = 0 Then
            Begin
               Select 1
                 Into V_Cnt
                 From Customer
                Where Nvl (C_Mobile, 0) = Nvl (P_C_Mobile, 0) And Rownum <= 1;
            Exception
               When Others Then
                  V_Cnt := 0;
            End;
         Else
            Begin
               Select 1
                 Into V_Cnt
                 From Customer
                Where Nvl (C_Mobile, 0) = Nvl (P_C_Mobile, 0) And C_Code <> P_C_Code And Rownum <= 1;
            Exception
               When Others Then
                  V_Cnt := 0;
            End;
         End If;

         If Nvl (V_Cnt, 0) > 0 Then
            Raise_Application_Error (-20288, Ias_Gen_Pkg.Get_Prompt (V_Lang_No, 6524) || ' ' || Ias_Gen_Pkg.Get_Msg (V_Lang_No, 581) || Chr(10) || 'C_MOBILE=' || P_C_Mobile);
         End If;
      End If;
      --------------------------------------------------------------------------------------------
      If Nvl (P_Upd_Flg, 0) = 0 Then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ---INSERT
         If P_C_Code Is Not Null Then
            Begin
               Select 1
                 Into V_Cnt
                 From Customer
                Where Nvl (C_Code_Trgt, 0) = Nvl (P_C_Code, 0) And Rownum <= 1;
            Exception
               When Others Then
                  V_Cnt := 0;
            End;
         End If;

         If  Nvl(V_Cnt, 0)<> 0 And Nvl(P_Sys_No,0)= 101  Then 
         V_Cnt := 0;
         End If;  

         If Nvl (V_Cnt, 0) = 0 Then
            If Nvl (V_Cust_D_Type, 0) = 1 And Nvl (P_Gnrt_Cst_Flg, 0) = 1 Then
               If V_Cst_Seq_Type = 1 Then
                  Begin
                     Select Nvl (Max (To_Number (C_Code)), 0) + 1 Into V_Cst_Code From Customer;
                  Exception
                     When No_Data_Found Then
                        Null;
                     When Others Then
                        Raise_Application_Error (-20289, 'Err   ' || Chr (10) || Sqlerrm);
                  End;
               Elsif V_Cst_Seq_Type = 2 Then
                  Begin
                     Select Nvl (Max (To_Number (C_Code)), 0) + 1
                       Into V_Cst_Code
                       From Customer
                      Where C_Group_Code = P_C_Group_Code;
                  Exception
                     When No_Data_Found Then
                        Null;
                     When Others Then
                        Raise_Application_Error (-20290, 'Err   ' || Chr (10) || Sqlerrm);
                  End;
               Elsif V_Cst_Seq_Type = 3 Then
                  Begin
                     Select Nvl (Max (To_Number (C_Code)), 0) + 1
                       Into V_Cst_Code
                       From Customer
                      Where C_Group_Code = P_C_Group_Code And C_Class = P_C_Class;
                  Exception
                     When No_Data_Found Then
                        V_Cst_Code := Null;
                     When Others Then
                        Raise_Application_Error (-20291, 'Err   ' || Chr (10) || Sqlerrm);
                  End;
               End If;
            
            Elsif Nvl(V_Cust_D_Type, 0) = 2 And Nvl (P_Gnrt_Cst_Flg, 0) = 1 then 
             If V_Cst_Seq_Type = 1 Then
                  Begin
                     Select Nvl (Max (C_Code), '0')  Into V_Cst_Code From Customer;
                  Exception
                     When No_Data_Found Then
                        Null;
                     When Others Then
                        Raise_Application_Error (-20742, 'Err   ' || Chr (10) || Sqlerrm);
                  End;
               Elsif V_Cst_Seq_Type = 2 Then
                  Begin
                     Select Nvl (Max (C_Code), '0') 
                       Into V_Cst_Code
                       From Customer
                      Where C_Group_Code = P_C_Group_Code;
                  Exception
                     When No_Data_Found Then
                        Null;
                     When Others Then
                        Raise_Application_Error (-20743, 'Err   ' || Chr (10) || Sqlerrm);
                  End;
               Elsif V_Cst_Seq_Type = 3 Then
                  Begin
                     Select Nvl (Max (C_Code),'0')
                       Into V_Cst_Code
                       From Customer
                      Where C_Group_Code = P_C_Group_Code And C_Class = P_C_Class;
                  Exception
                     When No_Data_Found Then
                        V_Cst_Code := Null;
                     When Others Then
                        Raise_Application_Error (-20744, 'Err   ' || Chr (10) || Sqlerrm);
                  End;
                  
                  END IF ;
                  
                  IF V_Cst_Code IS  NULL THEN 
                       V_Cst_Code:= GET_AUTO_INCRMNT_FNC(P_SRC_STR=> V_Cst_Code, P_MX_STR_LNTH=> 1000) ;
                  END IF;   
              
                Else   
               V_Cst_Code := P_C_Code;
               
            End If;
         Else
            Raise_Application_Error (-20292, Ias_Gen_Pkg.Get_Msg (V_Lang_No, 2057) || '=' || P_C_Code);
         End If;
         --------------------------------------------------------------------------------------------
         Begin
            Select C_A_Code
              Into V_C_Acode
              From Customer_Group
             Where C_Group_Code = P_C_Group_Code And Rownum <= 1;
         Exception
            When Others Then
               Null;
         End;

         --------------------------------------------------------------------------------------------
         Begin
            Select Nvl (Max (Cst_Seq), 0) + 1 Into V_Cst_Seq From Customer;
         Exception
            When Others Then
               Null;
         End;
         --------------------------------------------------------------------------------------------
         Begin
            Select 1
              Into V_Cnt
              From Customer
             Where C_Code = V_Cst_Code And Rownum <= 1;
         Exception
            When Others Then
               V_Cnt := 0;
         End;

         If Nvl (V_Cnt, 0) > 0 Then
            Raise_Application_Error (-20293, Ias_Gen_Pkg.Get_Msg (V_Lang_No, 2057) || '=' || V_Cst_Code);
         End If;

         --------------------------------------------------------------------------------------------
         Begin
            Insert Into Customer (C_Code
                                 ,C_A_Name
                                 ,C_E_Name
                                 ,C_A_Code
                                 ,Cst_Seq
                                 ,C_Group_Code
                                 ,C_Address
                                 ,C_Class
                                 ,Cntry_No
                                 ,Prov_No
                                 ,City_No
                                 ,R_Code
                                 ,Rep_Code
                                 ,Route_No
                                 ,Sortinroute
                                 ,Gps
                                 ,C_Phone
                                 ,C_Fax
                                 ,C_Box
                                 ,C_Person
                                 ,C_E_Mail
                                 ,C_Web_Site
                                 ,C_Mobile
                                 ,Respons_Person
                                 ,C_Code_Trgt
                                 ,C_Tax_Code
                                 ,Clc_Vat_Price_Typ
                                 ,Latitude
                                 ,Longitude
                                 ,Ad_U_Id
                                 ,Ad_Date
                                 ,Ad_Trmnl_Nm 
                                 ,Cr_No       
                                 ,Dstrct_Nm   
                                 ,Building_No 
                                 ,Street      
                                 ,Add_No      
                                 ,C_Box_Code  
                                 ,C_Since     
                                 ,Shrt_Add
                                 ,CSTMR_IDNTFR
                                 ,C_CLASS_VAT
                                 ,C_WHATSAPP_NO  )
                 Values (V_Cst_Code
                        ,P_C_A_Name
                        ,P_C_E_Name
                        ,V_C_Acode
                        ,V_Cst_Seq
                        ,P_C_Group_Code
                        ,P_C_Address
                        ,P_C_Class
                        ,P_Cntry_No
                        ,P_Prov_No
                        ,P_City_No
                        ,P_R_Code
                        ,P_Rep_Code
                        ,P_Route_No
                        ,P_Sortinroute
                        ,Decode (P_Gps, Null, (P_Latitude || ',' || P_Longitude), P_Gps)
                        ,P_C_Phone
                        ,P_C_Fax
                        ,P_C_Box
                        ,P_C_Person
                        ,P_C_E_Mail
                        ,P_C_Web_Site
                        ,P_C_Mobile
                        ,P_Respons_Person
                        ,P_C_Code
                        ,P_C_Tax_Code
                        ,P_Clc_Vat_Price_Typ
                        ,P_Latitude
                        ,P_Longitude
                        ,P_Ad_U_Id
                        ,Ys_Gen_Pkg.Get_Curdate
                        ,P_Ad_Trmnl_Nm
                        ,P_Cr_No      
                        ,P_Dstrct_Nm  
                        ,P_Building_No
                        ,P_Street     
                        ,P_Add_No     
                        ,P_C_Box_Code 
                        ,P_C_Since    
                        ,P_Shrt_Add 
                        ,P_CSTMR_IDNTFR  
                        ,P_C_CLASS_VAT
                        ,P_C_WHATSAPP_NO
                        );
         Exception
            When Others Then
               Raise_Application_Error (-20294, 'Err INSERT INTO CUSTOMER  ' || Chr (10) || Sqlerrm);
         End;
        -------------------------------------------------------------------------- 
        --------------------------------------------------------------------------
        Begin 
       Select Count(*)  Into V_Cnt 
                   From Xmltable('CST/CUSTOMER_CURR' Passing V_Xml_Type 
                      Columns A_Cy  Varchar(100) Path 'A_CY') ; 
       
         Exception
            When Others Then
            V_Cnt:=0;
         End; 
        --------------------------------------------------------------------------       
    If Nvl(V_Cnt,0) >=1 And V_Cst_Code Is Not Null Then      
         
       For Cst_Cur In (Select              Extractvalue( Value( Xmlcurdmy), '*/A_CY                    ') As A_Cy
                                          ,Extractvalue( Value( Xmlcurdmy), '*/INACTIVE                ') As Inactive
                                          ,Extractvalue( Value( Xmlcurdmy), '*/LEV_NO_CRDT             ') As LEV_NO_CRDT
                                          ,Extractvalue( Value( Xmlcurdmy), '*/LEV_NO_CSH              ') As Lev_No_Csh
                                          ,Extractvalue( Value( Xmlcurdmy), '*/INACTIVE_SALES          ') As INACTIVE_SALES
                                          ,Extractvalue( Value( Xmlcurdmy), '*/DFLT_FLG                ') As DFLT_FLG
                                      From Table( Xmlsequence( Extract( V_Xml_Type,'/CST/CUSTOMER_CURR'))) Xmlcurdmy)
                 Loop
         Begin
         

     --------------------------------------------------------------------------------------------                 
            If Cst_Cur.LEV_NO_CRDT Is Not Null Then
             Begin
                Select 1
                  Into V_Cnt
                  From IAS_PRICING_LEVELS
                 Where LEV_NO = Cst_Cur.LEV_NO_CRDT And Rownum <= 1;
             Exception
                When Others Then
                   V_Cnt := 0;
             End;

             If Nvl (V_Cnt, 0) = 0 Then
                Raise_Application_Error (-20300, Ias_Gen_Pkg.Get_Msg (V_Lang_No, 2011) || 'LEV_NO_CRDT=' || Cst_Cur.LEV_NO_CRDT);
             End If;
            End If;    

         --------------------------------------------------------------------------------------------
          If Cst_Cur.LEV_NO_CSH Is Not Null Then
             Begin
                Select 1
                  Into V_Cnt
                  From IAS_PRICING_LEVELS
                 Where LEV_NO = Cst_Cur.LEV_NO_CSH And Rownum <= 1;
             Exception
                When Others Then
                   V_Cnt := 0;
             End;

             If Nvl (V_Cnt, 0) = 0 Then
                Raise_Application_Error (-20301, Ias_Gen_Pkg.Get_Msg (V_Lang_No, 2011) || 'LEV_NO_CSH=' || Cst_Cur.LEV_NO_CSH);
             End If;
         End If;   
         
     -------------------------------------------------------------------------------------------- 
        Begin             
                      INSERT INTO CUSTOMER_CURR(   C_CODE, 
                                                   A_CY, 
                                                   INACTIVE,
                                                   AD_U_ID, 
                                                   AD_DATE,
                                                   LEV_NO,
                                                   LEV_NO_CSH,
                                                   INACTIVE_SALES,
                                                   DFLT_FLG
                                                   )                                               
                                               Select 
                                                    V_CST_CODE,
                                                    Cst_Cur.A_CY    ,
                                                    INACTIVE,
                                                    P_AD_U_ID,
                                                    YS_GEN_PKG.Get_Curdate,
                                                    Cst_Cur.LEV_NO_CRDT,
                                                    Cst_Cur.LEV_NO_CSH,
                                                    NVL(Cst_Cur.INACTIVE_SALES,0),
                                                    NVL(Cst_Cur.DFLT_FLG,0)
                                                     FROM ACCOUNT_CURR  WHERE A_CODE=V_C_ACODE and A_Cy =Cst_Cur.A_Cy;                  
                   Exception  When Others Then
                       ROLLBACK;
                    RAISE_APPLICATION_ERROR(-20302,'Err INSERT INTO CUSTOMER_CURR '||CHR(10)||SQLERRM);                     
         End ;                            
    End  ; 
    End Loop;  
       
    End If; 
         --------------------------------------------------------------------------------------------         
        IF  Nvl(V_Cnt,0) =0 AND  V_CST_CODE Is Not Null Then                        
         
         If P_LEV_NO_CRDT Is Not Null Then
             Begin
                Select 1
                  Into V_Cnt
                  From IAS_PRICING_LEVELS
                 Where LEV_NO = P_LEV_NO_CRDT And Rownum <= 1;
             Exception
                When Others Then
                   V_Cnt := 0;
             End;

             If Nvl (V_Cnt, 0) = 0 Then
                Raise_Application_Error (-20298, Ias_Gen_Pkg.Get_Msg (V_Lang_No, 2011) || 'P_LEV_NO_CRDT=' || P_LEV_NO_CRDT);
             End If;
         End If;    
         --------------------------------------------------------------------------------------------
          If P_LEV_NO_CSH Is Not Null Then
             Begin
                Select 1
                  Into V_Cnt
                  From IAS_PRICING_LEVELS
                 Where LEV_NO = P_LEV_NO_CSH And Rownum <= 1;
             Exception
                When Others Then
                   V_Cnt := 0;
             End;

             If Nvl (V_Cnt, 0) = 0 Then
                Raise_Application_Error (-20298, Ias_Gen_Pkg.Get_Msg (V_Lang_No, 2011) || 'P_LEV_NO_CSH=' || P_LEV_NO_CSH);
             End If;
         End If;    
         -------------------------------------------------------------------------------------------- 
        Begin             
                      INSERT INTO CUSTOMER_CURR(   C_CODE, 
                                                   A_CY, 
                                                   INACTIVE,
                                                   AD_U_ID, 
                                                   AD_DATE,
                                                   LEV_NO,
                                                   LEV_NO_CSH)                                               
                                               Select 
                                                    V_CST_CODE,
                                                    A_CY    ,
                                                    INACTIVE,
                                                    P_AD_U_ID,
                                                    YS_GEN_PKG.Get_Curdate,
                                                    P_LEV_NO_CRDT,
                                                    P_LEV_NO_CSH
                                                     FROM ACCOUNT_CURR  WHERE A_CODE=V_C_ACODE;                  
                   Exception  When Others Then
                       ROLLBACK;
                    RAISE_APPLICATION_ERROR(-20009,'Err INSERT INTO CUSTOMER_CURR '||CHR(10)||SQLERRM);                     
         End ;     
        END IF;                        
                  ----------------------------------------------
                   Begin                                
                             INSERT INTO IAS_PRIV_CUSTOMER( U_ID
                                                           ,C_CODE
                                                           ,A_CY
                                                           ,ADD_FLAG
                                                           ,VIEW_FLAG
                                                           ,AD_U_ID
                                                           ,AD_DATE)
                                                    Select  p.U_ID
                                                           ,c.C_CODE
                                                           ,p.A_CY                     
                                                           ,DECODE(p.U_ID,1,1,P_AD_U_ID,1,ADD_FLAG)
                                                           ,DECODE(p.U_ID,1,1,P_AD_U_ID,1,VIEW_FLAG) 
                                                           , P_AD_U_ID
                                                           ,IAS_GEN_PKG.GET_CURDATE 
                                                    FROM PRIV_ACC P ,  CUSTOMER C
                                                  WHERE P.A_CODE=C.C_A_CODE 
                                                      AND P.A_CODE=V_C_ACODE
                                                      AND C.C_CODE=V_CST_CODE
                                                      AND NVL(ADD_FLAG,0)+NVL(VIEW_FLAG,0)>0 ;
                                   
                                                                                       
                  Exception  When Others Then
                       ROLLBACK;
                        RAISE_APPLICATION_ERROR(-20009,'Err INSERT INTO Ias_Priv_Customer '||CHR(10)||SQLERRM);                     
                  End ;
                                                     
                                                                 


         Commit;
         P_Cst_Code := V_Cst_Code;
      Else                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   ----UPDATE
         Begin
            Update Customer
               Set C_A_Name = P_C_A_Name
                  ,C_E_Name = P_C_E_Name
                  ,C_Address = P_C_Address
                  ,C_Class = Decode (V_Cst_Seq_Type, 3, C_Class, P_C_Class)
                  ,Cntry_No = P_Cntry_No
                  ,Prov_No = P_Prov_No
                  ,City_No = P_City_No
                  ,R_Code = P_R_Code
                  ,Rep_Code = P_Rep_Code
                  ,Route_No = P_Route_No
                  ,Sortinroute = P_Sortinroute
                  ,Gps = Decode (P_Gps, Null, (P_Latitude || ',' || P_Longitude), P_Gps)
                  ,C_Phone = P_C_Phone
                  ,C_Fax = P_C_Fax
                  ,C_Box = P_C_Box
                  ,C_Person = P_C_Person
                  ,C_E_Mail = P_C_E_Mail
                  ,C_Web_Site = C_Web_Site
                  ,C_Mobile = P_C_Mobile
                  ,Respons_Person = P_Respons_Person
                  ,C_Tax_Code = P_C_Tax_Code
                  ,Clc_Vat_Price_Typ = P_Clc_Vat_Price_Typ
                  ,Latitude = P_Latitude
                  ,Longitude = P_Longitude
                  ,Up_U_Id = P_Up_U_Id
                  ,Up_Date = Ys_Gen_Pkg.Get_Curdate
                  ,Up_Trmnl_Nm = P_Up_Trmnl_Nm
                  ,Cr_No        =P_Cr_No          
                  ,Dstrct_Nm    =P_Dstrct_Nm      
                  ,Building_No  =P_Building_No    
                  ,Street       =P_Street         
                  ,Add_No       =P_Add_No         
                  ,C_Box_Code   =P_C_Box_Code     
                  ,C_Since      =P_C_Since        
                  ,Shrt_Add     =P_Shrt_Add 
                  ,CSTMR_IDNTFR=P_CSTMR_IDNTFR   
             Where C_Code = P_C_Code;
         Exception
            When Others Then
               Rollback;
               Raise_Application_Error (-20297, 'Err WHEN UPDATE CUSTOMER  ' || Chr (10) || Sqlerrm);
         End;

         Commit;
      End If;
   End Insrt_Cst_Prc;
   --##------------------------------------------------------------------------------------------------------------------------------##--
 Procedure Get_Prmtr_Prc (P_Sys_No          In     Number Default Null
                        ,P_Doc_Typ          In     Ias_Post_Mst.Doc_Type%Type Default Null
                        ,P_Pst_Typ          In     Number Default Null
                        ,P_Cur_Code         In     Ex_Rate.Cur_Code%Type Default Null
                        ,P_Cur_Rate         In     Ex_Rate.Cur_Rate%Type Default Null
                        ,P_Stock_Rate       In     Ex_Rate.Cur_Rate%Type Default Null
                        ,P_Doc_Date         In     Ias_Post_Dtl.Doc_Date%Type Default Null
                        ,P_Brn_No           In     S_Brn.Brn_No%Type Default Null
                        ,P_Brn_Usr          In     S_Brn.Brn_Usr%Type Default Null
                        ,P_Brn_Year         In     S_Brn.Brn_Year%Type Default Null
                        ,P_Usr_No           In     User_R.U_Id%Type Default Null
                        ,P_Clc_Tax_Method   In     Number --## 0 CALC TAX IN EXTRNAL ,1-AOUTO CALC TAX
                        ,P_Pst_From_Br      In     Number  --## 1- POSTING FORM BR TABLE  0- NOT FROM BR
                        ,P_DTS_ONLINE       In     NUMBER DEFAULT 0 --## 0 OFFLINE ,1-ONLINE 
                        ,P_Lng_No           In     Number Default Null
                        ,P_Msg_Txt             Out Varchar2
                        ,P_Err_No              Out Varchar2
                        ,P_Pkg_Nm              Out Varchar2)
Is
   V_Msg_No    Number;
   V_Cnt       Number; 
   V_PRIV_OUT_BILL_TYP  Number(1):=0;
   V_ACTIVE_VAT_DATE  date ;  
   V_DTS_USE_RQ_TRANSFER_AVLQTY Number(1):=0;
Begin
   --##-------------------------------------------------------------------------------##--
   --## claer all gloable variable
   --  Clr_Glbl_Var;
   --##-------------------------------------------------------------------------------##--
   G_Sys_No           := P_Sys_No;
   G_Doc_Typ          := P_Doc_Typ;
   G_Pst_Typ          := P_Pst_Typ;
   G_Cur_Code         := P_Cur_Code;
  -- G_Doc_Date         := To_Date (P_Doc_Date, 'DD/MM/RRRR');
   G_Doc_Date         :=Nvl (P_Doc_Date,To_Date(To_Char(Sysdate,'DD/MM/RRRR'),'DD/MM/RRRR'));
   G_Brn_No           := P_Brn_No;
   G_Brn_Usr          := P_Brn_Usr;
   G_Brn_Year         := P_Brn_Year;
   G_Usr_No           := P_Usr_No;
   G_Ad_U_Id          := P_Usr_No;
   G_Clc_Tax_Method   := Nvl (P_Clc_Tax_Method, 0);
   G_DTS_ONLINE       := Nvl (P_DTS_ONLINE, 0);   
   G_Lng_No           := P_Lng_No;
   G_Pst_From_Br      := Nvl (P_Pst_From_Br, 0);
   G_DIFF_AMT         :=0.1;
   G_SCHMA_NM         :=sys_context('USERENV','CURRENT_SCHEMA');

   --##-------------------------------------------------------------------------------##--
   --#BA_CHK
  /* If Nvl (G_Pst_From_Br, 0) = 1 Then
      G_Clc_Tax_Method   := 0;
   End If;*/
   --##-------------------------------------------------------------------------------##--
   If G_Lng_No Is Null Then
      Begin
         Select Lang_No
           Into G_Lng_Dflt
           From Ias_Sys.Lang_Def
          Where Lang_Dflt = 1 And Rownum <= 1;
      Exception
         When Others Then
            P_Err_No    := 20001;
            P_Msg_Txt   := 'Error When Select Deflt Language ';
            Goto Rtn_Rslt;
      End;

      G_Lng_No   := G_Lng_Dflt;
   Else
      Begin
         Select 1
           Into V_Cnt
           From Ias_Sys.Lang_Def
          Where Lang_No = G_Lng_No And Rownum <= 1;
      Exception
         When Others Then
            P_Err_No    := 20001;
            P_Msg_Txt   := 'The Entered Language is Invalid ';
            Goto Rtn_Rslt;
      End;

      G_Lng_No     := Nvl (P_Lng_No, 1);
      G_Lng_Dflt   := G_Lng_No;
   End If;
   --##-------------------------------------------------------------------------------##--
   Begin
      Select Nvl (Check_Lmt_Sorder, 0)
            ,Nvl (Max_Prd_Exp_Date_So_Day, 0)
            ,Nvl (Cc_Avail, 0)
            ,Nvl (Use_Projects, 0)
            ,Nvl (Use_Actvty, 0)
            ,Nvl (Ar_Cs_Type, 0)
            ,Nvl (Ar_Pj_Type, 0)
            ,Nvl (Ar_Actv_Type, 0)
            ,Nvl (No_Of_Decimal_Ar, 2)
            ,Nvl (Ar_Wc_Type, 0)
            ,Nvl (Ias_Para_Ar.Disc_Count, 0)
            ,Nvl (Max_Prd_Exp_Date_Sls_Quot_Day, 0)
            ,Nvl (Use_Batch_No, 0)
            ,Nvl (Use_Expire_Date, 0)
            ,Nvl (Ar_Ac_Link_Type, 0)
            ,Nvl (Ap_Ac_Link_Type, 0)
            ,Nvl (Show_Disc_Per_Items_Ar, 0)
            ,Nvl (Si_Repcode_Mandtry, 0)
            ,Nvl (Ar_Sorder_Serial, 0)
            ,Nvl (Doc_Gen_Ar, 0)
            ,Nvl (Costing_Type, 0)
            ,Nvl (Wtavg_Type, 0)
            ,Nvl (Calc_Vat_Amt_Type, 0)
            ,Nvl (Use_Price_Include_Vat, 0)
            ,Nvl (Use_Vat, 0)
            ,Nvl (Use_Out_Bills, 0)
            ,Nvl (Add_Porder_Qty, 0)
            ,Nvl (Invoicing_Serials, 0)
            ,Nvl (Item_Posting_Flag, 0)
            ,Nvl (Invoicing_Serials_Sr, 0)
            ,Nvl (Stkcost_Fraction, 0)
            ,Nvl (Use_Out_Bill_Direct, 0)
            ,Nvl (Roi_Type, 0)
            ,Nvl (Clc_Tax_Dscnt2, 0)
            ,Nvl (Clc_Tax_Dscnt3, 0)
            ,Nvl (P_Rate_Type, 0)
            ,Nvl (Use_Billno_Rtsale_Py, 0)
            ,NVL(USE_CLC_TAX_FREE_QTY,0)
            ,NVL(USE_OUT_BILL_DIRECT,0)
            ,NVL(Use_Serialno,0)
            ,Max_Prd_Exp_Date_Sls_Quot_Day
            ,Nvl(Quot_Exp_Date_Mandtry, 0)
            ,Nvl(Ias_Para_Ar.SHOW_SMAN_COMM_SI,0) 
            ,Nvl(Ias_Para_Ar.SHW_ITM_COMM_PER,0) 
            ,nvl(Ias_Para_Ar.Use_Sp_Sman,0)
            ,nvl(Conn_Activity_By_Wcode_Cc_code,0)
            ,ACTIVE_VAT_DATE
            ,Nvl(MAX_PRD_RESERVE_SO_DAY,0)
            ,nvl(Ias_Para_Ar.Paid_Instllmnt_Man,0)
            ,NVL(USE_BALANCED_BRN,0)
            ,TAX_CODE_LNGTH
            ,Nvl(AR_QT_WC_TYP,0)
            ,NVL(ALLW_SAL_WH_NOT_CONN_BRN,0)
            ,NVL (DATE_GEN_AR, 1)
            ,NVL (Use_E_Invoice, 0) 
        Into G_Check_Lmt_Sorder
            ,G_Max_Prd_Exp_Date_So_Day
            ,G_Cc_Avail
            ,G_Use_Projects
            ,G_Use_Actvty
            ,G_Ar_Cst_Type
            ,G_Ar_Pj_Type
            ,G_Ar_Actv_Type
            ,G_No_Of_Decimal_Ar
            ,G_Ar_Wc_Type
            ,G_Disc_Count
            ,G_Max_Prd_Exp_Date_Quot_Day
            ,G_Use_Batch_No
            ,G_Use_Expire_Date
            ,G_Aralt
            ,G_Apalt
            ,G_Show_Disc_Per_Items_Ar
            ,G_Si_Repcode_Mandtry
            ,G_Ar_Sorder_Serial
            ,G_Doc_Gen_Ar
            ,G_Costing_Type
            ,G_Wtavg_Type
            ,G_Calc_Vat_Amt_Type
            ,G_Use_Price_Include_Vat
            ,G_Use_Vat
            ,G_Use_Out_Bills
            ,G_Add_Porder_Qty
            ,G_Invoicing_Serials
            ,G_Item_Posting_Flag
            ,G_Invoicing_Serials_Sr
            ,G_Stkcost_Fraction
            ,G_Use_Out_Bill_Direct
            ,G_Roi_Type
            ,G_Clc_Tax_Dscnt2
            ,G_Clc_Tax_Dscnt3
            ,G_P_Rate_Type
            ,G_Use_Billno_Rtsale_Py
            ,G_USE_CLC_TAX_FREE_QTY
            ,G_USE_OUT_BILL_DIRECT
            ,G_Use_Serialno
            ,G_Max_Prd_Exp_Sls_Quot_Day
            ,G_Quot_Exp_Date_Mandtry
            ,G_SHOW_SMAN_COMM_SI
            ,G_SHW_ITM_COMM_PER 
            ,G_Use_Sp_Sman  
            ,G_Conn_Activity_By_Wcode_Cc 
           , V_ACTIVE_VAT_DATE
           , G_MAX_PRD_RESERVE_SO_DAY 
            ,G_Paid_Instllmnt_Man 
            ,G_USE_BALANCED_BRN 
            ,G_TAX_CODE_LNGTH
            ,G_AR_QT_WC_TYP 
            ,G_ALLW_SAL_WH_NOT_CONN_BRN    
            ,G_Date_Gen_Ar
            ,G_Use_E_Invoice             
        From Ias_Para_Gen
            ,Ias_Para_Ar
            ,Ias_Para_Inv
            ,Ias_Para_Ap
            ,Ias_Para_Gl;
   Exception
      When Others Then
         Raise_Application_Error (-20298, 'Error When Select PARAMETER , ' || Sqlerrm);
   End;
   --##-------------------------------------------------------------------------------##--
   If G_Use_Out_Bills=1 AND NVL(G_SYS_NO,0) =70 Then    
           Begin
             execute Immediate 'select Nvl(USE_RQ_TRANSFER_AVLQTY,0) from Dts_Para ' into  V_DTS_USE_RQ_TRANSFER_AVLQTY;
           Exception when Others Then 
               V_DTS_USE_RQ_TRANSFER_AVLQTY:=0;
           End ; 
   Else
      V_DTS_USE_RQ_TRANSFER_AVLQTY:=0;
   End If;             
   --##-------------------------------------------------------------------------------##--
   
   If nvl(G_Use_Vat,0)=1 Then    
       Begin
        SELECT 1 INTO v_cnt 
         FROM GNR_TAX_TYP_CLC_BRN 
           WHERE BRN_NO=G_Brn_No           
           and ACTV_DATE is not null
           and ACTV_DATE<=G_DOC_DATE 
            --and CLC_TYP_NO=P_CLC_TYP_NO 
         AND ROWNUM<=1;
       Exception When Others Then
            If V_ACTIVE_VAT_DATE is Not Null and V_ACTIVE_VAT_DATE<=G_Doc_Date Then
                G_Use_Vat:=1;
            Else
                 G_Use_Vat:=0;
            End If;                
       End ;       
   End If;
   --##-------------------------------------------------------------------------------##--
    IF G_DOC_TYP IN(4,52,53) THEN    
        G_DR_CR_FLG:=-1;
    ELSIF G_DOC_TYP IN(5,136) THEN
            G_DR_CR_FLG:=1;
    ELSE
          G_DR_CR_FLG:=NULL;
    END IF;                      
   --##-------------------------------------------------------------------------------##--
   If G_Doc_Typ Is Null Then
      P_Err_No    := 20001;
      P_Msg_Txt   := 'P_doc_type  Is Null';
      Goto Rtn_Rslt;
   End If;

   If G_Sys_No Is Null Then
      P_Err_No    := 20002;
      P_Msg_Txt   := 'SYS_NO IS NULL';
      Goto Rtn_Rslt;
   Else
      G_Sys_No   := P_Sys_No;
   End If;

   If G_Pst_Typ Is Null And G_Doc_Typ Not In (4, 5) Then
      G_Pst_Typ   := 2;
   End If;

   If G_Pst_Typ Is Null And G_Doc_Typ In (4, 5) Then
      P_Err_No    := 20004;
      P_Msg_Txt   := 'P_PST_TYP IS NULL';
      Goto Rtn_Rslt;
   Elsif G_Pst_Typ Not In (1, 2) Then
      P_Err_No    := 20005;
      P_Msg_Txt   := 'P_Pst_Typ Must Be Equal  1 OR 2';
      Goto Rtn_Rslt;
  End If;
   --##-------------------------------------------------------------------------------##--
    If G_Ad_U_Id Is Not Null Then
      Gnr_Api_Pkg.Chk_Inpt_Data (P_Inpt_Typ     => 'USR_NO'
                                ,P_Sys_Typ      => 1
                                ,P_Doc_Type     => G_Doc_Typ
                                ,P_Inpt_Code1   => G_Ad_U_Id
                                ,P_Lng_Dflt     => G_Lng_Dflt
                                ,P_Inpt_Nm      => G_Inpt_Nm
                                ,P_Msg_No       => V_Msg_No);

      If V_Msg_No Is Not Null Then
         P_Err_No    := 20008;
         P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No);
         Goto Rtn_Rslt;
      End If;
   Else
      P_Err_No    := 20009;
      P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 450);
      Goto Rtn_Rslt;
   End If;

   V_Msg_No           := Null;

   --##-------------------------------------------------------------------------------##--
       If G_Doc_Date Is Null Then
          P_Err_No    := 20012;
          P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 515);
          Goto Rtn_Rslt;
       End If;
       V_Msg_No           :=
          Ys_Gen_Pkg.Check_Date (P_Usr_No     => G_Ad_U_Id
                                ,P_Brn_No     => G_Brn_No
                                ,P_Doc_Date   => G_Doc_Date
                                ,P_Scr_Type   => 'FRM'
                                ,P_Frm_Type   =>1);

       If V_Msg_No Is Not Null And V_Msg_No <> 0  Then       
           If  G_Doc_Typ in (53,52) And v_msg_no=365 Then
               Null;
           Else    
              P_Err_No    := 20013;
              P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No);
              Goto Rtn_Rslt;
           End If;    
       End If;

       V_Msg_No           := Null;
   --##-------------------------------------------------------------------------------##--
   --## set and check currency
   G_Loc_Cur_Code     := Ias_Gen_Pkg.Get_Local_Cur;
   G_Stk_Cur_Code     := Ias_Gen_Pkg.Get_Stk_Cur;
   G_Stk_Rate         := Ias_Gen_Pkg.Get_Cur_Rate (G_Stk_Cur_Code);

   If P_Cur_Code Is Null Then
      P_Err_No    := 20006;
      P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 31) || Chr(10) || ' P_CUR_CODE Is Null , Must Be Entered , ';
      Goto Rtn_Rslt;
   Else
      Gnr_Api_Pkg.Chk_Inpt_Data (P_Inpt_Typ     => 'CUR_CODE'
                                ,P_Sys_Typ      => 1
                                ,P_Doc_Type     => G_Doc_Typ
                                ,P_Inpt_Code1   => P_Cur_Code
                                ,P_Lng_Dflt     => G_Lng_Dflt
                                ,P_Inpt_Nm      => G_Inpt_Nm
                                ,P_Msg_No       => V_Msg_No);

      If V_Msg_No Is Not Null Then
         P_Err_No    := 20007;
         P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No);
         Goto Rtn_Rslt;
      End If;
   End If;

   If Nvl (P_Cur_Rate, 0) <= 0  Or nvl(G_DTS_ONLINE,0)=1 Then
      G_Cur_Rate   := Ys_Gen_Pkg.Get_Cur_Rate (P_Cur_Code => G_Cur_Code,
                                               P_Rate_Type =>1    ,
                                               P_Date    =>G_Doc_Date ,
                                               P_USR_NO   =>G_Ad_U_Id );
   Else
      G_Cur_Rate   := P_Cur_Rate;
   End If;

   If P_Cur_Code = G_Loc_Cur_Code And G_Cur_Rate <> 1 Then
      G_Cur_Rate   := 1;
   End If;

   If G_Loc_Cur_Code = G_Stk_Cur_Code And G_Stk_Rate <> 1 Then
      G_Stk_Rate   := 1;
   End If;

   If P_Cur_Code = G_Stk_Cur_Code And G_Cur_Rate <> G_Stk_Rate Then
      G_Stk_Rate   := G_Cur_Rate;
   End If;

   --##-------------------------------------------------------------------------------##--  
   If G_Brn_No Is Not Null Then
      Gnr_Api_Pkg.Chk_Inpt_Data (P_Inpt_Typ     => 'BRN_NO'
                                ,P_Sys_Typ      => 1
                                ,P_Doc_Type     => G_Doc_Typ
                                ,P_Inpt_Code1   => G_Brn_No
                                ,P_Lng_Dflt     => G_Lng_Dflt
                                ,P_Inpt_Nm      => G_Inpt_Nm
                                ,P_Msg_No       => V_Msg_No);

      If V_Msg_No Is Not Null Then
         P_Err_No    := 20010;
         P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No);
         Goto Rtn_Rslt;
      End If;
   Else
      P_Err_No    := 20011;
      P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 449);
      Goto Rtn_Rslt;
   End If;

   V_Msg_No           := Null;

   --##-------------------------------------------------------------------------------##--  
   G_Brn_Year         :=NVL(P_Brn_Year, To_Number (To_Char (G_Doc_Date, 'RRRR')));   
   --##-------------------------------------------------------------------------------##--
   Begin
      G_Cmp_No   := Ias_Brn_Pkg.Get_Br_Cmp (G_Brn_No => G_Brn_No);
   Exception
      When Others Then
         Null;
   End;
   --##-------------------------------------------------------------------------------##--
   If G_Brn_Usr Is Null Then
      P_Err_No    := 20014;
      P_Msg_Txt   := 'BRN_USR IS NULL';
      Goto Rtn_Rslt;
   End If;

   If G_Brn_Year Is Null Then
      P_Err_No    := 20015;
      P_Msg_Txt   := 'Brn_Year IS NULL';
      Goto Rtn_Rslt;
   End If;
   --##-------------------------------------------------------------------------------##--
   If G_Loc_Cur_Code Is Null Then
      P_Err_No    := 20016;
      P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 227);
      Goto Rtn_Rslt;
   End If;
   --##-------------------------------------------------------------------------------##--
   If G_Cur_Rate Is Null Then
      P_Err_No    := 20017;
      P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 224);
      Goto Rtn_Rslt;
   End If;
   --##-------------------------------------------------------------------------------##--
   If G_Stk_Cur_Code Is Null Then
      P_Err_No    := 20018;
      P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 2);
      Goto Rtn_Rslt;
   End If;
   --##-------------------------------------------------------------------------------##--
   If G_Stk_Rate Is Null Then
      P_Err_No    := 20019;
      P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 889);
      Goto Rtn_Rslt;
   End If;
  --##-------------------------------------------------------------------------------##--
   Begin
       Select 1 
         Into V_CNT
         From S_Prd_Dtl
        Where YR_NO=G_Brn_Year
        AND ROWNUM<=1;
    Exception
       When Others Then
         P_Err_No    := 20487;
         P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 299)||' P_YEAR_NO='||G_Brn_Year;
         Goto Rtn_Rslt;
    End;
    --##-------------------------------------------------------------------------------##--
    BEGIN
        SELECT Nvl(pay_avl_qty,1) ,nvl(USE_RES_IN_SO_MNDTRY,0), NVL (ALLOW_UPDATE_AUTO_DATE, 0) 
               INTO G_pay_avl_qty  ,G_USE_RES_IN_SO_MNDTRY,G_ALLOW_UPDATE_AUTO_DATE
         From Privilege_Fixed
       where U_id=G_AD_U_ID
   AND ROWNUM<=1;
    EXCEPTION WHEN OTHERS THEN
       P_Err_No    := 20488;
       P_Msg_Txt   := 'ERROR IN Privilege_Fixed '||SQLERRM;
       Goto Rtn_Rslt;
    END ;
    --##------------------------------------------------------------------------------##--
     If G_Sys_No =61 And G_Doc_Typ In (4,5) And  ( G_Date_Gen_Ar = 3  Or G_Allow_Update_Auto_Date =0 
       Or(Nvl(Ias_Brn_Pkg.Is_Brn_Use_E_Invc(P_Brn_No => G_Brn_No), 0)  = 1 And G_Use_E_Invoice= 1 )) Then 
            G_Doc_Date :=To_Date (To_Char (SYSDATE, 'DD/MM/RRRR'), 'DD/MM/RRRR');
     End If ;
    --##------------------------------------------------------------------------------##--
    BEGIN
      EXECUTE IMMEDIATE 'SELECT CSH_CST FROM DTS_PARA ' INTO  G_DTS_C_CSH_CODE;
    EXCEPTION WHEN OTHERS THEN
       NULL;
    END ;
    --##------------------------------------------------------------------------------##--
    IF  NVL(G_Pst_Typ,0)=2 AND Nvl(G_Use_Out_Bills, 0) = 1 AND NVL(G_USE_OUT_BILL_DIRECT,0)=1 THEN
             BEGIN
                    Select 1 INTO V_PRIV_OUT_BILL_TYP
                        From S_Flags_Priv
                    Where U_Id = G_AD_U_ID
                      And Upper (Flg_Code) = 'OUT_BILL_TYP'                                              
                      And Flg_Value =1
                      And Priv_Flag = 1;
             EXCEPTION WHEN OTHERS THEN
               V_PRIV_OUT_BILL_TYP:=0;
            END ;
    END IF;       
     --##------------------------------------------------------------------------------##--         
     IF G_DOC_TYP IN(52,53,136) THEN
       G_USE_APPRVD_FLG:=1;
     ELSE
       G_USE_APPRVD_FLG:=0;
     END IF;         
    --##-------------------------------------------------------------------------------##--
    --## CHK_CRDT_LMIT 
      IF G_DOC_TYP =53 AND Nvl(G_Check_Lmt_Sorder, 0) = 1 and nvl(G_SYS_NO,0)=70 and NVL(G_DTS_ONLINE,0)=1  And Nvl(G_Stand_By,0) =0  THEN
        G_CHK_CRDT_LMIT := 1;     
      ELSIf Nvl(G_Check_Lmt_Sorder, 0) = 1 AND G_DOC_TYP=53 and nvl(G_SYS_NO,0)<>70  And Nvl(G_Stand_By,0) =0 Then
         G_CHK_CRDT_LMIT := 1;
      ELSIF G_DOC_TYP IN(5,136)  THEN
           G_CHK_CRDT_LMIT := 0;
      --#BA_CHK
     -- ELSIF G_DOC_TYP =4 AND NVL(G_Pst_Typ,0)=2 and nvl(G_SYS_NO,0)=70 and NVL(G_DTS_ONLINE,0)=1   THEN
      ELSIF G_DOC_TYP =4  And nvl(G_SYS_NO,0)=70 and NVL(G_DTS_ONLINE,0)=1   THEN
        G_CHK_CRDT_LMIT := 1;             
      ELSIF G_DOC_TYP =4 AND Nvl(G_Pst_FROM_BR, 0) = 1   THEN
        G_CHK_CRDT_LMIT := 0;      
      ELSIF G_DOC_TYP =4 AND NVL(G_Pst_Typ,0)=1   THEN
        G_CHK_CRDT_LMIT := 0;  
      ELSIF G_DOC_TYP =4 AND Nvl(G_Clc_Tax_Method, 0) = 1   THEN 
        G_CHK_CRDT_LMIT := 1; 
      ELSE
         G_CHK_CRDT_LMIT := 0;    
      End If;
      
      IF nvl(G_SYS_NO,0)=64   THEN
        G_CHK_CRDT_LMIT := 0;     
      END If;     
    --##-------------------------------------------------------------------------------##--
     --## CALC_OTHER_CHRG 
     --#BA_CHK     
    --  If G_DOC_TYP IN(4,5) AND NVL(G_CLC_TAX_METHOD,0)=1 AND NVL(G_Pst_FROM_BR,0)=0 And G_Sys_No<> 185 Then
      --If G_DOC_TYP IN(4,5) AND NVL(G_CLC_TAX_METHOD,0)=1 And G_Sys_No Not In(67, 185) Then  
      If NVL(G_CLC_TAX_METHOD,0)=1 And G_Sys_No Not In(67, 185) Then   
         G_CALC_OTHER_CHRG := 1;      
      ELSE
         G_CALC_OTHER_CHRG := 0;    
      End If;
    --##-------------------------------------------------------------------------------##--
    --## CALC_TAX_AUTO_FLG  
    --#BA_CHK      
     -- If NVL(G_CLC_TAX_METHOD,0)=1 AND NVL(G_Pst_FROM_BR,0)=0 Then
      If NVL(G_CLC_TAX_METHOD,0)=1 Then    
         G_CALC_TAX_AUTO_FLG := 1;      
      ELSE
         G_CALC_TAX_AUTO_FLG := 0;    
      End If;
    --##-------------------------------------------------------------------------------##--
     --## INSRT_INSTALLMENT_FLG     
      IF  G_DOC_TYP=4 AND (NVL(G_Pst_FROM_BR,0)=0 OR NVL(G_SYS_NO,0) IN(70,185)) THEN 
         G_INSRT_INSTALLMENT_FLG := 1; 
      ELSIF  G_DOC_TYP=4 AND NVL(G_Pst_FROM_BR,0)=1 THEN 
        G_INSRT_INSTALLMENT_FLG := 2;         
      ELSE
         G_INSRT_INSTALLMENT_FLG := 0;    
      End If;
    --##-------------------------------------------------------------------------------##--
     --## CHK_AVLQTY_FLG
      IF  G_DOC_TYP=4  AND NVL(G_SYS_NO,0) =70  And nvl(V_DTS_USE_RQ_TRANSFER_AVLQTY,0)=1 THEN
         G_CHK_AVLQTY_FLG := 0 ;  
      ElsIF  G_DOC_TYP=4 AND nvl(G_DTS_ONLINE,0)=1 AND NVL(G_SYS_NO,0) =70  THEN
        G_CHK_AVLQTY_FLG := 1 ;   
      ELSIF  G_DOC_TYP=4 AND NVL(G_Pst_Typ,0)=2 AND NVL(G_SYS_NO,0) In(70,185)  THEN 
         G_CHK_AVLQTY_FLG := 1;
      ELSIF  G_DOC_TYP=4 AND NVL(G_Pst_Typ,0)=2 AND Nvl(G_Use_Out_Bills, 0) = 0  THEN
         G_CHK_AVLQTY_FLG := 1;
       ELSIF  G_DOC_TYP=4 AND NVL(G_Pst_Typ,0)=2 AND Nvl(G_Use_Out_Bills, 0) = 1 AND NVL(G_pay_avl_qty,0)=1 THEN
           G_CHK_AVLQTY_FLG := 1;     
      ELSIF  G_DOC_TYP=4 AND NVL(G_Pst_Typ,0)=2 AND Nvl(G_Use_Out_Bills, 0) = 1 AND NVL(G_USE_OUT_BILL_DIRECT,0)=1 AND NVL(G_OUT_BILL_TYP,0)=1 
         AND NVL(V_PRIV_OUT_BILL_TYP,0)=1 THEN
           G_CHK_AVLQTY_FLG := 1;    
      ELSE
          G_CHK_AVLQTY_FLG := 0;  
      End If;      
    --##-------------------------------------------------------------------------------##--
    --## INSRT_OUT_BILLS_FLG  
     IF  G_DOC_TYP IN(4,5)  AND NVL(G_SYS_NO,0) =70  And nvl(V_DTS_USE_RQ_TRANSFER_AVLQTY,0)=1 THEN
        G_INSRT_OUT_BILLS_FLG := 0; 
     ElsIF   Nvl(G_Use_Out_Bills, 0) = 0  THEN 
         G_INSRT_OUT_BILLS_FLG := 0;   
      ELSIF  G_DOC_TYP IN(4,5) AND NVL(G_Pst_Typ,0)=2 AND NVL(G_SYS_NO,0) in(70,185) AND Nvl(G_Use_Out_Bills, 0) = 1  THEN 
         G_INSRT_OUT_BILLS_FLG := 1;
      ELSIF  G_DOC_TYP=5 AND NVL(G_Pst_Typ,0)=2 AND NVL(G_SYS_NO,0)<>70 AND Nvl(G_Use_Out_Bills, 0) = 1  THEN 
         G_INSRT_OUT_BILLS_FLG := 0;          
      ELSIF  G_DOC_TYP=4 AND NVL(G_Pst_Typ,0)=2 AND Nvl(G_Use_Out_Bills, 0) = 1 AND NVL(G_USE_OUT_BILL_DIRECT,0)=1 AND NVL(G_OUT_BILL_TYP,0)=1 
           AND NVL(V_PRIV_OUT_BILL_TYP,0)=1 THEN
           G_INSRT_OUT_BILLS_FLG := 1;    
      ELSE
          G_INSRT_OUT_BILLS_FLG := 0;  
      End If;  
      
      ------------------------------
      IF Nvl(G_Use_Out_Bills, 0)=1 THEN
         IF NVL(G_INSRT_OUT_BILLS_FLG,0)=1 THEN
              G_OUT_BILL_TYP:=1;
         ELSE
          G_OUT_BILL_TYP:=2;
         END IF;       
      ELSE
          G_OUT_BILL_TYP:=1;
      END IF;         
    --##-------------------------------------------------------------------------------##--
    --## CHK_ITM_PRICE      
      If G_DOC_TYP=4 AND NVL(G_CLC_TAX_METHOD,0)=1 AND NVL(G_Pst_FROM_BR,0)=0 Then  
         G_CHK_ITM_PRICE := 1;
      ELSIF G_DOC_TYP =4 AND NVL(G_Pst_Typ,0)=2 and nvl(G_SYS_NO,0)=70 and NVL(G_DTS_ONLINE,0)=1   THEN
         G_CHK_ITM_PRICE := 1;         
      ELSE
         G_CHK_ITM_PRICE := 0;    
      End If; 
      
      If G_Doc_Typ=53 And  Nvl(G_Sys_No,0)=61 Then
      G_Chk_Itm_Price :=1 ;
      End If;        
    --##-------------------------------------------------------------------------------##--
  --####################--
  <<RTN_RSLT>>
   If P_Msg_Txt Is Not Null OR P_Err_No IS NOT NULL Then
      P_Msg_Txt   := NVL(P_Msg_Txt,'Message Number Is Missing');
      P_Err_No    := P_Err_No;
      P_Pkg_Nm    := Nvl (P_Pkg_Nm, 'Ars_Api_Trns_Pkg.GET_PRMTR_PRC');
      Return;
   Else
      P_Msg_Txt   := Null;
      P_Err_No    := Null;
      P_Pkg_Nm    := Null;
   End If;
--####################--
Exception
   When Others Then
      P_Msg_Txt   := 'Error WHEN GET_PRMTR_PRC ' || Sqlerrm;
      P_Err_No    := 20299;
      P_Pkg_Nm    := Nvl (P_Pkg_Nm, 'Ars_Api_Trns_Pkg.GET_PRMTR_PRC');     
End Get_Prmtr_Prc;
   --##-----------------------------------------------------------------------------------------------------##--
Procedure INSRT_DOC_INTO_ONYX(P_Doc_Typ          In Ias_Post_Mst.Doc_Type%Type
                            ,P_COMMIT_FLG       In     NUMBER  --## 0 ROLLBACK ,1 COMMIT ,2 ,MANUAL COMMIT
                            ,P_CLC_TAX_METHOD   In     NUMBER  --## 0 CALC TAX IN EXTRNAL ,1-AOUTO CALC TAX
                            ,P_Lng_No           In     Number Default 1
                            ,P_Xml              In Clob
                            ,P_Json_Rslt        OUT VARCHAR2  )   
Is
   V_Doc_No Sales_Order.Order_No%Type;
   V_Json_Rslt Clob := '{"_Result": { "_Doc_No":"@DOC_NO","_Doc_Ser":"@DOC_SER","_Doc_Uuid":"@DOC_UUID","_Wrnng_Txt":"@WRNNG_TXT","_ErrMsg": "@errmsg","_ErrNo": @errno ,"_Pkg_Nm":"@Pkg_Nm"} }';
   V_Xml Clob;
   P_Msg_Txt   Varchar2 (4000) := Null;
   P_Pkg_Nm    Varchar2 (4000) := Null;
   P_Err_No    Int := Null;     
Begin
   V_Xml := P_Xml;
   G_COMMIT_FLG:= P_COMMIT_FLG;  
   ARS_API_CHK_PKG.INSRT_DOC_BY_XML (  P_Doc_Typ          =>P_Doc_Typ
                      ,P_Xml              =>V_Xml
                      ,P_COMMIT_FLG       =>P_COMMIT_FLG --## 0 ROLLBACK ,1 COMMIT ,2 ,MANUAL COMMIT
                      ,P_CLC_TAX_METHOD   =>P_CLC_TAX_METHOD  --## 0 CALC TAX IN EXTRNAL ,1-AOUTO CALC TAX                                                        
                      ,P_Pst_Typ          =>2--## 1 to br tables ,2 to onyx tables
                      ,P_Pst_FROM_BR      =>0
                      ,P_DTS_ONLINE       =>0
                      ,P_Lng_No           =>P_Lng_No                         
                      ,P_Msg_Txt          =>P_Msg_Txt
                      ,P_ERR_NO           =>P_Err_No
                      ,P_Pkg_Nm           =>P_Pkg_Nm);

   If P_Msg_Txt Is Not Null Then
      IF NVL(To_Number(P_Err_No),0)=20999 THEN
        V_Json_Rslt := Replace( V_Json_Rslt, '@DOC_NO',G_DOC_NO );
        V_Json_Rslt := Replace( V_Json_Rslt, '@DOC_SER', G_DOC_SER);
      ELSE
        V_Json_Rslt := Replace( V_Json_Rslt, '@DOC_NO', Null);
        V_Json_Rslt := Replace( V_Json_Rslt, '@DOC_SER', Null);
      END IF;     
      V_Json_Rslt := Replace( V_Json_Rslt, '@errno', To_Number( P_Err_No));
      V_Json_Rslt := Replace( V_Json_Rslt, '@errmsg',Replace( P_Msg_Txt,'"',' '));
      V_Json_Rslt := Replace( V_Json_Rslt, '@Pkg_Nm', P_Pkg_Nm);     
   Else
      IF NVL(P_COMMIT_FLG,0)=1 THEN
        V_Json_Rslt := Replace( V_Json_Rslt, '@DOC_NO',G_DOC_NO );
        V_Json_Rslt := Replace( V_Json_Rslt, '@DOC_SER', G_DOC_SER);
        V_Json_Rslt := Replace( V_Json_Rslt, '@DOC_UUID', G_DOC_UUID);
        V_Json_Rslt := Replace( V_Json_Rslt, '@WRNNG_TXT', G_WRNNG_TXT);
        V_Json_Rslt := Replace( V_Json_Rslt, '@errno', 0);
        V_Json_Rslt := Replace( V_Json_Rslt, '@errmsg', 'The operation accomplished successfully.');
        V_Json_Rslt := Replace( V_Json_Rslt, '@Pkg_Nm', Null);
      ELSE 
      
        IF V_Xml IS NOT NULL THEN
           V_Json_Rslt:=V_Xml;
        ELSE   
           V_Json_Rslt := Replace( V_Json_Rslt, '@DOC_NO',G_DOC_NO );
           V_Json_Rslt := Replace( V_Json_Rslt, '@DOC_SER', G_DOC_SER);
           V_Json_Rslt := Replace( V_Json_Rslt, '@DOC_UUID', G_DOC_UUID);
           V_Json_Rslt := Replace( V_Json_Rslt, '@WRNNG_TXT', G_WRNNG_TXT);
           V_Json_Rslt := Replace( V_Json_Rslt, '@errno', 0);
           V_Json_Rslt := Replace( V_Json_Rslt, '@errmsg', 'The operation accomplished successfully.');
           V_Json_Rslt := Replace( V_Json_Rslt, '@Pkg_Nm', Null);
        END IF;
          
      END IF;   
          
   End If;
    P_Json_Rslt:= V_Json_Rslt;
 Exception When Others Then
         Raise_Application_Error (-20300, 'Err IN INSRT_DOC_INTO_ONYX' || Chr (10) || Sqlerrm);      
End INSRT_DOC_INTO_ONYX;
 --##-----------------------------------------------------------------------------------------------------##--
 Procedure INSRT_DOC_INTO_BR( P_Doc_Typ          In Ias_Post_Mst.Doc_Type%Type
                             ,P_COMMIT_FLG       In     NUMBER  --## 0 ROLLBACK ,1 COMMIT ,2 ,MANUAL COMMIT
                             ,P_CLC_TAX_METHOD   In     NUMBER  --## 0 CALC TAX IN EXTRNAL ,1-AOUTO CALC TAX
                             ,P_DTS_ONLINE       In     NUMBER DEFAULT 0 --## 0 OFFLINE ,1-ONLINE
                             ,P_Lng_No           In     Number Default 1
                             ,P_Xml              In Clob
                             ,P_Json_Rslt        OUT VARCHAR2  ) 
Is
   V_Doc_No Sales_Order.Order_No%Type;
   V_Json_Rslt Clob := '{"_Result": { "_Doc_No":"@DOC_NO","_Doc_Ser":"@DOC_SER","_Doc_Uuid":"@DOC_UUID","_Wrnng_Txt":"@WRNNG_TXT","_ErrMsg": "@errmsg","_ErrNo": @errno ,"_Pkg_Nm":"@Pkg_Nm"} }';
   V_Xml Clob;
   P_Msg_Txt   Varchar2 (4000) := Null;
   P_Pkg_Nm    Varchar2 (4000) := Null;
   P_Err_No    Int := Null;     
Begin
   V_Xml := P_Xml;
   G_COMMIT_FLG:= P_COMMIT_FLG;
   ARS_API_CHK_PKG.INSRT_DOC_BY_XML (  P_Doc_Typ          =>P_Doc_Typ
                      ,P_Xml              =>V_Xml
                      ,P_COMMIT_FLG       =>P_COMMIT_FLG --## 0 ROLLBACK ,1 COMMIT ,2 ,MANUAL COMMIT
                      ,P_CLC_TAX_METHOD   =>P_CLC_TAX_METHOD  --## 0 CALC TAX IN EXTRNAL ,1-AOUTO CALC TAX                                                        
                      ,P_Pst_Typ          =>1--## 1 to br tables ,2 to onyx tables
                      ,P_Pst_FROM_BR      =>0
                      ,P_DTS_ONLINE       =>P_DTS_ONLINE
                      ,P_Lng_No           =>P_Lng_No                         
                      ,P_Msg_Txt          =>P_Msg_Txt
                      ,P_ERR_NO           =>P_Err_No
                      ,P_Pkg_Nm           =>P_Pkg_Nm);

   If P_Msg_Txt Is Not Null Then
      IF NVL(To_Number(P_Err_No),0)=20999 THEN
        V_Json_Rslt := Replace( V_Json_Rslt, '@DOC_NO',G_DOC_NO );
        V_Json_Rslt := Replace( V_Json_Rslt, '@DOC_SER', G_DOC_SER);
      ELSE
        V_Json_Rslt := Replace( V_Json_Rslt, '@DOC_NO', Null);
        V_Json_Rslt := Replace( V_Json_Rslt, '@DOC_SER', Null);
      END IF;
      P_Pkg_Nm:=P_Pkg_Nm||chr(10)||'Error_No='||P_Err_No||chr(10)||'Pst_typ='||g_pst_typ;
       V_Json_Rslt := Replace( V_Json_Rslt, '@errno', To_Number( P_Err_No));
       V_Json_Rslt := Replace( V_Json_Rslt, '@errmsg',Replace( P_Msg_Txt,'"',' '));
      V_Json_Rslt := Replace( V_Json_Rslt, '@Pkg_Nm', P_Pkg_Nm);     
   Else
      IF NVL(P_COMMIT_FLG,0)=1 THEN
        V_Json_Rslt := Replace( V_Json_Rslt, '@DOC_NO',G_DOC_NO );
        V_Json_Rslt := Replace( V_Json_Rslt, '@DOC_SER', G_DOC_SER);
        V_Json_Rslt := Replace( V_Json_Rslt, '@DOC_UUID', G_DOC_UUID);
        V_Json_Rslt := Replace( V_Json_Rslt, '@WRNNG_TXT', G_WRNNG_TXT);
        V_Json_Rslt := Replace( V_Json_Rslt, '@errno', 0);
        V_Json_Rslt := Replace( V_Json_Rslt, '@errmsg', 'The operation accomplished successfully.');
        V_Json_Rslt := Replace( V_Json_Rslt, '@Pkg_Nm', Null);
      ELSE 
      
        IF V_Xml IS NOT NULL THEN
           V_Json_Rslt:=V_Xml;
        ELSE   
            V_Json_Rslt := Replace( V_Json_Rslt, '@DOC_NO', G_DOC_NO);
            V_Json_Rslt := Replace( V_Json_Rslt, '@DOC_SER',G_DOC_SER);
            V_Json_Rslt := Replace( V_Json_Rslt, '@DOC_UUID', G_DOC_UUID);
            V_Json_Rslt := Replace( V_Json_Rslt, '@WRNNG_TXT', G_WRNNG_TXT);
           V_Json_Rslt := Replace( V_Json_Rslt, '@errno', 0);
           V_Json_Rslt := Replace( V_Json_Rslt, '@errmsg', 'The operation accomplished successfully.');
           V_Json_Rslt := Replace( V_Json_Rslt, '@Pkg_Nm', Null);
        END IF;
          
      END IF;   
          
   End If;
    P_Json_Rslt:= V_Json_Rslt;
Exception When Others Then
       Raise_Application_Error (-20301, 'Err IN INSRT_DOC_INTO_BR' || Chr (10) || Sqlerrm);          
End INSRT_DOC_INTO_BR;
 --##-----------------------------------------------------------------------------------------------------##--
   Procedure Post_From_Br_Prc (P_Sys_No     In     Number
                              ,P_Doc_Typ    In     Ias_Post_Mst.Doc_Type%Type
                              ,P_Doc_Ser    In  Ias_Post_Mst.Doc_Ser%Type
                              ,P_Lng_No     In     Number Default 1                              
                              ,P_Msg_Txt    Out Varchar2
                              ,P_ERR_NO   Out Varchar2
                              ,P_Pkg_Nm     Out Varchar2)
   Is
      V_Doc_No     Number;     
      V_DOC_SEQ    NUMBER;
      V_Sys_No    NUMBER:=P_Sys_No;
      V_rcrd_no    Number;
      V_CNT        NUMBER:=0;
   Begin
      If P_Doc_Typ Is Null Then
         P_Err_No := 20027;
         P_Msg_Txt := 'DOC_TYPE IS NULL ';
         Goto Rtn_Rslt;
      End If;
      
      If V_Sys_No Is Null Then
         P_Err_No := 20535;
         P_Msg_Txt := 'P_Sys_No IS NULL ';
         Goto Rtn_Rslt;
      End If;

      If P_Doc_Typ Not In (4, 5) Then
         P_Err_No := 20029;
         P_Msg_Txt := 'DOC_TYPE=' || P_Doc_Typ || ' This Doc_Typ Is Not Idientified ';
         Goto Rtn_Rslt;
      End If;
      
                       

      If P_Doc_Typ = 4 Then
      
         BEGIN
           Select 1 INTO V_CNT
                  From Ias_Bill_Mst_Br
                    Where Bill_Ser = P_Doc_Ser
                    AND ROWNUM<=1;
         EXCEPTION WHEN OTHERS THEN
         V_CNT:=0;
         END;
          
         IF NVL(V_CNT,0)=0 THEN
            P_Err_No := 20525;
            P_Msg_Txt :=  Ias_Gen_Pkg.Get_Msg (P_Lng_No => P_Lng_No, P_Msg_No => 297)||CHR(10)||'BILL_SER='||P_Doc_Ser;
            Goto Rtn_Rslt;
         END IF;
                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     -- BILL SALES
         For M_Cv In (Select *
                        From Ias_Bill_Mst_Br
                       Where Bill_Ser = P_Doc_Ser
                       and nvl(bill_post,0)=0
                       and nvl(cncl_flg,0)=0)
         Loop                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    --(11)
            --------------------------------------------------------------------------------
            If M_Cv.BILL_No Is Null Then
               P_Err_No := 20030;
               P_Msg_Txt := 'Error App DOC_NO IS NULL ';
               Goto Rtn_Rslt;
            End If;
            ---------------------------------------------------------------------------------
            Begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 --(1)
               Insrt_Ias_Bill_Mst (P_Sys_No                       => V_Sys_No
                                  ,P_Doc_Type                     => 4
                                  ,P_Bill_Doc_Type                => M_Cv.Bill_Doc_Type
                                  ,P_Doc_No                       => M_Cv.BILL_No
                                  ,P_Doc_Ser                      => M_Cv.BILL_SER
                                  ,P_Doc_Date                     => To_Date (To_Char (M_Cv.BILL_Date), 'DD/MM/RRRR')
                                  ,P_Cur_Code                     => M_Cv.BILL_CURRENCY
                                  ,P_Cur_Rate                     => M_Cv.BILL_Rate
                                  ,P_Stock_Rate                   => M_Cv.Stock_Rate
                                  ,P_C_Code                       => M_Cv.C_Code
                                  ,P_C_Name                       => M_Cv.C_Name
                                  ,P_A_Code                       => M_Cv.A_Code
                                  ,P_Cheque_No                    => M_Cv.Cheque_No
                                  ,P_Note_No                      => M_Cv.Note_No
                                  ,P_Cheque_Due_Date              => M_Cv.Cheque_Due_Date
                                  ,P_Bill_Due_Date                => M_Cv.Bill_Due_Date
                                  ,P_W_Code                       => M_Cv.W_Code
                                  ,P_R_Code                       => M_Cv.R_Code
                                  ,P_Rep_Code                     => M_Cv.Rep_Code
                                  ,P_Emp_No                       => M_Cv.Emp_No
                                  ,P_Ref_No                       => M_Cv.Ref_No
                                  ,P_Cash_No                      => M_Cv.Cash_No
                                  ,P_Cc_Code                      => M_Cv.Cc_Code
                                  ,P_Pj_No                        => M_Cv.Pj_No
                                  ,P_Actv_No                      => M_Cv.Actv_No
                                  ,P_Si_Type                      => M_Cv.Si_Type
                                  ,P_Stand_By                     => M_Cv.Stand_By
                                  ,P_Col_No                       => M_Cv.Col_No
                                  ,P_Cash_Ac_Fcc                  => M_Cv.Cash_Ac_Fcc
                                  ,P_Bank_No                      => M_Cv.Cash_No_Fcc
                                  ,P_A_Desc                       => M_Cv.A_Desc
                                  ,P_Bill_Py                      => M_Cv.Bill_Py
                                  ,P_External_Post                => M_Cv.External_Post
                                  ,P_Field1                       => M_Cv.Field1
                                  ,P_Field2                       => M_Cv.Field2
                                  ,P_Field3                       => M_Cv.Field3
                                  ,P_Field4                       => M_Cv.Field4
                                  ,P_Field5                       => M_Cv.Field5
                                  ,P_Field6                       => M_Cv.Field6
