            Exception
               When Others Then
                 P_Err_No := 20512;
                 P_Msg_Txt := 'Err when insert IAS_BILL_MST DOC_NO= ' || M_Cv.BILL_No || ' ' || Chr (10) || Sqlerrm;
                 Goto Rtn_Rslt;                 
            End;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  --(1)
            -------------------------------------------------------------------------------------------
            For D_Cv In (Select D.*,
                             (select  Listagg (SERIALNO, ',')Within Group (Order By RCRD_NO)              
                                from IAS_ITEM_SERIALNO_BR
                                WHERE  DOC_SER=D.BILL_SER
                                   AND I_CODE=D.I_CODE
                                   AND W_CODE=D.W_CODE
                                   AND RCRD_NO_DOC=D.RCRD_NO) SERIALNO_N
                           From Ias_Bill_Dtl_Br D
                          Where Bill_Ser = M_Cv.BILL_SER
                           ORDER BY D.BILL_NO,D.RCRD_NO)
            Loop                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 --(12)
               ---------------------
                V_DOC_SEQ:=NULL;
                V_Rcrd_No :=null;
               Begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              --(2)
                  Insrt_Ias_Bill_Dtl (P_I_Code                   => D_Cv.I_Code
