                                     ,P_Actv_No                  => nvl(D_Cv.Actv_No,G_Mst_Actv_No)
                                     ,P_Expire_Date              => To_Date (To_Char (D_Cv.Expire_Date), 'DD/MM/RRRR')
                                     ,P_Batch_No                 => D_Cv.Batch_No
                                     ,P_Free_Qty                 => D_Cv.Free_Qty
