                                     ,P_Dis_Amt_Dtl_Qt_Prm_Vat   => D_Cv.Dis_Amt_Dtl_Qt_Prm_Vat
                                     ,P_Dis_Per_Qt_Prm           => D_Cv.Dis_Per_Qt_Prm
                                     ,P_Dis_Amt_Dtl3_Vat         => D_Cv.Dis_Amt_Dtl3_Vat
