                                                  AND RCRD_NO=D_CV.RCRD_NO)                                 
                                                                 
                      Loop                     
                          Begin
                             Insrt_Gnr_Tax_Itm_Movmnt(P_Doc_Typ               => 5
                                                     ,P_Bill_Doc_Type          => Tax_Mvmnt_Cv.Bill_Doc_Type
                                                     ,P_Doc_Jv_Type            => Tax_Mvmnt_Cv.Doc_Jv_Type
                                                     ,P_Tax_No                 => Tax_Mvmnt_Cv.Tax_No
                                                     ,P_Clc_Typ_No             => Tax_Mvmnt_Cv.Clc_Typ_No
                                                     ,P_Agncy_No               => Tax_Mvmnt_Cv.Agncy_No
                                                     ,P_I_Code                 => Tax_Mvmnt_Cv.I_Code
                                                     ,P_Itm_Unt                => Tax_Mvmnt_Cv.Itm_Unt
                                                     ,P_P_Size                 => Tax_Mvmnt_Cv.P_Size
                                                     ,P_I_Price                => Tax_Mvmnt_Cv.I_Price
                                                     ,P_Disc_Amt               => Tax_Mvmnt_Cv.Disc_Amt
                                                     ,P_A_Code                 => Tax_Mvmnt_Cv.A_Code
                                                     ,P_Cur_Code               => Tax_Mvmnt_Cv.A_Cy
                                                     ,P_Ac_Rate                => Tax_Mvmnt_Cv.Ac_Rate
                                                     ,P_Tax_Prcnt              => Tax_Mvmnt_Cv.Tax_Prcnt
                                                     ,P_Tax_Amt                => Tax_Mvmnt_Cv.Tax_Amt
                                                     ,P_W_Code                 => Tax_Mvmnt_Cv.W_Code
                                                     ,P_Cc_Code                => G_Dtl_Cc_Code
                                                     ,P_Pj_No                  => G_Dtl_Pj_No
                                                     ,P_Actv_No                => G_Dtl_Actv_No                                                     
                                                     ,P_Doc_Sequence           => V_Doc_Seq
                                                     ,P_Rcrd_No                => V_Rcrd_No
                                                     ,P_Tax_Amt_L              => Tax_Mvmnt_Cv.Tax_Amt_L
                                                     ,P_I_Qty                  => Tax_Mvmnt_Cv.I_Qty
                                                     ,P_Free_Qty               => Tax_Mvmnt_Cv.Free_Qty
                                                     ,P_Ref_No                 => Tax_Mvmnt_Cv.Ref_No
                                                     ,P_Stk_Cost               => Tax_Mvmnt_Cv.Stk_Cost
                                                     ,P_Stk_Rate               => Tax_Mvmnt_Cv.Stk_Rate
                                                     ,P_Clc_Tax_Free_Qty_Flg   => Tax_Mvmnt_Cv.Clc_Tax_Free_Qty_Flg
                                                     ,P_Msg_Txt                => P_Msg_Txt
                                                     ,P_ERR_NO                 => P_Err_No
                                                     ,P_Pkg_Nm                 => P_Pkg_Nm);

                             If P_Msg_Txt Is Not Null Then
                                Goto Rtn_Rslt;
                             End If;
                            
                    Exception
                     When Others Then
                       P_Err_No := 20521;
                       P_Msg_Txt := 'ERR WHEN INSERT INSRT_GNR_TAX_ITM_MOVMNT DOC_NO= ' || M_Cv.RT_BILL_No || ' ' || Chr (10) || Sqlerrm;
                       Goto Rtn_Rslt;                        
                    End;                 
                  End Loop; 
                  ------------------------------- INSERT Other_Charges_Items---------------------------------------------------
                  For Othr_Chrg_Itm_Cv In (Select *
                                              FROM Other_Charges_Items_BR
                                                  WHERE  BILL_SER=M_CV.RT_BILL_SER
                                                      AND I_CODE=D_CV.I_CODE
                                                      AND RCRD_NO=D_CV.RCRD_NO )
                       Loop
                          Begin
                             Insrt_Other_Charges_Items(P_Doc_Typ     => 5
                                                      ,P_Sc_No       => Othr_Chrg_Itm_Cv.Sc_No
                                                      ,P_A_Code      => Othr_Chrg_Itm_Cv.A_Code
                                                      ,P_Cur_Code    => Othr_Chrg_Itm_Cv.A_Cy
                                                      ,P_Ac_Rate     => Othr_Chrg_Itm_Cv.Ac_Rate
                                                      ,P_Per         => Othr_Chrg_Itm_Cv.Per
                                                      ,P_Amt         => Othr_Chrg_Itm_Cv.Amt
                                                      ,P_W_Code      => Othr_Chrg_Itm_Cv.W_Code
                                                      ,P_Cc_Code     => G_Dtl_Cc_Code
                                                      ,P_Pj_No       => G_Dtl_Pj_No
                                                      ,P_Actv_No     => G_Dtl_Actv_No 
                                                      ,P_Rcrd_No     => Othr_Chrg_Itm_Cv.Rcrd_No
                                                      ,P_Si_Type     => Othr_Chrg_Itm_Cv.Si_Type
                                                      ,P_I_Code      => Othr_Chrg_Itm_Cv.I_Code
                                                      ,P_Itm_Unt     => Othr_Chrg_Itm_Cv.Itm_Unt
                                                      ,P_P_Size      => Othr_Chrg_Itm_Cv.P_Size
                                                      ,P_Bill_Py     => Othr_Chrg_Itm_Cv.Bill_Py
                                                      ,P_Unit_Amt    => Othr_Chrg_Itm_Cv.Unit_Amt
                                                      ,P_Post_Code   => Othr_Chrg_Itm_Cv.Post_Code
                                                      ,P_Msg_Txt     => P_Msg_Txt
                                                      ,P_ERR_NO    => P_Err_No
                                                      ,P_Pkg_Nm      => P_Pkg_Nm);

                             If P_Msg_Txt Is Not Null Then
                                Goto Rtn_Rslt;
                             End If;
                          Exception
                             When Others Then
                                P_Err_No := 20522;
                                 P_Msg_Txt := 'Err when insert OTHER_CHARGES_ITEMS RT_BILL_No= ' || M_Cv.RT_BILL_No || ' ' || Chr (10) || Sqlerrm;
                                 Goto Rtn_Rslt;                                
                          End;
                       End Loop; 
             -------------------------------------------------------------------------------------------------------------------------------------------
               Exception
                  When Others Then
                     P_Err_No :=  20524;
                     P_Msg_Txt := 'Err when insert IAS_RT_BILL_DTL RT_BILL_NO= ' || M_CV.RT_BILL_NO || ' ' || Chr (10) || Sqlerrm;
                     Goto Rtn_Rslt;
               End;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               --(2)
            --##------------------------------------------------------------------------------------------------------------------------------##--
            End Loop;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
            --------------------------------INSERT OTHER CHARGE-------------------------------------------------------------------------------------------------------------            
              For Othr_Chrg_Cv In ( Select *
                                        FROM Other_Charges_BR
                                             WHERE  BILL_SER=M_CV.RT_BILL_SER)
               Loop
                  Begin
                     Insrt_Other_Charges(P_Doc_Typ      => 5
                                        ,P_Bill_Doc_Type  => M_Cv.RT_Bill_Doc_Type
                                        ,P_BILL_TYPE      =>3
                                        ,P_Sc_No        => Othr_Chrg_Cv.Sc_No
                                        ,P_A_Code       => Othr_Chrg_Cv.A_Code
                                        ,P_Cur_Code     => Othr_Chrg_Cv.A_Cy
                                        ,P_Ac_Rate      => Othr_Chrg_Cv.Ac_Rate
                                        ,P_Per          => Othr_Chrg_Cv.Per
                                        ,P_Amt          => Othr_Chrg_Cv.Amt
                                        ,P_Inv_Item     => Othr_Chrg_Cv.Inv_Item
                                        ,P_Rcrd_No      => Othr_Chrg_Cv.Rcrd_No
                                        ,P_Bill_Py      => Othr_Chrg_Cv.Bill_Py
                                        ,P_Vat_Amt      => Othr_Chrg_Cv.Vat_Amt
                                        ,P_Vat_Per      => Othr_Chrg_Cv.Vat_Per
                                        ,P_Sc_Amt       => Othr_Chrg_Cv.Sc_Amt
                                        ,P_Sc_Ac_Rate   => Othr_Chrg_Cv.Sc_Ac_Rate
                                        ,P_Sc_A_Cy      => Othr_Chrg_Cv.Sc_A_Cy
                                        ,P_Msg_Txt      => P_Msg_Txt
                                        ,P_ERR_NO        => P_Err_No
                                        ,P_Pkg_Nm       => P_Pkg_Nm);

                     If P_Msg_Txt Is Not Null Then
                        Goto Rtn_Rslt;
                     End If;
                  Exception
                     When Others Then
                        P_Err_No := 20523;
                        P_Msg_Txt := 'Err when insert OTHER_CHARGES BILL_NO= ' || M_Cv.RT_BILL_No || ' ' || Chr (10) || Sqlerrm;
                         Goto Rtn_Rslt;                      
                  End;
               END LOOP;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     --(12)

            -----------------------------------------------------------------------------------------------------------------------------
             For Tax_INPT_Mvmnt_Cv In (SELECT  * FROM GNR_TAX_INPT_MOVMNT_BR
                                             WHERE INPT_TYP=1 AND  DOC_SER=M_CV.RT_BILL_SER     )                              
               Loop                    
                    Begin
                          INSRT_GNR_TAX_INPT_MOVMNT(
                                            P_DOC_TYP                    =>G_DOC_TYP
                                           ,P_BILL_DOC_TYPE              =>M_CV.RT_BILL_DOC_TYPE
                                           ,P_DOC_JV_TYPE                =>Tax_INPT_Mvmnt_Cv.DOC_JV_TYPE                                       
                                           ,P_TAX_NO                     =>Tax_INPT_Mvmnt_Cv.TAX_NO
                                          , P_CLC_TYP_NO                 =>Tax_INPT_Mvmnt_Cv.CLC_TYP_NO 
                                          , P_AGNCY_NO                   =>Tax_INPT_Mvmnt_Cv.AGNCY_NO                            
                                          , P_INPT_CODE                  =>Tax_INPT_Mvmnt_Cv.INPT_CODE 
                                           ,P_A_CODE                     =>Tax_INPT_Mvmnt_Cv.A_CODE 
                                          , P_A_CY                       =>Tax_INPT_Mvmnt_Cv.A_CY
                                          , P_AC_RATE                    =>Tax_INPT_Mvmnt_Cv.AC_RATE 
                                          , P_INPT_AMT                   =>Tax_INPT_Mvmnt_Cv.INPT_AMT 
                                          , P_TAX_PRCNT                  =>Tax_INPT_Mvmnt_Cv.TAX_PRCNT 
                                          , P_TAX_AMT                    =>Tax_INPT_Mvmnt_Cv.TAX_AMT
                                          , P_TAX_AMT_L                  =>Tax_INPT_Mvmnt_Cv.TAX_AMT_L 
                                          , P_Cc_Code                    =>G_Mst_Cc_Code
                                          , P_Pj_No                      =>G_Mst_Pj_No
                                          , P_Actv_No                    =>G_Mst_Actv_No  
                                          , P_REF_NO                     =>Tax_INPT_Mvmnt_Cv.REF_NO 
                                          , P_RCRD_NO                    =>Tax_INPT_Mvmnt_Cv.RCRD_NO 
                                          , P_DOC_SEQUENCE               =>Tax_INPT_Mvmnt_Cv.DOC_SEQUENCE
                                          ,P_Msg_Txt                     =>P_Msg_Txt
                                          ,P_ERR_NO                     =>P_ERR_NO
                                          ,P_Pkg_NM                     =>P_Pkg_NM); 

                             If P_Msg_Txt Is Not Null Then
                                Goto Rtn_Rslt;
                             End If;
                            
                    Exception
                     When Others Then
                       -- ---Rollback;
                        Raise_Application_Error( -20549, 'ERR WHEN INSERT INSRT_GNR_TAX_INPT_MOVMNT DOC_NO= ' || M_CV.RT_BILL_NO || ' ' || Chr( 10) || Sqlerrm);
                    End;                 
               End Loop;
               --##----------------------------------------------------------------------------##--
            --## CHK INSERT DATA
            Chk_Insrt_Data (P_Doc_Typ    => 5
                           ,P_Doc_Ser    => G_Doc_Ser
                           ,P_Msg_Txt    => P_Msg_Txt
                            ,P_ERR_NO   => P_Err_No
                            ,P_Pkg_NM   => P_Pkg_Nm);

            If P_Msg_Txt Is Not Null Then            
               ---Rollback;
               Goto Rtn_Rslt;
            End If;           
            Begin
               Update Ias_Rt_Bill_Mst_Br
                  Set Rt_Bill_Post = 1
                Where Rt_Bill_Ser = G_Doc_Ser;
            Exception
               When Others Then
                     P_Err_No :=  20524;
                     P_Msg_Txt := 'Err when UPDATE IAS_BILL_MST_BR  RT_BILL_NO= ' || M_CV.RT_BILL_NO || ' ' || Chr (10) || Sqlerrm;
                     Goto Rtn_Rslt;                 
            End;          
         ----------------------------------------------------------------------------------------------------------
         End Loop;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               --(11)
      End If;

     --####################--
     <<RTN_RSLT>>
      --####################--    
      If P_Msg_Txt Is Not Null OR P_Err_No IS NOT NULL Then
         P_Msg_Txt := NVL(P_Msg_Txt,'Message Number Is Missing')||Chr(10)||'DOC_SER='||G_DOC_SER ;
         P_ERR_NO := P_Err_No;
         P_Pkg_NM := NVL(P_Pkg_Nm,'Ars_Api_Trns_Pkg.Post_From_Br_Prc');
       ELSE
         P_Msg_Txt  := NULL ;
         P_ERR_NO := NULL;
         P_Pkg_NM   := NULL;
       END IF;    
   --####################--

   Exception
      When Others Then
         Raise_Application_Error (-20324, 'Err IN Post_From_Br_Prc' || Chr (10) || Sqlerrm);
   --RETURN SQLERRM;
   End Post_From_Br_Prc;

   --##----------------------------------------------------------------------------------------------------------------------##--
  Procedure Insrt_Sales_Order (P_Sys_No            In     Number
                            ,P_Doc_Type            In     Number
                            ,P_Doc_No              In     Sales_Order.Order_No%Type Default Null
                            ,P_Doc_Ser             In     Sales_Order.Order_Ser%Type Default Null
                            ,P_Doc_Date            In     Sales_Order.Order_Date%Type Default Null
                            ,P_Cur_Code            In     Sales_Order.Order_Cur%Type Default Null
                            ,P_Cur_Rate            In     Sales_Order.Cur_Rate%Type Default Null
