                    --2    Refuse
                    --3    In Progress
                    --4    Used In Invoice
         Begin
           Select Decode(Nvl(Procesed,0),1,4,Nvl(Approved,0)) Into V_Stat
                              From Sales_Order
                                Where Order_No=P_Doc_No And Order_Ser=P_Doc_Ser;
         Exception When Others Then
            V_Stat :=0;
         End;          

         If Nvl(V_Stat,0)=1 Then 
             P_Err_No := $$Plsql_Line;
             P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 4480);
              Goto Rtn_Rslt;
         Elsif Nvl(V_Stat,0)=3 Then 
             P_Err_No := $$Plsql_Line;
             P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 2213);
              Goto Rtn_Rslt;              
