    End If;
   --##-----------------------------------------------------------------------------------------##--
   If G_W_Code Is Not Null And YS_SYS_GEN_PKG.CHK_ACTV_SYSTEM (P_SYS_NO => 70 , P_Brn_Usr => G_Brn_Usr)=1 and nvl(G_SYS_NO,0)<>70 Then
         Begin
           Select 1 Into V_cnt from sales_man
                where w_code=G_w_code
                 and RowNum<=1;
        Exception when Others Then 
              V_cnt:=0;
        End; 
                                                 
        If Nvl(V_cnt,0)>0 Then
                 P_Err_No    := 20674;
                 P_MSG_TXT := IAS_GEN_PKG.GET_MSG (P_Lng_No, 5145);
                Goto Rtn_Rslt;                                                      
        End If;             
   End If;
  --##-----------------------------------------------------------------------------------------##--
   If  Nvl(G_SYS_NO,0)=70 And NVL(G_DTS_ONLINE,0)=1 And G_Rep_Code Is Not Null THEN
      Begin
        Select Nvl(USE_RES_IN_SO_APP,0),Nvl(SO_RES_PRD,0)
        Into G_DTS_USE_RES_IN_SO_APP,G_DTS_SO_RES_PRD
        From Sales_Man
        Where REPRS_CODE=G_Rep_Code
          And RowNum<=1;
      Exception when Others Then 
        G_DTS_USE_RES_IN_SO_APP:=0;
        G_DTS_SO_RES_PRD:=0;            
      End;
      
   Else   
     G_DTS_USE_RES_IN_SO_APP:=0;         
     G_DTS_SO_RES_PRD:=0;
   End if;        
   --##-----------------------------------------------------------------------------------------##--  
   Insert Into Sales_Order (Order_No
                           ,Order_Ser
                           ,Order_Date
                           ,Order_Cur
                           ,Cur_Rate
                           ,Stock_Rate
                           ,So_Type
                           ,C_Code
                           ,C_Name
                           ,A_Desc
                           ,Cc_Code
                           ,Pj_No
                           ,Actv_No
                           ,W_Code
                           ,Rep_Code
                           ,Emp_No
                           ,Vat_Amt
                           ,Order_Amt
                           ,Disc_Amt
                           ,Disc_Amt_Dtl
                           ,Disc_Amt_Mst
                           ,Othr_Amt
                           ,Vat_Amt_Othr
                           ,Othr_Amt_Disc
                           ,Disc_Amt_Mst_Vat
                           ,Vat_Amt_Disc_Mst
                           ,Disc_Amt_Aftr_Vat
                           ,Cash_No
                           ,Clc_Typ_No_Tax
                           ,Clc_Vat_Price_Typ
                           ,Ref_Doc_No
                           ,Ref_Doc_Date
                           ,Prepare_Date
                           ,Rec_Dealer_Date
                           ,Delivery_Date
                           ,R_Code
                           ,Driver_No
                           ,Bill_Doc_Type
                           ,Bill_Due_Date
                           ,Order_Expire_Date
                           ,Cheque_Due_Date
                           ,C_Code_Csh
                           ,C_Address
                           ,C_Mobile
                           ,Latitude
                           ,Longitude
                           ,Si_Type
                           ,External_Post
                           ,Field1
                           ,Field2
                           ,Field3
                           ,Field4
                           ,Field5
                           ,Field6
                           ,Field7
                           ,Field8
                           ,Field9
                           ,Field10
                           ,Procesed
                           ,Stand_By
                           ,Approved
                           ,CLC_TAX_FREE_QTY_FLG
                           ,ORDR_STAT_TYP
                           ,Doc_Ser_Extrnl
                           ,C_Tax_Code
                           ,Qt_Prm_No                                        
                           ,QT_PRM_RCRD_NO     
                           ,QT_PRM_SER 
                           ,Rcpnt_Cmpny     
                           ,Rcpnt_Name      
                           ,Rcpnt_Email     
                           ,Rcpnt_Addrees   
                           ,Rcpnt_City      
                           ,Rcpnt_Post_Code 
                           ,Rcpnt_State     
                           ,Rcpnt_Cntry     
                           ,Rcpnt_Cntry_Code   
                           ,SHO_SYS_TYP                         
                           ,Cmp_No
                           ,Brn_No
                           ,Brn_Year
                           ,Brn_Usr
                           ,Ad_Trmnl_Nm
                           ,Ad_U_Id
                           ,Ad_Date)
        Values (G_Doc_No
               ,G_Doc_Ser
               ,G_Doc_Date
               ,P_Cur_Code
               ,G_Cur_Rate
               ,G_Stk_Rate
               ,G_So_Type
               ,G_C_Code
               ,V_Cst_Nm
               ,V_Doc_Dsc
               ,Decode (G_Ar_Cst_Type, 1, G_Cc_Code, Null)
               ,Decode (G_Ar_Pj_Type, 1, G_Pj_No, Null)
               ,Decode (G_Ar_Actv_Type, 1, G_Actv_No, Null)
               ,Decode (G_Ar_Wc_Type, 1, G_W_Code, Null)
               ,G_Rep_Code
               ,P_Emp_No
               ,P_Vat_Amt
               ,Round (Nvl (P_Order_Amt, 0), G_No_Of_Decimal_Ar)
               ,P_Disc_Amt
               ,P_Disc_Amt_Dtl
               ,P_Disc_Amt_Mst
               ,P_Othr_Amt
               ,P_Vat_Amt_Othr
               ,P_Othr_Amt_Disc
               ,P_Disc_Amt_Mst_Vat
               ,P_Vat_Amt_Disc_Mst
               ,P_Disc_Amt_Aftr_Vat
               ,Nvl(G_Cash_No,G_Bank_No)
               ,G_Clc_Typ_No_Tax
               ,nvl(G_Clc_Vat_Price_Typ,1)
               ,P_Ref_Doc_No
               ,P_Ref_Doc_Date
               ,P_Prepare_Date
               ,P_Rec_Dealer_Date
               ,P_Delivery_Date
               ,V_R_Code
               ,DECODE(NVL(P_Driver_No,0), 0, NULL,P_Driver_No) 
               ,G_Bill_Doc_Type
               ,V_Doc_Due_Date
               ,V_Ordr_Exp_Date
               ,P_Cheque_Due_Date
               ,P_C_Code_Csh
               ,P_C_Address
               ,P_C_Mobile
               ,P_Latitude
               ,P_Longitude
               ,P_Si_Type
               ,G_External_Post
               ,P_Field1
               ,P_Field2
               ,P_Field3
               ,P_Field4
               ,P_Field5
               ,P_Field6
               ,P_Field7
               ,P_Field8
               ,P_Field9
               ,P_Field10
               ,0
               ,P_Stand_By  
               ,0
               ,NVL(G_CLC_TAX_FREE_QTY_FLG,0)
               ,1
               ,P_Doc_Ser_Extrnl
               ,V_Tax_Code
               ,P_Qt_Prm_No                                        
               ,P_QT_PRM_RCRD_NO     
               ,P_QT_PRM_SER 
               ,P_Rcpnt_Cmpny      
               ,P_Rcpnt_Name       
               ,P_Rcpnt_Email      
               ,P_Rcpnt_Addrees    
               ,P_Rcpnt_City       
               ,P_Rcpnt_Post_Code  
               ,P_Rcpnt_State      
               ,P_Rcpnt_Cntry      
               ,P_Rcpnt_Cntry_Code      
               ,P_SHO_SYS_TYP          
               ,G_Cmp_No
               ,G_Brn_No
               ,G_Brn_Year
               ,G_Brn_Usr
               ,P_Ad_Trmnl_Nm
               ,G_Ad_U_Id
               ,G_Ad_Date);

  --####################--
  <<RTN_RSLT>>
   If P_Msg_Txt Is Not Null OR P_Err_No IS NOT NULL Then
      Rollback;
      P_Msg_Txt := NVL(P_Msg_Txt,'Message Number Is Missing');
      P_Err_No := P_Err_No;
      P_Pkg_Nm := Nvl (P_Pkg_Nm, 'Ars_Api_Trns_Pkg.Insrt_Sales_Order');
      Return;
   End If;
--####################--

Exception
   When Others Then
      Rollback;
      P_Msg_Txt := 'Error When Insert Into Sales Order Master , ' || Chr(10) || Sqlerrm;
      P_Err_No := 20326;
      P_Pkg_Nm := Nvl (P_Pkg_Nm, 'Ars_Api_Trns_Pkg.Insrt_Sales_Order');
End Insrt_Sales_Order;

--##------------------------------------------------------------------------------------------------------------------------------------------------##--
  Procedure Insrt_Order_Detail (P_I_Code                 In     Order_Detail.I_Code%Type Default Null
                             ,P_Itm_Unt                In     Order_Detail.Itm_Unt%Type Default Null
                             ,P_I_Qty                  In     Order_Detail.I_Qty%Type Default Null
                             ,P_P_Qty                  In     Order_Detail.P_Qty%Type Default Null
                             ,P_P_Size                 In     Order_Detail.P_Size%Type Default Null
                             ,P_Free_Qty               In     Order_Detail.Free_Qty%Type Default Null
                             ,P_Barcode                In     Order_Detail.Barcode%Type Default Null
                             ,P_Batch_No               In     Order_Detail.Batch_No%Type Default Null
                             ,P_Expire_Date            In     Order_Detail.Expire_Date%Type Default Null
                             ,P_W_Code                 In     Order_Detail.W_Code%Type Default Null
                             ,P_Cc_Code                In     Order_Detail.Cc_Code%Type Default Null
                             ,P_Actv_No                In     Order_Detail.Actv_No%Type Default Null
                             ,P_Pj_No                  In     Order_Detail.Pj_No%Type Default Null
                             ,P_I_Price                In     Order_Detail.I_Price%Type Default Null
                             ,P_I_Price_Vat            In     Order_Detail.I_Price_Vat%Type Default Null
                             ,P_Measur_Price           In     Order_Detail.Measur_Price%Type Default Null
                             ,P_Othr_Amt               In     Order_Detail.Othr_Amt%Type Default Null
                             ,P_Othr_Amt_Disc          In     Order_Detail.Othr_Amt_Disc%Type Default Null
                             ,P_Vat_Amt                In     Order_Detail.Vat_Amt%Type Default Null
                             ,P_Vat_Amt_Aftr_Dis       In     Order_Detail.Vat_Amt_Aftr_Dis%Type Default Null
                             ,P_Vat_Amt_Bfr_Dis        In     Order_Detail.Vat_Amt_Bfr_Dis%Type Default Null
                             ,P_Vat_Amt_Dis_Dtl2_Vat   In     Order_Detail.Vat_Amt_Dis_Dtl2_Vat%Type Default Null
                             ,P_Vat_Amt_Dis_Dtl3_Vat   In     Order_Detail.Vat_Amt_Dis_Dtl3_Vat%Type Default Null
                             ,P_Vat_Amt_Dis_Dtl_Vat    In     Order_Detail.Vat_Amt_Dis_Dtl_Vat%Type Default Null
                             ,P_Vat_Amt_Dis_Mst_Vat    In     Order_Detail.Vat_Amt_Dis_Mst_Vat%Type Default Null
                             ,P_Vat_Amt_Othr           In     Order_Detail.Vat_Amt_Othr%Type Default Null
                             ,P_Vat_Per                In     Order_Detail.Vat_Per%Type Default Null
                             ,P_Dis_Amt                In     Order_Detail.Dis_Amt%Type Default Null
                             ,P_Dis_Amt_Aftr_Vat       In     Order_Detail.Dis_Amt_Aftr_Vat%Type Default Null
                             ,P_Dis_Amt_Dtl            In     Order_Detail.Dis_Amt_Dtl%Type Default Null
                             ,P_Dis_Amt_Dtl2           In     Order_Detail.Dis_Amt_Dtl2%Type Default Null
                             ,P_Dis_Amt_Dtl2_Vat       In     Order_Detail.Dis_Amt_Dtl2_Vat%Type Default Null
                             ,P_Dis_Amt_Dtl3           In     Order_Detail.Dis_Amt_Dtl3%Type Default Null
                             ,P_Dis_Amt_Dtl3_Vat       In     Order_Detail.Dis_Amt_Dtl3_Vat%Type Default Null
                             ,P_Dis_Amt_Dtl_Vat        In     Order_Detail.Dis_Amt_Dtl_Vat%Type Default Null
                             ,P_Dis_Amt_Mst            In     Order_Detail.Dis_Amt_Mst%Type Default Null
                             ,P_Dis_Amt_Mst_Vat        In     Order_Detail.Dis_Amt_Mst_Vat%Type Default Null
                             ,P_Dis_Per                In     Order_Detail.Dis_Per%Type Default Null
                             ,P_Dis_Per2               In     Order_Detail.Dis_Per2%Type Default Null
                             ,P_Dis_Per3               In     Order_Detail.Dis_Per3%Type Default Null
                             ,P_Doc_No_Ref             In     Order_Detail.Doc_No_Ref%Type Default Null
                             ,P_Doc_Seq                In Out Order_Detail.Doc_Seq%Type
                             ,P_Rcrd_No                In Out Order_Detail.Rcrd_NO%Type 
                             ,P_Doc_Sequence_Ref       In     Order_Detail.Doc_Sequence_Ref%Type Default Null
                             ,P_Doc_Ser_Ref            In     Order_Detail.Doc_Ser_Ref%Type Default Null
                             ,P_Doc_Type_Ref           In     Order_Detail.Doc_Type_Ref%Type Default Null
                             ,P_Rcrd_No_Ref              In     Ias_Bill_Dtl.Rcrd_No_Ref%Type Default Null
                             ,P_Emp_No                 In     Order_Detail.Emp_No%Type Default Null
                             ,P_External_Post          In     Order_Detail.External_Post%Type Default Null
                             ,P_Field_Dtl1             In     Order_Detail.Field_Dtl1%Type Default Null
                             ,P_Field_Dtl2             In     Order_Detail.Field_Dtl2%Type Default Null
                             ,P_Field_Dtl3             In     Order_Detail.Field_Dtl3%Type Default Null
                             ,P_F_Time                 In     Order_Detail.F_Time%Type Default Null
                             ,P_T_Time                 In     Order_Detail.T_Time%Type Default Null
                             ,P_Item_Desc              In     Order_Detail.Item_Desc%Type Default Null
                             ,P_I_Width                In     Order_Detail.I_Width%Type Default Null
                             ,P_I_Height               In     Order_Detail.I_Height%Type Default Null
                             ,P_I_Length               In     Order_Detail.I_Length%Type Default Null
                             ,P_I_Number               In     Order_Detail.I_Number%Type Default Null
                             ,P_Argmnt_No              In     Order_Detail.Argmnt_No%Type Default Null  
                             ,P_Wt_Qty                 In     Order_Detail.Wt_Qty%Type Default Null
                             ,P_Wt_Unt                 In     Order_Detail.Wt_Unt%Type Default Null                          
                             ,P_Rec_Attch              In     Order_Detail.Rec_Attch%Type Default Null
                             ,P_Reserved               In     Order_Detail.Reserved%Type Default Null
                             ,P_Res_Date               In     Order_Detail.Res_Date%Type Default Null
                             ,P_Res_Qty                In     Order_Detail.Res_Qty%Type Default Null
                             ,P_Lev_No                 In     Order_Detail.Lev_No%Type Default Null
                             ,P_PRM_GRP_NO             In     Order_Detail.PRM_GRP_NO%Type Default Null
                             ,P_QT_PRM_NO              In     Order_Detail.QT_PRM_NO%Type Default Null
                             ,P_QT_PRM_RCRD_NO         In     Order_Detail.QT_PRM_RCRD_NO%Type Default Null
                             ,P_QT_PRM_SER             In     Order_Detail.QT_PRM_SER%Type Default Null
                             ,P_Dis_Amt_Dtl_Qt_Prm     In     Order_Detail.Dis_Amt_Dtl_Qt_Prm%Type Default Null
                             ,P_Dis_Amt_Dtl_Qt_Prm_Vat In     Order_Detail.Dis_Amt_Dtl_Qt_Prm_Vat%Type Default Null
                             ,P_Dis_Per_Qt_Prm         In   Order_Detail.Dis_Per_Qt_Prm%Type Default Null
                             ,P_Msg_Txt                   Out Varchar2
                             ,P_Err_No                    Out Varchar2
                             ,P_Pkg_Nm                    Out Varchar2)
Is
   V_P_Size     Ias_Itm_Dtl.P_Size%Type;
   V_Cnt        Number;
   V_Msg_No     Number;
   V_Stkcost    Order_Detail.Stk_Cost%Type;
   V_Res_Qty    Order_Detail.Res_Qty%Type:=P_Res_Qty;
   V_Doc_Seq    Order_Detail.Doc_Seq%Type;
   V_I_Price    Number:=P_I_Price;
   V_I_Price_Vat  Number:=p_I_Price_Vat;
   V_Vat_Per    Number;
   V_Clc_Typ_No Number;
   V_Cc_Code    COST_CENTERS.Cc_Code%Type;  
   V_Pj_No      IAS_PROJECTS.Pj_No%Type;
   V_Actv_No    IAS_ACTVTY.Actv_No%Type;
   V_Res_Date  Date :=p_Res_Date;
   V_Reserved  Number(1):=P_Reserved;   
     
Begin
   --##---------------------------------------------------------------------------------------------------------------------------##--
   If G_Doc_Ser Is Null Or G_Doc_No Is Null Then
      P_Err_No := 20059;
      P_Msg_Txt := 'G_DOC_SER OR G_DOC_NO .. IS NULL ';
      Goto Rtn_Rslt;
   End If;

   --##---------------------------------------------------------------------------------------------------------------------------##--
   If G_Ar_Wc_Type = 1 Then
      G_W_Code := G_W_Code;
   Else
      G_W_Code := Nvl (P_W_Code, G_W_Code);
      
      If G_W_Code Is Not Null Then
        GNR_API_PKG.Chk_Inpt_Data (P_Inpt_Typ     => 'W_CODE'
                                   ,P_SYS_TYP      =>1
                                   ,P_DOC_TYPE     => G_DOC_TYP
                                   ,P_Inpt_Code1   => G_W_Code
                                   ,P_Inpt_Code2   => G_Brn_No
                                   ,P_Inpt_Code3   => G_ALLW_SAL_WH_NOT_CONN_BRN
                                   ,P_Inpt_Code4   => G_USE_BALANCED_BRN
                                   ,P_Lng_Dflt     => G_Lng_No
                                   ,P_Inpt_Nm      => G_Inpt_Nm
                                   ,P_Msg_No       => V_Msg_No);

         If V_Msg_No Is Not Null Then
            P_Err_No :=20737 ;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No) || ' W_CODE=' || G_W_Code;
            Goto Rtn_Rslt;
         End If;
      END IF;
   End If;

   If G_W_Code Is Null Then
      P_Err_No := 20060;
      P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 930);
      Goto Rtn_Rslt;
   End If;

   --##---------------------------------------------------------------------------------------------------------------------------##--
   If Nvl(G_DTS_USE_RES_IN_SO_APP,0)=1 Then                    
     V_Reserved:=1;
     V_Res_Date:=Nvl(G_DTS_SO_RES_PRD,0)+G_Doc_Date;
     V_Res_Qty  :=nvl(P_I_Qty,0)+Nvl(P_Free_Qty,0);
   ElsIf Nvl(G_USE_RES_IN_SO_MNDTRY,0)=1 and nvl(G_SYS_NO,0)=70 and NVL(G_DTS_ONLINE,0)=1 THEN     
     V_Reserved:=1;
     V_Res_Date:=G_doc_Date+G_MAX_PRD_RESERVE_SO_DAY;
     V_Res_Qty  :=nvl(P_I_Qty,0)+Nvl(P_Free_Qty,0);
   End if;
   --##---------------------------------------------------------------------------------------------------------------------------##--
   If Nvl (G_Use_Vat, 0) = 1 And G_Clc_Typ_No_Tax Is Not Null And Nvl (G_Clc_Tax_Method, 0) = 1 Then       
          If Nvl (Ys_Tax_Pkg.Get_Clc_Tax_Typ (P_Clc_Typ_No => G_Clc_Typ_No_Tax), 0) = 0 Then
            -- V_Vat_Per   := Ys_Tax_Pkg.Get_Itm_Tax_Prcnt (P_Clc_Typ_No => G_Clc_Typ_No_Tax, P_I_Code => P_I_Code, P_Clc_Usd_Itm => 1);
              V_Vat_Per   :=Ys_Tax_Pkg.Get_Itm_Tax_Prcnt_Sal ( P_Clc_Typ_No =>G_Clc_Typ_No_Tax  
                                                             , P_I_Code => P_I_CODE 
                                                              ,P_Clc_Usd_Itm => 1
                                                              ,P_I_Price=>P_I_Price
                                                              ,P_I_Price_Vat =>case when Nvl(G_Clc_Vat_Price_Typ,0) = 2 Then (Case when nvl(P_I_Price_Vat,0) =0 Then Nvl (P_I_Price, 0) Else Nvl (P_I_Price_Vat, 0) end) else Nvl (P_I_Price, 0) end  
                                                              ,P_Use_Price_Include_Vat=> case when Nvl(G_Clc_Vat_Price_Typ,0) = 2 then 1 else 0 end ); 
          Else
             V_Clc_Typ_No   := Ys_Tax_Pkg.Get_Clc_Typ_No_Exmpt (P_Clc_Typ_No => G_Clc_Typ_No_Tax);
            -- V_Vat_Per      := Ys_Tax_Pkg.Get_Itm_Tax_Prcnt (P_Clc_Typ_No => V_Clc_Typ_No, P_I_Code => P_I_Code, P_Clc_Usd_Itm => 1);
            V_Vat_Per   :=Ys_Tax_Pkg.Get_Itm_Tax_Prcnt_Sal ( P_Clc_Typ_No =>V_Clc_Typ_No  
                                                             , P_I_Code => P_I_CODE 
                                                              ,P_Clc_Usd_Itm => 1
                                                              ,P_I_Price=>P_I_Price
                                                              ,P_I_Price_Vat =>case when Nvl(G_Clc_Vat_Price_Typ,0) = 2 Then (Case when nvl(P_I_Price_Vat,0) =0 Then Nvl (P_I_Price, 0) Else Nvl (P_I_Price_Vat, 0) end) else Nvl (P_I_Price, 0) end  
                                                              ,P_Use_Price_Include_Vat=> case when Nvl(G_Clc_Vat_Price_Typ,0) = 2 then 1 else 0 end );
          End If;
          If nvl(V_Vat_Per,0)>0 And Nvl(G_Clc_Vat_Price_Typ,0) = 2 Then   
            --V_I_Price   := Nvl (P_I_Price_Vat, 0) / ( (Nvl (V_Vat_Per, 0) / 100) + 1);
             V_I_Price_Vat := Case when nvl(P_I_Price_Vat,0) =0 Then Nvl (P_I_Price, 0) Else Nvl (P_I_Price_Vat, 0) End;             
             V_I_Price   := Nvl (V_I_Price_Vat, 0) / ( (Nvl (V_Vat_Per, 0) / 100) + 1);
          Else
             V_I_Price   := P_I_Price;
          End If;
   Else
          V_I_Price   := P_I_Price;
          V_Vat_Per   := P_Vat_Per;
   End If;
   --##---------------------------------------------------------------------------------------------------------------------------##--
   --## CHK ITM DATA
   Gnr_Api_Pkg.Chk_Itm (P_Sys_No              => G_Sys_No
                       ,P_Sys_Typ             => 1 --##    P_SYS_TYP =  1 = SALE , 2= STOCKE ,3 = PURCHASE ,
                       ,P_Trns_Typ            => -1 --##.    (1=IN)(-1=OUT)
                       ,P_Doc_Type            => G_Doc_Typ
                       ,P_I_Code              => P_I_Code
                       ,P_Itm_Unt             => P_Itm_Unt
                       ,P_P_Size              => P_P_Size
                       ,P_I_Qty               => P_I_Qty
                       ,P_Free_Qty            => P_Free_Qty
                       ,P_Res_Qty             => V_Res_Qty
                       ,P_I_Price             => V_I_Price
                       ,P_I_Price_Vat         => V_I_Price_Vat
                       ,P_Measur_Price        => P_Measur_Price
                       ,P_Lev_No              => P_Lev_No
                       ,P_Qt_Prm_Method       => Null
                       ,P_Qut_Prm_Price       => Null
                       ,P_Qt_Prm_Ser          => P_Qt_Prm_Ser
                       ,P_Dis_Per             => P_Dis_Per
                       ,P_Dis_Amt_Dtl         => P_Dis_Amt_Dtl
                       ,P_Dis_Amt_Dtl_Vat     => P_Dis_Amt_Dtl_Vat
                       ,P_Dis_Per2            => P_Dis_Per2
                       ,P_Dis_Amt_Dtl2        => P_Dis_Amt_Dtl2
                       ,P_Dis_Amt_Dtl2_Vat    => P_Dis_Amt_Dtl2_Vat
                       ,P_Dis_Per3            => P_Dis_Per3
                       ,P_Dis_Amt_Dtl3        => P_Dis_Amt_Dtl3
                       ,P_Dis_Amt_Dtl3_Vat    => P_Dis_Amt_Dtl3_Vat
                       ,P_Dis_Amt_Mst         => P_Dis_Amt_Mst
                       ,P_W_Code              => G_W_Code
                       ,P_Expire_Date         => P_Expire_Date
                       ,P_Batch_No            => P_Batch_No
                       ,P_Brn_No              => G_Brn_No
                       ,P_Doc_Date            => G_Doc_Date
                       ,P_Doc_Ser             => G_Doc_Ser                    
                       ,P_C_Code              => G_C_Code
                       ,P_Cur_Code            => G_Cur_Code
                       ,P_Ac_Rate             => G_Cur_Rate
                       ,P_Usr_No              => G_Ad_U_Id
                       ,P_Clc_Vat_Price_Typ   => Nvl (G_Clc_Vat_Price_Typ, 1)
                       ,P_Bill_Doc_Type       => G_Bill_Doc_Type
                       ,P_Stk_Cost            => Null
                       ,P_Chk_Avlqty_Flg      => Nvl (V_Reserved, G_Chk_Avlqty_Flg)
                       ,P_Chk_Itm_Price       => G_Chk_Itm_Price --# 0 nocheck 1 check
                       ,P_Use_Vat             =>G_USE_VAT
                       ,P_Clc_Typ_No_Tax      =>G_Clc_Typ_No_Tax 
                       ,P_Lng_No              => G_Lng_No
                       ,P_Msg_Txt             => P_Msg_Txt
                       ,P_Pkg_Line            => P_Err_No
                       ,P_Pkg_Nm              => P_Pkg_Nm);

   If P_Msg_Txt Is Not Null Then
      Goto Rtn_Rslt;
   End If;

   V_P_Size := Ias_Itm_Pkg.Get_Icode_Size_Unit (P_I_Code => P_I_Code, P_Itm_Unt => P_Itm_Unt);

   --##-----------------------------------------------------------------------------------------------------------------------------##--
    If Nvl(V_P_Size,0)=0 Then
             P_Err_No    := 20670;
             P_MSG_TXT :='P_Size=0 For I_Code='||p_i_code;
            Goto Rtn_Rslt;                                                      
     End If;
    --##-------------------------------------------------------------------------------------------------------------------------------##--
   Begin
      V_Stkcost :=
         Ias_Itm_Inv_Pkg.Get_Itm_Cost (P_Costing_Type   => G_Costing_Type
                                      ,P_Wtavg_Type     => G_Wtavg_Type
                                      ,P_Icode          => P_I_Code
                                      ,P_Wcode          => G_W_Code
                                      , --P_ITM_UNT    => I.ITM_UNT                                            ,
                                       P_Psize          => Nvl (V_P_Size, 1)
                                      ,P_Iqty           => (Nvl (P_I_Qty, 0) + Nvl (P_Free_Qty, 0))
                                      ,P_Expdate        => Nvl (P_Expire_Date, '01/01/1900')
                                      ,P_Batchno        => Nvl (P_Batch_No, '0')
                                      ,P_Brn_No         => G_Brn_No
                                      ,P_Brn_Year       => G_Brn_Year
                                      ,P_Cmp_No         => G_Cmp_No
                                      ,P_Brn_Usr        => G_Brn_Usr);
   Exception
      When Others Then
         P_Msg_Txt := 'ERR WHEN GET ITM COST ' || Chr(10) || Sqlerrm;
         P_Err_No := 20327;
         P_Pkg_Nm := Nvl (P_Pkg_Nm, 'Ias_Itm_Inv_Pkg.Get_Itm_Cost');
         Goto Rtn_Rslt;
   End;

   --##-------------------------------------------------------------------------------------------------------------------------------##--
   If Nvl (V_Reserved, 0) = 1 Then
      If V_Res_Date Is Null Then
         P_Err_No := 20061;
         P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 336) || ', I_CODE = ' || P_I_Code;
         Goto Rtn_Rslt;
      Elsif V_Res_Date < G_Doc_Date Then
         P_Err_No := 20062;
         P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 5011) || ', I_CODE = ' || P_I_Code;
         Goto Rtn_Rslt;
      Elsif Nvl (V_Res_Qty, 0)> (Nvl(P_I_Qty,0)+Nvl (P_Free_Qty,0) )Then
         P_Err_No := 20063;
         P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 5014) || ', I_CODE = ' || P_I_Code;
         Goto Rtn_Rslt;
      Elsif Nvl (V_Reserved, 0) = 0 And V_Res_Date Is Not Null Then
         P_Err_No := 20064;
         P_Msg_Txt := 'RESERVED = 0 BUT RES_DATE IS NOT NULL , ITM_CODE = ' || P_I_Code;
         Goto Rtn_Rslt;
      Elsif Nvl (V_Res_Qty, 0) < 0 Then
         P_Err_No := 20065;
         P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 5015) || ', I_CODE = ' || P_I_Code;
         Goto Rtn_Rslt;
      End If;
   End If;

   --##-------------------------------------------------------------------------------------------------------------------------------##--
   --## SUB LDGR
     If G_Ar_Cst_Type = 2 Then
         G_Dtl_Cc_Code   := nvl(P_Cc_Code,G_Cc_Code);
      Else
         G_Dtl_Cc_Code   := G_Cc_Code;   
      End If;

      If G_Ar_Pj_Type = 2 Then
         G_Dtl_Pj_No   := nvl(P_Pj_No,G_Pj_No);
      Else
          G_Dtl_Pj_No   := G_Pj_No;
      End If;

      If G_Ar_Actv_Type = 2 Then
         G_Dtl_Actv_No   := nvl(P_Actv_No,G_Actv_No);
      Else
          G_Dtl_Actv_No   := G_Actv_No;         
      End If;

   Gnr_Api_Pkg.Chk_Sub_Ldgr (P_Sys_Typ     => 1
                            ,P_Sys_No      => G_Sys_No
                            ,P_Doc_Type    => G_Doc_Typ
                            ,P_Cst_Type    => G_Ar_Cst_Type
                            ,P_Pj_Type     => G_Ar_Pj_Type
                            ,P_Actv_Type   => G_Ar_Actv_Type
                            ,P_Cc_Code     => G_Dtl_Cc_Code
                            ,P_Pj_No       => G_Dtl_Pj_No
                            ,P_Actv_No     => G_Dtl_Actv_No
                            ,P_Rep_Code    => G_Rep_Code
                            ,P_A_Code      => G_A_Code
                            ,P_Chk_Ac_Cc   => 0
                            ,P_BILL_DOC_TYPE =>G_BILL_DOC_TYPE
                            ,P_C_CODE        =>G_C_CODE
                            ,P_P_Year        =>G_P_Year
                            ,P_Lng_No      => G_Lng_No
                            ,P_Msg_Txt     => P_Msg_Txt
                            ,P_Pkg_Line    => P_Err_No
                            ,P_Pkg_Nm      => P_Pkg_Nm);

   If P_Msg_Txt Is Not Null Then
      Goto Rtn_Rslt;
   End If;
   --##--------------------------------------------------------------------------------------------------------------------------------##--
   --## Update Doc Ref
            Update_Doc_Ref    ( P_Doc_Type           =>G_Doc_Typ
                               ,P_Pst_Typ            =>G_Pst_Typ
                               ,P_Doc_Ser            =>G_Doc_Ser
                               ,P_I_Code             =>P_I_Code
                               ,P_Itm_Unt            =>P_Itm_Unt
                               ,P_P_Size             =>V_P_Size
                               ,P_I_Qty              => P_I_Qty
                               ,P_Free_Qty           =>P_Free_Qty
                               ,P_Rcrd_No            =>G_Rcrd_No
                               ,P_Doc_Type_Ref       =>P_Doc_Type_Ref
                               ,P_Doc_No_Ref         =>P_Doc_No_Ref
                               ,P_Doc_Ser_Ref        =>P_Doc_Ser_Ref
                               ,P_Rcrd_No_Ref        =>P_Rcrd_No_Ref
                               ,P_Msg_Txt            =>P_Msg_Txt
                               ,P_Err_No              =>P_Err_No
                               ,P_Pkg_Nm              =>P_Pkg_Nm);
      If P_Msg_Txt Is Not Null Then
         Goto Rtn_Rslt;
      End If;
      --##--------------------------------------------------------------------------------------------------------------------------------##--                
      --## Conn Wcode By Activity To Get Cc_Code + Pj_No + Actv_No       
          If G_W_Code Is Not Null And Nvl(G_Conn_Activity_By_Wcode_Cc,0) = 1 Then           
              If ( G_Ar_Cst_Type=2) Or ( G_Ar_Pj_Type=2) Or  ( G_Ar_Actv_Type=2) Then                 
                Ias_Itm_Pkg.Get_Itm_Activity_Wcode_Info ( P_W_Code       =>G_W_Code,
                                                          P_Itm_Actv_No  => Ias_Itm_Pkg.Get_Itm_Activity (P_I_Code => P_I_Code ) ,
                                                          P_Cc_Code      => V_Cc_Code  ,
                                                          P_Pj_No        => V_Pj_No    ,
                                                          P_Actv_No      => V_Actv_No  ) ;
              End If ; 
              
              If G_Ar_Cst_Type=2 and V_Cc_Code is Not Null Then
                   G_Dtl_Cc_Code:=V_Cc_Code;               
              End If;
              
              If G_Ar_Pj_Type=2 and V_Pj_No is Not Null Then
                   G_Dtl_Pj_No:=V_Pj_No;                
              End If; 
              
              If G_Ar_Actv_Type=2 and V_Pj_No is Not Null Then
                   G_Dtl_Actv_No:=V_Actv_No;                 
              End If;          
                                                           
          End If ;
     --##--------------------------------------------------------------------------------------------------------------------------------##--   -- If P_Doc_Seq Is Null Then
   Begin
      Select Ias_Doc_Seq_Othr.Nextval Into V_Doc_Seq From Dual;
   Exception
      When Others Then
         P_Msg_Txt := 'Err. When Get DOC_SEQ' || Chr (10) || Sqlerrm;
         P_Err_No := 20328;
         Goto Rtn_Rslt;
   End;

   P_Doc_Seq := V_Doc_Seq; 
   --##--------------------------------------------------------------------------------------------------------------------------------##--
   G_Rcrd_No := Nvl (G_Rcrd_No, 0) + 1;
   P_Rcrd_No :=G_Rcrd_No;
   --##---------------------------------------------------------------------------------------------------------------------------##--
   Insert Into Order_Detail (So_Type
                            ,Order_No
                            ,Order_Ser
                            ,Bill_Doc_Type
                            ,I_Code
                            ,Itm_Unt
                            ,I_Qty
                            ,Free_Qty
                            ,P_Size
                            ,P_Qty
                            ,I_Price
                            ,Res_Date
                            ,Res_Qty
                            ,W_Code
                            ,Reserved
                            ,Rcrd_No
                            ,Barcode
                            ,Item_Desc
                            ,External_Post
                            ,Canceled
                            ,Expire_Date
                            ,Batch_No
                            ,Vat_Per
                            ,Vat_Amt
                            ,I_Length
                            ,I_Width
                            ,I_Height
                            ,I_Number
                            ,Field_Dtl1
                            ,Field_Dtl2
                            ,Field_Dtl3
                            ,Dis_Per
                            ,Dis_Amt_Dtl
                            ,Dis_Per2
                            ,Dis_Amt_Dtl2
                            ,Dis_Per3
                            ,Dis_Amt_Dtl3
                            ,Dis_Amt
                            ,Dis_Amt_Mst
                            ,Emp_No
                            ,Doc_Seq
                            ,Measur_Price
                            ,Othr_Amt
                            ,Si_Type
                            ,I_Price_Vat
                            ,Argmnt_No
                            ,Wt_Qty
                            ,Wt_Unt
                            ,Cc_Code
                            ,Doc_Type_Ref
                            ,Doc_No_Ref
                            ,Doc_Ser_Ref
                            ,Doc_Sequence_Ref
                            ,Stk_Cost
                            ,Othr_Amt_Disc
                            ,Vat_Amt_Othr
                            ,F_Time
                            ,T_Time
                            ,Dis_Amt_Dtl_Vat
                            ,Dis_Amt_Mst_Vat
                            ,Vat_Amt_Dis_Dtl_Vat
                            ,Vat_Amt_Aftr_Dis
                            ,Vat_Amt_Bfr_Dis
                            ,Vat_Amt_Dis_Mst_Vat -- ,RSRVD_QTY
                            ,Pj_No
                            ,Actv_No
                            ,Dis_Amt_Aftr_Vat
                            ,Dis_Amt_Dtl2_Vat
                            ,Dis_Amt_Dtl3_Vat
                            ,Vat_Amt_Dis_Dtl2_Vat
                            ,Vat_Amt_Dis_Dtl3_Vat
                           , Lev_No
                            ,PRM_GRP_NO 
                            ,QT_PRM_NO            
                            ,QT_PRM_RCRD_NO          
                            ,QT_PRM_SER              
                            ,Dis_Amt_Dtl_Qt_Prm      
                            ,Dis_Amt_Dtl_Qt_Prm_Vat  
                            ,Dis_Per_Qt_Prm
                            ,Doc_Seq_tmp                           
                            ,Cmp_No
                            ,Brn_No
                            ,Brn_Year
                            ,Brn_Usr)
        Values (G_So_Type
               ,G_Doc_No
               ,G_Doc_Ser
               ,G_Bill_Doc_Type
               ,P_I_Code
               ,P_Itm_Unt
               ,P_I_Qty
               ,P_Free_Qty
               ,V_P_Size
               ,(P_I_Qty * V_P_Size)
               ,V_I_Price
               ,V_Res_Date
               ,V_Res_Qty
               ,G_W_Code
               ,V_Reserved
               ,G_Rcrd_No
               ,P_Barcode
               ,P_Item_Desc
               ,G_External_Post
               ,0
               ,Nvl (P_Expire_Date, '01/01/1900')
               ,Nvl (P_Batch_No, '0')
               ,V_Vat_Per
               ,Nvl (P_Vat_Amt, 0)
               ,P_I_Length
               ,P_I_Width
               ,P_I_Height
               ,P_I_Number
               ,P_Field_Dtl1
               ,P_Field_Dtl2
               ,P_Field_Dtl3
               ,P_Dis_Per
               ,P_Dis_Amt_Dtl
               ,P_Dis_Per2
               ,P_Dis_Amt_Dtl2
               ,P_Dis_Per3
               ,P_Dis_Amt_Dtl3
               ,P_Dis_Amt
               ,P_Dis_Amt_Mst
               ,P_Emp_No
               ,V_Doc_Seq
               ,P_Measur_Price
               ,Nvl (P_Othr_Amt, 0)
               ,G_Si_Type
               ,V_I_Price_Vat
               ,P_Argmnt_No
               ,p_Wt_Qty
               ,p_Wt_Unt
               ,G_Dtl_Cc_Code
               ,P_Doc_Type_Ref
               ,P_Doc_No_Ref
               ,P_Doc_Ser_Ref
               ,P_Doc_Sequence_Ref
               ,V_Stkcost
               ,P_Othr_Amt_Disc
               ,P_Vat_Amt_Othr
               ,P_F_Time
               ,P_T_Time
               ,P_Dis_Amt_Dtl_Vat
               ,P_Dis_Amt_Mst_Vat
               ,P_Vat_Amt_Dis_Dtl_Vat
               ,P_Vat_Amt_Aftr_Dis
               ,P_Vat_Amt_Bfr_Dis
               ,P_Vat_Amt_Dis_Mst_Vat --,V_RES_QTY
               ,G_Dtl_Pj_No
               ,G_Dtl_Actv_No
               ,P_Dis_Amt_Aftr_Vat
               ,P_Dis_Amt_Dtl2_Vat
               ,P_Dis_Amt_Dtl3_Vat
               ,P_Vat_Amt_Dis_Dtl2_Vat
               ,P_Vat_Amt_Dis_Dtl3_Vat
               ,P_Lev_No
               ,P_PRM_GRP_NO 
               ,P_QT_PRM_NO            
                ,P_QT_PRM_RCRD_NO          
                ,P_QT_PRM_SER              
                ,P_Dis_Amt_Dtl_Qt_Prm      
                ,P_Dis_Amt_Dtl_Qt_Prm_Vat  
                ,P_Dis_Per_Qt_Prm 
                ,V_Doc_Seq               
               ,G_Cmp_No
               ,G_Brn_No
               ,G_Brn_Year
               ,G_Brn_Usr);

   ----------------------------------------------------------
 --  If Nvl (P_Reserved, 0) = 1 Then
      Insrt_Reserve_Prc (P_I_Code       => P_I_Code
                        ,P_Itm_Unt      => P_Itm_Unt
                        ,P_P_Size       => V_P_Size
                        ,P_I_Qty        => P_I_Qty
                        ,P_Res_Qty      => V_Res_Qty
                        ,P_W_Code       => G_W_Code
                        ,P_Expiredate   => P_Expire_Date
                        ,P_Batchno      => P_Batch_No
                        ,P_Res_Date     => V_Res_Date
                        ,P_Item_Desc    => P_Item_Desc
                        ,P_Rcrd_No      => G_Rcrd_No
                        ,P_Reserved     => V_Reserved
                        ,p_Doc_Sequence  =>v_Doc_Seq
                        ,P_Msg_Txt      =>P_Msg_Txt
                        ,P_ERR_NO       =>P_ERR_NO
                        ,P_Pkg_NM       =>P_Pkg_NM);
    If P_Msg_Txt Is Not Null Then
     Goto Rtn_Rslt;
    End If;                        
   ---------------------------------------------------------------
  --####################--
  <<RTN_RSLT>>
   If P_Msg_Txt Is Not Null OR P_Err_No IS NOT NULL Then
      Rollback;
      P_Msg_Txt := NVL(P_Msg_Txt,'Message Number Is Missing');
      P_Err_No := P_Err_No;
      P_Pkg_Nm := Nvl (P_Pkg_Nm, 'Ars_Api_Trns_Pkg.Insrt_Order_Detail');
      Return;
   End If;
--####################--

Exception
   When Others Then
      Rollback;
      P_Msg_Txt := 'Error When Insert Into Sales Order Detail , ' || Chr(10) || Sqlerrm;
      P_Err_No := 20329;
      P_Pkg_Nm := Nvl (P_Pkg_Nm, 'Ars_Api_Trns_Pkg.Insrt_Order_Detail');
End Insrt_Order_Detail;
--##-----------------------------------------------------------------------------------------------------##--
   Procedure Insrt_QUOTATION (P_Sys_No              In     Number
                               ,P_Doc_Type            In     Number
                               ,P_Doc_No              In     QUOTATION.QUOT_No%Type Default Null
                               ,P_Doc_Ser             In     QUOTATION.QUOT_Ser%Type Default Null
                               ,P_Doc_Date            In     QUOTATION.QUOT_Date%Type Default Null
                               ,P_Cur_Code            In     QUOTATION.QUOT_Cur%Type Default Null
                               ,P_Cur_Rate            In     QUOTATION.Cur_Rate%Type Default Null
                               ,P_QT_Type             In     QUOTATION.QT_Type%Type Default Null
                               ,P_C_Code              In     QUOTATION.C_Code%Type Default Null
                               ,P_C_Name              In     QUOTATION.C_Name%Type Default Null
                               ,P_C_Tax_Code          In     Ias_Bill_Mst.C_Tax_Code%Type Default Null
                               ,P_A_Desc              In     QUOTATION.A_Desc%Type Default Null
                               ,P_Cc_Code             In     QUOTATION.Cc_Code%Type Default Null
                               ,P_Pj_No               In     QUOTATION.Pj_No%Type Default Null
                               ,P_Actv_No             In     QUOTATION.Actv_No%Type Default Null
                               ,P_W_Code              In     QUOTATION.W_Code%Type Default Null
                               ,P_Rep_Code            In     QUOTATION.Rep_Code%Type Default Null                              
                               ,P_Vat_Amt             In     QUOTATION.Vat_Amt%Type Default Null
                               ,P_DOC_Amt             In     QUOTATION.QUOT_Amt%Type Default Null
                               ,P_Disc_Amt            In     QUOTATION.Disc_Amt%Type Default Null
                               ,P_Disc_Amt_Dtl        In     QUOTATION.Disc_Amt_Dtl%Type Default Null
                               ,P_Disc_Amt_Mst        In     QUOTATION.Disc_Amt_Mst%Type Default Null
                               ,P_Othr_Amt            In     QUOTATION.Othr_Amt%Type Default Null
                               ,P_Vat_Amt_Othr        In     QUOTATION.Vat_Amt_Othr%Type Default Null
                               ,P_Othr_Amt_Disc       In    QUOTATION.Othr_Amt_Disc%Type Default Null
                               ,P_Disc_Amt_Mst_Vat    In     QUOTATION.Disc_Amt_Mst_Vat%Type Default Null
                               ,P_Vat_Amt_Disc_Mst    In     QUOTATION.Vat_Amt_Disc_Mst%Type Default Null
                               ,P_Disc_Amt_Aftr_Vat   In     Sales_Order.Disc_Amt_Aftr_Vat%Type Default Null
                               ,P_Cash_No             In     Sales_Order.Cash_No%Type Default Null
                               ,P_Clc_Typ_No_Tax      In     Sales_Order.Clc_Typ_No_Tax%Type Default Null
                               ,P_Clc_Vat_Price_Typ   In     Sales_Order.Clc_Vat_Price_Typ%Type Default Null
                               ,P_PAY_TERMS           In     QUOTATION.PAY_TERMS%Type Default Null
                               ,P_REQ_DAYS            In     QUOTATION.REQ_DAYS%Type Default Null
                               ,P_REF_NO              In     QUOTATION.REF_NO%Type Default Null
                               ,P_REF_DATE            In     QUOTATION.REF_DATE%Type Default Null
                               ,P_QUOT_TEND           In     QUOTATION.QUOT_TEND%Type Default Null                                                          
                               ,P_QUOT_TEND_DATE      In     QUOTATION.QUOT_TEND_DATE%Type Default Null
                               ,P_PORT_OF_DEP         In     QUOTATION.PORT_OF_DEP%Type Default Null
                               ,P_Bill_Doc_Type       In     Sales_Order.Bill_Doc_Type%Type Default Null
                               ,P_QUOT_Due_Date       In     Sales_Order.Bill_Due_Date%Type Default Null
                               ,P_QUOT_Expire_Date   In      QUOTATION.QUOT_Expire_Date%Type Default Null
                               ,P_Cheque_Due_Date     In     QUOTATION.Cheque_Due_Date%Type Default Null                              
                               ,P_Si_Type             In     Sales_Order.Si_Type%Type Default Null
                               ,P_External_Post       In     Sales_Order.External_Post%Type Default Null
                               ,P_Field1              In     Sales_Order.Field1%Type Default Null
                               ,P_Field2              In     Sales_Order.Field2%Type Default Null
                               ,P_Field3              In     Sales_Order.Field3%Type Default Null
                               ,P_Field4              In     Sales_Order.Field4%Type Default Null
                               ,P_Field5              In     Sales_Order.Field5%Type Default Null
                               ,P_Field6              In     Sales_Order.Field6%Type Default Null
                               ,P_Field7              In     Sales_Order.Field7%Type Default Null
                               ,P_Field8              In     Sales_Order.Field8%Type Default Null
                               ,P_Field9              In     Sales_Order.Field9%Type Default Null
                               ,P_Field10             In     Sales_Order.Field10%Type Default Null
                               ,P_CLC_TAX_FREE_QTY_FLG In     Ias_Bill_Mst.CLC_TAX_FREE_QTY_FLG %Type Default Null
                               ,P_Doc_Ser_Extrnl      In     Ias_Bill_Mst.Doc_Ser_Extrnl%Type Default Null
                               ,P_Cmp_No              In     Sales_Order.Cmp_No%Type Default Null
                               ,P_Brn_No              In     Sales_Order.Brn_No%Type Default Null
                               ,P_Brn_Year            In     Sales_Order.Brn_Year%Type Default Null
                               ,P_Brn_Usr             In     Sales_Order.Brn_Usr%Type Default Null
                               ,P_Ad_Trmnl_Nm         In     Sales_Order.Ad_Trmnl_Nm%Type Default Null
                               ,P_Ad_U_Id             In     Sales_Order.Ad_U_Id%Type Default Null
                               ,P_Ad_Date             In     Sales_Order.Ad_Date%Type Default Null
                               ,P_CLC_TAX_METHOD      In     NUMBER  --## 0 CALC TAX IN EXTRNAL ,1-AOUTO CALC TAX
                               ,P_DTS_ONLINE                   In     NUMBER DEFAULT 0 --## 0 OFFLINE ,1-ONLINE
                               ,P_Lng_No              In     Number Default 1
                               ,P_Msg_Txt              Out Varchar2
                               ,P_ERR_NO               Out Varchar2
                               ,P_Pkg_NM               Out Varchar2)
Is
   V_Sys_No_Extrnl   Form_Detail.Sys_No%Type;
   V_Doc_Due_Date    Date;
   V_Crdt_Prd_Day    Number := 0;
   V_QUOT_Exp_Date   Date;
   V_R_Code          Sales_Order.R_Code%Type;
   V_Cst_Nm          Customer.C_A_Name%Type;
   V_Tax_Code        Customer.C_Tax_Code%Type;
   V_Msg_No          Number;
   V_Doc_Dsc         Sales_Order.A_Desc%Type;
   V_Inactv_Flg      Number;
   V_Cnt             Number;  
Begin
   --##-----------------------------------------------------------------------------------------------##--
   Clr_Glbl_Var;
   --##-----------------------------------------------------------------------------------------------##--
   G_Doc_Typ := 52;  
   V_Sys_No_Extrnl := G_Sys_No;
   --##-----------------------------------------------------------------------------------------##--
   V_Msg_No := Null;
   G_QT_Type          := Case When nvl(P_QT_Type,0)=0   Then Null Else P_QT_Type end ;  
   G_Cc_Code          := Case When nvl(P_Cc_Code,'0')='0' Then Null Else P_Cc_Code end ;
   G_Pj_No            := Case When nvl(P_Pj_No,'0')='0' Then Null Else P_Pj_No end ;
   G_Actv_No          := Case When nvl(P_Actv_No,'0')='0' Then Null Else P_Actv_No end ;
   G_Bill_Doc_Type   := Case When nvl(P_Bill_Doc_Type,0)=0 Then Null Else P_Bill_Doc_Type end; 
   G_Ad_Date          := Nvl (P_Ad_Date, Ias_Gen_Pkg.Get_Curdate);
   G_Ad_U_Id          := Case When nvl(Nvl(P_Ad_U_Id, G_Usr_No),0)=0 Then Null Else Nvl(P_Ad_U_Id, G_Usr_No) end;
   G_C_Code           := case When nvl(P_C_Code,'0')='0' Then Null Else P_C_Code end ;
   G_Rep_Code         := Case When nvl(P_Rep_Code,'0')='0' Then Null Else P_Rep_Code end ;
   G_Si_Type          := Case When nvl(P_Si_Type,0)=0  Then Null Else P_Si_Type end ;
   G_Clc_Typ_No_Tax   := Case When nvl(P_Clc_Typ_No_Tax,0)=0 Then Null Else P_Clc_Typ_No_Tax end  ;
   G_W_Code           := Case When nvl(P_W_Code,0)=0 Then Null Else P_W_Code end ;
   --G_Col_No   :=P_Col_No;   
    --##----------------------------------------------------------------------------------------------##--
    If G_Ad_U_Id Is Null Then
      P_Err_No := 20603;
      P_Msg_Txt := 'Ad_U_Id IS NULL ';
      Goto Rtn_Rslt;
    END IF;  
  --##----------------------------------------------------------------------------------------------##--           
   Get_Prmtr_Prc (P_Sys_No           => P_Sys_No
                 ,P_Doc_Typ          => G_Doc_Typ
                 ,P_Pst_Typ          => Null
                 ,P_Cur_Code         => P_Cur_Code
                 ,P_Cur_Rate         => P_Cur_Rate
                 ,P_Stock_Rate       => Null
                 ,P_Doc_Date         => P_Doc_Date
                 ,P_Brn_No           => P_Brn_No
                 ,P_Brn_Usr          => P_Brn_Usr
                 ,P_Brn_Year         => P_Brn_Year
                 ,P_Usr_No           => P_Ad_U_Id
                 ,P_Clc_Tax_Method   => P_Clc_Tax_Method
                 ,P_Pst_From_Br      => 0
                 ,P_DTS_ONLINE       =>P_DTS_ONLINE
                 ,P_Lng_No           => P_Lng_No
                 ,P_Msg_Txt          => P_Msg_Txt
                 ,P_Err_No           => P_Err_No
                 ,P_Pkg_Nm           => P_Pkg_Nm);

   If P_Msg_Txt Is Not Null Then
      Goto Rtn_Rslt;
   End If;
   --##----------------------------------------------------------------------------------------------##--
     IF  NVL(P_Sys_No,0)=70 THEN
        If P_DOC_SER_EXTRNL Is Null  Then
          P_Err_No := 20604;
          P_Msg_Txt := 'DOC_SER_EXTRNL IS NULL ';
          Goto Rtn_Rslt;
        END IF;
         
        BEGIN 
          SELECT 1 INTO V_CNT FROM QUOTATION
             WHERE DOC_SER_EXTRNL=P_DOC_SER_EXTRNL
             AND ROWNUM<=1;
        EXCEPTION WHEN OTHERS THEN
          V_CNT:=0;
        END ; 
        IF NVL(V_CNT,0)>0 THEN
            BEGIN 
              SELECT QUOT_NO,QUOT_SER INTO G_DOC_NO,G_DOC_SER FROM QUOTATION
                 WHERE DOC_SER_EXTRNL=P_DOC_SER_EXTRNL
                 AND ROWNUM<=1;
            EXCEPTION WHEN OTHERS THEN
              V_CNT:=0;
            END ;                 
           P_Err_No := 20999;
           P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 4942) || Chr (10) || ' DOC_SER_EXTRNL='||P_DOC_SER_EXTRNL;           
          Goto Rtn_Rslt;
        END IF;
        V_CNT:=0; 
     END IF; 
  --##----------------------------------------------------------------------------------------------##--
      G_Clc_Typ_No_Tax   := Case  When nvl(P_Clc_Typ_No_Tax,0)=0 Then Null
                               When nvl(G_Use_Vat,0) = 0      Then null
                               Else P_Clc_Typ_No_Tax end  ; 
   --##----------------------------------------------------------------------------------------------##--    
   If G_QT_Type Is Null Then
      P_Err_No := 20605;
      P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 2508) || Chr (10) || ' QT_TYPE IS NULL ';
      Goto Rtn_Rslt;
   Else     
        BEGIN 
             SELECT 1 INTO V_CNT 
              From Ias_Quot_Types
              WHERE Qt_Type=G_Qt_Type
              AND ROWNUM<=1;
        EXCEPTION WHEN OTHERS THEN            
            P_Err_No := 20606;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 5007)||CHR(10)||'QT_TYPE='||G_QT_TYPE;
            Goto Rtn_Rslt;         
         End ;
   End If;

   --##-----------------------------------------------------------------------------------------##--
   If P_Doc_No Is Not Null Then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          -- AND G_DOC_NO_PLCY = 1  THEN
      G_Doc_No := P_Doc_No;
   Else
      Get_Doc_No ( P_Doc_Typ  => G_Doc_Typ
                  ,P_Msg_Txt  => P_Msg_Txt
                  ,P_Err_No   => P_Err_No
                  ,P_Pkg_Nm   => P_Pkg_Nm);

       If P_Msg_Txt Is Not Null Then
          Goto Rtn_Rslt;
       End If;
   End If;  
   --##------------------------------------------------------------------------------------------------------------##--
   If nvl(G_Sys_no,0)=70 And G_Bill_Doc_Type=1 And G_C_Code Is Not Null and P_C_NAME is Not Null AND ( G_C_Code=nvl(G_DTS_C_CSH_CODE,'0') or Is_Csh_Cstmr(G_C_Code)=1) Then
     G_C_Code:=null;
     V_Cst_Nm:=P_C_Name;
   End if;
   
   If G_C_Code Is Not Null Then
      Gnr_Api_Pkg.Chk_Inpt_Data (P_Inpt_Typ     => 'C_CODE'
                                ,P_Sys_Typ      => 1
                                ,P_Doc_Type     => G_Doc_Typ
                                ,P_Inpt_Code1   => G_C_Code
                                ,P_Lng_Dflt     => G_Lng_Dflt
                                ,P_Inpt_Nm      => V_Cst_Nm
                                ,P_Msg_No       => V_Msg_No);

      If V_Msg_No Is Not Null Then
         P_Err_No := 20607;
         P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No);
         Goto Rtn_Rslt;
      End If;
   Else
      V_Cst_Nm := P_C_Name;
   End If;
   --##------------------------------------------------------------------------------------------------------------##--
  If G_Bill_Doc_Type=4 Then   
   If P_QUOT_Due_Date Is Not Null Then
      V_Doc_Due_Date := P_QUOT_Due_Date;
   Else
      If G_C_Code Is Not Null Then
         Begin
            Select Credit_Period
              Into V_Crdt_Prd_Day
              From Customer
             Where C_Code = P_C_Code And Rownum <= 1;
         Exception
            When Others Then
               Null;
         End;
      End If;

      --V_Doc_Due_Date := G_Doc_Date + Nvl (V_Crdt_Prd_Day, 0);
   End If;
 End if;
   --##------------------------------------------------------------------------------------------------------------##--
   If P_QUOT_Expire_Date Is Not Null Then
      V_QUOT_Exp_Date := P_QUOT_Expire_Date;
   ElsIf  G_Max_Prd_Exp_Sls_Quot_Day Is Not Null Then
       V_QUOT_Exp_Date:= G_Doc_Date+nvl(G_Max_Prd_Exp_Sls_Quot_Day,0);
   Else 
    V_QUOT_Exp_Date:=null;
   End If;
   
  

   If V_Doc_Due_Date Is Not Null And V_Doc_Due_Date < G_Doc_Date Then
      P_Err_No := 20608;
      P_Msg_Txt := 'Invalid Date (DOC_DUE_DATE) , Because DOC_DUE_DATE < DOC_DATE , ';
      Goto Rtn_Rslt;
   Elsif P_Cheque_Due_Date Is Not Null And P_Cheque_Due_Date < G_Doc_Date Then
      P_Err_No := 20609;
      P_Msg_Txt := 'Invalid Date (CHEQUE_DUE_DATE) , Because CHEQUE_DUE_DATE < DOC_DATE , ';
      Goto Rtn_Rslt;        
   Elsif V_QUOT_Exp_Date Is Not Null And V_QUOT_Exp_Date < G_Doc_Date Then
      P_Err_No := 20613;
      P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 1359);
      Goto Rtn_Rslt;
   ElsiF Nvl (G_Max_Prd_Exp_Sls_Quot_Day, 0) >0 And V_QUOT_Exp_Date Is not Null THEN
        IF (V_QUOT_Exp_Date )- (G_Doc_Date)>Nvl (G_Max_Prd_Exp_Sls_Quot_Day, 1)THEN
         P_Err_No := 20614;
         P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 1459);
         Goto Rtn_Rslt;      
        END IF;  
   ElsiF Nvl (G_Quot_Exp_Date_Mandtry, 0) =1 And V_QUOT_Exp_Date Is  Null THEN        
         P_Err_No := 20615;
         P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (G_Lng_No, 1601) || ' ' || Ias_Gen_Pkg.Get_Prompt (G_Lng_No, 5054);                            
   End If;   
   --##------------------------------------------------------------------------------------------------------------##--
   V_Msg_No := Null;

   If G_Use_Vat = 1 Then      
      If G_Clc_Typ_No_Tax Is Null Then
         P_Err_No := 20616;
         P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 1601) || ' ' || Ias_Gen_Pkg.Get_Prompt (G_Lng_No, 12526) || ' ,CLC_TYP_NO_TAX IS NULL ';
         Goto Rtn_Rslt;
      End If;
   Else
      G_Clc_Typ_No_Tax:=null;  
   End If;
   --##------------------------------------------------------------------------------------------------------------##--
   If G_Ar_Wc_Type = 1 Then
      G_W_Code := Nvl (G_W_Code, G_W_Code);
   Else
      G_W_Code := Nvl (G_W_Code, G_W_Code);
   End If;

   If Nvl (G_Ar_Wc_Type, 0) = 1 And nvl(G_AR_QT_WC_TYP,0)=1 And G_W_Code Is Null Then
      P_Err_No := 20617;
      P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 930);
      Goto Rtn_Rslt;
   End If;

   --##-----------------------------------------------------------------------------------------##--
   --## CHK ACCNT AND PYMNT
   Chk_Accnt (P_Cur_Code        => P_Cur_Code
             ,P_Cur_Rate        => G_Cur_Rate
             ,P_Stk_Rate        => G_Stk_Rate
             ,P_Cash_No         => P_Cash_No
             ,P_Bank_No         => Null                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     --P_BANK_NO
             ,P_C_Code          => G_C_Code
             ,P_Ac_Code         => Null
             ,P_Ac_Code_Dtl     => Null
             ,P_Ac_Dtl_Typ      => Null
             ,P_V_Code          => Null
             ,P_Bill_Doc_Type   => G_Bill_Doc_Type
             ,P_Doc_Amt         => P_DOC_Amt
             ,P_Msg_Txt         => P_Msg_Txt
             ,P_Err_No          => P_Err_No
             ,P_Pkg_Nm          => P_Pkg_Nm);

   If P_Msg_Txt Is Not Null Then
      Goto Rtn_Rslt;
   End If;
   --##------------------------------------------------------------------------------------------------------------##--
   If G_Use_Vat = 1 Then
      If G_Use_Price_Include_Vat = 1 Then
         G_Clc_Vat_Price_Typ := Nvl (P_Clc_Vat_Price_Typ, 2);
      Else
         G_Clc_Vat_Price_Typ := Nvl (P_Clc_Vat_Price_Typ, 1);
      End If;

      If G_Clc_Vat_Price_Typ Is Null Then
         P_Err_No := 20618;
         P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (G_Lng_No, 1601) || ' ' || Ias_Gen_Pkg.Get_Prompt (G_Lng_No, 11364) || Chr (10) || ' CLC_VAT_PRICE_TYP Is Null , ';
         Goto Rtn_Rslt;
      End If;
   Else
     G_Clc_Vat_Price_Typ:=1;     
   End If;

   --##------------------------------------------------------------------------------------------------------------##--
   --## CHK GNR DATA
   Chk_Gnr_Data (P_Brn_No           => G_Brn_No
                ,P_Ad_U_Id          => G_Ad_U_Id
                ,P_Emp_No           =>NULL
                ,P_Rep_Code         => G_Rep_Code
                ,P_Col_No           => G_Col_No
                ,P_R_Code           => NULL
                ,P_W_Code           => G_W_Code
                ,P_Clc_Typ_No_Tax   => G_Clc_Typ_No_Tax
                ,P_Msg_Txt          => P_Msg_Txt
                ,P_Err_No           => P_Err_No
                ,P_Pkg_Nm           => P_Pkg_Nm);

   If P_Msg_Txt Is Not Null Then
      Goto Rtn_Rslt;
   End If;

   --##-------------------------------------------------------------------------------------------------------------------------------##--
   --## SUB LDGR
   Gnr_Api_Pkg.Chk_Sub_Ldgr (P_Sys_Typ     => 1
                            ,P_Sys_No      => G_Sys_No
                            ,P_Doc_Type    => G_Doc_Typ
                            ,P_Cst_Type    => G_Ar_Cst_Type
                            ,P_Pj_Type     => G_Ar_Pj_Type
                            ,P_Actv_Type   => G_Ar_Actv_Type
                            ,P_Cc_Code     => G_Cc_Code
                            ,P_Pj_No       => G_Pj_No
                            ,P_Actv_No     => G_Actv_No
                            ,P_Rep_Code    => G_Rep_Code
                            ,P_A_Code      => G_A_Code
                            ,P_Chk_Ac_Cc   => 0
                            ,P_BILL_DOC_TYPE =>G_BILL_DOC_TYPE
                            ,P_C_CODE        =>G_C_CODE
                            ,P_P_Year        =>G_P_Year
                            ,P_Lng_No      => G_Lng_No
                            ,P_Msg_Txt     => P_Msg_Txt
                            ,P_Pkg_Line    => P_Err_No
                            ,P_Pkg_Nm      => P_Pkg_Nm);

   If P_Msg_Txt Is Not Null Then
      Goto Rtn_Rslt;
   End If;   
   --##--------------------------------------------------------------------------------------------------------##--
   If G_Si_Type Is Not Null Then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          -- SALES TYPE
      Gnr_Api_Pkg.Chk_Inpt_Data (P_Inpt_Typ     => 'SI_TYPE'
                                ,P_Sys_Typ      => 1
                                ,P_Doc_Type     => G_Doc_Typ
                                ,P_Inpt_Code1   => G_Si_Type
                                ,P_Lng_Dflt     => G_Lng_Dflt
                                ,P_Inpt_Nm      => G_Inpt_Nm
                                ,P_Msg_No       => V_Msg_No);

      If V_Msg_No Is Not Null Then
         P_Err_No := 20046;
         P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No) || ' , SI_TYPE ';
         Goto Rtn_Rslt;
      End If;
   End If;

   --##------------------------------------------------------------------------------------------------------------##--
   If Nvl (P_Vat_Amt, 0) < 0 Then
      P_Err_No := 20619;
      P_Msg_Txt := 'Invalid Value For (VAT_AMT) , Because VAT_AMT < 0  ';
      Goto Rtn_Rslt;
   End If;

   If Nvl (P_DOC_Amt, 0) < 0 Then
      P_Err_No := 20620;
      P_Msg_Txt := 'Invalid Value For (DOC_AMT) , Because DOC_AMT < 0  ';
      Goto Rtn_Rslt;
   End If;

   If Nvl (P_Disc_Amt_Mst, 0) < 0 Or Nvl (P_Disc_Amt_Dtl, 0) < 0 Or Nvl (P_Disc_Amt, 0) < 0 Then
      P_Err_No := 20621;
      P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 3312) || ' DISC_AMT_MST OR DISC_AMT_DTL OR DISC_AMT ';
      Goto Rtn_Rslt;
   End If;

   --##-----------------------------------------------------------------------------------------##--
   V_Doc_Dsc := P_A_Desc;

   --##-----------------------------------------------------------------------------------------##--
   If P_Sys_No = 61 Then
      V_Sys_No_Extrnl := Null;
      G_External_Post := 0;
   Else
      G_External_Post := G_Sys_No;
   End If;
   --##-----------------------------------------------------------------------------------------##--       
       Get_Doc_Ser ( P_Doc_Typ  => G_Doc_Typ
                    ,P_Msg_Txt  => P_Msg_Txt
                    ,P_Err_No   => P_Err_No
                    ,P_Pkg_Nm   => P_Pkg_Nm);

       If P_Msg_Txt Is Not Null Then
          Goto Rtn_Rslt;
       End If;
   
   --##-----------------------------------------------------------------------------------------##--
    Check_Duplicate ( P_Doc_Typ   => G_Doc_Typ
                      ,P_Doc_No    => G_Doc_No
                      ,P_Msg_Txt   => P_Msg_Txt
                      ,P_Err_No    => P_Err_No
                      ,P_Pkg_Nm    => P_Pkg_Nm);

   If P_Msg_Txt Is Not Null Then
      Goto Rtn_Rslt;
   End If;
  --##-----------------------------------------------------------------------------------------##--  
   --## CHK_MNDTRY_FLIDS
     ARS_API_CHK_PKG.Chk_Mndtry_Flids (P_Doc_Typ         => G_Doc_Typ
                    ,P_Rep_Code        => G_Rep_Code
                    ,P_Doc_Desc        => G_Doc_Dsc
                    ,P_Use_Vat           =>G_Use_Vat
                    ,P_Ref_No          => G_Ref_No
                    ,P_C_Code          => G_C_Code
                    ,P_Bill_Doc_Type   => G_Bill_Doc_Type
                    ,P_Lng_No          => G_Lng_No
                    ,P_Msg_Txt         => P_Msg_Txt
                    ,P_Err_No          => P_Err_No
                    ,P_Pkg_Nm          => P_Pkg_Nm);

   If P_Msg_Txt Is Not Null Then
      Goto Rtn_Rslt;
   End If;

   --##-----------------------------------------------------------------------------------------------##--
   --##CHK MNDTRY FLDS
   If G_Cmp_No Is Null Then
      P_Err_No := 20622;
      P_Msg_Txt := ' CMP_NO Is Null ';
      Goto Rtn_Rslt;
   End If;
   --##-----------------------------------------------------------------------------------------##--
   G_Ref_No := Null;
   --##-----------------------------------------------------------------------------------------##--
    If nvl(G_use_Vat,0)=1 Then 
       IF NVL(G_SYS_NO,0)=70 THEN 
         G_CLC_TAX_FREE_QTY_FLG:=NVL(P_CLC_TAX_FREE_QTY_FLG,0);
       ELSE 
          G_CLC_TAX_FREE_QTY_FLG:=G_USE_CLC_TAX_FREE_QTY;
       END IF; 
    Else
     G_CLC_TAX_FREE_QTY_FLG:=0;
    End If;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            -- P_REF_NO;
   --##-----------------------------------------------------------------------------------------##--  
   Insert Into QUOTATION ( QUOT_No
                           ,QUOT_Ser
                           ,QUOT_Date
                           ,QUOT_Cur
                           ,Cur_Rate                        
                           ,QT_TYPE
                           ,C_Code
                           ,C_Name
                           ,A_Desc
                           ,Cc_Code
                           ,Pj_No
                           ,Actv_No
                           ,W_Code
                           ,Rep_Code                        
                           ,Vat_Amt
                           ,QUOT_Amt
                           ,Disc_Amt
                           ,Disc_Amt_Dtl
                           ,Disc_Amt_Mst
                           ,Othr_Amt
                           ,Vat_Amt_Othr
                           ,Othr_Amt_Disc
                           ,Disc_Amt_Mst_Vat
                           ,Vat_Amt_Disc_Mst
                           --,Disc_Amt_Aftr_Vat
                           --,Cash_No
                           ,Clc_Typ_No_Tax
                           ,Clc_Vat_Price_Typ                                                                           
                           ,QUOT_Doc_Type
                           ,QUOT_Due_Date
                           ,QUOT_Expire_Date
                           ,Cheque_Due_Date                       
                           ,Si_Type
                           ,External_Post
                           ,Field1
                           ,Field2
                           ,Field3
                           ,Field4
                           ,Field5
                           ,Field6
                           ,Field7
                           ,Field8
                           ,Field9
                           ,Field10
                           ,PROCESSED                         
                           ,Approved
                           ,CLC_TAX_FREE_QTY_FLG                         
                           ,Doc_Ser_Extrnl
                           ,PAY_TERMS    
                            ,REQ_DAYS
                            ,REF_NO
                           , REF_DATE
                           , QUOT_TEND
                           , QUOT_TEND_DATE
                           , PORT_OF_DEP
                           ,Cmp_No
                           ,Brn_No
                           ,Brn_Year
                           ,Brn_Usr
                           ,Ad_Trmnl_Nm
                           ,Ad_U_Id
                           ,Ad_Date)
        Values (G_Doc_No
               ,G_Doc_Ser
               ,G_Doc_Date
               ,P_Cur_Code
               ,G_Cur_Rate             
               ,G_QT_Type
               ,G_C_Code
               ,V_Cst_Nm
               ,V_Doc_Dsc
               ,Decode (G_Ar_Cst_Type, 1, G_Cc_Code, Null)
               ,Decode (G_Ar_Pj_Type, 1, G_Pj_No, Null)
               ,Decode (G_Ar_Actv_Type, 1, G_Actv_No, Null)
               ,Decode (G_Ar_Wc_Type, 1, G_W_Code, Null)
               ,G_Rep_Code             
               ,P_Vat_Amt
               ,Round (Nvl (P_DOC_Amt, 0), G_No_Of_Decimal_Ar)
               ,P_Disc_Amt
               ,P_Disc_Amt_Dtl
               ,P_Disc_Amt_Mst
               ,P_Othr_Amt
               ,P_Vat_Amt_Othr
               ,P_Othr_Amt_Disc
               ,P_Disc_Amt_Mst_Vat
               ,P_Vat_Amt_Disc_Mst
              -- ,P_Disc_Amt_Aftr_Vat
             --  ,P_Cash_No
               ,G_Clc_Typ_No_Tax
               ,nvl(G_Clc_Vat_Price_Typ,1)                                         
               ,G_Bill_Doc_Type
               ,V_Doc_Due_Date
               ,V_QUOT_Exp_Date
               ,P_Cheque_Due_Date               
               ,P_Si_Type
               ,G_External_Post
               ,P_Field1
               ,P_Field2
               ,P_Field3
               ,P_Field4
               ,P_Field5
               ,P_Field6
               ,P_Field7
               ,P_Field8
               ,P_Field9
               ,P_Field10
               ,0               
               ,0
               ,NVL(G_CLC_TAX_FREE_QTY_FLG,0)               
               ,P_Doc_Ser_Extrnl
               ,P_PAY_TERMS    
               ,P_REQ_DAYS
               ,P_REF_NO
               ,P_REF_DATE
               ,P_QUOT_TEND
               ,P_QUOT_TEND_DATE
               ,P_PORT_OF_DEP
               ,G_Cmp_No
               ,G_Brn_No
               ,G_Brn_Year
               ,G_Brn_Usr
               ,P_Ad_Trmnl_Nm
               ,G_Ad_U_Id
               ,G_Ad_Date);

  --####################--
  <<RTN_RSLT>>
   If P_Msg_Txt Is Not Null OR P_Err_No Is Not Null Then
      Rollback;
      P_Msg_Txt := NVL(P_Msg_Txt,'Message Number Is Missing');
      P_Err_No := P_Err_No;
      P_Pkg_Nm := Nvl (P_Pkg_Nm, 'Ars_Api_Trns_Pkg.Insrt_QUOTATION');
      Return;
   End If;
--####################--

Exception
   When Others Then
      Rollback;
      P_Msg_Txt := 'Error When Insert Into QUOTATION Master , ' || Chr(10) || Sqlerrm;
      P_Err_No := 20623;
      P_Pkg_Nm := Nvl (P_Pkg_Nm, 'Ars_Api_Trns_Pkg.Insrt_QUOTATION');
End Insrt_QUOTATION;

--##------------------------------------------------------------------------------------------------------------------------------------------------##--
  Procedure Insrt_QUOTATION_DETAIL (P_I_Code                 In     Order_Detail.I_Code%Type Default Null
                             ,P_Itm_Unt                In     Order_Detail.Itm_Unt%Type Default Null
                             ,P_I_Qty                  In     Order_Detail.I_Qty%Type Default Null
                             ,P_P_Qty                  In     Order_Detail.P_Qty%Type Default Null
                             ,P_P_Size                 In     Order_Detail.P_Size%Type Default Null
                             ,P_Free_Qty               In     Order_Detail.Free_Qty%Type Default Null
                             ,P_Barcode                In     Order_Detail.Barcode%Type Default Null
                             ,P_Batch_No               In     Order_Detail.Batch_No%Type Default Null
                             ,P_Expire_Date            In     Order_Detail.Expire_Date%Type Default Null
                             ,P_W_Code                 In     Order_Detail.W_Code%Type Default Null
                             ,P_Cc_Code                In     Order_Detail.Cc_Code%Type Default Null
                             ,P_Actv_No                In     Order_Detail.Actv_No%Type Default Null
                             ,P_Pj_No                  In     Order_Detail.Pj_No%Type Default Null
                             ,P_I_Price                In     Order_Detail.I_Price%Type Default Null
                             ,P_I_Price_Vat            In     Order_Detail.I_Price_Vat%Type Default Null
                             ,P_Measur_Price           In     Order_Detail.Measur_Price%Type Default Null
                             ,P_Othr_Amt               In     Order_Detail.Othr_Amt%Type Default Null
                             ,P_Othr_Amt_Disc          In     Order_Detail.Othr_Amt_Disc%Type Default Null
                             ,P_Vat_Amt                In     Order_Detail.Vat_Amt%Type Default Null
                             ,P_Vat_Amt_Aftr_Dis       In     Order_Detail.Vat_Amt_Aftr_Dis%Type Default Null
                             ,P_Vat_Amt_Bfr_Dis        In     Order_Detail.Vat_Amt_Bfr_Dis%Type Default Null
                             ,P_Vat_Amt_Dis_Dtl2_Vat   In     Order_Detail.Vat_Amt_Dis_Dtl2_Vat%Type Default Null
                             ,P_Vat_Amt_Dis_Dtl3_Vat   In     Order_Detail.Vat_Amt_Dis_Dtl3_Vat%Type Default Null
                             ,P_Vat_Amt_Dis_Dtl_Vat    In     Order_Detail.Vat_Amt_Dis_Dtl_Vat%Type Default Null
                             ,P_Vat_Amt_Dis_Mst_Vat    In     Order_Detail.Vat_Amt_Dis_Mst_Vat%Type Default Null
                             ,P_Vat_Amt_Othr           In     Order_Detail.Vat_Amt_Othr%Type Default Null
                             ,P_Vat_Per                In     Order_Detail.Vat_Per%Type Default Null
                             ,P_Dis_Amt                In     Order_Detail.Dis_Amt%Type Default Null
                             ,P_Dis_Amt_Aftr_Vat       In     Order_Detail.Dis_Amt_Aftr_Vat%Type Default Null
                             ,P_Dis_Amt_Dtl            In     Order_Detail.Dis_Amt_Dtl%Type Default Null
                             ,P_Dis_Amt_Dtl2           In     Order_Detail.Dis_Amt_Dtl2%Type Default Null
                             ,P_Dis_Amt_Dtl2_Vat       In     Order_Detail.Dis_Amt_Dtl2_Vat%Type Default Null
                             ,P_Dis_Amt_Dtl3           In     Order_Detail.Dis_Amt_Dtl3%Type Default Null
                             ,P_Dis_Amt_Dtl3_Vat       In     Order_Detail.Dis_Amt_Dtl3_Vat%Type Default Null
                             ,P_Dis_Amt_Dtl_Vat        In     Order_Detail.Dis_Amt_Dtl_Vat%Type Default Null
                             ,P_Dis_Amt_Mst            In     Order_Detail.Dis_Amt_Mst%Type Default Null
                             ,P_Dis_Amt_Mst_Vat        In     Order_Detail.Dis_Amt_Mst_Vat%Type Default Null
                             ,P_Dis_Per                In     Order_Detail.Dis_Per%Type Default Null
                             ,P_Dis_Per2               In     Order_Detail.Dis_Per2%Type Default Null
                             ,P_Dis_Per3               In     Order_Detail.Dis_Per3%Type Default Null
                             ,P_Doc_No_Ref             In     Order_Detail.Doc_No_Ref%Type Default Null
                             ,P_Doc_Sequence           In OUT QUOTATION_DETAIL.Doc_Sequence%Type
                             ,P_Rcrd_No                In Out Order_Detail.Rcrd_NO%Type 
                             ,P_Doc_Sequence_Ref       In     Order_Detail.Doc_Sequence_Ref%Type Default Null
                             ,P_Doc_Ser_Ref            In     Order_Detail.Doc_Ser_Ref%Type Default Null
                             ,P_Doc_Type_Ref           In     Order_Detail.Doc_Type_Ref%Type Default Null
                             ,P_Rcrd_No_Ref            In     Ias_Bill_Dtl.Rcrd_No_Ref%Type Default Null
                             ,P_Emp_No                 In     Order_Detail.Emp_No%Type Default Null
                             ,P_External_Post          In     Order_Detail.External_Post%Type Default Null
                             ,P_Field_Dtl1             In     Order_Detail.Field_Dtl1%Type Default Null
                             ,P_Field_Dtl2             In     Order_Detail.Field_Dtl2%Type Default Null
                             ,P_Field_Dtl3             In     Order_Detail.Field_Dtl3%Type Default Null
                             ,P_F_Time                 In     Order_Detail.F_Time%Type Default Null
                             ,P_T_Time                 In     Order_Detail.T_Time%Type Default Null
                             ,P_Item_Desc              In     Order_Detail.Item_Desc%Type Default Null
                             ,P_I_Width                In     Order_Detail.I_Width%Type Default Null
                             ,P_I_Height               In     Order_Detail.I_Height%Type Default Null
                             ,P_I_Length               In     Order_Detail.I_Length%Type Default Null
                             ,P_I_Number               In     Order_Detail.I_Number%Type Default Null
                             ,P_Argmnt_No              In     Order_Detail.Argmnt_No%Type Default Null 
                             ,P_Wt_Qty                 In     QUOTATION_DETAIL.Wt_Qty%Type Default Null
                             ,P_Wt_Unt                 In     QUOTATION_DETAIL.Wt_Unt%Type Default Null                                                       
                             ,P_Rec_Attch              In     Order_Detail.Rec_Attch%Type Default Null
                             ,P_Reserved               In     Order_Detail.Reserved%Type Default Null
                             ,P_Res_Date               In     Order_Detail.Res_Date%Type Default Null
                             ,P_Res_Qty                In     Order_Detail.Res_Qty%Type Default Null
                             ,P_Lev_No                 In     Order_Detail.Lev_No%Type Default Null
                             ,P_PRM_GRP_NO             In     Order_Detail.PRM_GRP_NO%Type Default Null
                             ,P_QT_PRM_RCRD_NO         In     Order_Detail.QT_PRM_RCRD_NO%Type Default Null
                             ,P_QT_PRM_SER             In     Order_Detail.QT_PRM_SER%Type Default Null
                             ,P_Dis_Amt_Dtl_Qt_Prm     In     Order_Detail.Dis_Amt_Dtl_Qt_Prm%Type Default Null
                             ,P_Dis_Amt_Dtl_Qt_Prm_Vat In     Order_Detail.Dis_Amt_Dtl_Qt_Prm_Vat%Type Default Null
                             ,P_Dis_Per_Qt_Prm         In   Order_Detail.Dis_Per_Qt_Prm%Type Default Null
                             ,P_Msg_Txt                   Out Varchar2
                             ,P_Err_No                    Out Varchar2
                             ,P_Pkg_Nm                    Out Varchar2)
Is
   V_P_Size     Ias_Itm_Dtl.P_Size%Type;
   V_Cnt        Number;
   V_Msg_No     Number;
   V_Stkcost    Order_Detail.Stk_Cost%Type;
   V_Res_Qty    Order_Detail.Res_Qty%Type;
   V_Doc_Seq    Order_Detail.Doc_Seq%Type;
   V_I_Price    Number:=P_I_Price;
   V_I_Price_Vat  Number:=p_I_Price_Vat;
   V_Vat_Per    Number;
   V_Clc_Typ_No Number;
     
Begin
   --##---------------------------------------------------------------------------------------------------------------------------##--
   If G_Doc_Ser Is Null Or G_Doc_No Is Null Then
      P_Err_No := 20625;
      P_Msg_Txt := 'G_DOC_SER OR G_DOC_NO .. IS NULL ';
      Goto Rtn_Rslt;
   End If;

   --##---------------------------------------------------------------------------------------------------------------------------##--
   If G_Ar_Wc_Type = 1 Then
      G_W_Code := Nvl(G_W_Code,P_W_Code);
   Else
      G_W_Code := Nvl (P_W_Code, G_W_Code);
      If G_W_Code Is Not Null Then
        GNR_API_PKG.Chk_Inpt_Data (P_Inpt_Typ     => 'W_CODE'
                                   ,P_SYS_TYP      =>1
                                   ,P_DOC_TYPE     => G_DOC_TYP
                                   ,P_Inpt_Code1   => G_W_Code
                                   ,P_Inpt_Code2   => G_Brn_No
                                   ,P_Inpt_Code3   => G_ALLW_SAL_WH_NOT_CONN_BRN
                                   ,P_Inpt_Code4   => G_USE_BALANCED_BRN
                                   ,P_Lng_Dflt     => G_Lng_No
                                   ,P_Inpt_Nm      => G_Inpt_Nm
                                   ,P_Msg_No       => V_Msg_No);

         If V_Msg_No Is Not Null Then
            P_Err_No := 20738;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No) || ' W_CODE=' || G_W_Code;
            Goto Rtn_Rslt;
         End If;
      END IF;
   End If;

   If G_W_Code Is Null Then
      P_Err_No := 20626;
      P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 930);
      Goto Rtn_Rslt;
   End If;

   --##---------------------------------------------------------------------------------------------------------------------------##--
   If Nvl (G_Use_Vat, 0) = 1 And G_Clc_Typ_No_Tax Is Not Null And Nvl (G_Clc_Tax_Method, 0) = 1 Then       
         If Nvl (Ys_Tax_Pkg.Get_Clc_Tax_Typ (P_Clc_Typ_No => G_Clc_Typ_No_Tax), 0) = 0 Then
            -- V_Vat_Per   := Ys_Tax_Pkg.Get_Itm_Tax_Prcnt (P_Clc_Typ_No => G_Clc_Typ_No_Tax, P_I_Code => P_I_Code, P_Clc_Usd_Itm => 1);
              V_Vat_Per   :=Ys_Tax_Pkg.Get_Itm_Tax_Prcnt_Sal ( P_Clc_Typ_No =>G_Clc_Typ_No_Tax  
                                                             , P_I_Code => P_I_CODE 
                                                              ,P_Clc_Usd_Itm => 1
                                                              ,P_I_Price=>P_I_Price
                                                              ,P_I_Price_Vat =>case when Nvl(G_Clc_Vat_Price_Typ,0) = 2 Then (Case when nvl(P_I_Price_Vat,0) =0 Then Nvl (P_I_Price, 0) Else Nvl (P_I_Price_Vat, 0) end) else Nvl (P_I_Price, 0) end  
                                                              ,P_Use_Price_Include_Vat=> case when Nvl(G_Clc_Vat_Price_Typ,0) = 2 then 1 else 0 end ); 
          Else
             V_Clc_Typ_No   := Ys_Tax_Pkg.Get_Clc_Typ_No_Exmpt (P_Clc_Typ_No => G_Clc_Typ_No_Tax);
            -- V_Vat_Per      := Ys_Tax_Pkg.Get_Itm_Tax_Prcnt (P_Clc_Typ_No => V_Clc_Typ_No, P_I_Code => P_I_Code, P_Clc_Usd_Itm => 1);
            V_Vat_Per   :=Ys_Tax_Pkg.Get_Itm_Tax_Prcnt_Sal ( P_Clc_Typ_No =>V_Clc_Typ_No  
                                                             , P_I_Code => P_I_CODE 
                                                              ,P_Clc_Usd_Itm => 1
                                                              ,P_I_Price=>P_I_Price
                                                              ,P_I_Price_Vat =>case when Nvl(G_Clc_Vat_Price_Typ,0) = 2 Then (Case when nvl(P_I_Price_Vat,0) =0 Then Nvl (P_I_Price, 0) Else Nvl (P_I_Price_Vat, 0) end) else Nvl (P_I_Price, 0) end  
                                                              ,P_Use_Price_Include_Vat=> case when Nvl(G_Clc_Vat_Price_Typ,0) = 2 then 1 else 0 end );
          End If;
          If nvl(V_Vat_Per,0)>0 And Nvl(G_Clc_Vat_Price_Typ,0) = 2 Then   
           
             V_I_Price_Vat := Case when nvl(P_I_Price_Vat,0) =0 Then Nvl (P_I_Price, 0) Else Nvl (P_I_Price_Vat, 0) End;
             V_I_Price   := Nvl (V_I_Price_Vat, 0) / ( (Nvl (V_Vat_Per, 0) / 100) + 1);
          Else
             V_I_Price   := P_I_Price;
          End If;
   Else
          V_I_Price   := P_I_Price;
          V_Vat_Per   := P_Vat_Per;
   End If;
   --##---------------------------------------------------------------------------------------------------------------------------##--
   --## CHK ITM DATA
   Gnr_Api_Pkg.Chk_Itm (P_Sys_No              => G_Sys_No
                       ,P_Sys_Typ             => 1 --##    P_SYS_TYP =  1 = SALE , 2= STOCKE ,3 = PURCHASE ,
                       ,P_Trns_Typ            => -1 --##.    (1=IN)(-1=OUT)
                       ,P_Doc_Type            => G_Doc_Typ
                       ,P_I_Code              => P_I_Code
                       ,P_Itm_Unt             => P_Itm_Unt
                       ,P_P_Size              => P_P_Size
                       ,P_I_Qty               => P_I_Qty
                       ,P_Free_Qty            => P_Free_Qty
                       ,P_Res_Qty             => P_I_Qty
                       ,P_I_Price             => V_I_Price
                       ,P_I_Price_Vat         => V_I_Price_Vat
                       ,P_Measur_Price        => P_Measur_Price
                       ,P_Lev_No              => P_Lev_No
                       ,P_Qt_Prm_Method       => Null
                       ,P_Qut_Prm_Price       => Null
                       ,P_Qt_Prm_Ser          => P_Qt_Prm_Ser
                       ,P_Dis_Per             => P_Dis_Per
                       ,P_Dis_Amt_Dtl         => P_Dis_Amt_Dtl
                       ,P_Dis_Amt_Dtl_Vat     => P_Dis_Amt_Dtl_Vat
                       ,P_Dis_Per2            => P_Dis_Per2
                       ,P_Dis_Amt_Dtl2        => P_Dis_Amt_Dtl2
                       ,P_Dis_Amt_Dtl2_Vat    => P_Dis_Amt_Dtl2_Vat
                       ,P_Dis_Per3            => P_Dis_Per3
                       ,P_Dis_Amt_Dtl3        => P_Dis_Amt_Dtl3
                       ,P_Dis_Amt_Dtl3_Vat    => P_Dis_Amt_Dtl3_Vat
                       ,P_Dis_Amt_Mst         => P_Dis_Amt_Mst
                       ,P_W_Code              => G_W_Code
                       ,P_Expire_Date         => P_Expire_Date
                       ,P_Batch_No            => P_Batch_No
                       ,P_Brn_No              => G_Brn_No
                       ,P_Doc_Date            => G_Doc_Date
                       ,P_Doc_Ser             => G_Doc_Ser                    
                       ,P_C_Code              => G_C_Code
                       ,P_Cur_Code            => G_Cur_Code
                       ,P_Ac_Rate             => G_Cur_Rate
                       ,P_Usr_No              => G_Ad_U_Id
                       ,P_Clc_Vat_Price_Typ   => Nvl (G_Clc_Vat_Price_Typ, 1)
                       ,P_Bill_Doc_Type       => G_Bill_Doc_Type
                       ,P_Stk_Cost            => Null
                       ,P_Chk_Avlqty_Flg      => 0
                       ,P_Chk_Itm_Price       => G_Chk_Itm_Price --# 0 nocheck 1 check
                       ,P_Use_Vat             =>G_USE_VAT
                       ,P_Clc_Typ_No_Tax      =>G_Clc_Typ_No_Tax 
                       ,P_Lng_No              => G_Lng_No
                       ,P_Msg_Txt             => P_Msg_Txt
                       ,P_Pkg_Line            => P_Err_No
                       ,P_Pkg_Nm              => P_Pkg_Nm);

   If P_Msg_Txt Is Not Null Then
      Goto Rtn_Rslt;
   End If;

   V_P_Size := Ias_Itm_Pkg.Get_Icode_Size_Unit (P_I_Code => P_I_Code, P_Itm_Unt => P_Itm_Unt);        
   --##-------------------------------------------------------------------------------------------------------------------------------##--
    If Nvl(V_P_Size,0)=0 Then
             P_Err_No    := 20671;
             P_MSG_TXT :='P_Size=0 For I_Code='||p_i_code;
            Goto Rtn_Rslt;                                                      
     End If;
    --##-------------------------------------------------------------------------------------------------------------------------------##--
   --## SUB LDGR
      If G_Ar_Cst_Type = 2 Then
         G_Dtl_Cc_Code   := nvl(P_Cc_Code,G_Cc_Code);
      Else
         G_Dtl_Cc_Code   := G_Cc_Code;   
      End If;

      If G_Ar_Pj_Type = 2 Then
         G_Dtl_Pj_No   := nvl(P_Pj_No,G_Pj_No);
      Else
          G_Dtl_Pj_No   := G_Pj_No;
      End If;

      If G_Ar_Actv_Type = 2 Then
         G_Dtl_Actv_No   := nvl(P_Actv_No,G_Actv_No);
      Else
          G_Dtl_Actv_No   := G_Actv_No;         
      End If;

   Gnr_Api_Pkg.Chk_Sub_Ldgr (P_Sys_Typ     => 1
                            ,P_Sys_No      => G_Sys_No
                            ,P_Doc_Type    => G_Doc_Typ
                            ,P_Cst_Type    => G_Ar_Cst_Type
                            ,P_Pj_Type     => G_Ar_Pj_Type
                            ,P_Actv_Type   => G_Ar_Actv_Type
                            ,P_Cc_Code     => G_Dtl_Cc_Code
                            ,P_Pj_No       => G_Dtl_Pj_No
                            ,P_Actv_No     => G_Dtl_Actv_No
                            ,P_Rep_Code    => G_Rep_Code
                            ,P_A_Code      => G_A_Code
                            ,P_Chk_Ac_Cc   => 0
                            ,P_BILL_DOC_TYPE =>G_BILL_DOC_TYPE
                            ,P_C_CODE        =>G_C_CODE
                            ,P_P_Year        =>G_P_Year
                            ,P_Lng_No      => G_Lng_No
                            ,P_Msg_Txt     => P_Msg_Txt
                            ,P_Pkg_Line    => P_Err_No
                            ,P_Pkg_Nm      => P_Pkg_Nm);

   If P_Msg_Txt Is Not Null Then
      Goto Rtn_Rslt;
   End If;

   --##--------------------------------------------------------------------------------------------------------------------------------##--
   --## Update Doc Ref
            Update_Doc_Ref    ( P_Doc_Type           =>G_Doc_Typ
                               ,P_Pst_Typ            =>G_Pst_Typ
                               ,P_Doc_Ser            =>G_Doc_Ser
                               ,P_I_Code             =>P_I_Code
                               ,P_Itm_Unt            =>P_Itm_Unt
                               ,P_P_Size             =>V_P_Size
                               ,P_I_Qty              =>P_I_Qty
                               ,P_Free_Qty           =>P_Free_Qty
                               ,P_Rcrd_No            =>G_Rcrd_No
                               ,P_Doc_Type_Ref       =>P_Doc_Type_Ref
                               ,P_Doc_No_Ref         =>P_Doc_No_Ref
                               ,P_Doc_Ser_Ref        =>P_Doc_Ser_Ref
                               ,P_Rcrd_No_Ref        =>P_Rcrd_No_Ref
                               ,P_Msg_Txt            =>P_Msg_Txt
                               ,P_Err_No              =>P_Err_No
                               ,P_Pkg_Nm              =>P_Pkg_Nm);
      If P_Msg_Txt Is Not Null Then
         Goto Rtn_Rslt;
      End If;        
   --##--------------------------------------------------------------------------------------------------------------------------------##--
   -- If P_Doc_Seq Is Null Then
   Begin
      Select Ias_Doc_Seq_Othr.Nextval Into V_Doc_Seq From Dual;
   Exception
      When Others Then
         P_Msg_Txt := 'Err. When Get DOC_SEQ' || Chr (10) || Sqlerrm;
         P_Err_No := 20630;
         Goto Rtn_Rslt;
   End;

   P_Doc_Sequence := V_Doc_Seq; 
   --##--------------------------------------------------------------------------------------------------------------------------------##--
   G_Rcrd_No := Nvl (G_Rcrd_No, 0) + 1;
   P_Rcrd_No :=G_Rcrd_No;
   --##---------------------------------------------------------------------------------------------------------------------------##--
   Insert Into QUOTATION_DETAIL (QT_Type
                            ,QUOT_No
                            ,QUOT_Ser                       
                            ,I_Code
                            ,Itm_Unt
                            ,I_Qty
                            ,Free_Qty
                            ,P_Size
                            ,P_Qty
                            ,I_Price                         
                            ,W_Code                     
                            ,Rcrd_No
                            ,Barcode
                            ,Item_Desc
                            ,External_Post                         
                            ,Expire_Date
                            ,Batch_No
                            ,Vat_Per
                            ,Vat_Amt
                            ,I_Length
                            ,I_Width
                            ,I_Height
                            ,I_Number
                            ,Field_Dtl1
                            ,Field_Dtl2
                            ,Field_Dtl3
                            ,Dis_Per
                            ,Dis_Amt_Dtl
                            ,Dis_Per2
                            ,Dis_Amt_Dtl2
                            ,Dis_Per3
                            ,Dis_Amt_Dtl3
                            ,Dis_Amt
                            ,Dis_Amt_Mst                          
                            ,DOC_SEQUENCE                           
                            ,Othr_Amt
                            ,Si_Type
                            ,I_Price_Vat
                            ,Argmnt_No
                            ,Wt_Qty 
                            ,Wt_Unt 
                            ,Cc_Code
                            ,Doc_Type_Ref
                            ,Doc_No_Ref
                            ,Doc_Ser_Ref
                          --  ,Doc_Sequence_Ref
                            ,Stk_Cost
                            ,Othr_Amt_Disc
                            ,Vat_Amt_Othr
                            --,F_Time
                           -- ,T_Time
                            ,Dis_Amt_Dtl_Vat
                            ,Dis_Amt_Mst_Vat
                            ,Vat_Amt_Dis_Dtl_Vat
                            ,Vat_Amt_Aftr_Dis
                            ,Vat_Amt_Bfr_Dis
                            ,Vat_Amt_Dis_Mst_Vat 
                            ,Pj_No
                            ,Actv_No
                           -- ,Dis_Amt_Aftr_Vat
                            ,Dis_Amt_Dtl2_Vat
                            ,Dis_Amt_Dtl3_Vat
                            ,Vat_Amt_Dis_Dtl2_Vat
                            ,Vat_Amt_Dis_Dtl3_Vat
                           , Lev_No
                           -- ,PRM_GRP_NO             
                           -- ,QT_PRM_RCRD_NO          
                           -- ,QT_PRM_SER              
                           -- ,Dis_Amt_Dtl_Qt_Prm      
                           -- ,Dis_Amt_Dtl_Qt_Prm_Vat  
                          --  ,Dis_Per_Qt_Prm                           
                            ,Cmp_No
                            ,Brn_No
                            ,Brn_Year
                            ,Brn_Usr)
        Values (G_QT_Type
               ,G_Doc_No
               ,G_Doc_Ser            
               ,P_I_Code
               ,P_Itm_Unt
               ,P_I_Qty
               ,P_Free_Qty
               ,V_P_Size
               ,(P_I_Qty * V_P_Size)
               ,V_I_Price              
               ,G_W_Code              
               ,G_Rcrd_No
               ,P_Barcode
               ,P_Item_Desc
               ,G_External_Post               
               ,Nvl (P_Expire_Date, '01/01/1900')
               ,Nvl (P_Batch_No, '0')
               ,P_Vat_Per
               ,Nvl (P_Vat_Amt, 0)
               ,P_I_Length
               ,P_I_Width
               ,P_I_Height
               ,P_I_Number
               ,P_Field_Dtl1
               ,P_Field_Dtl2
               ,P_Field_Dtl3
               ,P_Dis_Per
               ,P_Dis_Amt_Dtl
               ,P_Dis_Per2
               ,P_Dis_Amt_Dtl2
               ,P_Dis_Per3
               ,P_Dis_Amt_Dtl3
               ,P_Dis_Amt
               ,P_Dis_Amt_Mst              
               ,V_Doc_Seq               
               ,Nvl (P_Othr_Amt, 0)
               ,G_Si_Type
               ,V_I_Price_Vat
               ,P_Argmnt_No
               ,P_Wt_Qty 
               ,P_Wt_Unt 
               ,G_Dtl_Cc_Code
               ,P_Doc_Type_Ref
               ,P_Doc_No_Ref
               ,P_Doc_Ser_Ref
              -- ,P_Doc_Sequence_Ref
               ,V_Stkcost
               ,P_Othr_Amt_Disc
               ,P_Vat_Amt_Othr
             --  ,P_F_Time
              -- ,P_T_Time
               ,P_Dis_Amt_Dtl_Vat
               ,P_Dis_Amt_Mst_Vat
               ,P_Vat_Amt_Dis_Dtl_Vat
               ,P_Vat_Amt_Aftr_Dis
               ,P_Vat_Amt_Bfr_Dis
               ,P_Vat_Amt_Dis_Mst_Vat 
               ,G_Dtl_Pj_No
               ,G_Dtl_Actv_No
               --,P_Dis_Amt_Aftr_Vat
               ,P_Dis_Amt_Dtl2_Vat
               ,P_Dis_Amt_Dtl3_Vat
               ,P_Vat_Amt_Dis_Dtl2_Vat
               ,P_Vat_Amt_Dis_Dtl3_Vat
               ,P_Lev_No
              -- ,P_PRM_GRP_NO             
               -- ,P_QT_PRM_RCRD_NO          
               -- ,P_QT_PRM_SER              
             --  ,P_Dis_Amt_Dtl_Qt_Prm      
               -- ,P_Dis_Amt_Dtl_Qt_Prm_Vat  
               -- ,P_Dis_Per_Qt_Prm                
               ,G_Cmp_No
               ,G_Brn_No
               ,G_Brn_Year
               ,G_Brn_Usr);                 
   ---------------------------------------------------------------
  --####################--
  <<RTN_RSLT>>
   If P_Msg_Txt Is Not Null OR P_Err_No Is Not Null Then
      Rollback;
      P_Msg_Txt := NVL(P_Msg_Txt,'Message Number Is Missing');
      P_Err_No := P_Err_No;
      P_Pkg_Nm := Nvl (P_Pkg_Nm, 'Ars_Api_Trns_Pkg.INSRT_QUOTATION_DETAIL');
      Return;
   End If;
--####################--

Exception
   When Others Then
      Rollback;
      P_Msg_Txt := 'Error When Insert Into QUOTATION_DETAIL , ' || Chr(10) || Sqlerrm;
      P_Err_No := 20631;
      P_Pkg_Nm := Nvl (P_Pkg_Nm, 'Ars_Api_Trns_Pkg.INSRT_QUOTATION_DETAIL');
End INSRT_QUOTATION_DETAIL;
--##-----------------------------------------------------------------------------------------------------##--

   Procedure Insrt_Ias_Bill_Mst (P_Sys_No                       In     Number
                             ,P_Doc_Type                     In     Number
                             ,P_Bill_Doc_Type                In     Ias_Bill_Mst.Bill_Doc_Type%Type Default Null
                             ,P_Doc_No                       In     Ias_Bill_Mst.Bill_No%Type Default Null
                             ,P_Doc_Ser                      In     Ias_Bill_Mst.Bill_Ser%Type Default Null
                             ,P_Doc_Date                     In     Ias_Bill_Mst.Bill_Date%Type Default Null
                             ,P_Cur_Code                     In     Ias_Bill_Mst.Bill_Currency%Type Default Null
                             ,P_Cur_Rate                     In     Ias_Bill_Mst.Bill_Rate%Type Default Null
                             ,P_Stock_Rate                   In     Ias_Bill_Mst.Stock_Rate%Type Default Null
                             ,P_C_Code                       In     Ias_Bill_Mst.C_Code%Type Default Null
                             ,P_C_Name                       In     Ias_Bill_Mst.C_Name%Type Default Null
                             ,P_A_Code                       In     Ias_Bill_Mst.A_Code%Type Default Null
                             ,P_Cheque_No                    In     Ias_Bill_Mst.Cheque_No%Type Default Null
                             ,P_Note_No                      In     Ias_Bill_Mst.Note_No%Type Default Null
                             ,P_Cheque_Due_Date              In     Ias_Bill_Mst.Cheque_Due_Date%Type Default Null
                             ,P_Bill_Due_Date                In     Ias_Bill_Mst.Bill_Due_Date%Type Default Null
                             ,P_W_Code                       In     Ias_Bill_Mst.W_Code%Type Default Null
                             ,P_R_Code                       In     Ias_Bill_Mst.R_Code%Type Default Null
                             ,P_Rep_Code                     In     Ias_Bill_Mst.Rep_Code%Type Default Null
                             ,P_Emp_No                       In     Ias_Bill_Mst.Emp_No%Type Default Null
                             ,P_Ref_No                       In     Ias_Bill_Mst.Ref_No%Type Default Null
                             ,P_Cash_No                      In     Ias_Bill_Mst.Cash_No%Type Default Null
                             ,P_Cc_Code                      In     Ias_Bill_Mst.Cc_Code%Type Default Null
                             ,P_Pj_No                        In     Ias_Bill_Mst.Pj_No%Type Default Null
                             ,P_Actv_No                      In     Ias_Bill_Mst.Actv_No%Type Default Null
                             ,P_Si_Type                      In     Ias_Bill_Mst.Si_Type%Type Default Null
                             ,P_Stand_By                     In     Ias_Bill_Mst.Stand_By%Type Default Null
                             ,P_Col_No                       In     Ias_Bill_Mst.Col_No%Type Default Null
                             ,P_Cash_Ac_Fcc                  In     Ias_Bill_Mst.Cash_Ac_Fcc%Type Default Null
                             ,P_Bank_No                      In     Ias_Bill_Mst.Cash_No_Fcc%Type Default Null
                             ,P_A_Desc                       In     Ias_Bill_Mst.A_Desc%Type Default Null
                             ,P_Bill_Py                      In     Ias_Bill_Mst.Bill_Py%Type Default Null
                             ,P_External_Post                In     Ias_Bill_Mst.External_Post%Type Default Null
                             ,P_Field1                       In     Ias_Bill_Mst.Field1%Type Default Null
                             ,P_Field2                       In     Ias_Bill_Mst.Field2%Type Default Null
                             ,P_Field3                       In     Ias_Bill_Mst.Field3%Type Default Null
                             ,P_Field4                       In     Ias_Bill_Mst.Field4%Type Default Null
                             ,P_Field5                       In     Ias_Bill_Mst.Field5%Type Default Null
                             ,P_Field6                       In     Ias_Bill_Mst.Field6%Type Default Null
                             ,P_Field7                       In     Ias_Bill_Mst.Field7%Type Default Null
                             ,P_Field8                       In     Ias_Bill_Mst.Field8%Type Default Null
                             ,P_Field9                       In     Ias_Bill_Mst.Field9%Type Default Null
                             ,P_Field10                      In     Ias_Bill_Mst.Field10%Type Default Null
                             ,P_C_Tel                        In     Ias_Bill_Mst.C_Tel%Type Default Null
                             ,P_C_Address                    In     Ias_Bill_Mst.C_Address%Type Default Null
                             ,P_Driver_No                    In     Ias_Bill_Mst.Driver_No%Type Default Null
                             ,P_Bill_Valued                  In     Ias_Bill_Mst.Bill_Valued%Type Default Null
                             ,P_Value_Date                   In     Ias_Bill_Mst.Value_Date%Type Default Null
                             ,P_Bill_Without_Auto_Othr_Amt   In     Ias_Bill_Mst.Bill_Without_Auto_Othr_Amt%Type Default Null
                             ,P_Qt_Prm_No                    In     Ias_Bill_Mst.Qt_Prm_No%Type Default Null
                             ,P_Qt_Prm_Ser                   In     Ias_Bill_Mst.Qt_Prm_Ser%Type Default Null
                             ,P_Qt_Prm_Rcrd_No               In     Ias_Bill_Mst.Qt_Prm_Rcrd_No%Type Default Null
                             ,P_Prm_Code                     In     Ias_Bill_Mst.Prm_Code%Type Default Null
                             ,P_Doc_Brn_No                   In     Ias_Bill_Mst.Doc_Brn_No%Type Default Null
                             ,P_Cmpny_No                     In     Ias_Bill_Mst.Cmpny_No%Type Default Null
                             ,P_Mobile_No                    In     Ias_Bill_Mst.Mobile_No%Type Default Null
                             ,P_Not_Use_Qut_Prm              In     Ias_Bill_Mst.Not_Use_Qut_Prm%Type Default Null
                             ,P_Receive_Nm                   In     Ias_Bill_Mst.Receive_Nm%Type Default Null
                             ,P_Conn_Si_With_Outgong         In     Ias_Bill_Mst.Conn_Si_With_Outgong%Type Default Null
                             ,P_C_Code_Csh                   In     Ias_Bill_Mst.C_Code_Csh%Type Default Null
                             ,P_C_Tax_Code                   In     Ias_Bill_Mst.C_Tax_Code%Type Default Null                           
                             ,P_Doc_No_Res                   In     Ias_Bill_Mst.Doc_No_Res%Type Default Null
                             ,P_Doc_Srl_Res                  In     Ias_Bill_Mst.Doc_Srl_Res%Type Default Null
                             ,P_Ac_Code                      In     Ias_Bill_Mst.Ac_Code%Type Default Null
                             ,P_Ac_Code_Dtl                  In     Ias_Bill_Mst.Ac_Code_Dtl%Type Default Null
                             ,P_Ac_Dtl_Typ                   In     Ias_Bill_Mst.Ac_Dtl_Typ%Type Default Null
                             ,P_Pymnt_Ac                     In     Ias_Bill_Mst.Pymnt_Ac%Type Default Null
                             ,P_Clc_Typ_No_Tax               In     Ias_Bill_Mst.Clc_Typ_No_Tax%Type Default Null
                             ,P_Doc_Ser_Extrnl               In     Ias_Bill_Mst.Doc_Ser_Extrnl%Type Default Null
                             ,P_DOC_NO_EXTRNL                IN     IAS_BILL_MST.DOC_NO_EXTRNL%TYPE DEFAULT NULL
                             ,P_Cncl_Flg                     In     Ias_Bill_Mst.Cncl_Flg%Type Default Null
                             ,P_Clc_Vat_Price_Typ            In     Ias_Bill_Mst.Clc_Vat_Price_Typ%Type Default Null
                             ,P_Bill_Amt                     In     Ias_Bill_Mst.Bill_Amt%Type Default Null
                             ,P_Vat_Amt                      In     Ias_Bill_Mst.Vat_Amt%Type Default Null
                             ,P_Disc_Amt_Aftr_Vat            In     Ias_Bill_Mst.Disc_Amt_Aftr_Vat%Type Default Null
                             ,P_Disc_Amt_Mst_Vat             In     Ias_Bill_Mst.Disc_Amt_Mst_Vat%Type Default Null
                             ,P_Vat_Amt_Disc_Mst             In     Ias_Bill_Mst.Vat_Amt_Disc_Mst%Type Default Null
                             ,P_Vat_Amt_Othr                 In     Ias_Bill_Mst.Vat_Amt_Othr%Type Default Null
                             ,P_Othr_Amt                     In     Ias_Bill_Mst.Othr_Amt%Type Default Null
                             ,P_Disc_Amt                     In     Ias_Bill_Mst.Disc_Amt%Type Default Null
                             ,P_Disc_Amt_Mst                 In     Ias_Bill_Mst.Disc_Amt_Mst%Type Default Null
                             ,P_Disc_Amt_Dtl                 In     Ias_Bill_Mst.Disc_Amt_Dtl%Type Default Null
                             ,P_Add_Disc_Amt_Mst             In     Ias_Bill_Mst.Add_Disc_Amt_Mst%Type Default Null
                             ,P_Add_Disc_Amt_Dtl             In     Ias_Bill_Mst.Add_Disc_Amt_Dtl%Type Default Null
                             ,P_Othr_Amt_Disc                In     Ias_Bill_Mst.Othr_Amt_Disc%Type Default Null
                             ,P_OUT_BILL_TYP               IN IAS_BILL_MST.OUT_BILL_TYP%TYPE                 DEFAULT NULL
                                ,P_BILL_STAT_TYP              IN IAS_BILL_MST.BILL_STAT_TYP%TYPE                DEFAULT NULL                                
                                ,P_CRD_DISC_PER               IN IAS_BILL_MST.CRD_DISC_PER%TYPE                 DEFAULT NULL
                                ,P_CRD_NO_DISC                IN IAS_BILL_MST.CRD_NO_DISC%TYPE                  DEFAULT NULL
                                ,P_CREDIT_CARD                IN IAS_BILL_MST.CREDIT_CARD%TYPE                  DEFAULT NULL
                                ,P_CR_CARD_AMT                IN IAS_BILL_MST.CR_CARD_AMT%TYPE                  DEFAULT NULL
                                ,P_CR_CARD_AMT_SCND           IN IAS_BILL_MST.CR_CARD_AMT_SCND%TYPE             DEFAULT NULL
                                ,P_CR_CARD_AMT_THRD           IN IAS_BILL_MST.CR_CARD_AMT_THRD%TYPE             DEFAULT NULL
                                ,P_CR_CARD_COMM_PER           IN IAS_BILL_MST.CR_CARD_COMM_PER%TYPE             DEFAULT NULL
                                ,P_CR_CARD_COMM_PER_SCND      IN IAS_BILL_MST.CR_CARD_COMM_PER_SCND%TYPE        DEFAULT NULL
                                ,P_CR_CARD_COMM_PER_THRD      IN IAS_BILL_MST.CR_CARD_COMM_PER_THRD%TYPE        DEFAULT NULL
                                ,P_CR_CARD_CST_NO             IN IAS_BILL_MST.CR_CARD_CST_NO%TYPE               DEFAULT NULL
                                ,P_CR_CARD_CST_NO_SCND        IN IAS_BILL_MST.CR_CARD_CST_NO_SCND%TYPE          DEFAULT NULL
                                ,P_CR_CARD_CST_NO_THRD        IN IAS_BILL_MST.CR_CARD_CST_NO_THRD%TYPE          DEFAULT NULL
                                ,P_CR_CARD_DOC_NO_REF         IN IAS_BILL_MST.CR_CARD_DOC_NO_REF%TYPE           DEFAULT NULL
                                ,P_CR_CARD_DOC_NO_REF_SCND    IN IAS_BILL_MST.CR_CARD_DOC_NO_REF_SCND%TYPE      DEFAULT NULL
                                ,P_CR_CARD_DOC_NO_REF_THRD    IN IAS_BILL_MST.CR_CARD_DOC_NO_REF_THRD%TYPE      DEFAULT NULL
                                ,P_CR_CARD_DSC                IN IAS_BILL_MST.CR_CARD_DSC%TYPE                  DEFAULT NULL
                                ,P_CR_CARD_DSC_SCND           IN IAS_BILL_MST.CR_CARD_DSC_SCND%TYPE             DEFAULT NULL
                                ,P_CR_CARD_DSC_THRD           IN IAS_BILL_MST.CR_CARD_DSC_THRD%TYPE             DEFAULT NULL
                                ,P_CR_CARD_MAX_COMM_AMT       IN IAS_BILL_MST.CR_CARD_MAX_COMM_AMT%TYPE         DEFAULT NULL
                                ,P_CR_CARD_MAX_COMM_AMT_SCND  IN IAS_BILL_MST.CR_CARD_MAX_COMM_AMT_SCND%TYPE    DEFAULT NULL
                                ,P_CR_CARD_MAX_COMM_AMT_THRD  IN IAS_BILL_MST.CR_CARD_MAX_COMM_AMT_THRD%TYPE    DEFAULT NULL
                                ,P_CR_CARD_NO                 IN IAS_BILL_MST.CR_CARD_NO%TYPE                   DEFAULT NULL
                                ,P_CR_CARD_NO_SCND            IN IAS_BILL_MST.CR_CARD_NO_SCND%TYPE              DEFAULT NULL
                                ,P_CR_CARD_NO_THRD            IN IAS_BILL_MST.CR_CARD_NO_THRD%TYPE              DEFAULT NULL
                                ,P_CR_DOC_NO_REF              IN IAS_BILL_MST.CR_DOC_NO_REF%TYPE                DEFAULT NULL
                                ,P_CR_DOC_NO_REF_SCND         IN IAS_BILL_MST.CR_DOC_NO_REF_SCND%TYPE           DEFAULT NULL
                                ,P_CR_DOC_NO_REF_THRD         IN IAS_BILL_MST.CR_DOC_NO_REF_THRD%TYPE           DEFAULT NULL
                                ,P_CR_VALUED                  IN IAS_BILL_MST.CR_VALUED%TYPE                    DEFAULT NULL
                                ,P_CR_VALUED_SCND             IN IAS_BILL_MST.CR_VALUED_SCND%TYPE               DEFAULT NULL
                                ,P_CR_VALUED_THRD             IN IAS_BILL_MST.CR_VALUED_THRD%TYPE               DEFAULT NULL
                                ,P_CR_VALUE_DATE              IN IAS_BILL_MST.CR_VALUE_DATE%TYPE                DEFAULT NULL
                                ,P_CR_VALUE_DATE_SCND         IN IAS_BILL_MST.CR_VALUE_DATE_SCND%TYPE           DEFAULT NULL
                                ,P_CR_VALUE_DATE_THRD         IN IAS_BILL_MST.CR_VALUE_DATE_THRD%TYPE           DEFAULT NULL
                             ,P_Cpn_Amt                      In     Ias_Bill_Mst.Cpn_Amt%Type Default Null
                             ,P_Bnk_Amt                      In     Ias_Bill_Mst.Bnk_Amt%Type Default Null
                             ,P_Cheque_Amt                   In     Ias_Bill_Mst.Cheque_Amt%Type Default Null
                             ,P_Prcnt_Amt                    In     Ias_Bill_Mst.Prcnt_Amt%Type Default Null
                             ,P_Ac_Amt                       In     Ias_Bill_Mst.Ac_Amt%Type Default Null
                             ,P_CLC_TAX_FREE_QTY_FLG         In     Ias_Bill_Mst.CLC_TAX_FREE_QTY_FLG %Type Default Null
                             ,P_E_INVC_MTHD_NO               IN     Ias_Bill_Mst.E_INVC_MTHD_NO %Type Default Null
                             ,P_TAX_BILL_TYP                 IN     Ias_Bill_Mst.TAX_BILL_TYP %Type Default Null
                             ,P_SHO_SYS_TYP                  IN     Ias_Bill_Mst.SHO_SYS_TYP %Type Default Null
                             ,P_Cmp_No                       In     Ias_Bill_Mst.Cmp_No%Type Default Null
                             ,P_Brn_No                       In     Ias_Bill_Mst.Brn_No%Type Default Null
                             ,P_Brn_Year                     In     Ias_Bill_Mst.Brn_Year%Type Default Null
                             ,P_Brn_Usr                      In     Ias_Bill_Mst.Brn_Usr%Type Default Null
                             ,P_Ad_U_Id                      In     Ias_Bill_Mst.Ad_U_Id%Type Default Null
                             ,P_Ad_Date                      In     Ias_Bill_Mst.Ad_Date%Type Default Null
                             ,P_Ad_Trmnl_Nm                  In     Ias_Bill_Mst.Ad_Trmnl_Nm%Type Default Null
                             ,P_Pst_Typ                      In     Number Default Null --## 1 to br tables ,2 to onyx tables                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        --## 1 to br tables ,2 to onyx tables
                             ,P_Clc_Tax_Method               In     Number --## 0 CALC TAX IN EXTRNAL ,1-AOUTO CALC TAX
                             ,P_Pst_From_Br                  In     Number --## 1- POSTING FORM BR TABLE  0- NOT FROM BR
                             ,P_DTS_ONLINE                   In     NUMBER DEFAULT 0 --## 0 OFFLINE ,1-ONLINE
                             ,P_Lng_No                       In     Number Default 1
                             ,P_Msg_Txt                         Out Varchar2
                             ,P_Err_No                          Out Varchar2
                             ,P_Pkg_Nm                          Out Varchar2)
Is
   V_Sys_No_Extrnl   Form_Detail.Sys_No%Type;
   V_Doc_Due_Date    Date;
   V_Crdt_Prd_Day    Number := 0;
   V_Cst_Nm          Customer.C_A_Name%Type;
   V_C_Tax_Code        Customer.C_Tax_Code%Type:=P_C_Tax_Code;
   V_TAX_BILL_TYP    CUSTOMER.C_CLASS_VAT%TYPE := P_TAX_BILL_TYP;
   V_Msg_No          Number;
   V_Inactv_Flg      Number;
   V_Cnt             Number;  
   V_Tbl_Mst         Varchar2 (2000);
   V_C_CLASS_VAT      NUMBER(5);
    V_CR_A_Code                  ACCOUNT.A_CODE%TYPE; 
    V_Credit_Card               IAS_BILL_MST.CREDIT_CARD%TYPE                  := P_CREDIT_CARD;
    V_CR_CARD_COMM_PER          IAS_BILL_MST.CR_CARD_COMM_PER%TYPE             := P_CR_CARD_COMM_PER;
    V_CR_CARD_COMM_PER_SCND     IAS_BILL_MST.CR_CARD_COMM_PER_SCND%TYPE        := P_CR_CARD_COMM_PER_SCND;
    V_CR_CARD_COMM_PER_THRD     IAS_BILL_MST.CR_CARD_COMM_PER_THRD%TYPE        :=P_CR_CARD_COMM_PER_THRD;       
    V_CR_CARD_MAX_COMM_AMT      IAS_BILL_MST.CR_CARD_MAX_COMM_AMT%TYPE         :=P_CR_CARD_MAX_COMM_AMT;
    V_CR_CARD_MAX_COMM_AMT_SCND IAS_BILL_MST.CR_CARD_MAX_COMM_AMT_SCND%TYPE    :=P_CR_CARD_MAX_COMM_AMT_SCND;
    V_CR_CARD_MAX_COMM_AMT_THRD IAS_BILL_MST.CR_CARD_MAX_COMM_AMT_THRD%TYPE    :=P_CR_CARD_MAX_COMM_AMT_THRD;
    V_E_INVC_MTHD_NO            IAS_BILL_MST.E_INVC_MTHD_NO%TYPE  ; 
    V_Comm_Per                  NUMBER;              
 Begin
   --##-----------------------------------------------------------------------------------------------##--
   Clr_Glbl_Var; -- CLEAR GLOBAL VARIABLES
   G_Pst_Typ          := Null;
   --##-----------------------------------------------------------------------------------------------##--
   G_Doc_Typ          := 4; -- SALES BILL
   G_Pst_Typ          := P_Pst_Typ;
   ------------------------------------------------------------------------------------------
   G_Doc_No           := P_Doc_No;
   G_Doc_Ser          := P_Doc_Ser;
   G_OUT_BILL_TYP     :=NVL(P_OUT_BILL_TYP,0);   
   
   --##----------------------------------------------------------------------------------------------##--
   Get_Prmtr_Prc (P_Sys_No           => P_Sys_No
                 ,P_Doc_Typ          => G_Doc_Typ
                 ,P_Pst_Typ          => P_Pst_Typ
                 ,P_Cur_Code         => P_Cur_Code
                 ,P_Cur_Rate         => P_Cur_Rate
                 ,P_Stock_Rate       => Null
                 ,P_Doc_Date         => P_Doc_Date
                 ,P_Brn_No           => P_Brn_No
                 ,P_Brn_Usr          => P_Brn_Usr
                 ,P_Brn_Year         => P_Brn_Year
                 ,P_Usr_No           => P_Ad_U_Id
                 ,P_Clc_Tax_Method   => P_Clc_Tax_Method
                 ,P_Pst_From_Br      => P_Pst_From_Br
                 ,P_DTS_ONLINE       =>P_DTS_ONLINE
                 ,P_Lng_No           => P_Lng_No
                 ,P_Msg_Txt          => P_Msg_Txt
                 ,P_Err_No           => P_Err_No
                 ,P_Pkg_Nm           => P_Pkg_Nm);

   If P_Msg_Txt Is Not Null Then
      Goto Rtn_Rslt;
   End If;

   --##----------------------------------------------------------------------------------------------##--
   If G_Pst_Typ = 1 Then
      V_Tbl_Mst   := 'IAS_BILL_MST_BR';
   Else
      V_Tbl_Mst   := 'IAS_BILL_MST';
   End If;   
   --##----------------------------------------------------------------------------------------------##--
    -- IF  NVL(P_Sys_No,0)=70 THEN
        If P_DOC_SER_EXTRNL Is Null  Then
          P_Err_No := 20529;
          P_Msg_Txt := 'DOC_SER_EXTRNL IS NULL ';
          Goto Rtn_Rslt;
        END IF;
        
        If G_Pst_Typ = 1 Then
            BEGIN 
              SELECT 1 INTO V_CNT  FROM IAS_BILL_MST_BR
                                    WHERE DOC_SER_EXTRNL=P_DOC_SER_EXTRNL
                                     AND ROWNUM<=1  ;
            EXCEPTION WHEN OTHERS THEN
              V_CNT:=0;
            END ; 
        Else
           BEGIN 
              SELECT 1 INTO V_CNT  FROM IAS_BILL_MST
                                    WHERE DOC_SER_EXTRNL=P_DOC_SER_EXTRNL
                                     AND ROWNUM<=1  ;
            EXCEPTION WHEN OTHERS THEN
              V_CNT:=0;
            END ;
         End If; 
       
        
        
        IF NVL(V_CNT,0)>0 THEN
            BEGIN 
              EXECUTE IMMEDIATE ' SELECT BILL_NO,BILL_SER FROM '||V_Tbl_Mst||' 
                                    WHERE DOC_SER_EXTRNL='''||P_DOC_SER_EXTRNL||'''
                                     AND ROWNUM<=1 ' INTO G_DOC_NO,G_DOC_SER ;
            EXCEPTION WHEN OTHERS THEN
              V_CNT:=0;
            END;  
           P_Err_No := 20999;
           P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 4942) || Chr (10) || ' DOC_SER_EXTRNL='||P_DOC_SER_EXTRNL;           
          Goto Rtn_Rslt;
        END IF;
        V_CNT:=0; 
   --  END IF;
   --##----------------------------------------------------------------------------------------------##--   
   V_Sys_No_Extrnl    := G_Sys_No;
   --##----------------------------------------------------------------------------------------------##--
   V_Msg_No           := Null;
   G_C_Code           := case When nvl(P_C_Code,'0')='0' Then Null Else P_C_Code end ;
   G_Emp_No           := Case When nvl(P_Emp_No,0)=0   Then Null Else P_Emp_No end ;
   G_R_Code           := Case When nvl(P_R_Code,0)=0   Then Null Else P_R_Code end ;
   G_Si_Type          := Case When nvl(P_Si_Type,0)=0  Then Null Else P_Si_Type end ;
   G_Bill_Doc_Type    := Case When nvl(P_Bill_Doc_Type,0)=0 Then Null Else P_Bill_Doc_Type end;
   G_Ad_Date          := Nvl (P_Ad_Date, Ias_Gen_Pkg.Get_Curdate);
   G_Clc_Typ_No_Tax   := Case  When nvl(P_Clc_Typ_No_Tax,0)=0 Then Null
                               When nvl(G_Use_Vat,0) = 0      Then null
                               Else P_Clc_Typ_No_Tax end  ;
   G_Cash_No          := Case When nvl(P_Cash_No,0)=0 Then Null Else P_Cash_No end ;
   G_W_Code          := Case When nvl(P_W_Code,0)=0 Then Null Else P_W_Code end ;
   G_Bank_No          := Case When nvl(P_Bank_No,0)=0 Then Null Else P_Bank_No end ;
   G_Rep_Code         := Case When nvl(P_Rep_Code,'0')='0' Then Null Else P_Rep_Code end ;
   G_Doc_Dsc          := P_A_Desc;
   G_Ref_No           := P_Ref_No;
   G_Cc_Code          := Case When nvl(P_Cc_Code,'0')='0' Then Null Else P_Cc_Code end ;
   G_Pj_No            := Case When nvl(P_Pj_No,'0')='0' Then Null Else P_Pj_No end ;
   G_Actv_No          := Case When nvl(P_Actv_No,'0')='0' Then Null Else P_Actv_No end ;
   G_Col_No           := Case When nvl(P_Col_No,0)=0 Then Null Else P_Col_No end ;
   G_Doc_Brn_No       := Case When nvl(P_Doc_Brn_No,0)=0 Then Null Else P_Doc_Brn_No end ;

   --##-----------------------------------------------------------------------------------------------##--
   If G_Doc_Dsc Is Null Then
      If G_Bill_Doc_Type in (4,8) Then
          G_Doc_Dsc:= Ias_Gen_Pkg.Get_Prompt(G_Lng_No,787);     
       ElsIf G_Bill_Doc_Type=1 Then        
          G_Doc_Dsc:= Ias_Gen_Pkg.Get_Prompt(G_Lng_No,3193);        
       End If;
   End if;
   If nvl(G_Sys_no,0)=70 And G_Bill_Doc_Type=1 And G_C_Code Is Not Null and P_C_NAME is Not Null AND ( G_C_Code=nvl(G_DTS_C_CSH_CODE,'0') or Is_Csh_Cstmr(G_C_Code)=1) Then
     G_C_Code:=null;
     V_Cst_Nm:=P_C_Name;
   End if;

   
   If G_C_Code Is Not Null Then
      Gnr_Api_Pkg.Chk_Inpt_Data (P_Inpt_Typ     => 'C_CODE'
                                ,P_Sys_Typ      => 1 --##    P_SYS_TYP =  1 = SALE , 2= STOCKE ,3 = PURCHASE ,                                                    ,
                                ,P_Doc_Type     => G_Doc_Typ
                                ,P_Inpt_Code1   => G_C_Code
                                ,P_Lng_Dflt     => G_Lng_Dflt
                                ,P_Inpt_Nm      => V_Cst_Nm
                                ,P_Msg_No       => V_Msg_No);

      If V_Msg_No Is Not Null Then
         P_Err_No    := 20070;
         P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No);
         Goto Rtn_Rslt;
      End If;
   Else
      V_Cst_Nm   := P_C_Name;
   End If;

   --##-----------------------------------------------------------------------------------------------##----
   If P_Bill_Due_Date Is Not Null Then
      V_Doc_Due_Date   := P_Bill_Due_Date;      
   Else
      If G_C_Code Is Not Null Then
         Begin
            Select Credit_Period
              Into V_Crdt_Prd_Day
              From Customer
             Where C_Code = P_C_Code And Rownum <= 1;
         Exception
            When Others Then
               Null;
         End;
      End If;

      V_Doc_Due_Date   := G_Doc_Date + Nvl (V_Crdt_Prd_Day, 0);
     
   End If;
    G_Doc_Due_Date   :=V_Doc_Due_Date;

   --##-----------------------------------------------------------------------------------------------##--
   If V_Doc_Due_Date Is Not Null And V_Doc_Due_Date < G_Doc_Date Then
      P_Err_No    := 20071;
      P_Msg_Txt   := 'Invalid Date (DOC_DUE_DATE) , Because DOC_DUE_DATE < DOC_DATE , ';
      Goto Rtn_Rslt;
   Elsif P_Cheque_Due_Date Is Not Null And P_Cheque_Due_Date < G_Doc_Date Then
      P_Err_No    := 20072;
      P_Msg_Txt   := 'Invalid Date (CHEQUE_DUE_DATE) , Because CHEQUE_DUE_DATE < DOC_DATE , ';
      Goto Rtn_Rslt;
   End If;
