                    ,P_CR_CARD_DOC_NO_REF              
                    ,P_CR_CARD_DOC_NO_REF_SCND       
                    ,P_CR_CARD_DOC_NO_REF_THRD     
                    ,P_CR_CARD_DSC                             
                    ,P_CR_CARD_DSC_SCND                    
                    ,P_CR_CARD_DSC_THRD                  
                    ,V_CR_CARD_MAX_COMM_AMT              
                    ,V_CR_CARD_MAX_COMM_AMT_SCND   
                    ,V_CR_CARD_MAX_COMM_AMT_THRD   
                    ,P_CR_CARD_NO                                
                    ,P_CR_CARD_NO_SCND                        
                    ,P_CR_CARD_NO_THRD                      
                    ,P_CR_DOC_NO_REF                         
                    ,P_CR_DOC_NO_REF_SCND               
                    ,P_CR_DOC_NO_REF_THRD                 
                    ,P_CR_VALUED                                     
                    ,P_CR_VALUED_SCND                         
                    ,P_CR_VALUED_THRD                            
                    ,P_CR_VALUE_DATE                             
                    ,P_CR_VALUE_DATE_SCND                  
                    ,P_CR_VALUE_DATE_THRD
                  ,P_Cpn_Amt
                  ,P_Bnk_Amt
                  ,P_Cheque_Amt
                  ,P_Prcnt_Amt
                  ,Nvl (P_Ac_Amt, 0)
                  ,NVL(G_CLC_TAX_FREE_QTY_FLG,0)
                  ,V_Comm_Per
                  ,Ias_Brn_Pkg.Get_Br_Inf ( G_brn_no => G_Brn_No ,P_inf_type =>'BRN_TAX_CODE')
                  ,G_Cmp_No
                  ,G_Brn_No
                  ,G_Brn_Year
                  ,G_Brn_Usr
                  ,G_Ad_U_Id
                  ,G_Ad_Date
                  ,P_Ad_Trmnl_Nm
                  ,V_E_INVC_MTHD_NO 
                  ,V_TAX_BILL_TYP
                  ,G_C_CODE_CSH) Return Cc_Code,Pj_No,Actv_No into G_Mst_Cc_Code,G_Mst_Pj_No,G_Mst_Actv_No;
   End If;

  --####################--
  <<RTN_RSLT>>
   If P_Msg_Txt Is Not Null OR P_Err_No IS NOT NULL Then
      Rollback;
      P_Msg_Txt   := NVL(P_Msg_Txt,'Message Number Is Missing');
      P_Err_No    := P_Err_No;
      P_Pkg_Nm    := Nvl (P_Pkg_Nm, 'Ars_Api_Trns_Pkg.Insrt_Ias_Bill_Mst');
      Return;
   Else
      P_Msg_Txt   := Null;
      P_Err_No    := Null;
      P_Pkg_Nm    := Null;
   End If;
--####################--
Exception
   When Others Then
      Rollback;
      P_Msg_Txt   := 'ERROR WHEN INSERT ' || V_Tbl_Mst || ' ' || Chr(10) || Sqlerrm;
      P_Err_No    := 20331;
      P_Pkg_Nm    := 'Ars_Api_Trns_Pkg.Insrt_Ias_Bill_Mst';
End Insrt_Ias_Bill_Mst;

--##-----------------------------------------------------------------------------------------------------##--
  Procedure Insrt_Ias_Bill_Dtl (P_I_Code                   In     Ias_Bill_Dtl.I_Code%Type Default Null
                             ,P_I_Qty                    In     Ias_Bill_Dtl.I_Qty%Type Default Null
                             ,P_P_Size                   In     Ias_Bill_Dtl.P_Size%Type Default Null
                             ,P_P_Qty                    In     Ias_Bill_Dtl.P_Qty%Type Default Null
                             ,P_I_Price                  In     Ias_Bill_Dtl.I_Price%Type Default Null
                             ,P_I_Price_Vat              In     Ias_Bill_Dtl.I_Price_Vat%Type Default Null
                             ,P_Stk_Cost                 In     Ias_Bill_Dtl.Stk_Cost%Type Default Null
                             ,P_Doc_Sequence             In Out Ias_Bill_Dtl.Doc_Sequence%Type
                             ,P_Rcrd_No                  In Out Ias_Bill_Dtl.Rcrd_NO%Type
                             ,P_W_Code                   In     Ias_Bill_Dtl.W_Code%Type Default Null
                             ,P_Cc_Code                  In     Ias_Bill_Dtl.Cc_Code%Type Default Null
                             ,P_Pj_No                    In     Ias_Bill_Dtl.Pj_No%Type Default Null
                             ,P_Actv_No                  In     Ias_Bill_Dtl.Actv_No%Type Default Null
                             ,P_Expire_Date              In     Ias_Bill_Dtl.Expire_Date%Type Default Null
                             ,P_Batch_No                 In     Ias_Bill_Dtl.Batch_No%Type Default Null
                             ,P_Free_Qty                 In     Ias_Bill_Dtl.Free_Qty%Type Default Null
                             ,P_Vat_Per                  In     Ias_Bill_Dtl.Vat_Per%Type Default Null
                             ,P_Vat_Amt                  In     Ias_Bill_Dtl.Vat_Amt%Type Default Null
                             ,P_Bnk_Amt_dtl              In     Ias_Bill_Dtl.Bnk_Amt_dtl%Type Default Null
                             ,P_Othr_Amt                 In     Ias_Bill_Dtl.Othr_Amt%Type Default Null
                             ,P_Item_Desc                In     Ias_Bill_Dtl.Item_Desc%Type Default Null
                             ,P_Barcode                  In     Ias_Bill_Dtl.Barcode%Type Default Null
                             ,P_So_No                    In     Ias_Bill_Dtl.So_No%Type Default Null
                             ,P_So_Ser                   In     Ias_Bill_Dtl.So_Ser%Type Default Null
                             ,P_Doc_Type_Ref             In     Ias_Bill_Dtl.Doc_Type_Ref%Type Default Null
                             ,P_Doc_No_Ref               In     Ias_Bill_Dtl.Doc_No_Ref%Type Default Null
                             ,P_Doc_Ser_Ref              In     Ias_Bill_Dtl.Doc_Ser_Ref%Type Default Null
                             ,P_Dis_Per                  In     Ias_Bill_Dtl.Dis_Per%Type Default Null
                             ,P_Dis_Amt                  In     Ias_Bill_Dtl.Dis_Amt%Type Default Null
                             ,P_Dis_Amt_Mst              In     Ias_Bill_Dtl.Dis_Amt_Mst%Type Default Null
                             ,P_Dis_Amt_Dtl              In     Ias_Bill_Dtl.Dis_Amt_Dtl%Type Default Null
                             ,P_Add_Dis_Amt_Mst          In     Ias_Bill_Dtl.Add_Dis_Amt_Mst%Type Default Null
                             ,P_Add_Dis_Amt_Dtl          In     Ias_Bill_Dtl.Add_Dis_Amt_Dtl%Type Default Null
                             ,P_Dis_Per2                 In     Ias_Bill_Dtl.Dis_Per2%Type Default Null
                             ,P_Dis_Amt_Dtl2             In     Ias_Bill_Dtl.Dis_Amt_Dtl2%Type Default Null
                             ,P_Dis_Per3                 In     Ias_Bill_Dtl.Dis_Per3%Type Default Null
                             ,P_Dis_Amt_Dtl3             In     Ias_Bill_Dtl.Dis_Amt_Dtl3%Type Default Null
                             ,P_Vat_Amt_Othr             In     Ias_Bill_Dtl.Vat_Amt_Othr%Type Default Null
                             ,P_Othr_Amt_Disc            In     Ias_Bill_Dtl.Othr_Amt_Disc%Type Default Null
                             ,P_Dis_Aftr_Vat_Mst         In     Ias_Bill_Dtl.Dis_Aftr_Vat_Mst%Type Default Null
                             ,P_Dis_Amt_Dtl_Vat          In     Ias_Bill_Dtl.Dis_Amt_Dtl_Vat%Type Default Null
                             ,P_Dis_Amt_Dtl2_Vat         In     Ias_Bill_Dtl.Dis_Amt_Dtl2_Vat%Type Default Null
                             ,P_Vat_Amt_Dis_Dtl_Vat      In     Ias_Bill_Dtl.Vat_Amt_Dis_Dtl_Vat%Type Default Null
                             ,P_Vat_Amt_Dis_Dtl3_Vat     In     Ias_Bill_Dtl.Vat_Amt_Dis_Dtl3_Vat%Type Default Null
                             ,P_Vat_Amt_Dis_Dtl2_Vat     In     Ias_Bill_Dtl.Vat_Amt_Dis_Dtl2_Vat%Type Default Null
                             ,P_Dis_Amt_Mst_Vat          In     Ias_Bill_Dtl.Dis_Amt_Mst_Vat%Type Default Null
                             ,P_Vat_Amt_Dis_Mst_Vat      In     Ias_Bill_Dtl.Vat_Amt_Dis_Mst_Vat%Type Default Null
                             ,P_Vat_Amt_Bfr_Dis          In     Ias_Bill_Dtl.Vat_Amt_Bfr_Dis%Type Default Null
                             ,P_Vat_Amt_Aftr_Dis         In     Ias_Bill_Dtl.Vat_Amt_Aftr_Dis%Type Default Null
                             ,P_Dis_Amt_Aftr_Vat         In     Ias_Bill_Dtl.Dis_Amt_Aftr_Vat%Type Default Null
                             ,P_Dis_Amt_Dtl_Qt_Prm       In     Ias_Bill_Dtl.Dis_Amt_Dtl_Qt_Prm%Type Default Null
                             ,P_Dis_Amt_Dtl_Qt_Prm_Vat   In     Ias_Bill_Dtl.Dis_Amt_Dtl_Qt_Prm_Vat%Type Default Null
                             ,P_Dis_Per_Qt_Prm           In     Ias_Bill_Dtl.Dis_Per_Qt_Prm%Type Default Null
                             ,P_Dis_Amt_Dtl3_Vat         In     Ias_Bill_Dtl.Dis_Amt_Dtl3_Vat%Type Default Null
                             ,P_Lev_No                   In     Ias_Bill_Dtl.Lev_No%Type Default Null
                             ,P_Prm_Grp_No               In     Ias_Bill_Dtl.Prm_Grp_No%Type Default Null
                             ,P_QT_PRM_NO                In     Ias_Bill_Dtl.QT_PRM_NO%Type Default Null
                             ,P_Qt_Prm_Rcrd_No           In     Ias_Bill_Dtl.Qt_Prm_Rcrd_No%Type Default Null
                             ,P_Qt_Prm_Ser               In     Ias_Bill_Dtl.Qt_Prm_Ser%Type Default Null
                             ,P_Rcrd_No_Ref              In     Ias_Bill_Dtl.Rcrd_No_Ref%Type Default Null
                             ,P_I_Length                 In     Ias_Bill_Dtl.I_Length%Type Default Null
                             ,P_I_Width                  In     Ias_Bill_Dtl.I_Width%Type Default Null
                             ,P_I_Height                 In     Ias_Bill_Dtl.I_Height%Type Default Null
                             ,P_I_Number                 In     Ias_Bill_Dtl.I_Number%Type Default Null
                             ,P_Field_Dtl1               In     Ias_Bill_Dtl.Field_Dtl1%Type Default Null
                             ,P_Field_Dtl2               In     Ias_Bill_Dtl.Field_Dtl2%Type Default Null
                             ,P_Field_Dtl3               In     Ias_Bill_Dtl.Field_Dtl3%Type Default Null
                             ,P_Field_Dtl4               In     Ias_Bill_Dtl.Field_Dtl1%Type Default Null
                             ,P_Field_Dtl5               In     Ias_Bill_Dtl.Field_Dtl1%Type Default Null
                             ,P_Field_Dtl6               In     Ias_Bill_Dtl.Field_Dtl1%Type Default Null
                             ,P_Field_Dtl7               In     Ias_Bill_Dtl.Field_Dtl1%Type Default Null
                             ,P_Field_Dtl8               In     Ias_Bill_Dtl.Field_Dtl1%Type Default Null
                             ,P_Field_Dtl9               In     Ias_Bill_Dtl.Field_Dtl1%Type Default Null
                             ,P_Field_Dtl10              In     Ias_Bill_Dtl.Field_Dtl1%Type Default Null                             
                             ,P_Up_Cnt                   In     Ias_Bill_Dtl.Up_Cnt%Type Default Null
                             ,P_Itm_Unt                  In     Ias_Bill_Dtl.Itm_Unt%Type Default Null
                             ,P_Wt_Qty                   In     Ias_Bill_Dtl.Wt_Qty%Type Default Null
                             ,P_Wt_Unt                   In     Ias_Bill_Dtl.Wt_Unt%Type Default Null
                             ,P_Emp_No                   In     Ias_Bill_Dtl.Emp_No%Type Default Null
                             ,P_Measur_Price             In     Ias_Bill_Dtl.Measur_Price%Type Default Null
                             ,P_Argmnt_No                In     Ias_Bill_Dtl.Argmnt_No%Type Default Null
                             ,P_Doc_Sequence_Ref         In     Ias_Bill_Dtl.Doc_Sequence_Ref%Type Default Null
                             ,P_SERIALNO_N               IN     CLOB  Default Null
                             ,P_DOC_SEQUENCE_BR          In     Ias_Bill_Dtl.DOC_SEQUENCE_BR%Type Default Null
                             ,P_RCRD_NO_BR               In     Ias_Bill_Dtl.RCRD_NO_BR%Type Default Null
                             ,P_Msg_Txt                     Out Varchar2
                             ,P_Err_No                      Out Varchar2
                             ,P_Pkg_Nm                      Out Varchar2)
Is
   V_P_Size           Ias_Itm_Dtl.P_Size%Type;
   V_Cnt              Number;
   V_Msg_No           Number;
   V_Stkcost          Ias_Bill_Dtl.Stk_Cost%Type;   
   V_Doc_Sequence     Ias_Bill_Dtl.Doc_Sequence%Type;
   V_Service_Itm      Number;
   V_Cst              Number;
   V_Use_Serialno     Number;
   V_Post_Code        Ias_Bill_Dtl.Post_Code%Type;
   V_Used_Itm         Number;  
   V_Tbl_Dtl          Varchar2 (2000);  
   V_I_Price          Number:=P_I_Price;
   V_I_Price_Vat      Number:=p_I_Price_Vat;
   V_Vat_Per          Number;
   V_Clc_Typ_No       Number;
   V_TBL_Serialno     Varchar2 (500);
   V_CNT_QTY          NUMBER; 
   V_Comm_Per           NUMBER;
   V_Comm_Amt_Dtl       NUMBER;
   V_Rep_Code_Sp       Ias_Bill_Dtl.Rep_Code_Sp%Type;
   V_Prm_Code_Out      Ias_Bill_Dtl.Prm_Code_Out%Type;
   V_Cc_Code                     COST_CENTERS.Cc_Code%Type;  
   V_Pj_No                       IAS_PROJECTS.Pj_No%Type;
   V_Actv_No                     IAS_ACTVTY.Actv_No%Type;    
   V_Out_qty                    Ias_Bill_Dtl.Out_qty%Type;
   V_OUT_FREE_QTY                    Ias_Bill_Dtl.Out_qty%Type;
Begin
   Begin
      If G_Doc_Ser Is Null Or G_Doc_No Is Null Then
         P_Err_No    := 20099;
         P_Msg_Txt   := 'G_DOC_SER OR G_DOC_NO .. IS NULL ';
         Goto Rtn_Rslt;
      End If;

      If G_Pst_Typ Is Null Then
         P_Err_No    := 20100;
         P_Msg_Txt   := 'PST_TYP IS NULL ';
         Goto Rtn_Rslt;
      Elsif G_Pst_Typ Not In (1, 2) Then
         P_Err_No    := 20101;
         P_Msg_Txt   := 'Pst_Typ Must Be Equal 1 Or 2 ';
         Goto Rtn_Rslt;
      End If;

      If G_Pst_Typ = 2 Then
         V_Tbl_Dtl          := 'IAS_BILL_DTL'; 
         V_TBL_Serialno     :='IAS_ITEM_SERIALNO';       
      Else
         V_Tbl_Dtl          := 'IAS_BILL_DTL_BR';
         V_TBL_Serialno     :='IAS_ITEM_SERIALNO_BR';          
      End If;

      --##-----------------------------------------------------------------------------------------##--
      If G_Ar_Wc_Type = 1 Then
         G_W_Code   := G_W_Code;
      Else
         G_W_Code   := Nvl (P_W_Code, G_W_Code);
       If G_W_Code Is Not Null Then
        GNR_API_PKG.Chk_Inpt_Data (P_Inpt_Typ     => 'W_CODE'
                                   ,P_SYS_TYP      =>1
                                   ,P_DOC_TYPE     => G_DOC_TYP
                                   ,P_Inpt_Code1   => G_W_Code
                                   ,P_Inpt_Code2   => G_Brn_No
                                   ,P_Inpt_Code3   => G_ALLW_SAL_WH_NOT_CONN_BRN
                                   ,P_Inpt_Code4   => G_USE_BALANCED_BRN
                                   ,P_Lng_Dflt     => G_Lng_No
                                   ,P_Inpt_Nm      => G_Inpt_Nm
                                   ,P_Msg_No       => V_Msg_No);

         If V_Msg_No Is Not Null Then
            P_Err_No :=20739 ;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No) || ' W_CODE=' || G_W_Code;
            Goto Rtn_Rslt;
         End If;
      END IF;
      End If;

      If G_W_Code Is Null Then
         P_Err_No    := 20102;
         P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 930);
         Goto Rtn_Rslt;
      End If;
      --##---------------------------------------------------------------------------------------------------------------------------##--
      If Nvl (G_Use_Vat, 0) = 1 And G_Clc_Typ_No_Tax Is Not Null And Nvl (G_Clc_Tax_Method, 0) = 1 And Nvl(G_sys_no,0)<>185  Then       
          If Nvl (Ys_Tax_Pkg.Get_Clc_Tax_Typ (P_Clc_Typ_No => G_Clc_Typ_No_Tax), 0) = 0 Then
            -- V_Vat_Per   := Ys_Tax_Pkg.Get_Itm_Tax_Prcnt (P_Clc_Typ_No => G_Clc_Typ_No_Tax, P_I_Code => P_I_Code, P_Clc_Usd_Itm => 1);
              V_Vat_Per   :=Ys_Tax_Pkg.Get_Itm_Tax_Prcnt_Sal ( P_Clc_Typ_No =>G_Clc_Typ_No_Tax  
                                                             , P_I_Code => P_I_CODE 
                                                              ,P_Clc_Usd_Itm => 1
                                                              ,P_I_Price=>P_I_Price
                                                              ,P_I_Price_Vat =>case when Nvl(G_Clc_Vat_Price_Typ,0) = 2 Then (Case when nvl(P_I_Price_Vat,0) =0 Then Nvl (P_I_Price, 0) Else Nvl (P_I_Price_Vat, 0) end) else Nvl (P_I_Price, 0) end  
                                                              ,P_Use_Price_Include_Vat=> case when Nvl(G_Clc_Vat_Price_Typ,0) = 2 then 1 else 0 end ); 
          Else
             V_Clc_Typ_No   := Ys_Tax_Pkg.Get_Clc_Typ_No_Exmpt (P_Clc_Typ_No => G_Clc_Typ_No_Tax);
            -- V_Vat_Per      := Ys_Tax_Pkg.Get_Itm_Tax_Prcnt (P_Clc_Typ_No => V_Clc_Typ_No, P_I_Code => P_I_Code, P_Clc_Usd_Itm => 1);
            V_Vat_Per   :=Ys_Tax_Pkg.Get_Itm_Tax_Prcnt_Sal ( P_Clc_Typ_No =>V_Clc_Typ_No  
                                                             , P_I_Code => P_I_CODE 
                                                              ,P_Clc_Usd_Itm => 1
                                                              ,P_I_Price=>P_I_Price
                                                              ,P_I_Price_Vat =>case when Nvl(G_Clc_Vat_Price_Typ,0) = 2 Then (Case when nvl(P_I_Price_Vat,0) =0 Then Nvl (P_I_Price, 0) Else Nvl (P_I_Price_Vat, 0) end) else Nvl (P_I_Price, 0) end  
                                                              ,P_Use_Price_Include_Vat=> case when Nvl(G_Clc_Vat_Price_Typ,0) = 2 then 1 else 0 end );
          End If;
          If nvl(V_Vat_Per,0)>0 And Nvl(G_Clc_Vat_Price_Typ,0) = 2 Then   
           V_I_Price_Vat := Case when nvl(P_I_Price_Vat,0) =0 Then Nvl (P_I_Price, 0) Else Nvl (P_I_Price_Vat, 0) End;
           V_I_Price   := Nvl (V_I_Price_Vat, 0) / ( (Nvl (V_Vat_Per, 0) / 100) + 1);           
          Else
             V_I_Price   := P_I_Price;
          End If;
      Else
          V_I_Price_Vat:=p_I_Price_Vat;
          V_I_Price   := P_I_Price;
          V_Vat_Per   := P_Vat_Per;
      End If;
      --##-----------------------------------------------------------------------------------------##--
      --## CHK ITM DATA
      Gnr_Api_Pkg.Chk_Itm (P_Sys_No              => G_Sys_No
                          ,P_Sys_Typ             => 1 --##    P_SYS_TYP =  1 = SALE , 2= STOCKE ,3 = PURCHASE ,
                          ,P_Trns_Typ            => -1 --##.    (1=IN)(-1=OUT)
                          ,P_Doc_Type            => G_Doc_Typ
                          ,P_I_Code              => P_I_Code
                          ,P_Itm_Unt             => P_Itm_Unt
                          ,P_P_Size              => P_P_Size
                          ,P_I_Qty               => P_I_Qty
                          ,P_Free_Qty            => P_Free_Qty
                          ,P_Res_Qty             => P_I_Qty
                          ,P_I_Price             => V_I_Price
                          ,P_I_Price_Vat         => V_I_Price_Vat
                          ,P_Measur_Price        => P_Measur_Price
                          ,P_Lev_No              => P_Lev_No
                          ,P_Qt_Prm_Method       => Null
                          ,P_Qut_Prm_Price       => Null --P_Qut_Prm_Price
                          ,P_Qt_Prm_Ser          => P_Qt_Prm_Ser
                          ,P_Dis_Per             => P_Dis_Per
                          ,P_Dis_Amt_Dtl         => P_Dis_Amt_Dtl
                          ,P_Dis_Amt_Dtl_Vat     => P_Dis_Amt_Dtl_Vat
                          ,P_Dis_Per2            => P_Dis_Per2
                          ,P_Dis_Amt_Dtl2        => P_Dis_Amt_Dtl2
                          ,P_Dis_Amt_Dtl2_Vat    => P_Dis_Amt_Dtl2_Vat
                          ,P_Dis_Per3            => P_Dis_Per3
                          ,P_Dis_Amt_Dtl3        => P_Dis_Amt_Dtl3
                          ,P_Dis_Amt_Dtl3_Vat    => P_Dis_Amt_Dtl3_Vat
                          ,P_Dis_Amt_Mst         => P_Dis_Amt_Mst
                          ,P_W_Code              => G_W_Code
                          ,P_Expire_Date         => P_Expire_Date
                          ,P_Batch_No            => P_Batch_No
                          ,P_Brn_No              => G_Brn_No
                          ,P_Doc_Date            => G_Doc_Date
                          ,P_Doc_Ser             => G_Doc_Ser                    
                          ,P_C_Code              => G_C_Code
                          ,P_Cur_Code            => G_Cur_Code
                          ,P_Ac_Rate             => G_Cur_Rate
                          ,P_Usr_No              => G_Ad_U_Id
                          ,P_Clc_Vat_Price_Typ   => Nvl (G_Clc_Vat_Price_Typ, 1)
                          ,P_Bill_Doc_Type       => G_Bill_Doc_Type
                          ,P_Stk_Cost            => Null
                          ,P_Chk_Avlqty_Flg      => G_Chk_Avlqty_Flg
                          ,P_Chk_Itm_Price       => G_Chk_Itm_Price --# 0 nocheck 1 check
                          ,P_Use_Vat             =>G_USE_VAT
                          ,P_Clc_Typ_No_Tax      =>G_Clc_Typ_No_Tax 
                          ,P_Lng_No              => G_Lng_No
                          ,P_Msg_Txt             => P_Msg_Txt
                          ,P_Pkg_Line            => P_Err_No
                          ,P_Pkg_Nm              => P_Pkg_Nm);

      If P_Msg_Txt Is Not Null Then
         Goto Rtn_Rslt;
      End If;

      V_P_Size         := Ias_Itm_Pkg.Get_Icode_Size_Unit (P_I_Code => P_I_Code, P_Itm_Unt => P_Itm_Unt);
      --##--------------------------------------------------------------------------------------------------------------##--
      If Nvl(V_P_Size,0)=0 Then
             P_Err_No    := 20667;
             P_MSG_TXT :='P_Size=0 For I_Code='||p_i_code;
            Goto Rtn_Rslt;                                                      
      End If;
      --##--------------------------------------------------------------------------------------------------------------##--
      Begin
         V_Stkcost      :=
            Ias_Itm_Inv_Pkg.Get_Itm_Cost (P_Costing_Type   => G_Costing_Type
                                         ,P_Wtavg_Type     => G_Wtavg_Type
                                         ,P_Icode          => P_I_Code
                                         ,P_Wcode          => G_W_Code
                                         ,P_Psize          => Nvl (V_P_Size, 1)
                                         ,P_Iqty           => (Nvl (P_I_Qty, 0) + Nvl (P_Free_Qty, 0))
                                         ,P_Expdate        => Nvl (P_Expire_Date, '01/01/1900')
                                         ,P_Batchno        => Nvl (P_Batch_No, '0')
                                         ,P_Brn_No         => G_Brn_No
                                         ,P_Brn_Year       => G_Brn_Year
                                         ,P_Cmp_No         => G_Cmp_No
                                         ,P_Brn_Usr        => G_Brn_Usr);
      Exception
         When Others Then
            P_Msg_Txt   := 'ERR WHEN GET ITM COST ' || Chr(10) || Sqlerrm;
            P_Err_No    := 20332;
            P_Pkg_Nm    := 'Ias_Itm_Inv_Pkg.Get_Itm_Cost';
            Goto Rtn_Rslt;
      End;
      --##-------------------------------------------------------------------------------------------------------------------------------##--
      --## SUB LDGR
      If G_Ar_Cst_Type = 2 Then
         G_Dtl_Cc_Code   := nvl(P_Cc_Code,G_Cc_Code);
      Else
         G_Dtl_Cc_Code   := G_Cc_Code;   
      End If;

      If G_Ar_Pj_Type = 2 Then
         G_Dtl_Pj_No   := nvl(P_Pj_No,G_Pj_No);
      Else
          G_Dtl_Pj_No   := G_Pj_No;
      End If;

      If G_Ar_Actv_Type = 2 Then
         G_Dtl_Actv_No   := nvl(P_Actv_No,G_Actv_No);
      Else
          G_Dtl_Actv_No   := G_Actv_No;         
      End If;
      
      Gnr_Api_Pkg.Chk_Sub_Ldgr (P_Sys_Typ     => 1
                               ,P_Sys_No      => G_Sys_No
                               ,P_Doc_Type    => G_Doc_Typ
                               ,P_Cst_Type    => G_Ar_Cst_Type
                               ,P_Pj_Type     => G_Ar_Pj_Type
                               ,P_Actv_Type   => G_Ar_Actv_Type
                               ,P_Cc_Code     => G_Dtl_Cc_Code
                               ,P_Pj_No       => G_Dtl_Pj_No
                               ,P_Actv_No     => G_Dtl_Actv_No
                               ,P_Rep_Code    => G_Rep_Code
                               ,P_A_Code      => G_A_Code
                               ,P_Chk_Ac_Cc   => 1
                               ,P_BILL_DOC_TYPE =>G_BILL_DOC_TYPE
                               ,P_C_CODE        =>G_C_CODE
                               ,P_P_Year        =>G_P_Year
                               ,P_Lng_No      => G_Lng_No
                               ,P_Msg_Txt     => P_Msg_Txt
                               ,P_Pkg_Line    => P_Err_No
                               ,P_Pkg_Nm      => P_Pkg_Nm);

      If P_Msg_Txt Is Not Null Then
         Goto Rtn_Rslt;
      End If;
      --##-----------------------------------------------------------------------------------------------##----


      --##--------------------------------------------------------------------------------------------------------------------------------##--
      Begin
         V_Post_Code   := Get_Post_Code_Inv (P_Type => G_Item_Posting_Flag, P_I_Code => P_I_Code, P_W_Code => G_W_Code);
      Exception
         When Others Then
            Null;
      End;
      --##--------------------------------------------------------------------------------------------------------------------------------##--
      --If P_Doc_Sequence Is Null Then
      Begin
         Select Ias_Doc_Seq.Nextval Into V_Doc_Sequence From Dual;
      Exception
         When Others Then
            ---Rollback;
            Raise_Application_Error (-20333, 'Err. When Get DOC_SEQ' || Chr (10) || Sqlerrm);
      End;

      P_Doc_Sequence   := V_Doc_Sequence;    
      --##--------------------------------------------------------------------------------------------------------------------------------##--
      G_Rcrd_No        := Nvl (G_Rcrd_No, 0) + 1;
      P_Rcrd_No        :=G_Rcrd_No;
      --##--------------------------------------------------------------------------------------------------------------------------------##--
      Select Service_Itm, Use_Serialno, Used_Itm
        Into V_Service_Itm, V_Use_Serialno, V_Used_Itm
        From Ias_Itm_Mst
       Where I_Code = P_I_Code And Rownum <= 1;

    --##--------------------------------------------------------------------------------------------------------------------------------##--
      --## Update Doc Ref
            Update_Doc_Ref    ( P_Doc_Type           =>G_Doc_Typ
                               ,P_Pst_Typ            =>G_Pst_Typ
                               ,P_Doc_Ser            =>G_Doc_Ser
                               ,P_I_Code             =>P_I_Code
                               ,P_Itm_Unt            =>P_Itm_Unt
                               ,P_P_Size             =>V_P_Size
                               ,P_I_Qty              => P_I_Qty
                               ,P_Free_Qty           =>P_Free_Qty
                               ,P_Rcrd_No            =>G_Rcrd_No
                               ,P_Doc_Type_Ref       =>P_Doc_Type_Ref
                               ,P_Doc_No_Ref         =>P_Doc_No_Ref
                               ,P_Doc_Ser_Ref        =>P_Doc_Ser_Ref
                               ,P_Rcrd_No_Ref        =>P_Rcrd_No_Ref
                               ,P_Msg_Txt            =>P_Msg_Txt
                               ,P_Err_No              =>P_Err_No
                               ,P_Pkg_Nm              =>P_Pkg_Nm);
      If P_Msg_Txt Is Not Null Then
         Goto Rtn_Rslt;
      End If;
      --##--------------------------------------------------------------------------------------------------------------------------------##--                               
                               
    If G_W_Code Is Not Null AND G_Ar_Wc_Type = 2 Then
      If  YS_SYS_GEN_PKG.CHK_ACTV_SYSTEM (P_SYS_NO => 70 , P_Brn_Usr => G_Brn_Usr)=1 and nvl(G_SYS_NO,0)<>70 Then
              Begin
               Select 1 Into V_Cnt 
               From Sales_Man 
               Where Nvl(W_Code,0)=G_W_Code 
               And Rownum<=1 ;       
            Exception When Others Then
               V_Cnt := 0;
            End;
            If Nvl(V_Cnt,0)>0 Then
                     P_Err_No    := 20648;
                     P_MSG_TXT := IAS_GEN_PKG.GET_MSG (G_Lng_No, 5145);
                    Goto Rtn_Rslt;                                                      
            End If;
      End If;
    End If;
     --##--------------------------------------------------------------------------------------------------------------------------------##--           
      --## Conn Wcode By Activity To Get Cc_Code + Pj_No + Actv_No       
          If G_W_Code Is Not Null And Nvl(G_Conn_Activity_By_Wcode_Cc,0) = 1 Then           
              If ( G_Ar_Cst_Type=2) Or ( G_Ar_Pj_Type=2) Or  ( G_Ar_Actv_Type=2) Then                 
                Ias_Itm_Pkg.Get_Itm_Activity_Wcode_Info ( P_W_Code       =>G_W_Code,
                                                          P_Itm_Actv_No  => Ias_Itm_Pkg.Get_Itm_Activity (P_I_Code => P_I_Code ) ,
                                                          P_Cc_Code      => V_Cc_Code  ,
                                                          P_Pj_No        => V_Pj_No    ,
                                                          P_Actv_No      => V_Actv_No  ) ;
              End If ; 
              
              If G_Ar_Cst_Type=2 and V_Cc_Code is Not Null Then
                   G_Dtl_Cc_Code:=V_Cc_Code;               
              End If;
              
              If G_Ar_Pj_Type=2 and V_Pj_No is Not Null Then
                   G_Dtl_Pj_No:=V_Pj_No;                
              End If; 
              
              If G_Ar_Actv_Type=2 and V_Actv_No is Not Null Then
                   G_Dtl_Actv_No:=V_Actv_No;                 
              End If;          
                                                           
          End If ;
     --##--------------------------------------------------------------------------------------------------------------------------------##-- 
      If Nvl (V_Service_Itm, 0) = 0 And (Nvl (P_I_Qty, 0) > 0 Or Nvl (P_Free_Qty, 0) > 0) And Nvl (G_Pst_Typ, 0) = 2 Then
       IF Nvl(G_Use_Out_Bills, 0) = 0 OR( Nvl(G_Use_Out_Bills, 0) = 1 AND NVL(G_INSRT_OUT_BILLS_FLG,0)=1) Then
        V_OUT_FREE_QTY:=Nvl (P_Free_Qty, 0);
        V_OUT_Qty:=Nvl (P_I_Qty, 0);
         Begin
            V_Cst   := 0;
            Ias_Itm_Inv_Pkg.Insrt_Sale_Cost (P_Cst           => V_Cst
                                            ,P_Wtavg_Type    => G_Wtavg_Type
                                            ,P_Icode         => P_I_Code
                                            ,P_Iqty          => Nvl (P_I_Qty, 0)
                                            ,P_Freeqty       => Nvl (P_Free_Qty, 0)
                                            ,P_Itm_Unt       => P_Itm_Unt
                                            ,P_Psize         => V_P_Size
                                            ,P_Cost_Type     => G_Costing_Type
                                            ,P_Wcode         => G_W_Code
                                            ,P_Doctype       => 1
                                            ,P_Docno         => G_Doc_No
                                            ,P_Billdoctype   => G_Bill_Doc_Type
                                            ,P_Cc_Code       => G_Dtl_Cc_Code
                                            ,P_Pj_No         => G_Dtl_Pj_No
                                            ,P_Actv_No       => G_Dtl_Actv_No
                                            ,P_Rcrdno        => G_Rcrd_No
                                            ,P_Expdate       => To_Date (Nvl (P_Expire_Date, '01/01/1900'), 'DD/MM/YYYY')
                                            ,P_Batchno       => Nvl (P_Batch_No, '0')
                                            ,P_Docser        => G_Doc_Ser
                                            ,P_Docseq        => V_Doc_Sequence
                                            ,P_Idate         => G_Doc_Date
                                            ,P_Vatamt        => Nvl (P_Vat_Amt, 0)
                                            ,P_Disamt        => P_Dis_Amt
                                            ,P_Acy           => G_Cur_Code
                                            ,P_Ac_Rate       => G_Cur_Rate
                                            ,P_Stk_Rate      => G_Stk_Rate
                                            ,P_C_Code        => G_C_Code
                                            ,P_Adesc         => G_Doc_Dsc
                                            ,P_Refno         => G_Ref_No
                                            ,P_Outno         => G_out_no 
                                            ,P_Outgrser      => G_out_ser
                                            ,P_Inout         => -1
                                            ,P_Iprice        => Nvl (V_I_Price, 0)
                                            ,P_Itm_Length    => P_I_Length
                                            ,P_Itm_Width     => P_I_Width
                                            ,P_Itm_Height    => P_I_Height
                                            ,P_Itm_Number    => P_I_Number
                                            ,P_Wt_Qty        => P_Wt_Qty
                                            ,P_Wt_Unt        => P_Wt_Unt
                                            ,P_Argmnt_No     => P_Argmnt_No
