                                            ,P_Brn_Year      => G_Brn_Year
                                            ,P_Cmp_No        => G_Cmp_No
                                            ,P_Brn_Usr       => G_Brn_Usr);
         Exception
            When Others Then             
               P_Err_No    := 20489;
               P_Msg_Txt   := 'Err. When Insrt Into Sale Cost ' || Chr (10) || Sqlerrm;
               P_Pkg_Nm    :='Ias_Itm_Inv_Pkg.Insrt_Sale_Cost';
               Goto Rtn_Rslt;             
         End;

         V_Cst   := Nvl (V_Cst, 0) * Nvl (V_P_Size, 1);
          Else
         V_Cst   := V_Stkcost;
       END IF;  
        Else
         V_Cst   := V_Stkcost;
      End If;
      --##--------------------------------------------------------------------------------------------------------------------------------##--
        If   G_SHW_ITM_COMM_PER = 1 Then
