                  SELECT 
                        Decode(Nvl(HAS_COMM,0),1,Decode(Nvl(Comm_Type,2),0,Comm_Amt)) Comm_Per,
                        Decode(Nvl(HAS_COMM,0),1,Decode(Nvl(Comm_Type,2),1,Comm_Amt)) Comm_Amt_Dtl
                        INTO 
