                       ,V_Comm_Amt_Dtl
                        FROM IAS_ITM_MST
                        WHERE I_CODE=P_I_CODE
                        AND ROWNUM<=1;
             EXCEPTION WHEN OTHERS THEN
                 V_Comm_Per:=NULL;
                 V_Comm_Amt_Dtl:=NULL;
             END; 
      END IF;
     --##--------------------------------------------------------------------------------------------------------------------------------##--
       If Nvl (G_Pst_Typ, 0) = 2 Then
         ----------------------------------
         --## get Rep_Code_Sp
           Begin
                If P_I_Code Is Not Null And G_R_Code Is Not Null And Nvl(G_Use_Sp_Sman,0)=1 Then
                     Begin
                            Select Sales_Man.Reprs_Code
                              Into V_Rep_Code_Sp
                              From Sales_Man, Ias_Itm_Sman, Ias_Rgn_Sman
                             Where Sales_Man.Reprs_Code = Ias_Itm_Sman.Rep_Code 
                               And Sales_Man.Reprs_Code = Ias_Rgn_Sman.Rep_Code 
                               And Nvl (Sales_Man.Conn_Sp_Sman, 0) = 1 
                               And Nvl (Sales_Man.Inactive, 0) = 0
                               And I_Code =P_I_Code
                               And Ias_Rgn_Sman.R_Code =G_R_Code
                               And RowNum<=1;
                     Exception When OThers Then
                          V_Rep_Code_Sp:=Null;                         
                     End;
               End IF;
            End;
          ----------------------------------------------
          --## get Prm_Code_Out
          Begin
                If V_Rep_Code_Sp Is Not Null And G_R_Code Is Not Null And Nvl(G_Use_Sp_Sman,0)=1 Then
                     Begin    
                            Select Ias_Rgn_Sman.Prm_Code 
                              Into V_Prm_Code_Out
                              From Ias_Promoters,Ias_Rgn_Sman,Ias_Prm_Rgn
                             Where Ias_Promoters.Prm_Code=Ias_Prm_Rgn.Prm_Code
                               And Ias_Rgn_Sman.R_Code=Ias_Prm_Rgn.R_Code
                               And Nvl(Ias_Promoters.Conn_Sp_Sman,0)=1
                               And Nvl(Ias_Promoters.INACTIVE,0)=0
                               And Ias_Rgn_Sman.Rep_Code=V_Rep_Code_Sp
                               And Ias_Rgn_Sman.R_Code=G_R_Code
                               And RowNum<=1;
                     Exception When Others Then
                            V_Prm_Code_Out:=Null;                            
                     End;
                 End IF;
          End; 
          ---------------------------------------------- 
