                     ,G_Cmp_No
                     ,G_Brn_No
                     ,G_Brn_Year
                     ,G_Brn_Usr)
                      Return Cc_Code,Pj_No,Actv_No into G_Dtl_Cc_Code,G_Dtl_Pj_No,G_Dtl_Actv_No;
      End If;
      
       If Nvl(G_Use_Serialno,0) <> 0 AND NVL(V_Use_Serialno,0)=1 Then
               --## Insert Serialno   
               IF P_Serialno_N||','=','  THEN
                    P_Err_No    := 20491;
                    P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 322) ||CHR(10)|| ' I_CODE = ' || P_I_Code;
                    Goto Rtn_Rslt; 
               END IF;
                                    
               Begin                          
                  Inv_Api_Trns_Pkg.Insrt_Ias_Item_Serialno ( 
                                             P_sys_no           => G_Sys_No
                                            ,P_TBL_NM           => V_TBL_Serialno
                                            ,P_Doc_Type         => 4
                                            ,P_Bill_Doc_Type    => G_Bill_Doc_Type
                                            ,P_Doc_No           => G_Doc_No
                                            ,P_Doc_Ser          => G_Doc_Ser
                                            ,P_Doc_Date         => G_Doc_Date
                                            ,P_I_Code           => P_I_Code
                                            ,P_Itm_Unt          => P_Itm_Unt
                                            ,P_I_Qty            => P_I_Qty
                                            ,P_Free_Qty         => P_Free_Qty
                                            ,P_P_Size           => V_P_Size
                                            ,P_Serialno         => P_Serialno_N||','
                                            ,P_Desc_No          => Null
                                            ,P_W_Code           => G_W_Code
                                            ,P_Cc_Code          => G_Dtl_Cc_Code
                                            ,P_Pj_No            => G_Dtl_Pj_No
                                            ,P_Actv_No          => G_Dtl_Actv_No
                                            ,P_Expire_Date      => To_Date (Nvl (P_Expire_Date, '01/01/1900'), 'Dd/Mm/Yyyy')
                                            ,P_Batch_No         => Nvl (P_Batch_No, '0')
                                            ,P_Free_Flg         => 0
                                            ,P_Bill_Cost        => 1
                                            ,P_Out_No           => Null
                                            ,P_Out_Gr_Ser       => Null
                                            ,P_In_Out           => -1--V_In_Out
                                            ,P_Rcrd_No          => G_Rcrd_No
                                            ,P_Rcrd_No_Doc      => G_Rcrd_No
                                            ,P_F_Doc_No         => NULL
                                            ,P_F_Doc_Ser        => NULL
                                            ,P_F_Rcrd_No        => NULL
                                            ,P_F_W_Code         => NULL                          
                                            ,P_External_Post    => G_External_Post
                                            ,P_Ad_Date          => G_Ad_Date
                                            ,P_Ad_U_Id          => G_Ad_U_Id
                                            ,P_Cmp_No           => G_Cmp_No
                                            ,P_Brn_No           => G_Brn_No
                                            ,P_Brn_Year         => G_Brn_Year
                                            ,P_Brn_Usr          => G_Brn_Usr
                                            ,P_Msg_Txt          => P_Msg_Txt
                                            ,P_Err_No           => P_Err_No
                                            ,P_Pkg_Nm           => P_Pkg_Nm
                                           ) ;
                       IF P_Msg_Txt IS NOT NULL THEN
                        Goto Rtn_Rslt;
                       END IF;              
               Exception
                  When Others Then
                     P_Err_No    := 20490;
                     P_Msg_Txt   := 'Err IN INSERT SERIALNO  ' || Sqlerrm;
                     Goto Rtn_Rslt;
               End;              
         End If;                            
     --####################--
     <<RTN_RSLT>>
      If P_Msg_Txt Is Not Null OR P_Err_No Is Not Null Then
         Rollback;
         P_Msg_Txt   := NVL(P_Msg_Txt,'Message Number Is Missing');
         P_Err_No    := P_Err_No;
         P_Pkg_Nm    := Nvl (P_Pkg_Nm, 'Ars_Api_Trns_Pkg.Insrt_Ias_Bill_Dtl');
         Return;
      Else
         P_Msg_Txt   := Null;
         P_Err_No    := Null;
         P_Pkg_Nm    := Null;
      End If;
   --####################--

   Exception
      When Others Then
         Rollback;
         P_Msg_Txt   := 'Error When Insert Into ' || V_Tbl_Dtl || Chr(10) || Sqlerrm;
         P_Err_No    := 20335;
         P_Pkg_Nm    := 'Ars_Api_Trns_Pkg.Insrt_Ias_Bill_Dtl';
   End;
End Insrt_Ias_Bill_Dtl;
