                  ,P_Field3
                  ,P_Field4
                  ,P_Field5
                  ,P_Field6
                  ,P_Field7
                  ,P_Field8
                  ,P_Field9
                  ,P_Field10
                  ,P_Prm_Code
                  ,Nvl (P_Bill_Amt, 0)
                  ,Nvl (P_Disc_Amt, 0)
                  ,Nvl (P_Disc_Amt_Mst, 0)
                  ,Nvl (P_Disc_Amt_Dtl, 0)
                  ,Nvl (P_Vat_Amt, 0)
                  ,Nvl (P_Othr_Amt, 0)
                  ,Nvl (P_Othr_Amt_Disc, 0)
                  ,Nvl (P_Vat_Amt_Othr, 0)
                  ,Nvl (P_Disc_Amt_Aftr_Vat, 0)
                  ,Nvl (P_Disc_Amt_Mst_Vat, 0)
                  ,Nvl (P_Vat_Amt_Disc_Mst, 0)
                  ,G_External_Post
                  , NVL(G_CLC_TAX_FREE_QTY_FLG,0)                  
                   ,V_CREDIT_CARD                             
                    ,P_CR_CARD_AMT                                
                    ,P_CR_CARD_AMT_SCND                     
                    ,P_CR_CARD_AMT_THRD                     
                    ,V_CR_CARD_COMM_PER                     
                    ,V_CR_CARD_COMM_PER_SCND          
                    ,V_CR_CARD_COMM_PER_THRD                                                                                                                                                                                                                                                                                       
                    ,P_CR_CARD_NO                                
                    ,P_CR_CARD_NO_SCND                        
                    ,P_CR_CARD_NO_THRD
                    ,P_Bnk_Amt 
                   ,Ias_Brn_Pkg.Get_Br_Inf ( G_brn_no => G_Brn_No ,P_inf_type =>'BRN_TAX_CODE')
                  ,G_Cmp_No
                  ,G_Brn_No
                  ,G_Brn_Year
                  ,G_Brn_Usr
                  ,G_Ad_U_Id
                  ,G_Ad_Date
                  ,P_Ad_Trmnl_Nm
                  ,V_E_INVC_MTHD_NO
                  ,V_C_TAX_CODE
                  ,V_TAX_BILL_TYP
                  )
                   Return Cc_Code,Pj_No,Actv_No into G_Mst_Cc_Code,G_Mst_Pj_No,G_Mst_Actv_No;
   End If;
   -----------------------------------------------------------------------------------------
  --####################--
  <<RTN_RSLT>>
   If P_Msg_Txt Is Not Null OR P_Err_No Is Not Null Then
      Rollback;
      P_Msg_Txt   := NVL(P_Msg_Txt,'Message Number Is Missing');
      P_Err_No    := P_Err_No;
      P_Pkg_Nm    := Nvl (P_Pkg_Nm, 'Ars_Api_Trns_Pkg.Insrt_Ias_Rt_Bill_Mst');
      Return;
   ELSE
      P_Msg_Txt   := NULL;
      P_Err_No    := NULL;
      P_Pkg_Nm    := NULL;   
   End If;
--####################--
Exception
   When Others Then
      Rollback;
      P_Msg_Txt   := 'ERROR WHEN INSERT ' || V_Tbl_Mst || ' ' || Chr (10) || Sqlerrm;
      P_Err_No    := 20339;
      P_Pkg_Nm    := 'Ars_Api_Trns_Pkg.Insrt_Ias_Rt_Bill_Mst';
End Insrt_Ias_Rt_Bill_Mst;

--##-----------------------------------------------------------------------------------------------------##--
 Procedure Insrt_Ias_Rt_Bill_Dtl (P_I_Code                 In     Ias_Rt_Bill_Dtl.I_Code%Type Default Null
                                ,P_I_Qty                  In     Ias_Rt_Bill_Dtl.I_Qty%Type Default Null
                                ,P_P_Size                 In     Ias_Rt_Bill_Dtl.P_Size%Type Default Null
                                ,P_Itm_Unt                In     Ias_Bill_Dtl.Itm_Unt%Type Default Null
                                ,P_I_Price                In     Ias_Rt_Bill_Dtl.I_Price%Type Default Null
                                ,P_I_Price_Vat            In     Ias_Rt_Bill_Dtl.I_Price_Vat%Type Default Null
                                ,P_Doc_Sequence           In Out Ias_Rt_Bill_Dtl.Doc_Sequence%Type
                                ,P_Rcrd_No                In Out Ias_Rt_Bill_Dtl.Rcrd_NO%Type
                                ,P_W_Code                 In     Ias_Rt_Bill_Dtl.W_Code%Type Default Null
                                ,P_Bill_No                In     Ias_Rt_Bill_Dtl.Bill_No%Type Default Null
                                ,P_Bill_Doc_Type          In     Ias_Rt_Bill_Dtl.Bill_Doc_Type%Type Default Null
                                ,P_Bill_Ser               In     Ias_Rt_Bill_Dtl.Bill_Ser%Type Default Null
                                ,P_Cc_Code                In     Ias_Rt_Bill_Dtl.Cc_Code%Type Default Null
                                ,P_Pj_No                  In     Ias_Rt_Bill_Dtl.Pj_No%Type Default Null
                                ,P_Actv_No                In     Ias_Rt_Bill_Dtl.Actv_No%Type Default Null
                                ,P_Expire_Date            In     Ias_Rt_Bill_Dtl.Expire_Date%Type Default Null
                                ,P_Batch_No               In     Ias_Rt_Bill_Dtl.Batch_No%Type Default Null
                                ,P_Free_Qty               In     Ias_Rt_Bill_Dtl.Free_Qty%Type Default Null
                                ,P_DOC_SEQUENCE_SI        In     Ias_Rt_Bill_Dtl.DOC_SEQUENCE_SI%Type Default Null
                                ,P_SI_RCRD_NO             In     Ias_Rt_Bill_Dtl.SI_RCRD_NO%Type      Default Null
                                ,P_Dis_Per                In     Ias_Rt_Bill_Dtl.Dis_Per%Type Default Null
                                ,P_Dis_Per2               In     Ias_Rt_Bill_Dtl.Dis_Per2%Type Default Null
                                ,P_Dis_Per3               In     Ias_Rt_Bill_Dtl.Dis_Per3%Type Default Null
                                ,P_Dis_Amt                In     Ias_Rt_Bill_Dtl.Dis_Amt%Type Default Null
                                ,P_Dis_Amt_Mst            In     Ias_Rt_Bill_Dtl.Dis_Amt_Mst%Type Default Null
                                ,P_Dis_Amt_Dtl            In     Ias_Rt_Bill_Dtl.Dis_Amt_Dtl%Type Default Null
                                ,P_Dis_Amt_Dtl2           In     Ias_Rt_Bill_Dtl.Dis_Amt_Dtl2%Type Default Null
                                ,P_Dis_Amt_Dtl3           In     Ias_Rt_Bill_Dtl.Dis_Amt_Dtl3%Type Default Null
                                ,P_Vat_Per                In     Ias_Rt_Bill_Dtl.Vat_Per%Type Default Null
                                ,P_Vat_Amt                In     Ias_Rt_Bill_Dtl.Vat_Amt%Type Default Null
                                ,P_Bnk_Amt_dtl            In     Ias_Rt_Bill_Dtl.Bnk_Amt_dtl%Type Default Null
                                ,P_Othr_Amt               In     Ias_Rt_Bill_Dtl.Othr_Amt%Type Default Null
                                ,P_Vat_Amt_Othr           In     Ias_Rt_Bill_Dtl.Vat_Amt_Othr%Type Default Null
                                ,P_Othr_Amt_Disc          In     Ias_Rt_Bill_Dtl.Othr_Amt_Disc%Type Default Null
                                ,P_Dis_Aftr_Vat_Mst       In     Ias_Rt_Bill_Dtl.Dis_Aftr_Vat_Mst%Type Default Null
                                ,P_Dis_Amt_Mst_Vat        In     Ias_Rt_Bill_Dtl.Dis_Amt_Mst_Vat%Type Default Null
                                ,P_Vat_Amt_Dis_Dtl_Vat    In     Ias_Rt_Bill_Dtl.Vat_Amt_Dis_Dtl_Vat%Type Default Null
                                ,P_Vat_Amt_Aftr_Dis       In     Ias_Rt_Bill_Dtl.Vat_Amt_Aftr_Dis%Type Default Null
                                ,P_Vat_Amt_Bfr_Dis        In     Ias_Rt_Bill_Dtl.Vat_Amt_Bfr_Dis%Type Default Null
                                ,P_Dis_Amt_Dtl_Vat        In     Ias_Rt_Bill_Dtl.Dis_Amt_Dtl_Vat%Type Default Null
                                ,P_Dis_Amt_Dtl2_Vat       In     Ias_Rt_Bill_Dtl.Dis_Amt_Dtl2_Vat%Type Default Null
                                ,P_Dis_Amt_Dtl3_Vat       In     Ias_Rt_Bill_Dtl.Dis_Amt_Dtl3_Vat%Type Default Null
                                ,P_Vat_Amt_Dis_Mst_Vat    In     Ias_Rt_Bill_Dtl.Vat_Amt_Dis_Mst_Vat%Type Default Null
                                ,P_Vat_Amt_Dis_Dtl2_Vat   In     Ias_Rt_Bill_Dtl.Vat_Amt_Dis_Dtl2_Vat%Type Default Null
                                ,P_Vat_Amt_Dis_Dtl3_Vat   In     Ias_Rt_Bill_Dtl.Vat_Amt_Dis_Dtl3_Vat%Type Default Null
                                ,P_Dis_Amt_Aftr_Vat       In     Ias_Rt_Bill_Dtl.Dis_Amt_Aftr_Vat%Type Default Null
                                ,P_Lev_No                 In     Ias_Bill_Dtl.Lev_No%Type Default Null
                                ,P_Item_Desc              In     Ias_Rt_Bill_Dtl.Item_Desc%Type Default Null
                                ,P_Barcode                In     Ias_Rt_Bill_Dtl.Barcode%Type Default Null
                                ,P_Field_Dtl1             In     Ias_Rt_Bill_Dtl.Field_Dtl1%Type Default Null
                                ,P_Field_Dtl2             In     Ias_Rt_Bill_Dtl.Field_Dtl2%Type Default Null
                                ,P_Field_Dtl3             In     Ias_Rt_Bill_Dtl.Field_Dtl3%Type Default Null
                                ,P_Emp_No                 In     Ias_Rt_Bill_Dtl.Emp_No%Type Default Null
                                ,P_Doc_Type_Ref           In     Ias_Rt_Bill_Dtl.Doc_Type_Ref%Type Default Null
                                ,P_Doc_No_Ref             In     Ias_Rt_Bill_Dtl.Doc_No_Ref%Type Default Null
                                ,P_Doc_Ser_Ref            In     Ias_Rt_Bill_Dtl.Doc_Ser_Ref%Type Default Null
                                ,P_Sub_C_Code             In     Ias_Rt_Bill_Dtl.Sub_C_Code%Type Default Null
                                ,P_Rcrd_No_Ref            In     Ias_Rt_Bill_Dtl.Rcrd_No_Ref%Type Default Null
                                ,P_Qt_Prm_No              In     Ias_Rt_Bill_Dtl.Qt_Prm_No%Type Default Null
                                ,P_Qt_Prm_Ser             In     Ias_Rt_Bill_Dtl.Qt_Prm_Ser%Type Default Null
                                ,P_Qt_Prm_Rcrd_No         In     Ias_Rt_Bill_Dtl.Qt_Prm_Rcrd_No%Type Default Null
                                ,P_I_Length               In     Ias_Rt_Bill_Dtl.I_Length%Type Default Null
                                ,P_I_Width                In     Ias_Rt_Bill_Dtl.I_Width%Type Default Null
                                ,P_I_Height               In     Ias_Rt_Bill_Dtl.I_Height%Type Default Null
                                ,P_I_Number               In     Ias_Rt_Bill_Dtl.I_Number%Type Default Null
                                ,P_Wt_Qty                 In     Ias_Rt_Bill_Dtl.Wt_Qty%Type Default Null
                                ,P_Wt_Unt                 In     Ias_Rt_Bill_Dtl.Wt_Unt%Type Default Null -- ,P_MEASUR_PRICE               IN IAS_RT_BILL_DTL.MEASUR_PRICE%TYPE                 DEFAULT NULL
                                ,P_Argmnt_No              In     Ias_Rt_Bill_Dtl.Argmnt_No%Type Default Null
                                ,P_SERIALNO_N             IN     CLOB  Default Null
                                ,P_Msg_Txt                   Out Varchar2
                                ,P_Err_No                    Out Varchar2
                                ,P_Pkg_Nm                    Out Varchar2)
Is
   V_P_Size                  Ias_Itm_Dtl.P_Size%Type;
   V_Cnt                     Number;
   V_Msg_No                  Number;
   V_Stkcost                 Ias_Bill_Dtl.Stk_Cost%Type;   
   V_Doc_Sequence            Ias_Bill_Dtl.Doc_Sequence%Type;
   V_Service_Itm             Number;
   V_Cst                     Number;
   V_Use_Serialno            Number;
   V_Post_Code               Ias_Bill_Dtl.Post_Code%Type;
   V_Used_Itm                Number;  
   V_Tbl_Dtl                 Varchar2 (2000); 
   V_Wcode                   Number;
   V_Allow_Enter_Zero_Cost   Number := 0;
   V_Wt_After                Number;
   V_Ret_No                  Ias_Rt_Bill_Mst.Rt_Bill_No%Type;
   V_Ret_Ser                 Ias_Rt_Bill_Mst.Rt_Bill_Ser%Type;
   V_Bill_No                 Ias_Bill_Mst.Bill_No%Type;
   V_Bill_Doc_Type           Number;
   V_Doc_Sequence_Si         Number;
   V_Si_Rcrd_No              Number;
   V_Si_I_Qty                Number;
   V_Si_Free_Qty             Number;
   V_I_Price                 Number:=P_I_Price;
   V_I_Price_Vat             Number:=p_I_Price_Vat;
   V_Vat_Per                 Number;
   V_Clc_Typ_No              Number;
   V_TBL_Serialno     Varchar2 (500);
   V_CNT_QTY          NUMBER; 
   V_Comm_Per           NUMBER;
   V_Comm_Amt_Dtl       NUMBER;
   V_Comm_Per_MST        NUMBER;
   V_Rep_Code_Sp       Ias_Bill_Dtl.Rep_Code_Sp%Type;
    V_Prm_Code_Out      Ias_Bill_Dtl.Prm_Code_Out%Type;
    V_Cc_Code           COST_CENTERS.Cc_Code%Type;  
    V_Pj_No             IAS_PROJECTS.Pj_No%Type;
    V_Actv_No           IAS_ACTVTY.Actv_No%Type;
    V_RET_QTY           Ias_RT_Bill_Dtl.RET_QTY%Type;
    V_RET_FREE_QTY      Ias_RT_Bill_Dtl.RET_FREE_QTY%Type;
    V_YR                Varchar2(500);     
   
Begin
   If G_Doc_Ser Is Null Or G_Doc_No Is Null Then
      P_Err_No    := 20138;
      P_Msg_Txt   := 'G_DOC_SER OR G_DOC_NO .. IS NULL ';
      Goto Rtn_Rslt;
   End If;

   If G_Pst_Typ Is Null Then
      P_Err_No    := 20139;
      P_Msg_Txt   := 'PST_TYP IS NULL ';
      Goto Rtn_Rslt;
   Elsif G_Pst_Typ Not In (1, 2) Then
      P_Err_No    := 20140;
      P_Msg_Txt   := 'Pst_Typ Must Be Equal 1 Or 2 ';
      Goto Rtn_Rslt;
   End If;

   If G_Pst_Typ = 2 Then
      V_Tbl_Dtl          := 'IAS_RT_BILL_DTL';
       V_TBL_Serialno     :='IAS_ITEM_SERIALNO';    
   Else
      V_Tbl_Dtl          := 'IAS_RT_BILL_DTL_BR';
       V_TBL_Serialno     :='IAS_ITEM_SERIALNO_BR';     
   End If;

   --##------------------------------------------------------------------------------------------##--
   If G_Ar_Wc_Type = 1 Then
      G_W_Code   := G_W_Code;
   Else
      G_W_Code   := Nvl (P_W_Code, G_W_Code);
      If G_W_Code Is Not Null Then
        GNR_API_PKG.Chk_Inpt_Data (P_Inpt_Typ     => 'W_CODE'
                                   ,P_SYS_TYP      =>1
                                   ,P_DOC_TYPE     => G_DOC_TYP
                                   ,P_Inpt_Code1   => G_W_Code
                                   ,P_Inpt_Code2   => G_Brn_No
                                   ,P_Inpt_Code3   => G_ALLW_SAL_WH_NOT_CONN_BRN
                                   ,P_Inpt_Code4   => G_USE_BALANCED_BRN
                                   ,P_Lng_Dflt     => G_Lng_No
                                   ,P_Inpt_Nm      => G_Inpt_Nm
                                   ,P_Msg_No       => V_Msg_No);

         If V_Msg_No Is Not Null Then
            P_Err_No :=20740 ;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No) || ' W_CODE=' || G_W_Code;
            Goto Rtn_Rslt;
         End If;
      END IF;
   End If;

   If G_W_Code Is Null Then
      P_Err_No    := 20141;
      P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 930);
      Goto Rtn_Rslt;
   End If;
   --##---------------------------------------------------------------------------------------------------------------------------##--
   If Nvl (G_Use_Vat, 0) = 1 And G_Clc_Typ_No_Tax Is Not Null And Nvl (G_Clc_Tax_Method, 0) = 1 Then       
         If Nvl (Ys_Tax_Pkg.Get_Clc_Tax_Typ (P_Clc_Typ_No => G_Clc_Typ_No_Tax), 0) = 0 Then
            -- V_Vat_Per   := Ys_Tax_Pkg.Get_Itm_Tax_Prcnt (P_Clc_Typ_No => G_Clc_Typ_No_Tax, P_I_Code => P_I_Code, P_Clc_Usd_Itm => 1);
              V_Vat_Per   :=Ys_Tax_Pkg.Get_Itm_Tax_Prcnt_Sal ( P_Clc_Typ_No =>G_Clc_Typ_No_Tax  
                                                             , P_I_Code => P_I_CODE 
                                                              ,P_Clc_Usd_Itm => 1
                                                              ,P_I_Price=>P_I_Price
                                                              ,P_I_Price_Vat =>case when Nvl(G_Clc_Vat_Price_Typ,0) = 2 Then (Case when nvl(P_I_Price_Vat,0) =0 Then Nvl (P_I_Price, 0) Else Nvl (P_I_Price_Vat, 0) end) else Nvl (P_I_Price, 0) end  
                                                              ,P_Use_Price_Include_Vat=> case when Nvl(G_Clc_Vat_Price_Typ,0) = 2 then 1 else 0 end ); 
          Else
             V_Clc_Typ_No   := Ys_Tax_Pkg.Get_Clc_Typ_No_Exmpt (P_Clc_Typ_No => G_Clc_Typ_No_Tax);
            -- V_Vat_Per      := Ys_Tax_Pkg.Get_Itm_Tax_Prcnt (P_Clc_Typ_No => V_Clc_Typ_No, P_I_Code => P_I_Code, P_Clc_Usd_Itm => 1);
            V_Vat_Per   :=Ys_Tax_Pkg.Get_Itm_Tax_Prcnt_Sal ( P_Clc_Typ_No =>V_Clc_Typ_No  
                                                             , P_I_Code => P_I_CODE 
                                                              ,P_Clc_Usd_Itm => 1
                                                              ,P_I_Price=>P_I_Price
                                                              ,P_I_Price_Vat =>case when Nvl(G_Clc_Vat_Price_Typ,0) = 2 Then (Case when nvl(P_I_Price_Vat,0) =0 Then Nvl (P_I_Price, 0) Else Nvl (P_I_Price_Vat, 0) end) else Nvl (P_I_Price, 0) end  
                                                              ,P_Use_Price_Include_Vat=> case when Nvl(G_Clc_Vat_Price_Typ,0) = 2 then 1 else 0 end );
          End If;
          If nvl(V_Vat_Per,0)>0 And Nvl(G_Clc_Vat_Price_Typ,0) = 2 Then
            V_I_Price_Vat := Case when nvl(P_I_Price_Vat,0) =0 Then Nvl (P_I_Price, 0) Else Nvl (P_I_Price_Vat, 0) End;   
            V_I_Price   := Nvl (V_I_Price_Vat, 0) / ( (Nvl (V_Vat_Per, 0) / 100) + 1);
          Else
             V_I_Price   := P_I_Price;
          End If;
   Else
          V_I_Price_Vat:=p_I_Price_Vat;
          V_I_Price   := P_I_Price;
          V_Vat_Per   := P_Vat_Per;
   End If;
   --##------------------------------------------------------------------------------------------##--   
   --## CHK ITM DATA
   Gnr_Api_Pkg.Chk_Itm (P_Sys_No              => G_Sys_No
                       ,P_Sys_Typ             => 1 --##    P_SYS_TYP =  1 = SALE , 2= STOCKE ,3 = PURCHASE ,
                       ,P_Trns_Typ            => 1 --##.    (1=IN)(-1=OUT)
                       ,P_Doc_Type            => G_Doc_Typ
                       ,P_I_Code              => P_I_Code
                       ,P_Itm_Unt             => P_Itm_Unt
                       ,P_P_Size              => P_P_Size
                       ,P_I_Qty               => P_I_Qty
                       ,P_Free_Qty            => P_Free_Qty
                       ,P_Res_Qty             => P_I_Qty
                       ,P_I_Price             => V_I_Price
                       ,P_I_Price_Vat         => V_I_Price_Vat
                       ,P_Measur_Price        => Null
                       ,P_Lev_No              => P_Lev_No
                       ,P_Qt_Prm_Method       => Null
                       ,P_Qut_Prm_Price       => Null
                       ,P_Qt_Prm_Ser          => P_Qt_Prm_Ser
                       ,P_Dis_Per             => P_Dis_Per
                       ,P_Dis_Amt_Dtl         => P_Dis_Amt_Dtl
                       ,P_Dis_Amt_Dtl_Vat     => P_Dis_Amt_Dtl_Vat
                       ,P_Dis_Per2            => P_Dis_Per2
                       ,P_Dis_Amt_Dtl2        => P_Dis_Amt_Dtl2
                       ,P_Dis_Amt_Dtl2_Vat    => P_Dis_Amt_Dtl2_Vat
                       ,P_Dis_Per3            => P_Dis_Per3
                       ,P_Dis_Amt_Dtl3        => P_Dis_Amt_Dtl3
                       ,P_Dis_Amt_Dtl3_Vat    => P_Dis_Amt_Dtl3_Vat
                       ,P_Dis_Amt_Mst         => P_Dis_Amt_Mst
                       ,P_W_Code              => G_W_Code
                       ,P_Expire_Date         => P_Expire_Date
                       ,P_Batch_No            => P_Batch_No
                       ,P_Brn_No              => G_Brn_No
                       ,P_Doc_Date            => G_Doc_Date
                       ,P_Doc_Ser             => G_Doc_Ser                    
                       ,P_C_Code              => G_C_Code
                       ,P_Cur_Code            => G_Cur_Code
                       ,P_Ac_Rate             => G_Cur_Rate
                       ,P_Usr_No              => G_Ad_U_Id
                       ,P_Clc_Vat_Price_Typ   => Nvl (G_Clc_Vat_Price_Typ, 1)
                       ,P_Bill_Doc_Type       => G_Rt_Bill_Doc_Type
                       ,P_Stk_Cost            => Null
                       ,P_Chk_Avlqty_Flg      => G_Chk_Avlqty_Flg
                       ,P_Chk_Itm_Price       => G_Chk_Itm_Price --# 0 nocheck 1 check
                       ,P_Use_Vat             =>G_USE_VAT
                       ,P_Clc_Typ_No_Tax      =>G_Clc_Typ_No_Tax 
                       ,P_Lng_No              => G_Lng_No
                       ,P_Msg_Txt             => P_Msg_Txt
                       ,P_Pkg_Line            => P_Err_No
                       ,P_Pkg_Nm              => P_Pkg_Nm);

   If P_Msg_Txt Is Not Null Then
      Goto Rtn_Rslt;
   End If;

   V_P_Size         := Ias_Itm_Pkg.Get_Icode_Size_Unit (P_I_Code => P_I_Code, P_Itm_Unt => P_Itm_Unt);

   --##-------------------------------------------------------------------------------------------------------------------------------##--
    If Nvl(V_P_Size,0)=0 Then
             P_Err_No    := 20668;
             P_MSG_TXT :='P_Size=0 For I_Code='||p_i_code;
            Goto Rtn_Rslt;                                                      
     End If;
    --##-------------------------------------------------------------------------------------------------------------------------------##--
   --## SUB LDGR
     If G_Ar_Cst_Type = 2 Then
         G_Dtl_Cc_Code   := nvl(P_Cc_Code,G_Cc_Code);
      Else
         G_Dtl_Cc_Code   := G_Cc_Code;   
      End If;

      If G_Ar_Pj_Type = 2 Then
         G_Dtl_Pj_No   := nvl(P_Pj_No,G_Pj_No);
      Else
          G_Dtl_Pj_No   := G_Pj_No;
      End If;

      If G_Ar_Actv_Type = 2 Then
         G_Dtl_Actv_No   := nvl(P_Actv_No,G_Actv_No);
      Else
          G_Dtl_Actv_No   := G_Actv_No;         
      End If;

   Gnr_Api_Pkg.Chk_Sub_Ldgr (P_Sys_Typ     => 1
                            ,P_Sys_No      => G_Sys_No
                            ,P_Doc_Type    => G_Doc_Typ
                            ,P_Cst_Type    => G_Ar_Cst_Type
                            ,P_Pj_Type     => G_Ar_Pj_Type
                            ,P_Actv_Type   => G_Ar_Actv_Type
                            ,P_Cc_Code     => G_Dtl_Cc_Code
                            ,P_Pj_No       => G_Dtl_Pj_No
                            ,P_Actv_No     => G_Dtl_Actv_No
                            ,P_Rep_Code    => G_Rep_Code
                            ,P_A_Code      => G_A_Code
                            ,P_Chk_Ac_Cc   => 1
                            ,P_BILL_DOC_TYPE =>G_BILL_DOC_TYPE
                            ,P_C_CODE        =>G_C_CODE
                            ,P_P_Year        =>G_P_Year
                            ,P_Lng_No      => G_Lng_No
                            ,P_Msg_Txt     => P_Msg_Txt
                            ,P_Pkg_Line    => P_Err_No
                            ,P_Pkg_Nm      => P_Pkg_Nm);

   If P_Msg_Txt Is Not Null Then
      Goto Rtn_Rslt;
   End If;

   --##--------------------------------------------------------------------------------------------------------------------------------##--
   If P_Doc_Type_Ref Is Null And (P_Doc_No_Ref Is Not Null Or P_Doc_Ser_Ref Is Not Null) Then
      P_Err_No    := 20142;
      P_Msg_Txt   := 'Err. Data Send P_DOC_TYP_REF Is Null But (DOC_NO_REF , DOC_SER_REF ) IS NOT NULL , FOR  ITM_CODE = ' || P_I_Code;
      Goto Rtn_Rslt;
   Elsif P_Doc_Type_Ref Is Not Null And (P_Doc_No_Ref Is Null Or P_Doc_Ser_Ref Is Null) Then
      P_Err_No    := 20143;
      P_Msg_Txt   := 'Err. Data Send P_DOC_TYP_REF Is Not Null But (DOC_NO_REF , DOC_SER_REF  ) IS NULL , FOR  ITM_CODE = ' || P_I_Code;
      Goto Rtn_Rslt;
   End If;

   If P_Doc_Type_Ref Is Not Null Then
      Begin
         Select 1
           Into V_Cnt
           From Ias_Sys.Ias_Docjv_Type_Systems
          Where Doc_Type = P_Doc_Type_Ref And Rownum <= 1;
      Exception
         When Others Then
            V_Cnt   := 0;
      End;

      If V_Cnt = 0 Then
         P_Err_No    := 20144;
         P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 1171) || ' DOC_TYP_REF , FOR  ITM_CODE = ' || P_I_Code;
         Goto Rtn_Rslt;
      End If;
   End If;

   --##--------------------------------------------------------------------------------------------------------------------------------##--    
     V_Doc_Sequence_Si   := P_Doc_Sequence_Si;
     V_Si_Rcrd_No        := P_Si_Rcrd_No;
     Begin
          ARS_API_CHK_PKG.CHK_RETRN_BILL_INSTLL(P_SYS_NO    =>G_sys_no                              
                                       ,P_rep_code          =>G_rep_code
                                       ,P_c_code            =>G_c_code
                                       ,P_RT_BILL_DOC_TYPE  =>G_RT_BILL_DOC_TYPE
                                       ,P_Bill_Currency     =>G_Cur_Code
                                       ,P_W_code            =>G_W_code
                                       ,P_RT_BILL_DATE      =>G_doc_Date
                                       ,P_Use_Vat           =>G_Use_Vat
                                       ,P_CLC_TYP_NO_TAX    =>G_CLC_TYP_NO_TAX
                                       ,P_p_year            =>G_p_year
                                       ,P_Prev_Year         =>G_Prev_Year
                                       ,P_Brn_Usr           => G_Brn_Usr                                                                                      
                                       ,P_Rt_Bill_Ser       =>G_doc_ser
                                       ,P_RT_Bill_No        => G_Doc_No                              
                                       ,P_Pst_Typ           =>G_Pst_Typ
                                       ,P_Bill_No           =>P_Bill_No
                                       ,P_Bill_Ser          =>P_Bill_Ser
                                       ,P_I_Code            =>P_I_Code
                                       ,P_P_Size            =>V_P_Size
                                       ,P_I_Qty             =>P_I_Qty
                                       ,P_Free_Qty          =>P_Free_Qty
                                       ,P_Expiredate        =>P_Expire_Date
                                       ,P_Batchno           =>P_Batch_no
                                       ,P_Doc_Sequence_Si   =>V_Doc_Sequence_Si
                                       ,P_Si_Rcrd_No        =>V_Si_Rcrd_No
                                       ,P_Brn_no            =>G_Brn_no
                                       ,P_Rtrn_From_Othr_Sman=>G_Rtrn_From_Othr_Sman                                                                        
                                       ,P_Usr_no            =>G_ad_u_id 
                                       ,P_Lng_No            =>G_Lng_No
                                       ,P_Msg_Txt           =>P_Msg_Txt
                                       ,P_Err_No            =>P_Err_No
                                       ,P_Pkg_Nm            =>P_Pkg_Nm);
     If P_Msg_Txt Is Not Null Then
          Goto Rtn_Rslt;
       End If;
   End ;  
--##--------------------------------------------------------------------------------------------------------------------------------##--                                         
   Begin
      V_Post_Code   := Get_Post_Code_Inv (P_Type => G_Item_Posting_Flag, P_I_Code => P_I_Code, P_W_Code => G_W_Code);
   Exception
      When Others Then
         Null;
   End;
   --##--------------------------------------------------------------------------------------------------------------------------------##--
   Begin
      Select Ias_Doc_Seq.Nextval Into V_Doc_Sequence From Dual;
   Exception
      When Others Then
         P_Msg_Txt   := 'Err. When Get DOC_SEQ' || Chr (10) || Sqlerrm;
         P_Err_No    := 20340;
         Goto Rtn_Rslt;
   End;  
   --##--------------------------------------------------------------------------------------------------------------------------------##--
   G_Rcrd_No        := Nvl (G_Rcrd_No, 0) + 1;
   P_Doc_Sequence:=V_Doc_Sequence;
   P_Rcrd_No     :=G_Rcrd_No;
   --##--------------------------------------------------------------------------------------------------------------------------------##--
    If G_W_Code Is Not Null AND G_Ar_Wc_Type = 2 Then
      If  YS_SYS_GEN_PKG.CHK_ACTV_SYSTEM (P_SYS_NO => 70 , P_Brn_Usr => G_Brn_Usr)=1 and nvl(G_SYS_NO,0)<>70 Then
              Begin
               Select 1 Into V_Cnt 
               From Sales_Man 
               Where Nvl(W_Code,0)=G_W_Code 
               And Rownum<=1 ;       
            Exception When Others Then
               V_Cnt := 0;
            End;
            If Nvl(V_Cnt,0)>0 Then
                     P_Err_No    := 20650;
                     P_MSG_TXT := IAS_GEN_PKG.GET_MSG (G_Lng_No, 5145);
                    Goto Rtn_Rslt;                                                      
            End If;
      End If;
    End If;
    --##-----------------------------------------------------------------------------------------##-- 
   Begin     
         Select Allow_Enter_Zero_Cost
           Into V_Allow_Enter_Zero_Cost
           From Privilege_Fixed
          Where U_Id = G_Ad_U_Id And Rownum <= 1;      
   Exception
      When Others Then
         P_Msg_Txt   := 'Error When Select From Privilege_Fixed In Post_Rt_Sales_Detail' || Chr(10) || Sqlerrm;
         P_Err_No    := 20341;
         Goto Rtn_Rslt;
   End;
   --##--------------------------------------------------------------------------------------------------------------------------------##--
   Select Service_Itm, Use_Serialno, Used_Itm
     Into V_Service_Itm, V_Use_Serialno, V_Used_Itm
     From Ias_Itm_Mst
    Where I_Code = P_I_Code And Rownum <= 1;

   --##--------------------------------------------------------------------------------------------------------------------------------##--
      If Nvl(V_Service_Itm,0)=0 Then 
           IF G_p_year In (0,3) And P_Bill_No Is Not Null And P_Bill_Ser Is Not Null Then     
              Begin                   
                      Select ((stk_cost/nvl(p_size,1))*nvl(V_P_Size,1)) Into V_Stkcost
                         from Ias_Bill_dtl
                           Where Bill_ser=P_Bill_Ser
                             And I_code=P_I_Code
                             And Rcrd_no=Nvl(V_Si_Rcrd_No,Rcrd_no)
                             And RowNum<=1;                                                   
              Exception when Others Then 
                 Begin
                  V_Stkcost := Inv_Get_Lst_Itm_Wtavg_Fnc (    P_I_Code     => P_I_code ,      
                                                              P_P_Size     =>V_P_Size  ,     
                                                              P_W_Code     =>G_W_Code  ,   
                                                              P_Cost_Type  =>G_Costing_Type  ,
                                                              P_Wtavg_Type =>G_Wtavg_Type     
                                                              )* nvl(V_P_Size,1);
                 EXCEPTION WHEN OTHERS THEN
                    P_Msg_Txt   := 'Error In Inv_Get_Lst_Itm_Wtavg_Fnc '||sqlerrm;
                    P_Err_No    := 20673;
                    Goto Rtn_Rslt;
                 END; 
              End ;
           ELSIF Nvl(G_p_year,0)=1 And P_Bill_No Is Not Null And P_Bill_Ser Is Not Null Then 
               V_P_Size:=nvl(V_P_Size,1);                
               V_YR:='IAS'||G_Prev_Year||G_Brn_Usr;   
                Begin                   
                    EXECUTE IMMEDIATE
                     ' SELECT ((STK_COST/NVL(P_SIZE,1))*NVL('||V_P_SIZE||',1)) 
                         FROM '||V_YR||'.IAS_BILL_DTL
                           WHERE BILL_SER='||P_BILL_SER||'
                             AND I_CODE='''||P_I_CODE||'''
                             AND RCRD_NO=NVL('||V_SI_RCRD_NO||',RCRD_NO)
                             AND ROWNUM<=1 ' Into V_Stkcost ;    
                             
                                                                            
                Exception when No_Data_found Then
                   V_Stkcost:=NULL;
                When Others Then 
                    P_Msg_Txt   := 'Err When Get Stk_cost From Previous Year '||sqlerrm;
                    P_Err_No    := 20700;
                    Goto Rtn_Rslt;
                End ;
                IF  V_Stkcost Is Null Then 
                         Begin
                          V_Stkcost := Inv_Get_Lst_Itm_Wtavg_Fnc (    P_I_Code     => P_I_code ,      
                                                                      P_P_Size     =>V_P_Size  ,     
                                                                      P_W_Code     =>G_W_Code  ,   
                                                                      P_Cost_Type  =>G_Costing_Type  ,
                                                                      P_Wtavg_Type =>G_Wtavg_Type     
                                                                      )* nvl(V_P_Size,1);
                         EXCEPTION WHEN OTHERS THEN
                            P_Msg_Txt   := 'Error In Inv_Get_Lst_Itm_Wtavg_Fnc '||sqlerrm;
                            P_Err_No    := 20701;
                            Goto Rtn_Rslt;
                         END; 
                End If;      
           Else   
             Begin
              V_Stkcost := Inv_Get_Lst_Itm_Wtavg_Fnc (    P_I_Code     => P_I_code ,      
                                                          P_P_Size     =>V_P_Size  ,     
                                                          P_W_Code     =>G_W_Code  ,   
                                                          P_Cost_Type  =>G_Costing_Type  ,
                                                          P_Wtavg_Type =>G_Wtavg_Type     
                                                          )* nvl(V_P_Size,1);
             EXCEPTION WHEN OTHERS THEN
                P_Msg_Txt   := 'Error In Inv_Get_Lst_Itm_Wtavg_Fnc '||sqlerrm;
                P_Err_No    := 20672;
                Goto Rtn_Rslt;
             END;                                             
                         
           End If;
      End If;     
   -------------------------------------------------------------------------------------------
   If Nvl (V_Service_Itm, 0) = 0 And V_Allow_Enter_Zero_Cost = 1 And Nvl (V_Stkcost, 0) = 0 Then
      P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 168);
      P_Err_No    := 20342;
      Goto Rtn_Rslt;
   End If;
   ------------------------------------------------------------------------------
    --## Update Doc Ref
            Update_Doc_Ref    ( P_Doc_Type           =>G_Doc_Typ
                               ,P_Pst_Typ            =>G_Pst_Typ
                               ,P_Doc_Ser            =>G_Doc_Ser
                               ,P_I_Code             =>P_I_Code
                               ,P_Itm_Unt            =>P_Itm_Unt
                               ,P_P_Size             =>V_P_Size
                               ,P_I_Qty              => P_I_Qty
                               ,P_Free_Qty           =>P_Free_Qty
                               ,P_Rcrd_No            =>G_Rcrd_No
                               ,P_Doc_Type_Ref       =>P_Doc_Type_Ref
                               ,P_Doc_No_Ref         =>P_Doc_No_Ref
                               ,P_Doc_Ser_Ref        =>P_Doc_Ser_Ref
                               ,P_Rcrd_No_Ref        =>P_Rcrd_No_Ref
                               ,P_Msg_Txt            =>P_Msg_Txt
                               ,P_Err_No              =>P_Err_No
                               ,P_Pkg_Nm              =>P_Pkg_Nm);
      If P_Msg_Txt Is Not Null Then
         Goto Rtn_Rslt;
      End If;
      --##--------------------------------------------------------------------------------------------------------------------------------##--
   BEGIN 
         SELECT Comm_Per,Comm_Amt_Dtl 
                INTO V_Comm_Per,V_Comm_Amt_Dtl 
       FROM IAS_BILL_DTL
         WHERE BILL_SER=P_BILL_SER
           AND I_CODE=P_I_CODE
           AND RCRD_NO= V_Si_Rcrd_No
         AND ROWNUM<=1;
   EXCEPTION WHEN OTHERS THEN
         V_Comm_Per    :=NULL;
         V_Comm_Amt_Dtl:=NULL;
   END; 
  ------------------------------------------------------------------------------ 
   BEGIN 
         SELECT Comm_Per INTO V_Comm_Per_MST
       FROM IAS_BILL_MST 
         WHERE BILL_SER=P_BILL_SER          
         AND ROWNUM<=1;
   EXCEPTION WHEN OTHERS THEN
         V_Comm_Per_MST    :=NULL;        
   END; 
  ------------------------------------------------------------------------------
  IF V_Comm_Per_MST IS NOT NULL THEN
       BEGIN 
             UPDATE IAS_RT_BILL_MST  SET Comm_Per=V_Comm_Per_MST
             WHERE RT_BILL_SER=G_DOC_SER          
               AND ROWNUM<=1;
       EXCEPTION WHEN OTHERS THEN
             NULL;       
       END; 
  END IF; 
  --##--------------------------------------------------------------------------------##--
  If Nvl (G_Pst_Typ, 0) = 2 And Nvl(G_Use_Sp_Sman,0)=1 Then
  
        If Nvl (G_p_year, 0) In (0, 3) And G_p_year Is Not Null  AND P_Bill_Ser Is NOT Null Then  
              -- If Nvl (G_p_year, 0) In (0, 3) Then
                     Begin
                      select Rep_Code_Sp,Prm_Code_Out
                        into V_Rep_Code_Sp,V_Prm_Code_Out
                        from ias_bill_dtl
                        Where Bill_ser=P_Bill_Ser
                        and i_code=P_I_code  
                        And rcrd_no=V_Si_Rcrd_No                      
                        And Rownum<=1;
                     Exception When Others Then 
                          V_Rep_Code_Sp:=Null;
                          V_Prm_Code_Out:=Null;
                    End ;              
               
        Else            
         ----------------------------------
         --## get Rep_Code_Sp
           Begin
                If P_I_Code Is Not Null And G_R_Code Is Not Null And Nvl(G_Use_Sp_Sman,0)=1 Then
                     Begin
                            Select Sales_Man.Reprs_Code
                              Into V_Rep_Code_Sp
                              From Sales_Man, Ias_Itm_Sman, Ias_Rgn_Sman
                             Where Sales_Man.Reprs_Code = Ias_Itm_Sman.Rep_Code 
                               And Sales_Man.Reprs_Code = Ias_Rgn_Sman.Rep_Code 
                               And Nvl (Sales_Man.Conn_Sp_Sman, 0) = 1 
                               And Nvl (Sales_Man.Inactive, 0) = 0
                               And I_Code =P_I_Code
                               And Ias_Rgn_Sman.R_Code =G_R_Code
                               And RowNum<=1;
                     Exception When OThers Then
                          V_Rep_Code_Sp:=Null;                         
                     End;
               End IF;
            End;
          ----------------------------------------------
          --## get Prm_Code_Out
          Begin
                If V_Rep_Code_Sp Is Not Null And G_R_Code Is Not Null And Nvl(G_Use_Sp_Sman,0)=1 Then
                     Begin    
                            Select Ias_Rgn_Sman.Prm_Code 
                              Into V_Prm_Code_Out
                              From Ias_Promoters,Ias_Rgn_Sman,Ias_Prm_Rgn
                             Where Ias_Promoters.Prm_Code=Ias_Prm_Rgn.Prm_Code
                               And Ias_Rgn_Sman.R_Code=Ias_Prm_Rgn.R_Code
                               And Nvl(Ias_Promoters.Conn_Sp_Sman,0)=1
                               And Nvl(Ias_Promoters.INACTIVE,0)=0
                               And Ias_Rgn_Sman.Rep_Code=V_Rep_Code_Sp
                               And Ias_Rgn_Sman.R_Code=G_R_Code
                               And RowNum<=1;
                     Exception When Others Then
                            V_Prm_Code_Out:=Null;                            
                     End;
                 End IF;
          End;           
          ----------------------------------------------
        End If;  
  End If; 
 --##--------------------------------------------------------------------------------------------------------------------------------##--           
      --## Conn Wcode By Activity To Get Cc_Code + Pj_No + Actv_No
          If G_W_Code Is Not Null And Nvl(G_Conn_Activity_By_Wcode_Cc,0) = 1   Then           
              If ( G_Ar_Cst_Type=2) Or ( G_Ar_Pj_Type=2) Or  ( G_Ar_Actv_Type=2) Then                 
                Ias_Itm_Pkg.Get_Itm_Activity_Wcode_Info ( P_W_Code       =>G_W_Code,
                                                          P_Itm_Actv_No  => Ias_Itm_Pkg.Get_Itm_Activity (P_I_Code => P_I_Code ) ,
                                                          P_Cc_Code      => V_Cc_Code  ,
                                                          P_Pj_No        => V_Pj_No    ,
                                                          P_Actv_No      => V_Actv_No  ) ;
              End If ; 
              
              If G_Ar_Cst_Type=2 and V_Cc_Code is Not Null Then
                   G_Dtl_Cc_Code:=V_Cc_Code;                
              End If;
              
              If G_Ar_Pj_Type=2 and V_Pj_No is Not Null Then
                   G_Dtl_Pj_No:=V_Pj_No;                
              End If; 
              
              If G_Ar_Actv_Type=2 and V_Pj_No is Not Null Then
                   G_Dtl_Actv_No:=V_Actv_No;                
              End If;          
                                                           
          End If ;
     --##--------------------------------------------------------------------------------------------------------------------------------##--                      
                        
   If Nvl (G_Pst_Typ, 0) = 2 Then
      Begin
         Insert Into Ias_Rt_Bill_Dtl (Rt_Bill_No
                                     ,Rt_Bill_Ser
                                     ,Rt_Bill_Doc_Type
                                     ,I_Code
                                     ,I_Qty
                                     ,P_Size
                                     ,Itm_Unt
                                     ,P_Qty
                                     ,I_Price
                                     ,I_Price_Vat
                                     ,Stk_Cost
                                     ,W_Code
                                     ,Bill_No
                                     ,Bill_Doc_Type
                                     ,Bill_Ser
                                     ,Cc_Code
                                     ,Pj_No
                                     ,Actv_No
                                     ,Expire_Date
                                     ,Batch_No
                                     ,Free_Qty
                                     ,Dis_Per
                                     ,Dis_Per2
                                     ,Dis_Per3
                                     ,Dis_Amt
                                     ,Dis_Amt_Mst
                                     ,Dis_Amt_Dtl
                                     ,Dis_Amt_Dtl2
                                     ,Dis_Amt_Dtl3
                                     ,Vat_Per
                                     ,Vat_Amt
                                     ,Othr_Amt
                                     ,Vat_Amt_Othr
                                     ,Othr_Amt_Disc
                                     ,Dis_Aftr_Vat_Mst
                                     ,Dis_Amt_Mst_Vat
                                     ,Vat_Amt_Dis_Dtl_Vat
                                     ,Vat_Amt_Aftr_Dis
                                     ,Vat_Amt_Bfr_Dis
                                     ,Dis_Amt_Dtl_Vat
                                     ,Dis_Amt_Dtl2_Vat
                                     ,Dis_Amt_Dtl3_Vat
                                     ,Vat_Amt_Dis_Mst_Vat
                                     ,Vat_Amt_Dis_Dtl2_Vat
                                     ,Vat_Amt_Dis_Dtl3_Vat
                                     ,Dis_Amt_Aftr_Vat
                                     ,Item_Desc
                                     ,Barcode
                                     ,Field_Dtl1
                                     ,Field_Dtl2
                                     ,Field_Dtl3
                                     ,Emp_No
                                     ,Doc_Type_Ref
                                     ,Doc_No_Ref
                                     ,Doc_Ser_Ref
                                     ,Sub_C_Code
                                     ,Rcrd_No_Ref
                                     ,Qt_Prm_No
                                     ,Qt_Prm_Ser
                                     ,Qt_Prm_Rcrd_No
                                     ,I_Length
                                     ,I_Width
                                     ,I_Height
                                     ,I_Number
                                     ,Wt_Qty
                                     ,Wt_Unt
                                     ,Argmnt_No
                                     ,Si_Rcrd_No
                                     ,Doc_Sequence_Si
                                     ,External_Post
                                     ,Post_Code
                                     ,Sr_Type
                                     ,Bnk_Amt_Dtl
                                     ,Cmp_No
                                     ,Brn_No
                                     ,Brn_Year
                                     ,Brn_Usr
                                     ,Rcrd_No
                                     ,Doc_Sequence
                                     ,Ret_Qty
                                     ,Ret_Free_Qty
                                     ,Comm_Per
                                     ,Comm_Amt_Dtl
                                     ,Rep_Code_Sp      
                                     ,Prm_Code_Out
                                     ,Lev_No)
              Values (G_Doc_No
                     ,G_Doc_Ser
                     ,G_Rt_Bill_Doc_Type
                     ,P_I_Code
                     ,P_I_Qty
                     ,V_P_Size
                     ,P_Itm_Unt
                     , (P_I_Qty * V_P_Size)
                     ,V_I_Price
                     ,V_I_Price_Vat
                     ,V_Stkcost
                     ,G_W_Code
                     ,P_Bill_No
                     ,P_Bill_Doc_Type
                     ,P_Bill_Ser
                     ,G_Dtl_Cc_Code
                     ,G_Dtl_Pj_No
                     ,G_Dtl_Actv_No
                     ,Nvl (P_Expire_Date, '01/01/1900')
                     ,Nvl (P_Batch_No, '0')
                     ,P_Free_Qty
                     ,P_Dis_Per
                     ,P_Dis_Per2
                     ,P_Dis_Per3
                     ,P_Dis_Amt
                     ,P_Dis_Amt_Mst
                     ,P_Dis_Amt_Dtl
                     ,P_Dis_Amt_Dtl2
                     ,P_Dis_Amt_Dtl3
                     ,V_Vat_Per
                     ,P_Vat_Amt
                     ,P_Othr_Amt
                     ,P_Vat_Amt_Othr
                     ,P_Othr_Amt_Disc
                     ,P_Dis_Aftr_Vat_Mst
                     ,P_Dis_Amt_Mst_Vat
                     ,P_Vat_Amt_Dis_Dtl_Vat
                     ,P_Vat_Amt_Aftr_Dis
                     ,P_Vat_Amt_Bfr_Dis
                     ,P_Dis_Amt_Dtl_Vat
                     ,P_Dis_Amt_Dtl2_Vat
                     ,P_Dis_Amt_Dtl3_Vat
                     ,P_Vat_Amt_Dis_Mst_Vat
                     ,P_Vat_Amt_Dis_Dtl2_Vat
                     ,P_Vat_Amt_Dis_Dtl3_Vat
                     ,P_Dis_Amt_Aftr_Vat
                     ,P_Item_Desc
                     ,P_Barcode
                     ,P_Field_Dtl1
                     ,P_Field_Dtl2
                     ,P_Field_Dtl3
                     ,P_Emp_No
                     ,P_Doc_Type_Ref
                     ,P_Doc_No_Ref
                     ,P_Doc_Ser_Ref
                     ,P_Sub_C_Code
                     ,P_Rcrd_No_Ref
                     ,P_Qt_Prm_No
                     ,P_Qt_Prm_Ser
                     ,P_Qt_Prm_Rcrd_No
                     ,P_I_Length
                     ,P_I_Width
                     ,P_I_Height
                     ,P_I_Number
                     ,P_Wt_Qty
                     ,P_Wt_Unt
                     ,P_Argmnt_No
                     ,V_Si_Rcrd_No
                     ,V_Doc_Sequence_Si
                     ,G_External_Post
                     ,V_Post_Code
                     ,G_Sr_Type
                     ,P_Bnk_Amt_Dtl
                     ,G_Cmp_No
                     ,G_Brn_No
                     ,G_Brn_Year
                     ,G_Brn_Usr
                     ,G_Rcrd_No
                     ,V_Doc_Sequence
                     ,Decode (G_Use_Out_Bills, 1, P_I_Qty, 0)
                     ,Decode (G_Use_Out_Bills, 1, P_Free_Qty, 0)
                     ,V_Comm_Per
                     ,V_Comm_Amt_Dtl
                     ,V_Rep_Code_Sp      
                     ,V_Prm_Code_Out
                     ,P_Lev_No)
                     Return Cc_Code,Pj_No,Actv_No into G_Dtl_Cc_Code,G_Dtl_Pj_No,G_Dtl_Actv_No;
      Exception
         When Others Then
            P_Msg_Txt   := 'Error When Insert Into IAS_RT_BILL_DTL' || Chr (10) || Sqlerrm;
            P_Err_No    := 20344;
            P_Pkg_Nm    := 'Ars_Api_Trns_Pkg.INSRT_IAS_RT_BILL_DTL';
            Goto Rtn_Rslt;
      End;
    

      If Nvl (G_Use_Out_Bills, 0) = 1 Then
         V_Ret_No    := G_Ret_No;
         V_Ret_Ser   := G_Ret_Ser;
      End If;
      --------------------------------------------
      If Nvl (V_Service_Itm, 0) = 0 Then
         --## Calc_WatAvg
         Begin
            V_Wt_After      :=
               Calc_Wtavg_Cost (P_Cost_Type    => G_Costing_Type
                               ,P_Wtavg_Type   => G_Wtavg_Type
                               ,P_Icode        => P_I_Code
                               ,P_Iqty         => P_I_Qty
                               ,P_Frqty        => Nvl (P_Free_Qty, 0)
                               ,P_Icost        => Nvl (V_Stkcost, 0)
                               ,P_Psize        => V_P_Size
                               ,P_Wcode        => G_W_Code
                               ,P_Frc_No       => G_Stkcost_Fraction
                               ,P_Brn_No       => G_Brn_No
                               ,P_Brn_Year     => G_Brn_Year
                               ,P_Cmp_No       => G_Cmp_No
                               ,P_Brn_Usr      => G_Brn_Usr);
         Exception
            When Others Then
               P_Msg_Txt   := 'Error When Calc WtAvg Error , (Rt Sales) ' || Chr(10) || Sqlerrm;
               P_Err_No    := 20345;
               P_Pkg_Nm    := 'Calc_Wtavg_Cost';
               Goto Rtn_Rslt;
         End;
         --##-------------------------------------------------------------------------------------##--
