                                ,P_Disc_Amt_Aftr_Vat   In     Ias_Rt_Bill_Mst.Disc_Amt_Aftr_Vat%Type Default Null
                                ,P_Disc_Amt_Mst_Vat    In     Ias_Rt_Bill_Mst.Disc_Amt_Mst_Vat%Type Default Null
                                ,P_Vat_Amt_Disc_Mst    In     Ias_Rt_Bill_Mst.Vat_Amt_Disc_Mst%Type Default Null
                                ,P_CLC_TAX_FREE_QTY_FLG In     Ias_Bill_Mst.CLC_TAX_FREE_QTY_FLG %Type Default Null
                                ,P_E_INVC_MTHD_NO       IN     Ias_Rt_Bill_Mst.E_INVC_MTHD_NO %Type Default Null
                                ,P_C_Tax_Code          In     Ias_Bill_Mst.C_Tax_Code%Type Default Null
                                ,P_Rtrn_From_Othr_Sman In Number Default 0   --## 0 same sman-1 other sman
                                ,P_Cmp_No              In     Ias_Rt_Bill_Mst.Cmp_No%Type Default Null
                                ,P_Brn_No              In     Ias_Rt_Bill_Mst.Brn_No%Type Default Null
                                ,P_Brn_Year            In     Ias_Rt_Bill_Mst.Brn_Year%Type Default Null
                                ,P_Brn_Usr             In     Ias_Rt_Bill_Mst.Brn_Usr%Type Default Null
                                ,P_Ad_U_Id             In     Ias_Rt_Bill_Mst.Ad_U_Id%Type Default Null
                                ,P_Ad_Date             In     Ias_Rt_Bill_Mst.Ad_Date%Type Default Null
                                ,P_Ad_Trmnl_Nm         In     Ias_Rt_Bill_Mst.Ad_Trmnl_Nm%Type Default Null
                                ,P_Pst_Typ             In     Number Default Null --## 1 to br tables ,2 to onyx tables                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             --## 1 to br tables ,2 to onyx tables
                                ,P_Clc_Tax_Method      In     Number --## 0 CALC TAX IN EXTRNAL ,1-AOUTO CALC TAX
                                ,P_Pst_From_Br         In     Number --## 1- POSTING FORM BR TABLE  0- NOT FROM BR
                                ,P_DTS_ONLINE          In     NUMBER DEFAULT 0 --## 0 OFFLINE ,1-ONLINE
                                ,P_Lng_No              In     Number Default 1
                                ,P_Msg_Txt                Out Varchar2
                                ,P_Err_No                 Out Varchar2
                                ,P_Pkg_Nm                 Out Varchar2)
Is
   V_Sys_No_Extrnl    Form_Detail.Sys_No%Type;
   V_Doc_Due_Date     Date;
   V_Crdt_Prd_Day     Number := 0;
   V_Cst_Nm           Customer.C_A_Name%Type;  
   -- V_CUR_RATE           NUMBER;
   --V_STK_RATE           NUMBER;
   V_Msg_No           Number;
   V_Inactv_Flg       Number;
   V_Cnt              Number;  
   V_Tbl_Mst          Varchar2 (2000);
   V_Ret_No           Ias_Rt_Bill_Mst.Rt_Bill_No%Type;
   V_Ret_Ser          Ias_Rt_Bill_Mst.Rt_Bill_Ser%Type;
   V_Rt_Vat_Prd_Typ   Number;
   V_E_INVC_MTHD_NO    Ias_Rt_Bill_Mst.E_INVC_MTHD_NO%Type;
   V_C_Tax_Code        Customer.C_Tax_Code%Type:=P_C_Tax_Code;
   V_TAX_BILL_TYP    CUSTOMER.C_CLASS_VAT%TYPE := null; 

Begin
   --##-----------------------------------------------------------------------------------------------##--
   Clr_Glbl_Var; -- CLEAR GLOBAL VARIABLES
   G_Pst_Typ            := Null;
   --##-----------------------------------------------------------------------------------------------##--
   G_Doc_Typ            := 136; -- SALES BILL
   G_Pst_Typ            := P_Pst_Typ;
   ------------------------------------------------------------------------------------------
   G_Doc_No             := P_Doc_No;
  -- G_Doc_Ser            := P_Doc_Ser;
  G_BILL_NO_MNL         :=P_BILL_NO_MNL;
   --##-----------------------------------------------------------------------------------------------##--
   Get_Prmtr_Prc (P_Sys_No           => P_Sys_No
                 ,P_Doc_Typ          => G_Doc_Typ
                 ,P_Pst_Typ          => P_Pst_Typ
                 ,P_Cur_Code         => P_Cur_Code
                 ,P_Cur_Rate         => P_Cur_Rate
                 ,P_Stock_Rate       => Null
                 ,P_Doc_Date         => P_Doc_Date
                 ,P_Brn_No           => P_Brn_No
                 ,P_Brn_Usr          => P_Brn_Usr
                 ,P_Brn_Year         => P_Brn_Year
                 ,P_Usr_No           => P_Ad_U_Id
                 ,P_Clc_Tax_Method   => P_Clc_Tax_Method
                 ,P_Pst_From_Br      => P_Pst_From_Br
                 ,P_DTS_ONLINE       =>P_DTS_ONLINE
                 ,P_Lng_No           => P_Lng_No
                 ,P_Msg_Txt          => P_Msg_Txt
                 ,P_Err_No           => P_Err_No
                 ,P_Pkg_Nm           => P_Pkg_Nm);

   If P_Msg_Txt Is Not Null Then
      Goto Rtn_Rslt;
   End If;
   --##----------------------------------------------------------------------------------------------##--
   V_Sys_No_Extrnl      := G_Sys_No;

  
   --##-----------------------------------------------------------------------------------------------##--
   V_Msg_No             := Null;
   G_C_Code             := case When nvl(P_C_Code,'0')='0' Then Null Else P_C_Code end ;
   G_Emp_No             := Case When nvl(P_Emp_No,0)=0   Then Null Else P_Emp_No end ;
   G_R_Code             := Case When nvl(P_R_Code,0)=0   Then Null Else P_R_Code end ;
   G_Sr_Type            := Case When nvl(P_Sr_Type,0)=0   Then Null Else P_Sr_Type end ;
   G_Rt_Bill_Doc_Type   := Case When nvl(P_Rt_Bill_Doc_Type,0)=0   Then Null Else P_Rt_Bill_Doc_Type end ;
   G_Ad_Date            := Nvl (P_Ad_Date, Ias_Gen_Pkg.Get_Curdate);
    G_Clc_Typ_No_Tax   := Case  When nvl(P_Clc_Typ_No_Tax,0)=0 Then Null
                                When nvl(G_Use_Vat,0) = 0      Then null
                                Else P_Clc_Typ_No_Tax end  ;
   G_Cash_No            := Case When nvl(P_Cash_No,0)=0 Then Null Else P_Cash_No end ;
   G_Bank_No            := Case When nvl(P_Bank_No,0)=0 Then Null Else P_Bank_No end ;
   G_Rep_Code           := Case When nvl(P_Rep_Code,'0')='0' Then Null Else P_Rep_Code end ;
   G_Doc_Dsc            := P_A_Desc;
   G_Ref_No             := P_Ref_No;
   G_P_Year             := P_P_Year;
   G_Cc_Code            := Case When nvl(P_Cc_Code,'0')='0' Then Null Else P_Cc_Code end ;
   G_Pj_No              := Case When nvl(P_Pj_No,'0')='0' Then Null Else P_Pj_No end ;
   G_Actv_No            := Case When nvl(P_Actv_No,'0')='0' Then Null Else P_Actv_No end ;
   G_Col_No             := Case When nvl(P_Col_No,0)=0 Then Null Else P_Col_No end ;
   G_Prev_Year          :=p_Prev_Year;
   G_RTRN_FROM_OTHR_SMAN:=Nvl(p_RTRN_FROM_OTHR_SMAN,0);
   G_W_Code             := Case When nvl(P_W_Code,0)=0 Then Null Else P_W_Code end ;
   --##----------------------------------------------------------------------------------------------##--
     IF  NVL(P_Sys_No,0)=70 THEN
        If P_DOC_SER_EXTRNL Is Null  Then
          P_Err_No := 20562;
          P_Msg_Txt := 'DOC_SER_EXTRNL IS NULL ';
          Goto Rtn_Rslt;
        END IF;
         
        BEGIN 
          SELECT 1 INTO V_CNT FROM IAS_RT_BILL_MST_RQ  
                                WHERE DOC_SER_EXTRNL=P_DOC_SER_EXTRNL
                                 AND ROWNUM<=1 ;
        EXCEPTION WHEN OTHERS THEN
          V_CNT:=0;
        END ; 
        IF NVL(V_CNT,0)>0 THEN
            BEGIN 
              SELECT RT_BILL_NO,RT_BILL_SER 
               INTO G_DOC_NO,G_DOC_SER
               FROM IAS_RT_BILL_MST_RQ 
                                    WHERE DOC_SER_EXTRNL=P_DOC_SER_EXTRNL
                                     AND ROWNUM<=1  ;
            EXCEPTION WHEN OTHERS THEN
              V_CNT:=0;          
             P_Err_No := 20999;
             P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 4942) || Chr (10) || ' DOC_SER_EXTRNL='||P_DOC_SER_EXTRNL;           
             Goto Rtn_Rslt;
            END; 
        END IF;
        V_CNT:=0; 
     END IF;
   --##----------------------------------------------------------------------------------------------##--
   If nvl(G_Sys_no,0)=70 And G_Rt_Bill_Doc_Type=1 And G_C_Code Is Not Null and P_C_NAME is Not Null AND ( G_C_Code=nvl(G_DTS_C_CSH_CODE,'0') or Is_Csh_Cstmr(G_C_Code)=1) Then
     G_C_Code:=null;
     V_Cst_Nm:=P_C_Name;
   End if;
   
   If G_C_Code Is Not Null Then
      Gnr_Api_Pkg.Chk_Inpt_Data (P_Inpt_Typ     => 'C_CODE'
                                ,P_Sys_Typ      => 1
                                ,P_Doc_Type     => G_Doc_Typ
                                ,P_Inpt_Code1   => G_C_Code
                                ,P_Lng_Dflt     => G_Lng_Dflt
                                ,P_Inpt_Nm      => V_Cst_Nm
                                ,P_Msg_No       => V_Msg_No);

      If V_Msg_No Is Not Null Then
         P_Err_No    := 20563;
         P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No);
         Goto Rtn_Rslt;
      End If;
   Else
      V_Cst_Nm   := P_C_Name;
   End If;
   --##-----------------------------------------------------------------------------------------------##--
   If P_Rt_Bill_Due_Date Is Not Null Then
      V_Doc_Due_Date   := P_Rt_Bill_Due_Date;
   Else
      If G_C_Code Is Not Null Then
         Begin
            Select Credit_Period
              Into V_Crdt_Prd_Day
              From Customer
             Where C_Code = P_C_Code And Rownum <= 1;
         Exception
            When Others Then
               Null;
         End;
      End If;

      V_Doc_Due_Date   := G_Doc_Date + Nvl (V_Crdt_Prd_Day, 0);
   End If;

   --##-----------------------------------------------------------------------------------------------##--
   If V_Doc_Due_Date Is Not Null And V_Doc_Due_Date < G_Doc_Date Then
      P_Err_No    := 20564;
      P_Msg_Txt   := 'Invalid Date (DOC_DUE_DATE) , Because DOC_DUE_DATE < DOC_DATE , ';
      Goto Rtn_Rslt;
   Elsif P_Cheque_Due_Date Is Not Null And P_Cheque_Due_Date < G_Doc_Date Then
      P_Err_No    := 20565;
      P_Msg_Txt   := 'Invalid Date (CHEQUE_DUE_DATE) , Because CHEQUE_DUE_DATE < DOC_DATE , ';
      Goto Rtn_Rslt;
   End If;

   V_Msg_No             := Null;

   If G_Use_Vat = 1 Then
      If G_Clc_Typ_No_Tax Is Null Then
         P_Err_No    := 20566;
         P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 1601) || ' ' || Ias_Gen_Pkg.Get_Prompt (G_Lng_No, 12526) || ' ,CLC_TYP_NO_TAX IS NULL ';
         Goto Rtn_Rslt;
      End If;
   End If;
   --##-----------------------------------------------------------------------------------------------##--
   If G_Ar_Wc_Type = 1 Then
      G_W_Code   := Nvl (G_W_Code, G_W_Code);
   Else
      G_W_Code   := Nvl (G_W_Code, G_W_Code);
   End If;

   If Nvl (G_Ar_Wc_Type, 0) = 1 And G_W_Code Is Null Then
      P_Err_No    := 20567;
      P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 930);
      Goto Rtn_Rslt;
   End If;
   --##-----------------------------------------------------------------------------------------------##--
   --## CHK ACCNT AND PYMNT
   
   IF NVL(G_RT_Bill_Doc_Type,0) IN(2,6,5) THEN      
     G_Bank_No          := NVL(G_Bank_No,G_Cash_No);
     G_Cash_No          := NULL;
   ELSE
     G_Bank_No          := NULL;
     G_Cash_No          := G_Cash_No;
   END IF;
   
   
   Chk_Accnt (P_Cur_Code        => P_Cur_Code
             ,P_Cur_Rate        => G_Cur_Rate
             ,P_Stk_Rate        => G_Stk_Rate
             ,P_Cash_No         => G_Cash_No
             ,P_Bank_No         => G_Bank_No
             ,P_C_Code          => G_C_Code
             ,P_Ac_Code         => Nvl (P_Ac_Code, P_A_Code)
             ,P_Ac_Code_Dtl     => P_Ac_Code_Dtl
             ,P_Ac_Dtl_Typ      => P_Ac_Dtl_Typ
             ,P_V_Code          => Null
             ,P_Bill_Doc_Type   => G_Rt_Bill_Doc_Type
             ,P_Doc_Amt         => P_Bill_Amt
             ,P_Msg_Txt         => P_Msg_Txt
             ,P_Err_No          => P_Err_No
             ,P_Pkg_Nm          => P_Pkg_Nm);

   If P_Msg_Txt Is Not Null Then     
      Goto Rtn_Rslt;
   End If;
   --##-----------------------------------------------------------------------------------------------##--
   --## CHK GNR DATA
   Chk_Gnr_Data (P_Brn_No           => G_Brn_No
                ,P_Ad_U_Id          => G_Ad_U_Id
                ,P_Emp_No           => G_Emp_No
                ,P_Rep_Code         => G_Rep_Code
                ,P_Col_No           => G_Col_No
                ,P_R_Code           => G_R_Code
                ,P_W_Code           => G_W_Code
                ,P_Clc_Typ_No_Tax   => G_Clc_Typ_No_Tax
                ,P_Msg_Txt          => P_Msg_Txt
                ,P_Err_No           => P_Err_No
                ,P_Pkg_Nm           => P_Pkg_Nm);

   If P_Msg_Txt Is Not Null Then
      Goto Rtn_Rslt;
   End If;
   --##-----------------------------------------------------------------------------------------------##--
   --## SUB LDGR
   Gnr_Api_Pkg.Chk_Sub_Ldgr (P_Sys_Typ     => 1
                            ,P_Sys_No      => G_Sys_No
                            ,P_Doc_Type    => G_Doc_Typ
                            ,P_Cst_Type    => G_Ar_Cst_Type
                            ,P_Pj_Type     => G_Ar_Pj_Type
                            ,P_Actv_Type   => G_Ar_Actv_Type
                            ,P_Cc_Code     => G_Cc_Code
                            ,P_Pj_No       => G_Pj_No
                            ,P_Actv_No     => G_Actv_No
                            ,P_Rep_Code    => G_Rep_Code
                            ,P_A_Code      => G_A_Code
                            ,P_Chk_Ac_Cc   => 1
                            ,P_BILL_DOC_TYPE =>G_BILL_DOC_TYPE
                            ,P_C_CODE        =>G_C_CODE
                            ,P_P_Year        =>G_P_Year
                            ,P_Lng_No      => G_Lng_No
                            ,P_Msg_Txt     => P_Msg_Txt
                            ,P_Pkg_Line    => P_Err_No
                            ,P_Pkg_Nm      => P_Pkg_Nm);

   If P_Msg_Txt Is Not Null Then
      Goto Rtn_Rslt;
   End If;
   --##-----------------------------------------------------------------------------------------------##--
   If G_R_Code Is Null Then
      If G_C_Code Is Not Null Then
         Begin
            Select R_Code
              Into G_R_Code
              From Customer
             Where C_Code = G_C_Code And Rownum <= 1;
         Exception
            When Others Then
               Null;
         End;
      End If;
   Else
      G_R_Code   := P_R_Code;
   End If;
   --##-----------------------------------------------------------------------------------------------##--
   If G_Use_Vat = 1 Then
      If G_Use_Price_Include_Vat = 1 Then
         G_Clc_Vat_Price_Typ   := Nvl (P_Clc_Vat_Price_Typ, 2);
      Else
         G_Clc_Vat_Price_Typ   := Nvl (P_Clc_Vat_Price_Typ, 1);
      End If;

      If G_Clc_Vat_Price_Typ Is Null Then
         P_Err_No    := 20568;
         P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (G_Lng_No, 1601) || ' ' || Ias_Gen_Pkg.Get_Prompt (G_Lng_No, 11364) || Chr (10) || ' CLC_VAT_PRICE_TYP Is Null , ';
         Goto Rtn_Rslt;
      End If;
   Else
     G_Clc_Vat_Price_Typ:=1;     
   End If;
   --##-----------------------------------------------------------------------------------------------##--
   If Nvl (P_Vat_Amt, 0) < 0 Then
      P_Err_No    := 20569;
      P_Msg_Txt   := 'Invalid Value For (VAT_AMT) , Because VAT_AMT < 0  ';
      Goto Rtn_Rslt;
   End If;
   
   If Nvl (P_Bill_Amt, 0) < 0 Then
      P_Err_No    := 20570;
      P_Msg_Txt   := 'Invalid Value For (BILL_AMT) , Because BILL_AMT < 0  ';
      Goto Rtn_Rslt;
   End If;
   --##-----------------------------------------------------------------------------------------------##--
   If G_Sr_Type Is Not Null Then -- RT SALES TYPE
         BEGIN
             SELECT 1
               INTO G_INPT_NM
               FROM IAS_AR_TYPS
              WHERE AR_TYPE_NO=9
              AND TYP_NO = G_Sr_Type
                    AND ROWNUM <= 1;
         EXCEPTION
             WHEN OTHERS THEN
                P_Err_No    := 20571;
                P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No) || ' SR_TYPE=' || G_Sr_Type;
                Goto Rtn_Rslt;
         END;

      If V_Msg_No Is Not Null Then
         P_Err_No    := 20572;
         P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No) || ' SR_TYPE=' || G_Sr_Type;
         Goto Rtn_Rslt;
      End If;
   Else
      P_Err_No    := 20573;
      P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 1601) || ' ' || Ias_Gen_Pkg.Get_Prompt (G_Lng_No, 1326);
      Goto Rtn_Rslt;
   End If;
   --##-----------------------------------------------------------------------------------------------##--
   If G_P_Year Is Null Then
      P_Err_No    := 20574;
      P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (G_Lng_No, 1601) || ' P_YEAR';
      Goto Rtn_Rslt;
   Else
      If G_P_Year Not In (0, 1, 2, 3) Then
         P_Err_No    := 20575;
         P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 312) || ' P_P_YEAR =' || G_P_Year;
         Goto Rtn_Rslt;
      End If;
   End If;
   
   
   -----------------------------------------------------
   
   If G_P_Year=1 and G_Prev_Year Is Null Then   
         P_Err_No    := 20576;
         P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 312) || ' Prev_Year ';
         Goto Rtn_Rslt;
   Elsif G_P_Year in(0,3) Then    
     G_Prev_Year:=G_brn_Year;      
   End if;
   
      
   
   -------------------------------------------------------------------------------------------##--
   --##CHK MNDTRY FLDS
   If G_Invoicing_Serials_Sr In (3, 6) And G_Cc_Code Is Null Then
      P_Err_No    := 20577;
      P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 87) || ' CC_CODE IS NULL';
      Goto Rtn_Rslt;
   End If;

   If G_Invoicing_Serials_Sr In (4, 5, 8, 9) And G_W_Code Is Null Then
      P_Err_No    := 20578;
      P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (G_Lng_No, 1601) || ' ' || Ias_Gen_Pkg.Get_Prompt (G_Lng_No, 1326);
      Goto Rtn_Rslt;
   End If;

   If G_Invoicing_Serials_Sr In (7, 8, 9, 10) And G_Sr_Type Is Null Then
      P_Err_No    := 20579;
      P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (G_Lng_No, 1601) || ' ' || Ias_Gen_Pkg.Get_Prompt (G_Lng_No, 947);
      Goto Rtn_Rslt;
   End If;

   If G_Invoicing_Serials_Sr In (2, 5, 6, 9, 10) And G_Rt_Bill_Doc_Type Is Null Then
      P_Err_No    := 20580;
      P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (G_Lng_No, 1601) || ' ' || Ias_Gen_Pkg.Get_Prompt (G_Lng_No, 535);
      Goto Rtn_Rslt;
   End If;

   --##-----------------------------------------------------------------------------------------------##--
   If Nvl (P_Disc_Amt_Mst, 0) < 0 Or Nvl (P_Disc_Amt_Dtl, 0) < 0 Or Nvl (P_Disc_Amt, 0) < 0 Then
      P_Err_No    := 20581;
      P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 3312) || ' DISC_AMT_MST OR DISC_AMT_DTL OR DISC_AMT ';
      Goto Rtn_Rslt;
   End If;

   --##-----------------------------------------------------------------------------------------------##--
   If P_Sys_No = 61 Then -- SALES SYSTEM
      V_Sys_No_Extrnl   := Null;
      G_External_Post   := 0;
   Else
      G_External_Post   := G_Sys_No;
   End If;
   --##-----------------------------------------------------------------------------------------------##--
   --## GET AND CHEACK DOC_NO
   If P_Doc_No Is Not Null Then
      G_Doc_No   := P_Doc_No;
   Else
       Get_Doc_No ( P_Doc_Typ  => G_Doc_Typ
                  ,P_Msg_Txt  => P_Msg_Txt
                  ,P_Err_No   => P_Err_No
                  ,P_Pkg_Nm   => P_Pkg_Nm);

       If P_Msg_Txt Is Not Null Then
          Goto Rtn_Rslt;
       End If;
   End If;

   If G_Doc_No Is Null Then
      P_Err_No    := 20582;
      P_Msg_Txt   := ' RT_BILL_NO IS NULL ';
      Goto Rtn_Rslt;        
   End If;
   --##-----------------------------------------------------------------------------------------------##--
   --## GET AND CHEACK DOC_SER
    If P_Doc_SER Is NOT Null Then
        G_Doc_SER:=P_Doc_SER;
    ELSE    
      Get_Doc_Ser ( P_Doc_Typ  => G_Doc_Typ
                    ,P_Msg_Txt  => P_Msg_Txt
                    ,P_Err_No   => P_Err_No
                    ,P_Pkg_Nm   => P_Pkg_Nm);

       If P_Msg_Txt Is Not Null Then
          Goto Rtn_Rslt;
       End If;
    END iF;      
       
   If G_Doc_SER Is Null Then
      P_Err_No    := 20583;
      P_Msg_Txt   := ' RT_BILL_SER IS NULL ';
      Goto Rtn_Rslt;        
   End If;
   
   If P_Doc_Ser Is Not Null Then
      If NVL(P_Doc_Ser,0) <> NVL(G_Doc_Ser,0) Then
         P_Err_No    := 20584;
         P_Msg_Txt   := ' P_Doc_Ser Sent Is Invalid Syntax =' || P_Doc_Ser || ' ';
         Goto Rtn_Rslt;
      End If;
   End If;
  --##-----------------------------------------------------------------------------------------------##--
    Check_Duplicate (P_Doc_Typ   => G_Doc_Typ
                     ,P_Doc_No    => G_Doc_No
                     ,P_Msg_Txt   => P_Msg_Txt
                     ,P_Err_No    => P_Err_No
                     ,P_Pkg_Nm    => P_Pkg_Nm);

      If P_Msg_Txt Is Not Null Then
         Goto Rtn_Rslt;
      End If;

   --##-----------------------------------------------------------------------------------------------##--
   --##CHK_CONN_CST_COL
     ARS_API_CHK_PKG.Chk_Conn_Cst_Col (P_C_Code    => G_C_Code
                    ,P_Col_No    => G_Col_No
                    ,P_Lng_No    => G_Lng_No
                    ,P_Msg_Txt   => P_Msg_Txt
                    ,P_Err_No    => P_Err_No
                    ,P_Pkg_Nm    => P_Pkg_Nm);

   If P_Msg_Txt Is Not Null Then
      Goto Rtn_Rslt;
   End If;
   --##-----------------------------------------------------------------------------------------------##--
   --##CHK REP_CODE
     ARS_API_CHK_PKG.Chk_Sman_Conn_Data (P_Sys_No          => P_Sys_No
                      ,P_Rep_Code        => G_Rep_Code
                      ,P_Bill_Doc_Type   => G_Bill_Doc_Type
                      ,P_W_Code          => G_W_Code
                      ,P_Cash_No         => G_Cash_No
                      ,P_Cc_Code         => G_Cc_Code
                      ,P_Pj_No           => G_Pj_No
                      ,P_Actv_No         => G_Actv_No
                      ,P_Lng_No          => G_Lng_No
                      ,P_Msg_Txt         => P_Msg_Txt
                      ,P_Err_No          => P_Err_No
                      ,P_Pkg_Nm          => P_Pkg_Nm);

   If P_Msg_Txt Is Not Null Then
      Goto Rtn_Rslt;
   End If;
   --##-----------------------------------------------------------------------------------------------##--
   SET_TAX_BILL_TYP( P_BILL_DOC_TYPE=>G_Rt_Bill_Doc_type
                      ,P_C_CODE       =>G_C_Code
                      ,P_Use_Vat      =>G_Use_Vat
                      ,P_C_TAX_CODE   =>V_C_TAX_CODE
                      ,P_TAX_BILL_TYP  => V_TAX_BILL_TYP                        
                      ) ;       
  --##-----------------------------------------------------------------------------------------##--    
   If Nvl (P_Rt_Vat_Prd_Typ, 0) Not In (1, 2) Then
      V_Rt_Vat_Prd_Typ   := 1;
   ELSE
     V_Rt_Vat_Prd_Typ   := P_Rt_Vat_Prd_Typ;   
   End If;
   --##-----------------------------------------------------------------------------------------------##--
    If nvl(G_use_Vat,0)=1 Then 
       IF NVL(G_SYS_NO,0)=70 THEN 
         G_CLC_TAX_FREE_QTY_FLG:=NVL(P_CLC_TAX_FREE_QTY_FLG,0);
       ELSE 
          G_CLC_TAX_FREE_QTY_FLG:=G_USE_CLC_TAX_FREE_QTY;
       END IF; 
    Else
     G_CLC_TAX_FREE_QTY_FLG:=0;
    End If;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          -- P_REF_NO;
   --##-----------------------------------------------------------------------------------------##--
  
      Begin
         Insert Into Ias_Rt_Bill_Mst_RQ (Rt_Bill_No
                                     ,Rt_Bill_Ser
                                     ,Rt_Bill_Doc_Type
                                     ,Rt_Bill_Date
                                     ,Rt_Bill_Currency
                                     ,Rt_Bill_Rate
                                     ,Stock_Rate
                                     ,P_Year
                                     ,C_Code
                                     ,C_Name
                                     ,A_Code
                                     ,BILL_NO_MNL
                                     ,Cheque_No
                                     ,Cheque_Amt
                                     ,Cheque_Due_Date
                                     ,Rt_Bill_Due_Date
                                     ,W_Code
                                     ,R_Code
                                     ,Cash_No
                                     ,Cc_Code
                                     ,Pj_No
                                     ,Actv_No
                                     ,Cash_Ac_Fcc
                                     ,Cash_No_Fcc
                                     ,Clc_Typ_No_Tax
                                     ,Ac_Code
                                     ,Ac_Code_Dtl
                                     ,Ac_Dtl_Typ
                                     ,Rep_Code
                                     ,Emp_No
                                     ,Sr_Type
                                     ,Ref_No
                                     ,A_Desc
                                     ,Return_Res
                                     ,Prev_Year
                                     ,Classify_No
                                     ,Classify_Ser
                                     ,W_Code_Bill
                                     ,Cc_Code_Bill
                                     ,Rep_Code_Bill
                                     ,Stand_By
                                     ,Note_No
                                     ,Driver_No
                                     ,Doc_Brn_No
                                     ,Processed
                                     ,Res_Typ                                    
                                   --  ,Rt_Vat_Prd_Typ                                                                  
                                     ,Pymnt_Ac
                                     ,Ac_Amt
                                     ,Doc_Ser_Extrnl                                   
                                     ,Clc_Vat_Price_Typ                                  
                                     ,Field1
                                     ,Field2
                                     ,Field3
                                     ,Field4
                                     ,Field5
                                     ,Field6
                                     ,Field7
                                     ,Field8
                                     ,Field9
                                     ,Field10
                                     ,Prm_Code
                                     ,Bill_Amt
                                     ,Disc_Amt
                                     ,Disc_Amt_Mst
                                     ,Disc_Amt_Dtl
                                     ,Vat_Amt
                                     ,Othr_Amt
                                     ,Othr_Amt_Disc
                                    ,Vat_Amt_Othr
                                     ,Disc_Amt_Aftr_Vat
                                     ,Disc_Amt_Mst_Vat
                                     ,Vat_Amt_Disc_Mst
                                     ,External_Post
                                     ,CLC_TAX_FREE_QTY_FLG
                                     ,Cmp_No
                                     ,Brn_No
                                     ,Brn_Year
                                     ,Brn_Usr
                                     ,Ad_U_Id
                                     ,Ad_Date
                                     ,Ad_Trmnl_Nm
                                     ,C_TAX_CODE
                                     ,TAX_BILL_TYP 
                                     )
              Values (G_Doc_No
                     ,G_Doc_Ser
                     ,G_Rt_Bill_Doc_Type
                     ,G_Doc_Date
                     ,G_Cur_Code
                     ,G_Cur_Rate
                     ,G_Stk_Rate
                     ,G_P_Year
                     ,G_C_Code
                     ,V_Cst_Nm
                     ,G_A_Code
                    , G_BILL_NO_MNL
                     ,P_Cheque_No
                     ,P_Cheque_Amt
                     ,P_Cheque_Due_Date
                     ,V_Doc_Due_Date
                     ,Decode (G_Ar_Wc_Type, 1, G_W_Code, Null)
                     ,G_R_Code
                     ,NVL(G_Cash_No,G_BANK_NO)
                     ,Decode (G_Ar_Cst_Type, 1, G_Cc_Code, Null)
                     ,Decode (G_Ar_Pj_Type, 1, G_Pj_No, Null)
                     ,Decode (G_Ar_Actv_Type, 1, G_Actv_No, Null)
                     ,G_Cash_Ac_Fcc
                     ,G_Bank_No
                     ,G_Clc_Typ_No_Tax
                     ,G_Ac_Code
                     ,G_Ac_Code_Dtl
                     ,G_Ac_Dtl_Typ
                     ,G_Rep_Code
                     ,G_Emp_No
                     ,G_Sr_Type
                     ,G_Ref_No
                     ,G_Doc_Dsc
                     ,P_Return_Res
                     ,Decode(G_P_Year,1,P_Prev_Year,null)
                     ,P_Classify_No
                     ,P_Classify_Ser
                     ,P_W_Code_Bill
                     ,P_Cc_Code_Bill
                     ,P_Rep_Code_Bill
                     ,Nvl (P_Stand_By, 0)
                     ,P_Note_No
                     ,DECODE(NVL(P_Driver_No,0), 0, NULL,P_Driver_No)  
                     ,Nvl (P_Doc_Brn_No, G_Brn_No)
                     ,0
                     ,P_Res_Typ                     
                   --  ,V_Rt_Vat_Prd_Typ                                     
                     ,P_Pymnt_Ac
                     ,P_Ac_Amt
                     ,P_Doc_Ser_Extrnl                   
                     ,nvl(G_Clc_Vat_Price_Typ,1)                   
                     ,P_Field1
                     ,P_Field2
                     ,P_Field3
                     ,P_Field4
                     ,P_Field5
                     ,P_Field6
                     ,P_Field7
                     ,P_Field8
                     ,P_Field9
                     ,P_Field10
                     ,P_Prm_Code
                     ,Nvl (P_Bill_Amt, 0)
                     ,Nvl (P_Disc_Amt, 0)
                     ,Nvl (P_Disc_Amt_Mst, 0)
                     ,Nvl (P_Disc_Amt_Dtl, 0)
                     ,Nvl (P_Vat_Amt, 0)
                     ,Nvl (P_Othr_Amt, 0)
                     ,Nvl (P_Othr_Amt_Disc, 0)
                     ,Nvl (P_Vat_Amt_Othr, 0)
                     ,Nvl (P_Disc_Amt_Aftr_Vat, 0)
                     ,Nvl (P_Disc_Amt_Mst_Vat, 0)
                     ,Nvl (P_Vat_Amt_Disc_Mst, 0)
                     ,G_External_Post
                     ,NVL(G_CLC_TAX_FREE_QTY_FLG,0)
                     ,G_Cmp_No
                     ,G_Brn_No
                     ,G_Brn_Year
                     ,G_Brn_Usr
                     ,G_Ad_U_Id
                     ,G_Ad_Date
                     ,P_Ad_Trmnl_Nm 
                     ,V_C_TAX_CODE
                     ,V_TAX_BILL_TYP                     
                     );
      Exception
         When Others Then
            P_Msg_Txt   := 'ERROR WHEN INSERT IAS_RT_BILL_MST_RQ ' || Chr (10) || Sqlerrm;
            P_Err_No    := 20585;
            P_Pkg_Nm    := 'Ars_Api_Trns_Pkg.INSRT_IAS_RT_BILL_MST_RQ';
            Goto Rtn_Rslt;
      End;

     
   -----------------------------------------------------------------------------------------
  --####################--
  <<RTN_RSLT>>
   If P_Msg_Txt Is Not Null OR P_Err_No Is Not Null Then
      Rollback;
      P_Msg_Txt   := NVL(P_Msg_Txt,'Message Number Is Missing');
      P_Err_No    := P_Err_No;
      P_Pkg_Nm    := Nvl (P_Pkg_Nm, 'Ars_Api_Trns_Pkg.Insrt_Ias_Rt_Bill_Mst_RQ');
      Return;
   ELSE
      P_Msg_Txt   := NULL;
      P_Err_No    := NULL;
      P_Pkg_Nm    := NULL;   
   End If;
--####################--
Exception
   When Others Then
      Rollback;
      P_Msg_Txt   := 'ERROR WHEN INSERT ' || V_Tbl_Mst || ' ' || Chr (10) || Sqlerrm;
      P_Err_No    := 20586;
      P_Pkg_Nm    := 'Ars_Api_Trns_Pkg.Insrt_Ias_Rt_Bill_Mst_RQ';
End Insrt_Ias_Rt_Bill_Mst_RQ;

--##-----------------------------------------------------------------------------------------------------##--
 Procedure Insrt_Ias_Rt_Bill_Dtl_RQ (P_I_Code                 In     Ias_Rt_Bill_Dtl.I_Code%Type Default Null
                                ,P_I_Qty                  In     Ias_Rt_Bill_Dtl.I_Qty%Type Default Null
                                ,P_P_Size                 In     Ias_Rt_Bill_Dtl.P_Size%Type Default Null
                                ,P_Itm_Unt                In     Ias_Bill_Dtl.Itm_Unt%Type Default Null
                                ,P_I_Price                In     Ias_Rt_Bill_Dtl.I_Price%Type Default Null
                                ,P_I_Price_Vat            In     Ias_Rt_Bill_Dtl.I_Price_Vat%Type Default Null
                                ,P_Doc_Sequence           In Out Ias_Rt_Bill_Dtl.Doc_Sequence%Type
                                ,P_Rcrd_No                In Out Ias_Rt_Bill_Dtl.Rcrd_NO%Type
                                ,P_W_Code                 In     Ias_Rt_Bill_Dtl.W_Code%Type Default Null
                                ,P_Bill_No                In     Ias_Rt_Bill_Dtl.Bill_No%Type Default Null
                                ,P_Bill_Doc_Type          In     Ias_Rt_Bill_Dtl.Bill_Doc_Type%Type Default Null
                                ,P_Bill_Ser               In     Ias_Rt_Bill_Dtl.Bill_Ser%Type Default Null
                                ,P_Cc_Code                In     Ias_Rt_Bill_Dtl.Cc_Code%Type Default Null
                                ,P_Pj_No                  In     Ias_Rt_Bill_Dtl.Pj_No%Type Default Null
                                ,P_Actv_No                In     Ias_Rt_Bill_Dtl.Actv_No%Type Default Null
                                ,P_Expire_Date            In     Ias_Rt_Bill_Dtl.Expire_Date%Type Default Null
                                ,P_Batch_No               In     Ias_Rt_Bill_Dtl.Batch_No%Type Default Null
                                ,P_Free_Qty               In     Ias_Rt_Bill_Dtl.Free_Qty%Type Default Null
                                ,P_DOC_SEQUENCE_SI        In     Ias_Rt_Bill_Dtl.DOC_SEQUENCE_SI%Type Default Null
                                ,P_SI_RCRD_NO             In     Ias_Rt_Bill_Dtl.SI_RCRD_NO%Type      Default Null
                                ,P_Dis_Per                In     Ias_Rt_Bill_Dtl.Dis_Per%Type Default Null
                                ,P_Dis_Per2               In     Ias_Rt_Bill_Dtl.Dis_Per2%Type Default Null
                                ,P_Dis_Per3               In     Ias_Rt_Bill_Dtl.Dis_Per3%Type Default Null
                                ,P_Dis_Amt                In     Ias_Rt_Bill_Dtl.Dis_Amt%Type Default Null
                                ,P_Dis_Amt_Mst            In     Ias_Rt_Bill_Dtl.Dis_Amt_Mst%Type Default Null
                                ,P_Dis_Amt_Dtl            In     Ias_Rt_Bill_Dtl.Dis_Amt_Dtl%Type Default Null
                                ,P_Dis_Amt_Dtl2           In     Ias_Rt_Bill_Dtl.Dis_Amt_Dtl2%Type Default Null
                                ,P_Dis_Amt_Dtl3           In     Ias_Rt_Bill_Dtl.Dis_Amt_Dtl3%Type Default Null
                                ,P_Vat_Per                In     Ias_Rt_Bill_Dtl.Vat_Per%Type Default Null
                                ,P_Vat_Amt                In     Ias_Rt_Bill_Dtl.Vat_Amt%Type Default Null
                                ,P_Othr_Amt               In     Ias_Rt_Bill_Dtl.Othr_Amt%Type Default Null
                                ,P_Vat_Amt_Othr           In     Ias_Rt_Bill_Dtl.Vat_Amt_Othr%Type Default Null
                                ,P_Othr_Amt_Disc          In     Ias_Rt_Bill_Dtl.Othr_Amt_Disc%Type Default Null
                                ,P_Dis_Aftr_Vat_Mst       In     Ias_Rt_Bill_Dtl.Dis_Aftr_Vat_Mst%Type Default Null
                                ,P_Dis_Amt_Mst_Vat        In     Ias_Rt_Bill_Dtl.Dis_Amt_Mst_Vat%Type Default Null
                                ,P_Vat_Amt_Dis_Dtl_Vat    In     Ias_Rt_Bill_Dtl.Vat_Amt_Dis_Dtl_Vat%Type Default Null
                                ,P_Vat_Amt_Aftr_Dis       In     Ias_Rt_Bill_Dtl.Vat_Amt_Aftr_Dis%Type Default Null
                                ,P_Vat_Amt_Bfr_Dis        In     Ias_Rt_Bill_Dtl.Vat_Amt_Bfr_Dis%Type Default Null
                                ,P_Dis_Amt_Dtl_Vat        In     Ias_Rt_Bill_Dtl.Dis_Amt_Dtl_Vat%Type Default Null
                                ,P_Dis_Amt_Dtl2_Vat       In     Ias_Rt_Bill_Dtl.Dis_Amt_Dtl2_Vat%Type Default Null
                                ,P_Dis_Amt_Dtl3_Vat       In     Ias_Rt_Bill_Dtl.Dis_Amt_Dtl3_Vat%Type Default Null
                                ,P_Vat_Amt_Dis_Mst_Vat    In     Ias_Rt_Bill_Dtl.Vat_Amt_Dis_Mst_Vat%Type Default Null
                                ,P_Vat_Amt_Dis_Dtl2_Vat   In     Ias_Rt_Bill_Dtl.Vat_Amt_Dis_Dtl2_Vat%Type Default Null
                                ,P_Vat_Amt_Dis_Dtl3_Vat   In     Ias_Rt_Bill_Dtl.Vat_Amt_Dis_Dtl3_Vat%Type Default Null
                                ,P_Dis_Amt_Aftr_Vat       In     Ias_Rt_Bill_Dtl.Dis_Amt_Aftr_Vat%Type Default Null
                                ,P_Lev_No                 In     Ias_Bill_Dtl.Lev_No%Type Default Null
                                ,P_Item_Desc              In     Ias_Rt_Bill_Dtl.Item_Desc%Type Default Null
                                ,P_Barcode                In     Ias_Rt_Bill_Dtl.Barcode%Type Default Null
                                ,P_Field_Dtl1             In     Ias_Rt_Bill_Dtl.Field_Dtl1%Type Default Null
                                ,P_Field_Dtl2             In     Ias_Rt_Bill_Dtl.Field_Dtl2%Type Default Null
                                ,P_Field_Dtl3             In     Ias_Rt_Bill_Dtl.Field_Dtl3%Type Default Null
                                ,P_Emp_No                 In     Ias_Rt_Bill_Dtl.Emp_No%Type Default Null
                                ,P_Doc_Type_Ref           In     Ias_Rt_Bill_Dtl.Doc_Type_Ref%Type Default Null
                                ,P_Doc_No_Ref             In     Ias_Rt_Bill_Dtl.Doc_No_Ref%Type Default Null
                                ,P_Doc_Ser_Ref            In     Ias_Rt_Bill_Dtl.Doc_Ser_Ref%Type Default Null
                                ,P_Sub_C_Code             In     Ias_Rt_Bill_Dtl.Sub_C_Code%Type Default Null
                                ,P_Rcrd_No_Ref            In     Ias_Rt_Bill_Dtl.Rcrd_No_Ref%Type Default Null
                                ,P_Qt_Prm_No              In     Ias_Rt_Bill_Dtl.Qt_Prm_No%Type Default Null
                                ,P_Qt_Prm_Ser             In     Ias_Rt_Bill_Dtl.Qt_Prm_Ser%Type Default Null
                                ,P_Qt_Prm_Rcrd_No         In     Ias_Rt_Bill_Dtl.Qt_Prm_Rcrd_No%Type Default Null
                                ,P_I_Length               In     Ias_Rt_Bill_Dtl.I_Length%Type Default Null
                                ,P_I_Width                In     Ias_Rt_Bill_Dtl.I_Width%Type Default Null
                                ,P_I_Height               In     Ias_Rt_Bill_Dtl.I_Height%Type Default Null
                                ,P_I_Number               In     Ias_Rt_Bill_Dtl.I_Number%Type Default Null
                                ,P_Wt_Qty                 In     Ias_Rt_Bill_Dtl.Wt_Qty%Type Default Null
                                ,P_Wt_Unt                 In     Ias_Rt_Bill_Dtl.Wt_Unt%Type Default Null -- ,P_MEASUR_PRICE               IN IAS_RT_BILL_DTL.MEASUR_PRICE%TYPE                 DEFAULT NULL
                                ,P_Argmnt_No              In     Ias_Rt_Bill_Dtl.Argmnt_No%Type Default Null
                                ,P_SERIALNO_N             IN     CLOB  Default Null
                                ,P_Msg_Txt                   Out Varchar2
                                ,P_Err_No                    Out Varchar2
                                ,P_Pkg_Nm                    Out Varchar2)
Is
   V_P_Size                  Ias_Itm_Dtl.P_Size%Type;
   V_Cnt                     Number;
   V_Msg_No                  Number;
   V_Stkcost                 Ias_Bill_Dtl.Stk_Cost%Type;
   V_Doc_Sequence            Ias_Bill_Dtl.Doc_Sequence%Type;
   V_Service_Itm             Number;
   V_Cst                     Number;
   V_Use_Serialno            Number;
   V_Post_Code               Ias_Bill_Dtl.Post_Code%Type;
   V_Used_Itm                Number;  
   V_Tbl_Dtl                 Varchar2 (2000); 
   V_Wcode                   Number;
   V_Allow_Enter_Zero_Cost   Number := 0;
   V_Wt_After                Number;
   V_Ret_No                  Ias_Rt_Bill_Mst.Rt_Bill_No%Type;
   V_Ret_Ser                 Ias_Rt_Bill_Mst.Rt_Bill_Ser%Type;
   V_Bill_No                 Ias_Bill_Mst.Bill_No%Type;
   V_Bill_Doc_Type           Number;
   V_Doc_Sequence_Si         Number;
   V_Si_Rcrd_No              Number;
   V_Si_I_Qty                Number;
   V_Si_Free_Qty             Number;
   V_I_Price                 Number:=P_I_Price;
   V_I_Price_Vat             Number:=p_I_Price_Vat;
   V_Vat_Per                 Number;
   V_Clc_Typ_No              Number;
   V_TBL_Serialno     Varchar2 (500);
   V_CNT_QTY          NUMBER; 
   
Begin
   If G_Doc_Ser Is Null Or G_Doc_No Is Null Then
      P_Err_No    := 20587;
      P_Msg_Txt   := 'G_DOC_SER OR G_DOC_NO .. IS NULL ';
      Goto Rtn_Rslt;
   End If;

   If G_Pst_Typ Is Null Then
      P_Err_No    := 20588;
      P_Msg_Txt   := 'PST_TYP IS NULL ';
      Goto Rtn_Rslt;
   Elsif G_Pst_Typ Not In (1, 2) Then
      P_Err_No    := 20589;
      P_Msg_Txt   := 'Pst_Typ Must Be Equal 1 Or 2 ';
      Goto Rtn_Rslt;
   End If;

  
       V_TBL_Serialno     :='IAS_ITEM_SERIALNO_OTHER';     
   

   --##------------------------------------------------------------------------------------------##--
   If G_Ar_Wc_Type = 1 Then
      G_W_Code   := G_W_Code;
   Else
      G_W_Code   := Nvl (P_W_Code, G_W_Code);
      If G_W_Code Is Not Null Then
        GNR_API_PKG.Chk_Inpt_Data (P_Inpt_Typ     => 'W_CODE'
                                   ,P_SYS_TYP      =>1
                                   ,P_DOC_TYPE     => G_DOC_TYP
                                   ,P_Inpt_Code1   => G_W_Code
                                   ,P_Inpt_Code2   => G_Brn_No
                                   ,P_Inpt_Code3   => G_ALLW_SAL_WH_NOT_CONN_BRN
                                   ,P_Inpt_Code4   => G_USE_BALANCED_BRN
                                   ,P_Lng_Dflt     => G_Lng_No
                                   ,P_Inpt_Nm      => G_Inpt_Nm
                                   ,P_Msg_No       => V_Msg_No);

         If V_Msg_No Is Not Null Then
            P_Err_No :=20741 ;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No) || ' W_CODE=' || G_W_Code;
            Goto Rtn_Rslt;
         End If;
      END IF;
   End If;

   If G_W_Code Is Null Then
      P_Err_No    := 20590;
      P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 930);
      Goto Rtn_Rslt;
   End If;
   --##---------------------------------------------------------------------------------------------------------------------------##--
   If Nvl (G_Use_Vat, 0) = 1 And G_Clc_Typ_No_Tax Is Not Null And Nvl (G_Clc_Tax_Method, 0) = 1 Then       
         If Nvl (Ys_Tax_Pkg.Get_Clc_Tax_Typ (P_Clc_Typ_No => G_Clc_Typ_No_Tax), 0) = 0 Then
            -- V_Vat_Per   := Ys_Tax_Pkg.Get_Itm_Tax_Prcnt (P_Clc_Typ_No => G_Clc_Typ_No_Tax, P_I_Code => P_I_Code, P_Clc_Usd_Itm => 1);
              V_Vat_Per   :=Ys_Tax_Pkg.Get_Itm_Tax_Prcnt_Sal ( P_Clc_Typ_No =>G_Clc_Typ_No_Tax  
                                                             , P_I_Code => P_I_CODE 
                                                              ,P_Clc_Usd_Itm => 1
                                                              ,P_I_Price=>P_I_Price
                                                              ,P_I_Price_Vat =>case when Nvl(G_Clc_Vat_Price_Typ,0) = 2 Then (Case when nvl(P_I_Price_Vat,0) =0 Then Nvl (P_I_Price, 0) Else Nvl (P_I_Price_Vat, 0) end) else Nvl (P_I_Price, 0) end  
                                                              ,P_Use_Price_Include_Vat=> case when Nvl(G_Clc_Vat_Price_Typ,0) = 2 then 1 else 0 end ); 
          Else
             V_Clc_Typ_No   := Ys_Tax_Pkg.Get_Clc_Typ_No_Exmpt (P_Clc_Typ_No => G_Clc_Typ_No_Tax);
            -- V_Vat_Per      := Ys_Tax_Pkg.Get_Itm_Tax_Prcnt (P_Clc_Typ_No => V_Clc_Typ_No, P_I_Code => P_I_Code, P_Clc_Usd_Itm => 1);
            V_Vat_Per   :=Ys_Tax_Pkg.Get_Itm_Tax_Prcnt_Sal ( P_Clc_Typ_No =>V_Clc_Typ_No  
                                                             , P_I_Code => P_I_CODE 
                                                              ,P_Clc_Usd_Itm => 1
                                                              ,P_I_Price=>P_I_Price
                                                              ,P_I_Price_Vat =>case when Nvl(G_Clc_Vat_Price_Typ,0) = 2 Then (Case when nvl(P_I_Price_Vat,0) =0 Then Nvl (P_I_Price, 0) Else Nvl (P_I_Price_Vat, 0) end) else Nvl (P_I_Price, 0) end  
                                                              ,P_Use_Price_Include_Vat=> case when Nvl(G_Clc_Vat_Price_Typ,0) = 2 then 1 else 0 end );
          End If;
          If nvl(V_Vat_Per,0)>0 And Nvl(G_Clc_Vat_Price_Typ,0) = 2 Then
            V_I_Price_Vat := Case when nvl(P_I_Price_Vat,0) =0 Then Nvl (P_I_Price, 0) Else Nvl (P_I_Price_Vat, 0) End;   
            V_I_Price   := Nvl (V_I_Price_Vat, 0) / ( (Nvl (V_Vat_Per, 0) / 100) + 1);
          Else
             V_I_Price   := P_I_Price;
          End If;
   Else
          V_I_Price   := P_I_Price;
          V_Vat_Per   := P_Vat_Per;
   End If;
   --##------------------------------------------------------------------------------------------##--   
   --## CHK ITM DATA
   Gnr_Api_Pkg.Chk_Itm (P_Sys_No              => G_Sys_No
                       ,P_Sys_Typ             => 1 --##    P_SYS_TYP =  1 = SALE , 2= STOCKE ,3 = PURCHASE ,
                       ,P_Trns_Typ            => 1 --##.    (1=IN)(-1=OUT)
                       ,P_Doc_Type            => G_Doc_Typ
                       ,P_I_Code              => P_I_Code
                       ,P_Itm_Unt             => P_Itm_Unt
                       ,P_P_Size              => P_P_Size
                       ,P_I_Qty               => P_I_Qty
                       ,P_Free_Qty            => P_Free_Qty
                       ,P_Res_Qty             => P_I_Qty
                       ,P_I_Price             => V_I_Price
                       ,P_I_Price_Vat         => V_I_Price_Vat
                       ,P_Measur_Price        => Null
                       ,P_Lev_No              => P_Lev_No
                       ,P_Qt_Prm_Method       => Null
                       ,P_Qut_Prm_Price       => Null
                       ,P_Qt_Prm_Ser          => P_Qt_Prm_Ser
                       ,P_Dis_Per             => P_Dis_Per
                       ,P_Dis_Amt_Dtl         => P_Dis_Amt_Dtl
                       ,P_Dis_Amt_Dtl_Vat     => P_Dis_Amt_Dtl_Vat
                       ,P_Dis_Per2            => P_Dis_Per2
                       ,P_Dis_Amt_Dtl2        => P_Dis_Amt_Dtl2
                       ,P_Dis_Amt_Dtl2_Vat    => P_Dis_Amt_Dtl2_Vat
                       ,P_Dis_Per3            => P_Dis_Per3
                       ,P_Dis_Amt_Dtl3        => P_Dis_Amt_Dtl3
                       ,P_Dis_Amt_Dtl3_Vat    => P_Dis_Amt_Dtl3_Vat
                       ,P_Dis_Amt_Mst         => P_Dis_Amt_Mst
                       ,P_W_Code              => G_W_Code
                       ,P_Expire_Date         => P_Expire_Date
                       ,P_Batch_No            => P_Batch_No
                       ,P_Brn_No              => G_Brn_No
                       ,P_Doc_Date            => G_Doc_Date
                       ,P_Doc_Ser             => G_Doc_Ser                    
                       ,P_C_Code              => G_C_Code
                       ,P_Cur_Code            => G_Cur_Code
                       ,P_Ac_Rate             => G_Cur_Rate
                       ,P_Usr_No              => G_Ad_U_Id
                       ,P_Clc_Vat_Price_Typ   => Nvl (G_Clc_Vat_Price_Typ, 1)
                       ,P_Bill_Doc_Type       => G_Rt_Bill_Doc_Type
                       ,P_Stk_Cost            => Null
                       ,P_Chk_Avlqty_Flg      => G_Chk_Avlqty_Flg
                       ,P_Chk_Itm_Price       => G_Chk_Itm_Price --# 0 nocheck 1 check
                       ,P_Use_Vat             =>G_USE_VAT
                       ,P_Clc_Typ_No_Tax      =>G_Clc_Typ_No_Tax 
                       ,P_Lng_No              => G_Lng_No
                       ,P_Msg_Txt             => P_Msg_Txt
                       ,P_Pkg_Line            => P_Err_No
                       ,P_Pkg_Nm              => P_Pkg_Nm);

   If P_Msg_Txt Is Not Null Then
      Goto Rtn_Rslt;
   End If;

   V_P_Size         := Ias_Itm_Pkg.Get_Icode_Size_Unit (P_I_Code => P_I_Code, P_Itm_Unt => P_Itm_Unt);

   --##-------------------------------------------------------------------------------------------------------------------------------##--
    If Nvl(V_P_Size,0)=0 Then
             P_Err_No    := 20669;
             P_MSG_TXT :='P_Size=0 For I_Code='||p_i_code;
            Goto Rtn_Rslt;                                                      
     End If;
    --##-------------------------------------------------------------------------------------------------------------------------------##--
   --## SUB LDGR
    If G_Ar_Cst_Type = 2 Then
         G_Dtl_Cc_Code   := nvl(P_Cc_Code,G_Cc_Code);
      Else
         G_Dtl_Cc_Code   := G_Cc_Code;   
      End If;

      If G_Ar_Pj_Type = 2 Then
         G_Dtl_Pj_No   := nvl(P_Pj_No,G_Pj_No);
      Else
          G_Dtl_Pj_No   := G_Pj_No;
      End If;

      If G_Ar_Actv_Type = 2 Then
         G_Dtl_Actv_No   := nvl(P_Actv_No,G_Actv_No);
      Else
          G_Dtl_Actv_No   := G_Actv_No;         
      End If;

   Gnr_Api_Pkg.Chk_Sub_Ldgr (P_Sys_Typ     => 1
                            ,P_Sys_No      => G_Sys_No
                            ,P_Doc_Type    => G_Doc_Typ
                            ,P_Cst_Type    => G_Ar_Cst_Type
                            ,P_Pj_Type     => G_Ar_Pj_Type
                            ,P_Actv_Type   => G_Ar_Actv_Type
                            ,P_Cc_Code     => G_Dtl_Cc_Code
                            ,P_Pj_No       => G_Dtl_Pj_No
                            ,P_Actv_No     => G_Dtl_Actv_No
                            ,P_Rep_Code    => G_Rep_Code
                            ,P_A_Code      => G_A_Code
                            ,P_Chk_Ac_Cc   => 1
                            ,P_BILL_DOC_TYPE =>G_BILL_DOC_TYPE
                            ,P_C_CODE        =>G_C_CODE
                            ,P_P_Year        =>G_P_Year
                            ,P_Lng_No      => G_Lng_No
                            ,P_Msg_Txt     => P_Msg_Txt
                            ,P_Pkg_Line    => P_Err_No
                            ,P_Pkg_Nm      => P_Pkg_Nm);

   If P_Msg_Txt Is Not Null Then
      Goto Rtn_Rslt;
   End If;

   --##--------------------------------------------------------------------------------------------------------------------------------##--
   If P_Doc_Type_Ref Is Null And (P_Doc_No_Ref Is Not Null Or P_Doc_Ser_Ref Is Not Null) Then
      P_Err_No    := 20591;
      P_Msg_Txt   := 'Err. Data Send P_DOC_TYP_REF Is Null But (DOC_NO_REF , DOC_SER_REF ) IS NOT NULL , FOR  ITM_CODE = ' || P_I_Code;
      Goto Rtn_Rslt;
   Elsif P_Doc_Type_Ref Is Not Null And (P_Doc_No_Ref Is Null Or P_Doc_Ser_Ref Is Null) Then
      P_Err_No    := 20592;
      P_Msg_Txt   := 'Err. Data Send P_DOC_TYP_REF Is Not Null But (DOC_NO_REF , DOC_SER_REF  ) IS NULL , FOR  ITM_CODE = ' || P_I_Code;
      Goto Rtn_Rslt;
   End If;

   If P_Doc_Type_Ref Is Not Null Then
      Begin
         Select 1
           Into V_Cnt
           From Ias_Sys.Ias_Docjv_Type_Systems
          Where Doc_Type = P_Doc_Type_Ref And Rownum <= 1;
      Exception
         When Others Then
            V_Cnt   := 0;
      End;

      If V_Cnt = 0 Then
         P_Err_No    := 20593;
         P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 1171) || ' DOC_TYP_REF , FOR  ITM_CODE = ' || P_I_Code;
         Goto Rtn_Rslt;
      End If;
   End If;

   --##--------------------------------------------------------------------------------------------------------------------------------##--    
     V_Doc_Sequence_Si   := P_Doc_Sequence_Si;
     V_Si_Rcrd_No        := P_Si_Rcrd_No;
     Begin
          ARS_API_CHK_PKG.CHK_RETRN_BILL_INSTLL(P_SYS_NO    =>G_sys_no                              
                                       ,P_rep_code          =>G_rep_code
                                       ,P_c_code            =>G_c_code
                                       ,P_RT_BILL_DOC_TYPE  =>G_RT_BILL_DOC_TYPE
                                       ,P_Bill_Currency     =>G_Cur_Code
                                       ,P_W_code            =>G_W_code
                                       ,P_RT_BILL_DATE      =>G_doc_Date
                                       ,P_CLC_TYP_NO_TAX    =>G_CLC_TYP_NO_TAX
                                       ,P_p_year            =>G_p_year
                                       ,P_Prev_Year         =>G_Prev_Year
                                       ,P_Brn_Usr           => G_Brn_Usr                                                                                      
                                       ,P_Rt_Bill_Ser       =>G_doc_ser
                                       ,P_RT_Bill_No        => G_Doc_No                              
                                       ,P_Pst_Typ           =>G_Pst_Typ
                                       ,P_Bill_No           =>P_Bill_No
                                       ,P_Bill_Ser          =>P_Bill_Ser
                                       ,P_I_Code            =>P_I_Code
                                       ,P_P_Size            =>V_P_Size
                                       ,P_I_Qty             =>P_I_Qty
                                       ,P_Free_Qty          =>P_Free_Qty
                                       ,P_Expiredate        =>P_Expire_Date
                                       ,P_Batchno           =>P_Batch_no
                                       ,P_Doc_Sequence_Si   =>V_Doc_Sequence_Si
                                       ,P_Si_Rcrd_No        =>V_Si_Rcrd_No
                                       ,P_Brn_no            =>G_Brn_no
                                       ,P_Rtrn_From_Othr_Sman=>G_Rtrn_From_Othr_Sman                                     
                                       ,P_Usr_no            =>G_ad_u_id 
                                       ,P_Lng_No            =>G_Lng_No
                                       ,P_Msg_Txt           =>P_Msg_Txt
                                       ,P_Err_No            =>P_Err_No
                                       ,P_Pkg_Nm            =>P_Pkg_Nm);
     If P_Msg_Txt Is Not Null Then
          Goto Rtn_Rslt;
       End If;
   End ;  
--##--------------------------------------------------------------------------------------------------------------------------------##--                                         
   Begin
      V_Post_Code   := Get_Post_Code_Inv (P_Type => G_Item_Posting_Flag, P_I_Code => P_I_Code, P_W_Code => G_W_Code);
   Exception
      When Others Then
         Null;
   End;
   --##--------------------------------------------------------------------------------------------------------------------------------##--
   Begin
      Select Ias_Doc_Seq.Nextval Into V_Doc_Sequence From Dual;
   Exception
      When Others Then
         P_Msg_Txt   := 'Err. When Get DOC_SEQ' || Chr (10) || Sqlerrm;
         P_Err_No    := 20594;
         Goto Rtn_Rslt;
   End;  
   --##--------------------------------------------------------------------------------------------------------------------------------##--
   G_Rcrd_No        := Nvl (G_Rcrd_No, 0) + 1;
   P_Doc_Sequence:=V_Doc_Sequence;
   P_Rcrd_No     :=G_Rcrd_No;
   --##--------------------------------------------------------------------------------------------------------------------------------##--
   Begin
      If Nvl (G_Ad_U_Id, 0) <> 1 Then
         Select Allow_Enter_Zero_Cost
           Into V_Allow_Enter_Zero_Cost
           From Privilege_Fixed
          Where U_Id = G_Ad_U_Id And Rownum <= 1;
      End If;
   Exception
      When Others Then
         P_Msg_Txt   := 'Error When Select From Privilege_Fixed In Post_Rt_Sales_Detail' || Chr(10) || Sqlerrm;
         P_Err_No    := 20595;
         Goto Rtn_Rslt;
   End;
   --##--------------------------------------------------------------------------------------------------------------------------------##--
   Select Service_Itm, Use_Serialno, Used_Itm
     Into V_Service_Itm, V_Use_Serialno, V_Used_Itm
     From Ias_Itm_Mst
    Where I_Code = P_I_Code And Rownum <= 1;

   --##--------------------------------------------------------------------------------------------------------------------------------##--
   If G_Costing_Type = 2 Then -- WtAvrg
      V_Stkcost   := Ias_Itm_Pkg.Get_Grand_Wtavg (P_Wtavg_Type => G_Wtavg_Type, P_Icode => P_I_Code, P_Wcode => G_W_Code) * Nvl (V_P_Size, 1);
      If G_Costing_Type = 2 And G_Wtavg_Type In (2, 3) Then
         If Nvl (V_Stkcost, 0) = 0 Then
            Begin
               Select W_Code
                 Into V_Wcode
                 From Warehouse_Details
                Where Nvl (Main_Wcode, 0) = 1;
            Exception
               When Others Then
                  V_Wcode   := Null;
            End;

            If V_Wcode Is Not Null Then
               V_Stkcost   := Ias_Itm_Pkg.Get_Grand_Wtavg (P_Wtavg_Type => G_Wtavg_Type, P_Icode => P_I_Code, P_Wcode => V_Wcode) * Nvl (V_P_Size, 1);
            End If;
         End If;
      End If;
   Else -- FIFO
      V_Stkcost      :=
           Last_Incoming_Price (P_Wtavg_Type   => G_Wtavg_Type
                               ,P_Icode        => P_I_Code
                               ,P_Psize        => V_P_Size
                               ,P_Wcode        => G_W_Code
                               ,P_Type         => 1)
         * Nvl (V_P_Size, 1);
   End If;
   -------------------------------------------------------------------------------------------
    --## Update Doc Ref
            Update_Doc_Ref    ( P_Doc_Type           =>G_Doc_Typ
                               ,P_Pst_Typ            =>G_Pst_Typ
                               ,P_Doc_Ser            =>G_Doc_Ser
                               ,P_I_Code             =>P_I_Code
                               ,P_Itm_Unt            =>P_Itm_Unt
                               ,P_P_Size             =>V_P_Size
                               ,P_I_Qty              => P_I_Qty
                               ,P_Free_Qty           =>P_Free_Qty
                               ,P_Rcrd_No            =>G_Rcrd_No
                               ,P_Doc_Type_Ref       =>P_Doc_Type_Ref
                               ,P_Doc_No_Ref         =>P_Doc_No_Ref
                               ,P_Doc_Ser_Ref        =>P_Doc_Ser_Ref
                               ,P_Rcrd_No_Ref        =>P_Rcrd_No_Ref
                               ,P_Msg_Txt            =>P_Msg_Txt
                               ,P_Err_No              =>P_Err_No
                               ,P_Pkg_Nm              =>P_Pkg_Nm);
      If P_Msg_Txt Is Not Null Then
         Goto Rtn_Rslt;
      End If;
  --##--------------------------------------------------------------------------------------------------------------------------------##--        
      Begin
         Insert Into Ias_Rt_Bill_Dtl_RQ (Rt_Bill_No
                                     ,Rt_Bill_Ser
                                     ,Rt_Bill_Doc_Type
                                     ,I_Code
                                     ,I_Qty
                                     ,P_Size
                                     ,Itm_Unt
                                     ,P_Qty
                                     ,I_Price
                                     ,I_Price_Vat
                                     ,Stk_Cost
                                     ,W_Code
                                     ,Bill_No
                                     ,Bill_Doc_Type
                                     ,Bill_Ser
                                     ,Cc_Code
                                     ,Pj_No
                                     ,Actv_No
                                     ,Expire_Date
                                     ,Batch_No
                                     ,Free_Qty
                                     ,Dis_Per
                                     ,Dis_Per2
                                     ,Dis_Per3
                                     ,Dis_Amt
                                     ,Dis_Amt_Mst
                                     ,Dis_Amt_Dtl
                                     ,Dis_Amt_Dtl2
                                     ,Dis_Amt_Dtl3
                                     ,Vat_Per
                                     ,Vat_Amt
                                     ,Othr_Amt
                                     ,Vat_Amt_Othr
                                     ,Othr_Amt_Disc
                                     ,Dis_Aftr_Vat_Mst
                                     ,Dis_Amt_Mst_Vat
                                     ,Vat_Amt_Dis_Dtl_Vat
                                     ,Vat_Amt_Aftr_Dis
                                     ,Vat_Amt_Bfr_Dis
                                     ,Dis_Amt_Dtl_Vat
                                     ,Dis_Amt_Dtl2_Vat
                                     ,Dis_Amt_Dtl3_Vat
                                     ,Vat_Amt_Dis_Mst_Vat
                                     ,Vat_Amt_Dis_Dtl2_Vat
                                     ,Vat_Amt_Dis_Dtl3_Vat
                                     ,Dis_Amt_Aftr_Vat
                                     ,Item_Desc
                                     ,Barcode
                                     ,Field_Dtl1
                                     ,Field_Dtl2
                                     ,Field_Dtl3
                                     ,Emp_No
                                     ,Doc_Type_Ref
                                     ,Doc_No_Ref
                                     ,Doc_Ser_Ref
                                     ,Sub_C_Code
                                     --,Rcrd_No_Ref
                                    -- ,Qt_Prm_No
                                   --  ,Qt_Prm_Ser
                                    -- ,Qt_Prm_Rcrd_No
                                     ,I_Length
                                     ,I_Width
                                     ,I_Height
                                     ,I_Number
                                     ,Wt_Qty
                                     ,Wt_Unt
                                     ,Argmnt_No
                                     ,Si_Rcrd_No
                                     ,Doc_Sequence_Si
                                     ,External_Post
                                     ,Post_Code
                                     ,Sr_Type
                                     ,Cmp_No
                                     ,Brn_No
                                     ,Brn_Year
                                     ,Brn_Usr
                                     ,Rcrd_No
                                     ,Doc_Sequence
                                     ,Lev_No
                                    )
              Values (G_Doc_No
                     ,G_Doc_Ser
                     ,G_Rt_Bill_Doc_Type
                     ,P_I_Code
                     ,P_I_Qty
                     ,V_P_Size
                     ,P_Itm_Unt
                     , (P_I_Qty * V_P_Size)
                     ,V_I_Price
                     ,V_I_Price_Vat
                     ,V_Stkcost
                     ,G_W_Code
                     ,P_Bill_No
                     ,P_Bill_Doc_Type
                     ,P_Bill_Ser
                     ,G_Dtl_Cc_Code
                     ,G_Dtl_Pj_No
                     ,G_Dtl_Actv_No
                     ,Nvl (P_Expire_Date, '01/01/1900')
                     ,Nvl (P_Batch_No, '0')
                     ,P_Free_Qty
                     ,P_Dis_Per
                     ,P_Dis_Per2
                     ,P_Dis_Per3
                     ,P_Dis_Amt
                     ,P_Dis_Amt_Mst
                     ,P_Dis_Amt_Dtl
                     ,P_Dis_Amt_Dtl2
                     ,P_Dis_Amt_Dtl3
                     ,V_Vat_Per
                     ,P_Vat_Amt
                     ,P_Othr_Amt
                     ,P_Vat_Amt_Othr
                     ,P_Othr_Amt_Disc
                     ,P_Dis_Aftr_Vat_Mst
                     ,P_Dis_Amt_Mst_Vat
                     ,P_Vat_Amt_Dis_Dtl_Vat
                     ,P_Vat_Amt_Aftr_Dis
                     ,P_Vat_Amt_Bfr_Dis
                     ,P_Dis_Amt_Dtl_Vat
                     ,P_Dis_Amt_Dtl2_Vat
                     ,P_Dis_Amt_Dtl3_Vat
                     ,P_Vat_Amt_Dis_Mst_Vat
                     ,P_Vat_Amt_Dis_Dtl2_Vat
                     ,P_Vat_Amt_Dis_Dtl3_Vat
                     ,P_Dis_Amt_Aftr_Vat
                     ,P_Item_Desc
                     ,P_Barcode
                     ,P_Field_Dtl1
                     ,P_Field_Dtl2
                     ,P_Field_Dtl3
                     ,P_Emp_No
                     ,P_Doc_Type_Ref
                     ,P_Doc_No_Ref
                     ,P_Doc_Ser_Ref
                     ,P_Sub_C_Code
                   --  ,P_Rcrd_No_Ref
                   --  ,P_Qt_Prm_No
                     --,P_Qt_Prm_Ser
                    -- ,P_Qt_Prm_Rcrd_No
                     ,P_I_Length
                     ,P_I_Width
                     ,P_I_Height
                     ,P_I_Number
                     ,P_Wt_Qty
                     ,P_Wt_Unt
                     ,P_Argmnt_No
                     ,V_Si_Rcrd_No
                     ,V_Doc_Sequence_Si
                     ,G_External_Post
                     ,V_Post_Code
                     ,G_Sr_Type
                     ,G_Cmp_No
                     ,G_Brn_No
                     ,G_Brn_Year
                     ,G_Brn_Usr
                     ,G_Rcrd_No
                     ,V_Doc_Sequence
                     ,P_Lev_No
                   );
      Exception
         When Others Then
            P_Msg_Txt   := 'Error When Insert Into IAS_RT_BILL_DTL_RQ' || Chr (10) || Sqlerrm;
            P_Err_No    := 20596;
            P_Pkg_Nm    := 'Ars_Api_Trns_Pkg.INSRT_IAS_RT_BILL_DTL_RQ';
            Goto Rtn_Rslt;
      End;     
  ------------------------------------------------------------------------------
        If Nvl(G_Use_Serialno,0) <> 0 AND NVL(V_Use_Serialno,0)=1 Then
               --## Insert Serialno   
               IF P_Serialno_N IS NULL THEN
                    P_Err_No    := 20597;
                    P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 322) ||CHR(10)|| ' I_CODE = ' || P_I_Code;
                    Goto Rtn_Rslt; 
               END IF;
                                    
                           
         End If;
  --####################--
  <<RTN_RSLT>>
   If P_Msg_Txt Is Not Null OR P_Err_No Is Not Null Then
      Rollback;
      P_Msg_Txt   := NVL(P_Msg_Txt,'Message Number Is Missing');
      P_Err_No    := P_Err_No;
      P_Pkg_Nm    := Nvl (P_Pkg_Nm, 'Ars_Api_Trns_Pkg.Insrt_Ias_Rt_Bill_Dtl_RQ');
      Return;
   Else
      P_Msg_Txt   := Null;
      P_Err_No    := Null;
      P_Pkg_Nm    := Null;
   End If;
--####################--
Exception
   When Others Then
      Rollback;
      P_Msg_Txt   := 'Error When Insert Into  Ias_Rt_Bill_Dtl_RQ'  || Chr(10) || Sqlerrm;
      P_Err_No    := 20598;
      P_Pkg_Nm    := 'Ars_Api_Trns_Pkg.Insrt_Ias_Rt_Bill_Dtl_RQ';
End Insrt_Ias_Rt_Bill_Dtl_RQ;
--##-----------------------------------------------------------------------------------------------------##--  
  Procedure Get_Doc_No (P_Doc_Typ   In     Number
                     ,P_Msg_Txt      Out Varchar2
                     ,P_Err_No       Out Varchar2
                     ,P_Pkg_Nm       Out Varchar2)
Is
   V_Msgs_No         Number := Null;  
   V_Doc_Type        Number;
   V_Dts_Doc_Type    Number;
   V_Bill_Doc_Type   Number;
   V_Typ_No          Number;
Begin
   If P_Doc_Typ = 53 Then
      V_Doc_Type        := 53;
      V_Dts_Doc_Type    := 2;
      V_Bill_Doc_Type   := G_Bill_Doc_Type;
      V_Typ_No          := G_So_Type;
   ELSIf P_Doc_Typ = 52 Then
      V_Doc_Type        := 52;
      V_Dts_Doc_Type    := 1;
      V_Bill_Doc_Type   := G_Bill_Doc_Type;
      V_Typ_No          := G_QT_Type;
   ELSIf P_Doc_Typ = 136 Then
      V_Doc_Type        := 136;
      V_Dts_Doc_Type    := 9;
      V_Bill_Doc_Type   := G_RT_Bill_Doc_Type;
      V_Typ_No          := G_SR_Type;   
   Elsif P_Doc_Typ = 4 Then
      V_Doc_Type        := 4;
      V_Dts_Doc_Type    := 3;
      V_Bill_Doc_Type   := G_Bill_Doc_Type;
      V_Typ_No          := G_Si_Type;
   Elsif P_Doc_Typ = 5 Then
      V_Doc_Type        := 5;
      V_Dts_Doc_Type    := 4;
      V_Bill_Doc_Type   := G_Rt_Bill_Doc_Type;
      V_Typ_No          := G_Sr_Type;
   End If;

   -----------------------------------------------------------
   If G_Sys_No = 70 Then
      Begin
         Execute Immediate ' SELECT  Get_Dts_Trans_Ser( P_Doc_Type      =>' || V_Dts_Doc_Type || ',                                                        
                                                      P_Year            =>' || G_Brn_Year || ', 
                                                      P_Brn_No          =>' || G_Brn_No || ' ,
                                                      P_Typ_No          =>' || V_Typ_No || ',
                                                      P_Bill_doc_Type   =>' || V_Bill_Doc_Type || ' ,                                                       
                                                      P_Sman            =>'''|| G_Rep_Code ||''',
                                                      P_Doc_No          =>Null,
                                                      P_No_Srl          => 1  ,
                                                      P_W_CODE          =>'''||G_W_Code||''',
                                                      P_CC_CODE         => '''||G_Cc_Code||''',
                                                      P_Usr_No          => '||G_ad_u_id||',
                                                      P_Trmnl_No        =>Null      ) FROM DUAL ' Into G_Doc_No;
      Exception
         When Others Then
            P_Msg_Txt   := 'Err. When GENERT DOC_NO' || Chr(10) || Sqlerrm;
            P_Err_No    := 20388;
            P_Pkg_Nm    := 'Get_Dts_Trans_Ser';
            Goto Rtn_Rslt;
      End;
   Else
      Begin
         G_Doc_No      :=
            Ar_Doc_Sq_Pkg.Get_Doc_No (P_Doc_Typ    => V_Doc_Type
                                     ,P_Pay_Typ    => V_Bill_Doc_Type
                                     ,P_Brn_Year   => G_Brn_Year
                                     ,P_Brn_No     => G_Brn_No
                                     ,P_Cc_Code    => G_Cc_Code
                                     ,P_W_Code     => G_W_Code
                                     ,P_Typ_No     => V_Typ_No
                                     ,P_Sys_No     => G_Sys_No
                                     ,P_Usr_No     => G_ad_u_id
                                     ,P_Trmnl_No   => null );
      Exception
         When Others Then
            P_Msg_Txt   := 'Err. When GENERT DOC_NO' || Chr(10) || Sqlerrm;
            P_Err_No    := 20389;
            P_Pkg_Nm    := 'AR_DOC_SQ_PKG.GET_DOC_NO';
            Goto Rtn_Rslt;
      End;
   End If;

  -----------------------------------------------------------
  --####################--
  <<RTN_RSLT>>
   If P_Msg_Txt Is Not Null OR P_Err_No Is Not Null Then
      P_Msg_Txt   := NVL(P_Msg_Txt,'Message Number Is Missing');
      P_Err_No    := P_Err_No;
      P_Pkg_Nm    := Nvl (P_Pkg_Nm, 'Ars_Api_Trns_Pkg.Get_Doc_No');
      Return;
   Else
      P_Msg_Txt   := Null;
      P_Err_No    := Null;
      P_Pkg_Nm    := Null;
   End If;
--####################--
Exception
   When Others Then
      P_Msg_Txt   := 'Err. When GENERT DOC_NO' || Chr(10) || Sqlerrm;
      P_Err_No    := 20350;
      P_Pkg_Nm    := 'AR_DOC_SQ_PKG.GET_DOC_NO';
End Get_Doc_No;

   --##-----------------------------------------------------------------------------------------------------##--
  Procedure Get_Doc_Ser (P_Doc_Typ   In     Number
                      ,P_Msg_Txt      Out Varchar2
                      ,P_Err_No       Out Varchar2
                      ,P_Pkg_Nm       Out Varchar2)
Is
   V_Msgs_No         Number := Null;
   V_Doc_Type        Number;
   V_Dts_Doc_Type    Number;
   V_Bill_Doc_Type   Number;
   V_Typ_No          Number;
Begin
   If P_Doc_Typ = 53 Then
      V_Doc_Type        := 53;
      V_Dts_Doc_Type    := 2;
      V_Bill_Doc_Type   := G_Bill_Doc_Type;
      V_Typ_No          := G_So_Type;
   ELSIf P_Doc_Typ = 52 Then
      V_Doc_Type        := 52;
      V_Dts_Doc_Type    := 1;
      V_Bill_Doc_Type   := G_Bill_Doc_Type;
      V_Typ_No          := G_QT_Type;   
   ELSIf P_Doc_Typ = 136 Then
      V_Doc_Type        := 136;
      V_Dts_Doc_Type    := 9;
      V_Bill_Doc_Type   := G_RT_Bill_Doc_Type;
      V_Typ_No          := G_SR_Type;      
   Elsif P_Doc_Typ = 4 Then
      V_Doc_Type        := 4;
      V_Dts_Doc_Type    := 3;
      V_Bill_Doc_Type   := G_Bill_Doc_Type;
      V_Typ_No          := G_Si_Type;
   Elsif P_Doc_Typ = 5 Then
      V_Doc_Type        := 5;
      V_Dts_Doc_Type    := 4;
      V_Bill_Doc_Type   := G_Rt_Bill_Doc_Type;
      V_Typ_No          := G_Sr_Type;
   End If;

   ------------------------------------------------------------
   If G_Sys_No = 70 Then
      Begin
         Execute Immediate ' SELECT  Get_Dts_Trans_Ser( P_Doc_Type       =>' || V_Dts_Doc_Type || ',                                                        
                                                          P_Year            =>' || G_Brn_Year || ', 
                                                          P_Brn_No          =>' || G_Brn_No || ' ,
                                                          P_Typ_No          =>' || V_Typ_No || ',
                                                          P_Bill_doc_Type   =>' || V_Bill_Doc_Type || ' ,                                                       
                                                          P_Sman            =>'''|| G_Rep_Code ||''',
                                                          P_Doc_No          =>' || G_Doc_No || ',
                                                          P_No_Srl          => 2 ,  
                                                          P_W_CODE          =>'''||G_W_Code||''',
                                                          P_CC_CODE         => '''||G_Cc_Code||''',
                                                          P_Usr_No          => '||G_ad_u_id||',
                                                          P_Trmnl_No         =>Null   ) FROM DUAL ' Into G_Doc_Ser;
      Exception
         When Others Then
            P_Msg_Txt   := 'Err. When GENERT DOC_SER' || Chr(10) || Sqlerrm;
            P_Err_No    := 20390;
            P_Pkg_Nm    := 'Get_Dts_Trans_Ser';
            Goto Rtn_Rslt;
      End;
   Else
      Begin
         G_Doc_Ser      :=
            Ar_Doc_Sq_Pkg.Get_Doc_Srl (P_Doc_Typ    => V_Doc_Type
                                      ,P_Pay_Typ    => V_Bill_Doc_Type
                                      ,P_Brn_Year   => G_Brn_Year
                                      ,P_Brn_No     => G_Brn_No
                                      ,P_Cc_Code    => G_Cc_Code
                                      ,P_W_Code     => G_W_Code
                                      ,P_Typ_No     => V_Typ_No
                                      ,P_Doc_No     => G_Doc_No
                                      ,P_Sys_No     => G_Sys_No
                                      ,P_Usr_No     => G_ad_u_id
                                      ,P_Trmnl_No   => null);
      Exception
         When Others Then
            P_Msg_Txt   := 'Err. When GENERT DOC_SER' || Chr(10) || Sqlerrm;
            P_Err_No    := 20391;
            P_Pkg_Nm    := 'AR_DOC_SQ_PKG.GET_DOC_SRL';
            Goto Rtn_Rslt;
      End;
   End If;
  ------------------------------------------------------------
  --####################--
  <<RTN_RSLT>>
   If P_Msg_Txt Is Not Null OR P_Err_No Is Not Null Then
      P_Msg_Txt   := NVL(P_Msg_Txt,'Message Number Is Missing');
      P_Err_No    := P_Err_No;
      P_Pkg_Nm    := Nvl (P_Pkg_Nm, 'Ars_Api_Trns_Pkg.Get_Doc_Ser');
      Return;
   Else
      P_Msg_Txt   := Null;
      P_Err_No    := Null;
      P_Pkg_Nm    := Null;
   End If;
--####################--
Exception
   When Others Then
      P_Msg_Txt   := 'Err. When GENERT DOC_SER' || Chr(10) || Sqlerrm;
      P_Err_No    := 20351;
      P_Pkg_Nm    := 'Ars_Api_Trns_Pkg.Get_Doc_Ser';
End Get_Doc_Ser;

   --##-----------------------------------------------------------------------------------------------------##--
  Procedure Check_Duplicate (P_Doc_Typ   In     Number
                          ,P_Doc_No    In     Ias_Post_Mst.Doc_No%Type
                          ,P_Msg_Txt      Out Varchar2
                          ,P_Err_No       Out Varchar2
                          ,P_Pkg_Nm       Out Varchar2)
Is
   V_Cnt             Number;
   V_Msg_No          Number;
   V_Doc_Type        Number;
   V_Bill_Doc_Type   Number;
   V_Typ_No          Number;
Begin
   If P_Doc_Typ Is Null Then
      P_Err_No    := 20149;
      P_Msg_Txt   := 'DOC_TYP IS NULL';
      Goto Rtn_Rslt;
   End If;

   If P_Doc_No Is Null Then
      P_Err_No    := 20150;
      P_Msg_Txt   := 'DOC_NO IS NULL';
      Goto Rtn_Rslt;
   End If;

   -----------------------------------------------------
   If P_Doc_Typ = 53 Then
      V_Doc_Type        := 53;
      V_Bill_Doc_Type   := G_Bill_Doc_Type;
      V_Typ_No          := G_So_Type;
   ELSIf P_Doc_Typ = 52 Then
      V_Doc_Type        := 52;
      V_Bill_Doc_Type   := G_Bill_Doc_Type;
      V_Typ_No          := G_QT_Type;   
   Elsif P_Doc_Typ = 4 Then
      V_Doc_Type        := 4;
      V_Bill_Doc_Type   := G_Bill_Doc_Type;
      V_Typ_No          := G_Si_Type;
   Elsif P_Doc_Typ = 5 Then
      V_Doc_Type        := 5;
      V_Bill_Doc_Type   := G_Rt_Bill_Doc_Type;
      V_Typ_No          := G_Sr_Type;
   Elsif P_Doc_Typ = 136 Then
      V_Doc_Type        := 136;
      V_Bill_Doc_Type   := G_Rt_Bill_Doc_Type;
      V_Typ_No          := G_Sr_Type;      
   End If;
   -----------------------------------------------------
   If G_Doc_Ser Is Null Then
      P_Err_No    := 20096;
      P_Msg_Txt   := ' DOC_SER IS NULL ';
      Goto Rtn_Rslt;
   End If;
   -------------------------------------------------
  ARS_API_CHK_PKG.Check_Duplicate (  P_Sys_No       =>G_Sys_No, 
                                      P_DOC_TYP      =>V_Doc_Type,
                                      P_Pst_Typ       =>G_Pst_Typ,
                                      P_Doc_Ser       =>G_Doc_Ser,  
                                      P_Bill_Doc_Type  =>V_Bill_Doc_Type,      
                                      P_BRN_YEAR      =>G_Brn_Year,
                                      P_BRN_NO        =>G_Brn_No ,
                                      P_CC_CODE      =>G_Cc_Code,
                                      P_W_CODE        =>G_W_Code,
                                      P_TYP_NO       =>V_Typ_No,
                                      P_DOC_NO        =>G_Doc_No  ,                           
                                      P_Usr_No      =>G_AD_U_ID,
                                      P_Trmnl_No     => Null,
                                      P_Lng_No     =>G_Lng_No,                       
                                      P_Msg_Txt   =>P_Msg_Txt,
                                      P_Err_No      =>P_Err_No,
                                      P_Pkg_Nm      =>P_Pkg_Nm);
    If P_Msg_Txt Is Not Null Then
      Goto Rtn_Rslt;
    End If;                                        
  -----------------------------------------------------
  --####################--
  <<RTN_RSLT>>
   If P_Msg_Txt Is Not Null OR P_Err_No Is Not Null Then
      P_Msg_Txt   := NVL(P_Msg_Txt,'Message Number Is Missing');
      P_Err_No    := P_Err_No;
      P_Pkg_Nm    := Nvl (P_Pkg_Nm, 'ARS_API_TRNS_PKG.Check_Duplicate');
   Else
      P_Msg_Txt   := Null;
      P_Err_No    := Null;
      P_Pkg_Nm    := Null;
   End If; 
   --####################--
Exception
   When Others Then
       P_Msg_Txt   := 'Error IN Check_Duplicate' || Chr(10) || Sqlerrm;
       P_Err_No    := 20352;
       P_Pkg_Nm    := 'ARS_API_TRNS_PKG.Check_Duplicate';      
End Check_Duplicate;
   --##-----------------------------------------------------------------------------------------------------##--
   Procedure Chk_Accnt (P_Cur_Code        In     Ex_Rate.Cur_Code%Type
                       ,P_Cur_Rate        In     Ex_Rate.Cur_Rate%Type Default Null
                       ,P_Stk_Rate        In     Ex_Rate.Cur_Rate%Type Default Null
                       ,P_Cash_No         In     Cash_In_Hand.Cash_No%Type Default Null
                       ,P_Bank_No         In     Cash_At_Bank.Bank_No%Type Default Null
                       ,P_C_Code          In     Customer.C_Code%Type Default Null
                       ,P_Ac_Code         In     Ias_Post_Dtl.A_Code%Type Default Null
                       ,P_Ac_Code_Dtl     In     Ias_Post_Dtl.Ac_Code_Dtl%Type Default Null
                       ,P_Ac_Dtl_Typ      In     Ias_Post_Dtl.Ac_Dtl_Typ%Type Default Null
                       ,P_V_Code          In     V_Details.V_Code%Type Default Null
                       ,P_Bill_Doc_Type   In     Ias_Bill_Mst.Bill_Doc_Type%Type Default Null
                       ,P_Doc_Amt         In     Number Default Null
                       ,P_Msg_Txt         Out Varchar2
                       ,P_ERR_NO        Out Varchar2
                       ,P_Pkg_NM       Out Varchar2)
   Is
      V_Msg_No     Number;
      V_Cnt        Number;     
      V_Ac_Dtl_Typ NUMBER(5);
      V_C_cc_code  cost_centers.cc_code%type;
      V_Rep_cc_code  cost_centers.cc_code%type;     
   Begin
      ------------------------------------------------------------------------------------------


      If P_Bill_Doc_Type Is Null Then
         P_Err_No := 20152;
         P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 886);
         Goto Rtn_Rslt;
      Else
         Begin
            Select 1
              Into V_Cnt
              From S_Flags
             Where Flg_Code = 'TYPE_NAME_SI' And Flg_Value = Nvl (P_Bill_Doc_Type, 0) And Rownum <= 1;
         Exception
            When Others Then
               V_Cnt := 0;
         End;

         If Nvl (V_Cnt, 0) = 0 Then
            P_Err_No := 20153;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 886);
            Goto Rtn_Rslt;
         End If;
      End If;


      If G_Doc_Typ IN(52,53 ) Then
         If Nvl (P_Bill_Doc_Type, 0) = 4 And P_C_Code Is Null Then
            P_Err_No := 20154;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 411);
            Goto Rtn_Rslt;
         End If;
      Else
         If Nvl (P_Bill_Doc_Type, 0) = 1 And P_Cash_No Is Null Then
            P_Err_No := 20155;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 965);
            Goto Rtn_Rslt;
         Elsif Nvl (P_Bill_Doc_Type, 0) IN( 2,6,5) And P_Bank_No Is Null Then
            P_Err_No := 20156;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 265);
            Goto Rtn_Rslt;
         Elsif Nvl (P_Bill_Doc_Type, 0) = 4 And P_C_Code Is Null Then
            P_Err_No := 20157;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 411);
            Goto Rtn_Rslt;          
         Elsif Nvl (P_Bill_Doc_Type, 0) = 8 And P_Ac_Code Is Null Then
            P_Err_No := 20158;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 84);
            Goto Rtn_Rslt;
         End If;
      End If;

      --- G_BILL_DOC_TYPE:=P_BILL_DOC_TYPE;
      ------------------------------------------------------------------------------------------
      If P_Msg_Txt Is Null Then
         If P_Ac_Code Is Null And P_Ac_Code_Dtl Is Not Null Then
            P_Err_No := 20159;
            P_Msg_Txt := 'P_AC_CODE_DTL IS NOT NULL BUT P_AC_CODE IS NULL , ';
            Goto Rtn_Rslt;
         Elsif P_Ac_Code Is Not Null And P_Ac_Code_Dtl Is Null And Nvl (P_Ac_Dtl_Typ, 0) <> 0 Then
            P_Err_No := 20160;
            P_Msg_Txt := 'P_AC_CODE_DTL IS NULL AND P_AC_DTL_TYP <>  0 ,';
            Goto Rtn_Rslt;
         Elsif P_Ac_Code Is Not Null And P_Ac_Code_Dtl Is Not Null And Nvl (P_Ac_Dtl_Typ, 0) = 0 Then
            P_Err_No := 20161;
            P_Msg_Txt := 'P_AC_CODE_DTL IS NOT NULL AND P_AC_DTL_TYP = 0 ,';
            Goto Rtn_Rslt;        
         End If;

         If P_Ac_Code Is Not Null And P_Ac_Code_Dtl Is Not Null Then
            If Nvl (P_Ac_Dtl_Typ, 0) <> Ys_Ac_Dtl_Pkg.Get_Ac_Dtl_Typ (P_Ac_Code) Then
               P_Err_No := 20162;
               P_Msg_Txt := 'P_AC_CODE_DTL IS NOT NULL , BUT P_AC_DTL_TYP IS NOT CORRECT FOR THIS AC_CODE ,';
               Goto Rtn_Rslt;
            End If;
         End If;
         If P_C_Code Is Not Null Then           
         GNR_API_PKG.Chk_Inpt_Data (P_Inpt_Typ     => 'C_CODE'
                                   ,P_SYS_TYP      =>1
                                   ,P_DOC_TYPE     => G_DOC_TYP
                                   ,P_Inpt_Code1   => P_C_Code
                                   ,P_Lng_Dflt     => G_Lng_Dflt
                                   ,P_Inpt_Nm      => G_Inpt_Nm
                                   ,P_Msg_No       => V_Msg_No);            

            If V_Msg_No Is Not Null Then
               P_Err_No := 20163;
               P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No);
               Goto Rtn_Rslt;
            End If;
         End If;

         If P_Cash_No Is Not Null Then            
            GNR_API_PKG.Chk_Inpt_Data (P_Inpt_Typ     => 'CASH_NO'
                                       ,P_SYS_TYP      =>1
                                       ,P_DOC_TYPE     => G_DOC_TYP
                                       ,P_Inpt_Code1   => P_Cash_No
                                       ,P_Inpt_Code2   => G_Brn_no
                                       ,P_Lng_Dflt     => G_Lng_Dflt
                                       ,P_Inpt_Nm      => G_Inpt_Nm
                                       ,P_Msg_No       => V_Msg_No);               

            If V_Msg_No Is Not Null Then
               P_Err_No := 20164;
               P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No);
               Goto Rtn_Rslt;
            End If;
         End If;

         If P_Bank_No Is Not Null Then           
             GNR_API_PKG.Chk_Inpt_Data (P_Inpt_Typ     => 'BANK_NO'
                                       ,P_SYS_TYP      =>1
                                       ,P_DOC_TYPE     => G_DOC_TYP
                                       ,P_Inpt_Code1   => P_Bank_No
                                       ,P_Lng_Dflt     => G_Lng_Dflt
                                       ,P_Inpt_Nm      => G_Inpt_Nm
                                       ,P_Msg_No       => V_Msg_No);              

            If V_Msg_No Is Not Null Then
               P_Err_No := 20165;
               P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No);
               Goto Rtn_Rslt;
            End If;
         End If;

         If P_V_Code Is Not Null Then           
            GNR_API_PKG.Chk_Inpt_Data (P_Inpt_Typ     => 'V_CODE'
                                       ,P_SYS_TYP      =>1
                                       ,P_DOC_TYPE     => G_DOC_TYP
                                       ,P_Inpt_Code1   => P_V_Code
                                       ,P_Lng_Dflt     => G_Lng_Dflt
                                       ,P_Inpt_Nm      => G_Inpt_Nm
                                       ,P_Msg_No       => V_Msg_No);              

            If V_Msg_No Is Not Null Then
               P_Err_No := 20166;
               P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No);
               Goto Rtn_Rslt;
            End If;
         End If;
         -----------------------------------------------------------------------------
         If P_Cash_No Is Not Null Then
            G_Ac_Code_Csh := Ys_Ac_Dtl_Pkg.Get_Ac_Dtl_Acode (P_Ac_Code_Dtl => P_Cash_No, P_Ac_Dtl_Typ => 1);

            If G_Ac_Code_Csh Is Null Then
               P_Err_No := 20167;
               P_Msg_Txt := 'P_CASH_NO IS NOT NULL BUT G_AC_CODE_CSH IS NULL  ,';
               Goto Rtn_Rslt;
            End If;
         End If;

         If P_Bank_No Is Not Null Then
            G_Ac_Code_Bnk := Ys_Ac_Dtl_Pkg.Get_Ac_Dtl_Acode (P_Ac_Code_Dtl => P_Bank_No, P_Ac_Dtl_Typ => 2);
            If G_Ac_Code_Bnk Is Null Then
               P_Err_No := 20168;
               P_Msg_Txt := 'P_BANK_NO IS NOT NULL BUT G_AC_CODE_BNK IS NULL ';
               Goto Rtn_Rslt;
            End If;
         End If;

         If P_C_Code Is Not Null Then
            G_Ac_Code_Cst := Ys_Ac_Dtl_Pkg.Get_Ac_Dtl_Acode (P_Ac_Code_Dtl => P_C_Code, P_Ac_Dtl_Typ => 3);
            If G_Ac_Code_Cst Is Null Then
               P_Err_No := 20169;
               P_Msg_Txt := 'P_C_CODE IS NOT NULL BUT G_AC_CODE_CST IS NULL  ,';
               Goto Rtn_Rslt;
            End If;
         End If;

         If P_V_Code Is Not Null Then
            G_Ac_Code_Vnd := Ys_Ac_Dtl_Pkg.Get_Ac_Dtl_Acode (P_Ac_Code_Dtl => P_Cash_No, P_Ac_Dtl_Typ => 4);

            If G_Ac_Code_Vnd Is Null Then
               P_Err_No := 20170;
               P_Msg_Txt := 'P_V_CODE IS NOT NULL BUT G_AC_CODE_VND IS NULL  ,';
               Goto Rtn_Rslt;
            End If;
         End If;
         ---------------------------------------------------------------------------------
         If G_Ac_Code_Csh Is Not Null And P_Cash_No Is Not Null And Nvl (P_Bill_Doc_Type, 0) = 1 Then            
                 Begin 
                    V_Ac_Dtl_Typ:=1;                             
                    Ys_Ac_Dtl_Pkg.Chk_Ac_Dtl (P_Ac_Code_Dtl   => P_Cash_No
                                             ,P_Ac_Code       => G_Ac_Code_Csh
                                             ,P_Ac_Dtl_Nm     => G_Inpt_Nm
                                             ,P_Ac_Dtl_Typ    => V_Ac_Dtl_Typ
                                             ,P_Cur_Code      => P_CUR_CODE
                                             ,P_Ar_Flg        => 0
                                             ,P_Scr_Typ       => 3
                                             ,P_Aralt         => G_Aralt
                                             ,P_Apalt         => G_Apalt
                                             ,P_Doc_Date      => G_Doc_Date
                                             ,P_Usr_No        => G_Ad_U_Id
                                             ,P_Lng_No        => G_Lng_Dflt
                                             ,P_Msg_No        => V_Msg_No);
                 Exception
                    When Others Then
                       P_Err_No := 20171;
                       P_Msg_Txt := 'ERROR IN Ys_Ac_Dtl_Pkg.Chk_Ac_Dtl'||Chr(10)||SQLERRM;
                       Goto Rtn_Rslt;
                 End;
            If V_Msg_No Is Not Null Then
               P_Err_No := 20172;
               P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No);
               Goto Rtn_Rslt;
            End If;
         End If;

         If G_Ac_Code_Bnk Is Not Null And P_Bank_No Is Not Null And Nvl (P_Bill_Doc_Type, 0) IN(2,6,5) Then           
                 Begin   
                        V_Ac_Dtl_Typ:=2;                              
                        Ys_Ac_Dtl_Pkg.Chk_Ac_Dtl (P_Ac_Code_Dtl   => P_Bank_No
                                                 ,P_Ac_Code       => G_Ac_Code_Bnk
                                                 ,P_Ac_Dtl_Nm     => G_Inpt_Nm
                                                 ,P_Ac_Dtl_Typ    => V_Ac_Dtl_Typ
                                                 ,P_Cur_Code      => P_CUR_CODE
                                                 ,P_Ar_Flg        => 0
                                                 ,P_Scr_Typ       => 3
                                                 ,P_Aralt         => G_Aralt
                                                 ,P_Apalt         => G_Apalt
                                                 ,P_Doc_Date      => G_Doc_Date
                                                 ,P_Usr_No        => G_Ad_U_Id
                                                 ,P_Lng_No        => G_Lng_Dflt
                                                 ,P_Msg_No        => V_Msg_No);
                 Exception
                    When Others Then
                       P_Err_No := 20173;
                       P_Msg_Txt := 'ERROR IN Ys_Ac_Dtl_Pkg.Chk_Ac_Dtl'||Chr(10)||SQLERRM;
                       Goto Rtn_Rslt;
                 End;               

            If V_Msg_No Is Not Null Then
               P_Err_No := 20174;
               P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No);
               Goto Rtn_Rslt;
            End If;
         End If;

         If G_Ac_Code_Cst Is Not Null And P_C_Code Is Not Null And Nvl (P_Bill_Doc_Type, 0) = 4 Then          
                 Begin 
                        V_Ac_Dtl_Typ:=3;                             
                        Ys_Ac_Dtl_Pkg.Chk_Ac_Dtl (P_Ac_Code_Dtl   => P_C_Code
                                                 ,P_Ac_Code       => G_Ac_Code_Cst
                                                 ,P_Ac_Dtl_Nm     => G_Inpt_Nm
                                                 ,P_Ac_Dtl_Typ    => V_Ac_Dtl_Typ
                                                 ,P_Cur_Code      => P_CUR_CODE
                                                 ,P_Ar_Flg        => 0
                                                 ,P_Scr_Typ       => 3
                                                 ,P_Aralt         => G_Aralt
                                                 ,P_Apalt         => G_Apalt
                                                 ,P_Doc_Date      => G_Doc_Date
                                                 ,P_Usr_No        => G_Ad_U_Id
                                                 ,P_Lng_No        => G_Lng_Dflt
                                                 ,P_Msg_No        => V_Msg_No);
                 Exception
                    When Others Then
                       P_Err_No := 20175;
                       P_Msg_Txt := 'ERROR IN Ys_Ac_Dtl_Pkg.Chk_Ac_Dtl'||Chr(10)||SQLERRM;
                       Goto Rtn_Rslt;
                 End; 

            If V_Msg_No Is Not Null Then
               P_Err_No := 20176;
               P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No);
               Goto Rtn_Rslt;
            End If;
         End If;

         If G_Ac_Code_Vnd Is Not Null And P_V_Code Is Not Null Then           
             Begin  
                        V_Ac_Dtl_Typ:=4;                                 
                        Ys_Ac_Dtl_Pkg.Chk_Ac_Dtl (P_Ac_Code_Dtl   => P_V_Code
                                                 ,P_Ac_Code       => G_Ac_Code_Vnd
                                                 ,P_Ac_Dtl_Nm     => G_Inpt_Nm
                                                 ,P_Ac_Dtl_Typ    => V_Ac_Dtl_Typ
                                                 ,P_Cur_Code      => P_CUR_CODE
                                                 ,P_Ar_Flg        => 0
                                                 ,P_Scr_Typ       => 3
                                                 ,P_Aralt         => G_Aralt
                                                 ,P_Apalt         => G_Apalt
                                                 ,P_Doc_Date      => G_Doc_Date
                                                 ,P_Usr_No        => G_Ad_U_Id
                                                 ,P_Lng_No        => G_Lng_Dflt
                                                 ,P_Msg_No        => V_Msg_No);
             Exception
                When Others Then
                       P_Err_No := 20177;
                       P_Msg_Txt := 'ERROR IN Ys_Ac_Dtl_Pkg.Chk_Ac_Dtl'||Chr(10)||SQLERRM;
                       Goto Rtn_Rslt;
             End;            

            If V_Msg_No Is Not Null Then
               P_Err_No := 20178;
               P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No);
               Goto Rtn_Rslt;
            End If;
         End If;

         If P_Ac_Code Is Not Null Then
            If P_Ac_Code_Dtl Is Not Null And P_Ac_Dtl_Typ Is Not Null Then              
                 Begin
                    V_Ac_Dtl_Typ:=P_Ac_Dtl_Typ;                                        
                    Ys_Ac_Dtl_Pkg.Chk_Ac_Dtl (P_Ac_Code_Dtl   => P_Ac_Code_Dtl
                                             ,P_Ac_Code       => P_Ac_Code
                                             ,P_Ac_Dtl_Nm     => G_Inpt_Nm
                                             ,P_Ac_Dtl_Typ    => V_Ac_Dtl_Typ
                                             ,P_Cur_Code      => P_CUR_CODE
                                             ,P_Ar_Flg        => 0
                                             ,P_Scr_Typ       => 3
                                             ,P_Aralt         => G_Aralt
                                             ,P_Apalt         => G_Apalt
                                             ,P_Doc_Date      => G_Doc_Date
                                             ,P_Usr_No        => G_Ad_U_Id
                                             ,P_Lng_No        => G_Lng_Dflt
                                             ,P_Msg_No        => V_Msg_No);
                 Exception
                    When Others Then
                       P_Err_No := 20179;
                       P_Msg_Txt := 'ERROR IN Ys_Ac_Dtl_Pkg.Chk_Ac_Dtl'||Chr(10)||SQLERRM;
                       Goto Rtn_Rslt;
                 End;             

               If V_Msg_No Is Not Null Then
                  P_Err_No := 20180;
                  P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No);
                  Goto Rtn_Rslt;
               End If;           
            End If;
         End If;
      End If;

      --##-------------------------------------------------------------------------------------------------------------------------------##--
      --##CHK CURRENCY
      If P_Cash_No Is Not Null And Nvl (P_Bill_Doc_Type, 0) = 1 Then
         If Ys_Ac_Dtl_Pkg.Chk_Ac_Dtl_Acy (P_Ac_Code_Dtl => P_Cash_No, P_Ac_Dtl_Typ => 1, P_A_Cy => P_Cur_Code) = 0 And Nvl (P_Bill_Doc_Type, 0) = 1 Then
            P_Err_No := 20181;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 797) || '= ' || P_Cur_Code || ' ' || 'CASH_NO=' || P_Cash_No;
            Goto Rtn_Rslt;
         End If;
      End If;

      If P_Bank_No Is Not Null And Nvl (P_Bill_Doc_Type, 0) IN( 2,5,6) Then
         If Ys_Ac_Dtl_Pkg.Chk_Ac_Dtl_Acy (P_Ac_Code_Dtl => P_Bank_No, P_Ac_Dtl_Typ => 2, P_A_Cy => P_Cur_Code) = 0 And Nvl (P_Bill_Doc_Type, 0) = 2 Then
            P_Err_No := 20182;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 797) || '= ' || P_Cur_Code || ' ' || 'BANK_NO=' || P_Bank_No;
            Goto Rtn_Rslt;
         End If;
      End If;

      If P_C_Code Is Not Null Then
         If Ys_Ac_Dtl_Pkg.Chk_Ac_Dtl_Acy (P_Ac_Code_Dtl => P_C_Code, P_Ac_Dtl_Typ => 3, P_A_Cy => P_Cur_Code) = 0 And Nvl (P_Bill_Doc_Type, 0) = 4 Then
            P_Err_No := 20183;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 797) || '= ' || P_Cur_Code || ' ' || 'C_CODE=' || P_C_Code;
            Goto Rtn_Rslt;
         End If;
      End If;

      If P_V_Code Is Not Null Then
         If Ys_Ac_Dtl_Pkg.Chk_Ac_Dtl_Acy (P_Ac_Code_Dtl => P_V_Code, P_Ac_Dtl_Typ => 4, P_A_Cy => P_Cur_Code) = 0 And Nvl (P_Bill_Doc_Type, 0) = 4 Then
            P_Err_No := 20184;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 797) || '= ' || P_Cur_Code || ' ' || 'V_CODE=' || P_V_Code;
            Goto Rtn_Rslt;
         End If;
      End If;

      If P_Ac_Code Is Not Null Then
         If P_Ac_Code_Dtl Is Not Null Then           
                 V_Ac_Dtl_Typ:=P_Ac_Dtl_Typ;         
                 Begin                                     
                            Ys_Ac_Dtl_Pkg.Chk_Ac_Dtl (P_Ac_Code_Dtl   => P_Ac_Code_Dtl
                                                     ,P_Ac_Code       => P_Ac_Code
                                                     ,P_Ac_Dtl_Nm     => G_Inpt_Nm
                                                     ,P_Ac_Dtl_Typ    => V_Ac_Dtl_Typ
                                                     ,P_Cur_Code      => P_Cur_Code
                                                     ,P_Ar_Flg        => 0
                                                     ,P_Scr_Typ       => 3
                                                     ,P_Aralt         => G_Aralt
                                                     ,P_Apalt         => G_Apalt
                                                     ,P_Doc_Date      => G_Doc_Date
                                                     ,P_Usr_No        => G_Ad_U_Id
                                                     ,P_Lng_No        => G_Lng_Dflt
                                                     ,P_Msg_No        => V_Msg_No);
                 Exception
                    When Others Then
                       P_Err_No := 20185;
                       P_Msg_Txt := 'ERROR IN Ys_Ac_Dtl_Pkg.Chk_Ac_Dtl'||Chr(10)||SQLERRM;
                       Goto Rtn_Rslt;
                 End;          

            If V_Msg_No Is Not Null Then
               P_Err_No := 20186;
               P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No);
               Goto Rtn_Rslt;
            End If;
         End If;

         If Ias_Acode_Pkg.Check_Acy (P_A_Code => P_Ac_Code, P_A_Cy => P_Cur_Code) = 0 Then
            P_Err_No := 20187;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 797) || '= ' || P_Cur_Code || ' ' || 'AC_CODE=' || P_Ac_Code;
            Goto Rtn_Rslt;
         End If;
      End If;
      --##--------------------------------------------------------------------------------------------------------------------------##--
      --## CHK AMT
      If Nvl (P_Doc_Amt, 0) < 0 Then
         P_Err_No := 20188;
         P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 3312);
         Goto Rtn_Rslt;     
      End If;

      G_Doc_Amt := Nvl (P_Doc_Amt, 0);
      
      If Nvl (P_Bill_Doc_Type, 0) = 4 And P_C_Code Is Not Null Then
            G_A_Code := G_Ac_Code_Cst;
      End If;     
            
      If G_Doc_Typ In (4, 5) Then
         If Nvl (P_Bill_Doc_Type, 0) = 1 And P_Cash_No Is Not Null Then
            G_A_Code := G_Ac_Code_Csh;        
         Elsif Nvl (P_Bill_Doc_Type, 0) IN( 2,5,6) And P_Bank_No Is Not Null Then
            G_Cash_Ac_Fcc := G_Ac_Code_Bnk;
            G_A_Code := G_Ac_Code_Bnk; 
            G_Cash_No:= P_Bank_No;        
         Elsif Nvl (P_Bill_Doc_Type, 0) = 4 And P_C_Code Is Not Null Then
            G_A_Code := G_Ac_Code_Cst;
         Elsif Nvl (P_Bill_Doc_Type, 0) = 7 Then
            G_A_Code := Nvl(G_A_Code,p_Ac_code);   
         END IF; 
                    
         If Nvl (P_Bill_Doc_Type, 0) = 8 And P_Ac_Code Is Not Null Then
            G_Ac_Code := P_Ac_Code;
            G_Ac_Code_Dtl := P_Ac_Code_Dtl;
            G_Ac_Dtl_Typ := P_Ac_Dtl_Typ;
            G_A_Code:=G_Ac_Code;
         End If;
      End If;

      If G_Ac_Code_Dtl Is Not Null And G_Ac_Code Is Not Null Then                               
                Begin                                      
                    Ys_Ac_Dtl_Pkg.Chk_Ac_Dtl (P_Ac_Code_Dtl   => G_Ac_Code_Dtl
                                             ,P_Ac_Code       => G_Ac_Code
                                             ,P_Ac_Dtl_Nm     => G_Inpt_Nm
                                             ,P_Ac_Dtl_Typ    => G_Ac_Dtl_Typ
                                             ,P_Cur_Code      => P_Cur_Code
                                             ,P_Ar_Flg        => 0
                                             ,P_Scr_Typ       => 3
                                             ,P_Aralt         => G_Aralt
                                             ,P_Apalt         => G_Apalt
                                             ,P_Doc_Date      => G_Doc_Date
                                             ,P_Usr_No        => G_Ad_U_Id
                                             ,P_Lng_No        => G_Lng_Dflt
                                             ,P_Msg_No        => V_Msg_No);
                Exception
                    When Others Then
                       P_Err_No := 20191;
                       P_Msg_Txt := 'ERROR IN Ys_Ac_Dtl_Pkg.Chk_Ac_Dtl'||Chr(10)||SQLERRM;
                       Goto Rtn_Rslt;
                End;        

         If V_Msg_No Is Not Null Then
            P_Err_No := 20192;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No);
            Goto Rtn_Rslt;
         End If;
      Elsif G_Ac_Code_Dtl Is Null And G_Ac_Code Is Not Null Then        
             GNR_API_PKG.Chk_Inpt_Data (P_Inpt_Typ     => 'AC_CODE'
                                       ,P_SYS_TYP      =>1
                                       ,P_DOC_TYPE     => G_DOC_TYP
                                       ,P_Inpt_Code1   => G_Ac_Code
                                       ,P_Lng_Dflt     => G_Lng_Dflt
                                       ,P_Inpt_Nm      => G_Inpt_Nm
                                       ,P_Msg_No       => V_Msg_No);              

         If V_Msg_No Is Not Null Then
            P_Err_No := 20193;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No);
            Goto Rtn_Rslt;
         End If;
      End If;
     --##--------------------------------------------------------------------------------------------------------------------------##--
    /*  If G_Sys_No=70  Then-- And G_Bill_Doc_Type=4 And G_C_Code Is Not Null Then
           Begin
               Select Cc_Code Into V_C_CC_Code
                  From Customer
                  Where c_code=G_C_Code
                  and rownum<=1;
           Exception When Others Then
               V_C_CC_Code:=Null;
           End;
             
           Begin
               Select Cc_Code Into V_Rep_CC_Code
                  From sales_Man
                  Where REPRS_CODE=G_Rep_Code
                  and rownum<=1;
           Exception When Others Then
               V_Rep_CC_Code:=Null;
           End;
           ---------------------------
            If G_Doc_typ<>5 Then 
                If  Nvl(P_Bill_Doc_Type,0)=4  Then
                      G_CC_Code:=Nvl(Nvl(V_C_CC_Code,V_Rep_CC_Code),G_CC_Code);
                Else             
                      G_CC_Code:=Nvl(Nvl(V_Rep_CC_Code,V_C_CC_Code),G_CC_Code);   
                   End if;
            End If;          
           ---------------------------
           If G_Doc_typ= 5 And nvl(G_p_Year,0)= 2 Then
               If  Nvl(P_Bill_Doc_Type,0)=4  Then
                  G_CC_Code:=Nvl(Nvl(V_C_CC_Code,V_Rep_CC_Code),G_CC_Code);
               Else             
                  G_CC_Code:=Nvl(Nvl(V_Rep_CC_Code,V_C_CC_Code),G_CC_Code);   
               End if;  
           Elsif G_Doc_typ= 5 And nvl(G_p_Year,0)<> 2 Then
             If  Nvl(P_Bill_Doc_Type,0)=4  Then
                  G_CC_Code:=Nvl(G_CC_Code,Nvl(V_C_CC_Code,V_Rep_CC_Code));
               Else             
                  G_CC_Code:=Nvl(G_CC_Code,Nvl(V_Rep_CC_Code,V_C_CC_Code));   
             End if;             
           End If; 
           ---------------------------     
                 
     End If;*/
     --##--------------------------------------------------------------------------------------------------------------------------##--
    If G_Doc_typ=4 Then
          Declare 
           V_C_Class_Vat Number;
           V_Cst_Brn_No  Number;
           Begin
          
              IF P_C_Code Is Not Null And Nvl(P_Bill_Doc_Type,0) = 4 And Nvl(G_Paid_Instllmnt_Man,0) = 1 Then 
                    Begin
                      Select C_Class_Vat ,Conn_Brn_No
                        Into V_C_Class_Vat,V_Cst_Brn_No
                        From Customer
                       Where C_Code=P_C_Code
                       and RowNum<=1;
                    Exception When Others Then 
                        V_C_Class_Vat:=Null;
                        V_Cst_Brn_No :=Null;
                    End;
                    
                    If Nvl(Ias_Cmp_Pkg.Is_Cmp_Use_Tax_Due_Date(V_Cst_Brn_No),0) = 1 And Nvl(V_C_Class_Vat,0) = 4 Then
                         G_Bill_Tax_Status :=2;
                        
                    Else
                         G_Bill_Tax_Status :=1;
                    End If;
              Else
                      G_Bill_Tax_Status :=1;            
              End If;
               G_Tax_Due_Date    :=G_Doc_Due_Date;
         Exception When Others Then
           Null;
         End;
    End If;
    
    If G_Bill_Tax_Status Is Null Then
      G_Bill_Tax_Status:=1;
    End If;
     --##--------------------------------------------------------------------------------------------------------------------------##--
     <<RTN_RSLT>>
      If P_Msg_Txt Is Not Null OR P_Err_No Is Not Null Then         
         P_Msg_Txt := NVL(P_Msg_Txt,'Message Number Is Missing');
         P_ERR_NO := P_Err_No;
         P_Pkg_NM:=NVL(P_Pkg_NM,'Ars_Api_Trns_Pkg.Chk_Accnt');
         Return;
      ELSE
         P_Msg_Txt := NULL;
         P_ERR_NO := NULL;
         P_Pkg_NM:=NULL;  
      End If;
   --####################--
   --##--------------------------------------------------------------------------------------------------------------------------##--
   Exception When Others then
         P_Msg_Txt := 'Error in Chk_Accnt '||sqlerrm;
         P_ERR_NO  := 20398;
         P_Pkg_NM  :='Ars_Api_Trns_Pkg.Chk_Accnt';
   End Chk_Accnt;

   --##----------------------------------------------------------------------------------------------------------------------------------------------------##--
   Procedure Chk_Gnr_Data (P_Brn_No           In     Ias_Bill_Mst.Brn_No%Type Default Null
                          ,P_Ad_U_Id          In     Ias_Bill_Mst.Ad_U_Id%Type Default Null
                          ,P_Emp_No           In     Ias_Bill_Mst.Emp_No%Type Default Null
                          ,P_Rep_Code         In     Ias_Bill_Mst.Rep_Code%Type Default Null
                          ,P_Col_No           In     Ias_Bill_Mst.Col_No%Type Default Null
                          ,P_R_Code           In     Ias_Bill_Mst.R_Code%Type Default Null
                          ,P_W_Code           In     Ias_Bill_Mst.W_Code%Type Default Null
                          ,P_Clc_Typ_No_Tax   In     Ias_Bill_Mst.Clc_Typ_No_Tax%Type Default Null
                          ,P_Msg_Txt          Out Varchar2
                          ,P_ERR_NO         Out Varchar2
                          ,P_Pkg_NM           Out Varchar2)
   Is
      V_Msg_No     Number;
      V_Msgs_No    Number := Null;     
   Begin
      If P_Ad_U_Id Is Not Null Then
         GNR_API_PKG.Chk_Inpt_Data (P_Inpt_Typ     => 'USR_NO'
                                   ,P_SYS_TYP      =>1
                                   ,P_DOC_TYPE     => G_DOC_TYP
                                   ,P_Inpt_Code1   => P_Ad_U_Id
                                   ,P_Lng_Dflt     => G_Lng_Dflt
                                   ,P_Inpt_Nm      => G_Inpt_Nm
                                   ,P_Msg_No       => V_Msg_No);

         If V_Msg_No Is Not Null Then
            P_Err_No := 20194;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No) || ' USR_NO=' || P_Ad_U_Id;
            Goto Rtn_Rslt;
         End If;
      End If;

      If P_W_Code Is Not Null Then
        GNR_API_PKG.Chk_Inpt_Data (P_Inpt_Typ     => 'W_CODE'
                                   ,P_SYS_TYP      =>1
                                   ,P_DOC_TYPE     => G_DOC_TYP
                                   ,P_Inpt_Code1   => P_W_Code
                                   ,P_Inpt_Code2   => P_Brn_No
                                   ,P_Inpt_Code3   => G_ALLW_SAL_WH_NOT_CONN_BRN
                                   ,P_Inpt_Code4   => G_USE_BALANCED_BRN
                                   ,P_Lng_Dflt     => G_Lng_Dflt
                                   ,P_Inpt_Nm      => G_Inpt_Nm
                                   ,P_Msg_No       => V_Msg_No);

         If V_Msg_No Is Not Null Then
            P_Err_No := 20195;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No) || ' W_CODE=' || P_W_Code;
            Goto Rtn_Rslt;
         End If;
      End If;

      If P_Clc_Typ_No_Tax Is Not Null Then
         GNR_API_PKG.Chk_Inpt_Data (P_Inpt_Typ     => 'CLC_TYP_NO_TAX'
                                   ,P_SYS_TYP      =>1
                                   ,P_DOC_TYPE     => G_DOC_TYP
                                   ,P_Inpt_Code1   => P_Clc_Typ_No_Tax
                                   ,P_Inpt_Code2   => P_Brn_No
                                   ,P_Lng_Dflt     => G_Lng_Dflt
                                   ,P_Inpt_Nm      => G_Inpt_Nm
                                   ,P_Msg_No       => V_Msg_No);

         If V_Msg_No Is Not Null Then
            P_Err_No := 20196;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No) || ' CLC_TYP_NO_TAX=' || P_Clc_Typ_No_Tax;
            Goto Rtn_Rslt;
         End If;
      End If;

      If P_R_Code Is Not Null Then
         GNR_API_PKG.Chk_Inpt_Data (P_Inpt_Typ     => 'R_CODE'
                                   ,P_SYS_TYP      =>1
                                   ,P_DOC_TYPE     => G_DOC_TYP
                                   ,P_Inpt_Code1   => P_R_Code
                                   ,P_Lng_Dflt     => G_Lng_Dflt
                                   ,P_Inpt_Nm      => G_Inpt_Nm
                                   ,P_Msg_No       => V_Msg_No);

         If V_Msg_No Is Not Null Then
            P_Err_No := 20197;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No) || ' R_CODE=' || P_R_Code;
            Goto Rtn_Rslt;
         End If;
      End If;

      If P_Rep_Code Is Not Null Then
         GNR_API_PKG.Chk_Inpt_Data (P_Inpt_Typ     => 'REP_CODE'
                                   ,P_SYS_TYP      =>1
                                   ,P_DOC_TYPE     => G_DOC_TYP
                                   ,P_Inpt_Code1   => P_Rep_Code
                                   ,P_Lng_Dflt     => G_Lng_Dflt
                                   ,P_Inpt_Nm      => G_Inpt_Nm
                                   ,P_Msg_No       => V_Msg_No);

         If V_Msg_No Is Not Null Then
            P_Err_No := 20198;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No) || ' REP_CODE=' || P_Rep_Code;
            Goto Rtn_Rslt;
         End If;
      END IF;
         
      if P_Rep_Code Is Null And (G_Sys_No = 70 Or (G_Si_Repcode_Mandtry = 1 And G_Doc_Typ In (4, 5))) Then
         P_Err_No := 20199;
         P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 811);
         Goto Rtn_Rslt;
      End If;

      If P_Col_No Is Not Null Then
         GNR_API_PKG.Chk_Inpt_Data (P_Inpt_Typ     => 'COL_NO'
                                   ,P_SYS_TYP      =>1
                                   ,P_DOC_TYPE     => G_DOC_TYP
                                   ,P_Inpt_Code1   => P_Col_No
                                   ,P_Lng_Dflt     => G_Lng_Dflt
                                   ,P_Inpt_Nm      => G_Inpt_Nm
                                   ,P_Msg_No       => V_Msg_No);

         If V_Msg_No Is Not Null Then
            P_Err_No := 20200;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No) || ' COL_NO=' || P_Col_No;
            Goto Rtn_Rslt;
         End If;
      End If;

      If P_Emp_No Is Not Null Then
         GNR_API_PKG.Chk_Inpt_Data (P_Inpt_Typ     => 'EMP_NO'
                                   ,P_SYS_TYP      =>1
                                   ,P_DOC_TYPE     => G_DOC_TYP
                                   ,P_Inpt_Code1   => P_Emp_No
                                   ,P_Lng_Dflt     => G_Lng_Dflt
                                   ,P_Inpt_Nm      => G_Inpt_Nm
                                   ,P_Msg_No       => V_Msg_No);

         If V_Msg_No Is Not Null Then
            P_Err_No := 20201;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No) || ' EMP_NO=' || P_Emp_No;
            Goto Rtn_Rslt;
         End If;
      End If;

     --####################--
     <<RTN_RSLT>>
      If P_Msg_Txt Is Not Null OR P_Err_No Is Not Null Then
         ---Rollback;
         P_Msg_Txt := NVL(P_Msg_Txt,'Message Number Is Missing');
         P_ERR_NO := P_Err_No;
         P_Pkg_NM   :='Ars_Api_Trns_Pkg.Chk_Gnr_Data';
         Return;
      End If;
   --####################--
   Exception When Others then
         P_Msg_Txt := 'Error in Chk_Gnr_Data '||sqlerrm;
         P_ERR_NO  := 20399;
         P_Pkg_NM  :='Ars_Api_Trns_Pkg.Chk_Gnr_Data';
   End Chk_Gnr_Data;
   --##--------------------------------------------------------------------------------------------------------------------------------##--          
  Procedure Insrt_Reserve_Prc (P_I_Code       In Item_Movement.I_Code%Type
                               ,P_Itm_Unt      In Item_Movement.Itm_Unt%Type 
                               ,P_P_Size       In Item_Movement.P_Size%Type  default null
                               ,P_I_Qty        In Item_Movement.I_Qty%Type  default null
                               ,P_Res_Qty      In Item_Movement.I_Qty%Type  default null
                               ,P_W_Code       In Item_Movement.W_Code%Type default null
                               ,P_Expiredate   In Item_Movement.Expire_Date%Type default null
                               ,P_Batchno      In Item_Movement.Batch_No%Type default null
                               ,P_Res_Date     In Ias_Reserve_Dtl.T_Date%Type default null
                               ,P_Item_Desc    In Ias_Reserve_Dtl.Item_Desc%Type default null
                               ,P_Rcrd_No      In Number default null
                               ,P_Reserved     In Number default 0
                               ,p_Doc_Sequence in number default null
                               ,P_Msg_Txt    Out Varchar2
                               ,P_ERR_NO   Out Varchar2
                               ,P_Pkg_NM   Out Varchar2)
   Is
   Begin
      If G_Doc_Ser Is Not Null Then
         If G_Rsrv_Ser Is Null Then
            ---------------------------------------------------------------------------------
            Begin
               Select Nvl (Max (Doc_No), 0) + 1
                 Into G_Rsrv_No
                 From Ias_Reserve_Mst
                Where Doc_Type_Ref = G_Doc_Typ;
            Exception
               When Others Then
                  G_Rsrv_No := 1;
            End;

            G_Rsrv_Ser := G_Brn_Year || 2 || Lpad (G_Brn_No, 6, '0') || G_Rsrv_No;
            ---------------------------------------------------------------------------------
            Begin
               Insert Into Ias_Reserve_Mst (Doc_Type
                                           ,Doc_No
                                           ,Doc_Ser
                                           ,Doc_No_Ref
                                           ,Doc_Type_Ref
                                           ,Doc_Ser_Ref
                                           ,C_Code
                                           ,Cc_Code
                                           ,Pj_No
                                           ,Actv_No
                                           ,Brn_No
                                           ,Cmp_No
                                           ,Brn_Usr
                                           ,Brn_Year
                                           ,Ad_U_Id
                                           ,Ad_Date)
                    Values (2
                           ,G_Rsrv_No
                           ,G_Rsrv_Ser
                           ,G_Doc_No
                           ,G_Doc_Typ
                           ,G_Doc_Ser
                           ,G_C_Code
                           ,G_Cc_Code
                           ,G_Pj_No
                           ,G_Actv_No
                           ,G_Brn_No
                           ,G_Cmp_No
                           ,G_Brn_Usr
                           ,G_Brn_Year
                           ,G_Ad_U_Id
                           ,G_Ad_Date);
            Exception
               When Others Then
                   P_Msg_Txt := 'ERROR WHEN INSER INTO IAS_RESERVE_MST'||sqlerrm;
                   P_ERR_NO  := 20353;
                    Goto Rtn_Rslt;                  
            End;
         End If;
      End If;
     -------------------------------------------------------------------------------------
      If G_Rsrv_Ser Is Not Null Then
         Begin
            Insert Into Ias_Reserve_Dtl (Doc_Type
                                        ,Doc_No
                                        ,Doc_Ser
                                        ,Doc_No_Ref
                                        ,Doc_Type_Ref
                                        ,Doc_Ser_Ref
                                        ,I_Code
                                        ,Itm_Unt
                                        ,W_Code
                                        ,Expire_Date
                                        ,Batch_No
                                        ,I_Qty
                                        ,P_Size
                                        ,P_Qty
                                        ,Cp_Qty
                                        ,Reserved
                                        ,C_Code
                                        ,Cc_Code
                                        ,Pj_No
                                        ,Actv_No
                                        ,T_Date
                                        ,Doc_Sequence
                                        ,Rcrd_No
                                        ,Item_Desc
                                        ,Ad_U_Id
                                        ,Ad_Date
                                        ,Brn_No
                                        ,Brn_Year
                                        ,Cmp_No
                                        ,Brn_Usr)
                 Values (2
                        ,G_Rsrv_No
                        ,G_Rsrv_Ser
                        ,G_Doc_No
                        ,G_Doc_Typ
                        ,G_Doc_Ser
                        ,P_I_Code
                        ,P_Itm_Unt
                        ,P_W_Code
                        ,Nvl (P_Expiredate, '01/01/1900')
                        ,Nvl (P_Batchno, '0')
                        ,P_Res_Qty
                        ,P_P_Size
                        ,Nvl (P_Res_Qty, 0) * Nvl (P_P_Size, 1)
                        ,Nvl (P_Res_Qty, 0) * Nvl (P_P_Size, 1)
                        ,Nvl (P_Reserved, 0)
                        ,G_C_Code
                        ,G_Cc_Code
                        ,G_Pj_No
                        ,G_Actv_No
                        ,P_Res_Date
                        ,p_Doc_Sequence
                        ,P_Rcrd_No
                        ,P_Item_Desc
                        ,G_Ad_U_Id
                        ,G_Ad_Date
                        ,G_Brn_No
                        ,G_Brn_Year
                        ,G_Cmp_No
                        ,G_Brn_Usr);
         Exception
            When Others Then
                   P_Msg_Txt := 'ERROR WHEN INSER INTO IAS_RESERVE_DTL'||sqlerrm;
                   P_ERR_NO  := 20354;
                    Goto Rtn_Rslt;                 
         End;
      End If;
      --####################--
     <<RTN_RSLT>>
      If P_Msg_Txt Is Not Null OR P_Err_No Is Not Null Then        
         P_Msg_Txt := NVL(P_Msg_Txt,'Message Number Is Missing');
         P_ERR_NO  := P_Err_No;
         P_Pkg_NM  :='Ars_Api_Trns_Pkg.Insrt_Reserve_Prc';
         Return;
      End If;
   --####################--
   Exception When Others then
         P_Msg_Txt := 'Error in Insrt_Reserve_Prc '||sqlerrm;
         P_ERR_NO  := 20400;
         P_Pkg_NM  :='Ars_Api_Trns_Pkg.Insrt_Reserve_Prc';
   End Insrt_Reserve_Prc;

   --##-----------------------------------------------------------------------------------------------------##--
   Procedure Insrt_Installment (P_Bill_Doc_Type   In     Ias_Bill_Mst.Bill_Doc_Type%Type
                               ,P_Doc_Ser         In     Ias_Bill_Mst.Bill_Ser%Type
                               ,P_Pymnt_Ac        In     Ias_Bill_Mst.Pymnt_Ac%Type Default Null
                               ,P_Ac_Dtl_Typ      In     Ias_Bill_Mst.Ac_Dtl_Typ%Type Default Null
                               ,P_No_Of_Decimal   In     Number Default 2
                               ,P_Pst_Typ         In     Number Default Null
                               ,P_Lng_No          In     Number Default 1
                               ,P_Msg_Txt         Out Varchar2
                               ,P_ERR_NO        Out Varchar2
                               ,P_Pkg_NM                     Out Varchar2)
   Is
      V_Cnt           Number := 0;
      V_No_Instlmnt   Number := 0;
      V_Cnt_Paid      Number := 0;
      V_Bamt          Number := 0;
      V_I_Amt         Number := 0;
      V_Paid_Amt      Number := 0;
      V_Oamt          Number := 0;
      V_Msgs_No       Number := Null;     
      V_Sqlerrm       Varchar2 (4000) := Null;     
      V_Tbl_Instil    Varchar2 (2000);
      V_Tbl_Mst       Varchar2 (2000);      
   Begin
      --##-------------------------------------------------------------------------------------##--
      If P_Pst_Typ Is Null Then
         P_Err_No := 20202;
         P_Msg_Txt := 'PST_TYP IS NULL ';
         Goto Rtn_Rslt;
      Elsif P_Pst_Typ Not In (1, 2) Then
         P_Err_No := 20203;
         P_Msg_Txt := 'Pst_Typ Must Be Equal 1 Or 2 ';
         Goto Rtn_Rslt;
      End If;

      If P_Pst_Typ = 2 Then
         V_Tbl_Instil := 'Installment';
         V_Tbl_Mst := 'IAS_BILL_MST ';
      Else
         V_Tbl_Instil := 'Installment_BR';
         V_Tbl_Mst := 'IAS_BILL_MST_BR ';
      End If;

      If P_Bill_Doc_Type = 4 Or (Nvl (P_Pymnt_Ac, 0) = 1 And Nvl (P_Ac_Dtl_Typ, 0) = 3) Then
         V_Cnt := Ias_Gen_Pkg.Get_Cnt ('Select Count(1) From ' || V_Tbl_Instil || ' 
                                                              Where doc_type= 4 
                                                                And Bill_Ser=' || P_Doc_Ser || '
                                                                And Nvl(I_Py,0)=0');

         V_Cnt_Paid := Ias_Gen_Pkg.Get_Cnt ('Select Count(1) From  ' || V_Tbl_Instil || '           
                                                                          Where doc_type= 4 
                                                                            And Bill_Ser=' || P_Doc_Ser || '
                                                                            And Nvl(Paid_Amt,0)+Nvl(Adj_Amt,0)>0
                                                                            And Nvl(I_Py,0)=0');

         If P_Bill_Doc_Type = 4 Then
            V_No_Instlmnt := 1;
         End If;

         If Nvl (P_Pymnt_Ac, 0) = 1 And Nvl (P_Ac_Dtl_Typ, 0) = 3 Then
            V_No_Instlmnt := Nvl (V_No_Instlmnt, 0) + 1;
         End If;

         If Nvl (V_Cnt, 0) <= Nvl (V_No_Instlmnt, 0) And Nvl (V_Cnt_Paid, 0) = 0 Then
            Begin
               Execute Immediate ' DELETE  ' || V_Tbl_Instil || ' WHERE BILL_SER=' || P_Doc_Ser || ' AND NVL(I_PY,0)=0 ';
            Exception
               When Others Then
                  Null;
            End;
         End If;

         --##-------------------------------------------------------------------------------------##--
         If P_Bill_Doc_Type = 4 Then
            --BEGIN
            --------------------------------------------------------------------------------------------
            If Nvl (V_Cnt, 0) <= Nvl (V_No_Instlmnt, 0) And Nvl (V_Cnt_Paid, 0) = 0 Then
               Begin
                  Execute Immediate '   INSERT INTO ' || V_Tbl_Instil || ' ( DOC_TYPE        , 
                                                          BILL_DOC_TYPE   , 
                                                          BILL_NO                  ,
                                                          BILL_SER        , 
                                                          I_NO            , 
                                                          I_DATE          ,
                                                          DOC_DATE        ,  
                                                          I_AMT           , 
                                                          CHEQUE_NO       , 
                                                          CHEQUE_DUE_DATE , 
                                                          C_CODE          ,
                                                          CC_CODE         ,
                                                          PJ_NO           ,
                                                          ACTV_NO         ,
                                                          A_CY            , 
                                                          PAID_AMT        ,                                           
                                                          AC_RATE         ,
                                                          REF_NO          ,
                                                          DR_NO           , 
                                                          I_PY            , 
                                                          RCRD_NO         ,
                                                          BRN_NO          , 
                                                          BRN_YEAR        ,
                                                          CMP_NO          ,
                                                          BRN_USR   ,
                                                          A_CODE ,
                                                          DR_TYP     )  
                                                      SELECT  4               , 
                                                              BILL_DOC_TYPE   , 
                                                              BILL_NO         ,
                                                              BILL_SER        , 
                                                              1               , 
                                                              NVL(BILL_DUE_DATE,BILL_DATE) ,
                                                              BILL_DATE       ,  
                                                              ROUND(((NVL(BILL_AMT,0)-NVL(DISC_AMT_MST,0)-NVL(DISC_AMT_DTL,0)-NVL(DISC_AMT_AFTR_VAT,0)-NVL(POINT_RPLC_AMT,0)-NVL(INSRNCE_CSH_AMT,0))+(NVL(OTHR_AMT,0)+NVL(VAT_AMT,0)+NVL(VAT_AMT_OTHR,0)+NVL(ASS_AMT,0))-(NVL(CR_CARD_AMT,0)+NVL(CR_CARD_AMT_SCND,0)+NVL(CR_CARD_AMT_THRD,0))),' || P_No_Of_Decimal || '),                                               
                                                              CHEQUE_NO       , 
                                                              CHEQUE_DUE_DATE , 
                                                              C_CODE          , 
                                                              CC_CODE         ,
                                                              PJ_NO           ,
                                                              ACTV_NO         ,        
                                                              BILL_CURRENCY   , 
                                                              0               ,                           
                                                              BILL_RATE       ,
                                                              REF_NO          ,
                                                              NULL            , 
                                                              0               , 
                                                              1               ,
                                                              BRN_NO          , 
                                                              BRN_YEAR        ,
                                                              CMP_NO          ,
                                                              BRN_USR   ,
                                                              A_CODE ,
                                                              1 DR_TYP     
                                                         FROM ' || V_Tbl_Mst || '
                                                        WHERE BILL_SER=' || P_Doc_Ser;
               EXCEPTION  WHEN NO_DATA_FOUND THEN
                    NULL;
                  When Others Then
                  P_Err_No := 20204;
                  P_Msg_Txt := 'ERROR WHEN INSRT INTO ' || V_Tbl_Instil || ' ' || Chr (10) || Sqlerrm;
                   Goto Rtn_Rslt;                    
               End;
            Else
               Begin
                  Execute Immediate '  SELECT ((NVL(BILL_AMT,0)-NVL(DISC_AMT_MST,0)-NVL(DISC_AMT_DTL,0)-NVL(DISC_AMT_AFTR_VAT,0)-NVL(POINT_RPLC_AMT,0)-NVL(INSRNCE_CSH_AMT,0))+(NVL(OTHR_AMT,0)+NVL(VAT_AMT,0)+NVL(VAT_AMT_OTHR,0)+NVL(ASS_AMT,0))-(NVL(CR_CARD_AMT,0)+NVL(CR_CARD_AMT_SCND,0)+NVL(CR_CARD_AMT_THRD,0))),NVL(OTHR_AMT,0)  
                        FROM ' || V_Tbl_Mst || ' 
                       WHERE BILL_SER=' || P_Doc_Ser Into V_Bamt, V_Oamt;

                  Execute Immediate '  SELECT SUM(NVL(I_AMT,0)),SUM(NVL(PAID_AMT,0)+NVL(ADJ_AMT,0))   
                        FROM ' || V_Tbl_Instil || ' 
                       WHERE DOC_TYPE=4
                         AND BILL_SER=' || P_Doc_Ser || ' 
                         AND NVL(I_PY,0)=0 ' Into V_I_Amt, V_Paid_Amt;
               Exception WHEN NO_DATA_FOUND THEN
                    NULL;
                  When Others Then
                     P_Err_No := 20205;
                     P_Msg_Txt := 'ERROR IN' || V_Tbl_Instil || ' ' || Chr (10) || Sqlerrm;
                     Goto Rtn_Rslt;  
               End;

               If Round (Nvl (V_Bamt, 0), P_No_Of_Decimal) <> Round (Nvl (V_I_Amt, 0), P_No_Of_Decimal) Then
                  P_Err_No := 20206;
                  P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No, 942) || ' , ' || Ias_Gen_Pkg.Get_Prompt (P_Lng_No, 669) || ' = ' || V_Bamt || ' , ' || Ias_Gen_Pkg.Get_Prompt (P_Lng_No, 409) || ' = ' || V_Oamt;
                  Goto Rtn_Rslt;
               Elsif Nvl (V_Paid_Amt, 0) > 0 And Round (Nvl (V_Paid_Amt, 0), P_No_Of_Decimal) > Round (Nvl (V_I_Amt, 0), P_No_Of_Decimal) Then
                  P_Err_No := 20207;
                  P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No, 4693) || ' , ' || Ias_Gen_Pkg.Get_Prompt (P_Lng_No, 2554) || ' = ' || Round (Nvl (V_Paid_Amt, 0), P_No_Of_Decimal) || ' , ' || Ias_Gen_Pkg.Get_Prompt (P_Lng_No, 2026) || ' = ' || Round (Nvl (V_I_Amt, 0), P_No_Of_Decimal);
                  Goto Rtn_Rslt;
               End If;
            End If;
         End If;

         If Nvl (P_Pymnt_Ac, 0) = 1 And Nvl (P_Ac_Dtl_Typ, 0) = 3 And Nvl (V_Cnt, 0) <= Nvl (V_No_Instlmnt, 0) And Nvl (V_Cnt_Paid, 0) = 0 Then
            Begin
               Execute Immediate '   INSERT INTO ' || V_Tbl_Instil || '( DOC_TYPE        , 
                                                  BILL_DOC_TYPE   , 
                                                  BILL_NO                  ,
                                                  BILL_SER        , 
                                                  I_NO            , 
                                                  I_DATE          ,
                                                  DOC_DATE        ,  
                                                  I_AMT           , 
                                                  CHEQUE_NO       , 
                                                  CHEQUE_DUE_DATE , 
                                                  C_CODE          ,
                                                  CC_CODE         ,
                                                  PJ_NO           ,
                                                  ACTV_NO         ,
                                                  A_CY            , 
                                                  PAID_AMT        ,                                           
                                                  AC_RATE         ,
                                                  REF_NO          ,
                                                  DR_NO           , 
                                                  I_PY            , 
                                                  RCRD_NO         ,
                                                  BRN_NO          , 
                                                  BRN_YEAR        ,
                                                  CMP_NO          ,
                                                  BRN_USR ,
                                                  A_CODE  ,
                                                  DR_TYP      )  
                                              SELECT  4               , 
                                                      BILL_DOC_TYPE   , 
                                                      BILL_NO         ,
                                                      BILL_SER        , 
                                                      2               , 
                                                      NVL(BILL_DUE_DATE,BILL_DATE) ,
                                                      BILL_DATE       ,  
                                                      ROUND(NVL(INSRNCE_CSH_AMT,0),' || P_No_Of_Decimal || '),                                               
                                                      CHEQUE_NO       , 
                                                      CHEQUE_DUE_DATE , 
                                                      AC_CODE_DTL     , 
                                                      CC_CODE         ,
                                                      PJ_NO           ,
                                                  ACTV_NO         ,        
                                                      BILL_CURRENCY   , 
                                                      0               ,                           
                                                      BILL_RATE       ,
                                                      REF_NO          ,
                                                      NULL            , 
                                                      0               , 
                                                      1               ,
                                                      BRN_NO          , 
                                                      BRN_YEAR        ,
                                                      CMP_NO          ,
                                                  BRN_USR ,
                                                  A_CODE ,
                                                  1 DR_TYP       
                                                 FROM ' || V_Tbl_Mst || ' 
                                                WHERE BILL_SER=' || P_Doc_Ser || '
                                                  AND ROWNUM<=1 ';
            Exception
               When Others Then                
                     P_Err_No := 20209;
                     P_Msg_Txt := 'ERROR WHEN INSRT INTO ' || V_Tbl_Instil || ' ' || Chr (10) || Sqlerrm;
                     Goto Rtn_Rslt;                
            End;
         End If;
      End If;

     --##-------------------------------------------------------------------------------------##--
     --####################--
     <<RTN_RSLT>>
      If P_Msg_Txt Is Not Null OR P_Err_No Is Not Null Then
         P_Msg_Txt := NVL(P_Msg_Txt,'Message Number Is Missing');
         P_ERR_NO :=P_Err_No;
         P_Pkg_NM := NVL(P_Pkg_Nm,'Ars_Api_Trns_Pkg.Insrt_Installment');
         Return;
      ELSE 
         P_Msg_Txt := NULL;
         P_ERR_NO :=NULL;
         P_Pkg_NM   := NULL;    
      End If;
   --####################--
   Exception When Others then
         P_Msg_Txt := 'Error in Insrt_Installment '||sqlerrm;
         P_ERR_NO  := 20401;
         P_Pkg_NM  :='Ars_Api_Trns_Pkg.Insrt_Installment'; 
   End Insrt_Installment;

   --##-----------------------------------------------------------------------------------------------------##--
  Procedure Update_Doc_Ref    ( P_Doc_Type               In Number                            default null
                               ,P_Pst_Typ                In Number                            default null
                               ,P_Doc_Ser                In Ias_Post_Dtl.Doc_Ser%Type         Default Null
                               ,P_I_Code                 In Item_Movement.I_Code%Type         Default Null
                               ,P_Itm_Unt                In Item_Movement.Itm_Unt%Type        Default Null
                               ,P_P_Size                 In Item_Movement.P_Size%Type         default null
                               ,P_I_Qty                  In Item_Movement.I_Qty%Type          default null
                               ,P_Free_Qty               In Item_Movement.I_Qty%Type          default null                                 
                               ,P_Rcrd_No                In Number                            default null
                               ,P_Doc_Type_Ref           In Ias_Rt_Bill_Dtl.Doc_Type_Ref%Type Default Null
                               ,P_Doc_No_Ref             In Ias_Rt_Bill_Dtl.Doc_No_Ref%Type   Default Null
                               ,P_Doc_Ser_Ref            In Ias_Rt_Bill_Dtl.Doc_Ser_Ref%Type  Default Null                             
                               ,P_Rcrd_No_Ref            In Ias_Rt_Bill_Dtl.Rcrd_No_Ref%Type  Default Null 
                               ,P_Msg_Txt                Out Varchar2
                               ,P_ERR_NO                 Out Varchar2
                               ,P_Pkg_NM                 Out Varchar2) Is
   V_Doc_Type_nm VarChar2(500);
   V_Cnt  Number;   
   V_Tbl_Mst_Nm         Varchar2(2000);
   V_Tbl_Dtl_Nm         Varchar2(2000); 
   V_Fld_Doc_Ser        Varchar2(500);
   V_Fld_Doc_No         Varchar2(500);      
   V_Fld_Rcrd_no        Varchar2(500);                            
  Begin
  
  
        If P_Doc_Type_Ref Is Null And (P_Doc_No_Ref Is Not Null Or P_Doc_Ser_Ref Is Not Null) Then
          P_Err_No := 20066;
          P_Msg_Txt := 'Err. Data Send P_DOC_TYP_REF Is Null But (DOC_NO_REF , DOC_SER_REF ) IS NOT NULL , FOR  I_CODE = ' || P_I_Code || Chr (10);
          Goto Rtn_Rslt;
       Elsif P_Doc_Type_Ref Is Not Null And (P_Doc_No_Ref Is Null Or P_Doc_Ser_Ref Is Null) Then
          P_Err_No := 20067;
          P_Msg_Txt := 'Err. Data Send P_DOC_TYP_REF Is Not Null But (DOC_NO_REF , DOC_SER_REF  ) IS NULL , FOR  I_CODE = ' || P_I_Code;
          Goto Rtn_Rslt;
        Elsif P_Doc_Type_Ref Is Not Null And  P_Doc_Ser_Ref Is Not Null And  P_Rcrd_No_Ref Is Null Then
          P_Err_No := 20666;
          P_Msg_Txt := 'Err. Data Send P_Doc_Ser_Ref Is Not Null But P_Rcrd_No_Ref IS NULL , FOR  I_CODE = ' || P_I_Code;
          Goto Rtn_Rslt;   
       End If;
       ---------------------------------------------------------
       If P_Doc_Type_Ref Is  Null Then
         Return;
       End If;
       -----------------------------------------------------------
           If P_Doc_Type_Ref = 53 Then    
              V_Tbl_Mst_Nm :=       'SALES_ORDER';
              V_Tbl_Dtl_Nm :=       'ORDER_DETAIL';
              V_Fld_Doc_Ser :=      'ORDER_SER';
              V_Fld_Rcrd_no :=      'RCRD_NO';
              V_Fld_Doc_No :=       'ORDER_NO';         
           ELSIf P_Doc_Type_Ref = 52 Then      
              V_Tbl_Mst_Nm :=       'QUOTATION';
              V_Tbl_Dtl_Nm :=       'QUOTATION_DETAIL';
              V_Fld_Doc_Ser :=      'QUOT_SER';
              V_Fld_Rcrd_no :=      'RCRD_NO';
              V_Fld_Doc_No :=       'QUOT_NO'; 
           ELSIf P_Doc_Type_Ref = 185 Then      
              V_Tbl_Mst_Nm :=       'STN_BILL_MST';
              V_Tbl_Dtl_Nm :=       'STN_BILL_DTL';
              V_Fld_Doc_Ser :=      'DOC_SER';
              V_Fld_Rcrd_no :=      'RCRD_NO';
              V_Fld_Doc_No :=       'DOC_NO'; 
           ELSIf P_Doc_Type_Ref = 1410 Then      
              V_Tbl_Mst_Nm :=       'DTS_STK_CST_MST';
              V_Tbl_Dtl_Nm :=       'DTS_STK_CST_DTL';
              V_Fld_Doc_Ser :=      'DOC_SER';
              V_Fld_Rcrd_no :=      'RCRD_NO';
              V_Fld_Doc_No :=       'DOC_NO';                            
           ELSIf P_Doc_Type_Ref = 136 Then     
              V_Tbl_Mst_Nm :=       'IAS_RT_BILL_MST_RQ';
              V_Tbl_Dtl_Nm :=       'IAS_RT_BILL_DTL_RQ';
              V_Fld_Doc_Ser :=      'RT_BILL_SER';
              V_Fld_Rcrd_no :=      'RCRD_NO';
              V_Fld_Doc_No :=       'RT_BILL_NO';    
           ELSIf P_Doc_Type_Ref = 143 Then      
              V_Tbl_Mst_Nm :=       'IAS_AR_CNTRCT_MST';
              V_Tbl_Dtl_Nm :=       'IAS_AR_CNTRCT_DTL';
              V_Fld_Doc_Ser :=      'DOC_SRL';
              V_Fld_Rcrd_no :=      'RCRD_NO';
              V_Fld_Doc_No :=       'CNTRCT_NO';                         
           Elsif P_Doc_Type_Ref = 4 Then
              If Nvl(G_Pst_Typ, 0) = 2 Then         
                 V_Tbl_Mst_Nm :=       'IAS_BILL_MST';
                 V_Tbl_Dtl_Nm :=       'IAS_BILL_DTL';       
              Elsif Nvl(P_Pst_Typ, 0) = 1 Then         
                 V_Tbl_Mst_Nm :=       'IAS_BILL_MST_BR';
                 V_Tbl_Dtl_Nm :=       'IAS_BILL_DTL_BR';        
              End If;
              V_Fld_Doc_Ser :=    'BILL_SER';
              V_Fld_Doc_No :=     'BILL_NO';      
              V_Fld_Rcrd_no :=     'RCRD_NO';           
           Elsif P_Doc_Type_Ref = 5 Then
              If Nvl(P_Pst_Typ, 0) = 2 Then       
                 V_Tbl_Mst_Nm :=       'IAS_RT_BILL_MST';
                 V_Tbl_Dtl_Nm :=       'IAS_RT_BILL_DTL';         
              Elsif Nvl(G_Pst_Typ, 0) = 1 Then        
                 V_Tbl_Mst_Nm :=       'IAS_RT_BILL_MST_BR';
                 V_Tbl_Dtl_Nm :=       'IAS_RT_BILL_DTL_BR';        
              End If;     
              V_Fld_Doc_Ser :=    'RT_BILL_SER';
              V_Fld_Doc_No :=     'RT_BILL_NO';              
              V_Fld_Rcrd_no :=     'RCRD_NO';      
           End If; 
       -----------------------------------------------------------
       If P_Doc_Type_Ref Is Not Null And G_Sys_no<>185 Then
          Begin
             Select m.Doc_Type_Name 
              into  V_Doc_Type_nm        
               From Ias_Sys.IAS_DOCJV_TYPE_SYSTEMS_MST m
              Where Doc_Type = P_Doc_Type_Ref
              and  Lang_no  = nvl(g_lng_no,1)                  
              And Rownum <= 1;
          Exception
             When Others Then
                P_Err_No := 20068;
                P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 1171) || ' DOC_TYP_REF , FOR  I_CODE = ' || P_I_Code;
                Goto Rtn_Rslt;
          End;
          ---------------------------------------------------------              
             Begin
               execute Immediate '
                Select 1                  
                  From  '||V_Tbl_Dtl_Nm||'  
                 Where  '||V_Fld_Doc_No ||'= '||P_Doc_No_Ref||'   
                 And    '||V_Fld_Doc_Ser||'  = '||P_Doc_Ser_Ref||'  
                 And Rownum <= 1 ' INTO V_Cnt ;
             Exception
                When No_data_found Then
                      V_Cnt := 0;
                When Others Then
                   P_Err_No := 20663;
                   P_Msg_Txt := 'Erorr When get Doc_Type_ref '||sqlerrm;
                   Goto Rtn_Rslt;
             End;

             If V_Cnt = 0 Then
                 P_Err_No := 20069;
                 P_Msg_Txt := V_Doc_Type_nm||chr(10)
                              ||Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 345)||chr(10)
                              ||'DOC_NO_REF='||P_DOC_NO_REF ||chr(10)
                              ||'DOC_SER_REF='||P_DOC_SER_REF||chr(10)
                              ||'I_Code='||P_I_Code||chr(10);                                       
                Goto Rtn_Rslt;
             End If;          
          ---------------------------------------------------------
          If nvl(P_Doc_Type_Ref,0)=52 Then    
                  Begin
                    Update Quotation Set Processed =1 
                     Where Quot_Ser=P_DOC_SER_REF;
                  Exception When others Then                   
                      null;
                  End;                    
          ElsIf nvl(P_Doc_Type_Ref,0)=53 Then    
                  Begin
                    Update Sales_Order Set Procesed =1 
                     Where Order_Ser=P_DOC_SER_REF;
                  Exception When others Then                   
                     Null;
                  End; 
                  
                 If Nvl(P_Pst_Typ, 0) = 2 Then        
                      Begin
                        Update Order_Detail a Set Reserved=Null ,Res_Date=Null              
                         Where Doc_Ser_Ref=P_DOC_SER_REF
                          and i_code    =p_i_code
                          and rcrd_no=p_rcrd_no_ref;                     
                      Exception When others Then
                       Null;
                      End;
                  End If;
          ElsIf nvl(P_Doc_Type_Ref,0)=136 Then            
               Begin
                  Update Ias_Rt_Bill_Mst_Rq Set Processed = 1 
                   Where Rt_Bill_ser=P_DOC_SER_REF;                
                 Exception when others then
                 null;
               End; 
          ElsIf nvl(P_Doc_Type_Ref,0)=1410 Then            
               Begin
                 EXECUTE Immediate ' Update DTS_STK_CST_MST Set Processed = 1 
                        Where DOC_SER='||P_DOC_SER_REF||'  ';                
                 Exception when others then
                 null;
               End; 
          ElsIf nvl(P_Doc_Type_Ref,0)=143 Then            
               Begin
                 EXECUTE Immediate ' Update IAS_AR_CNTRCT_MST Set Processed = 1 
                        Where DOC_SRL='||P_DOC_SER_REF||'';                
                 Exception when others then
                 null;
               End;        
       
          End If;          
        --------------------------------------------------------------------          
       End If;
   
  --####################--
     <<RTN_RSLT>>
      If P_Msg_Txt Is Not Null OR P_Err_No Is Not Null Then
         P_Msg_Txt := NVL(P_Msg_Txt,'Message Number Is Missing');
         P_ERR_NO :=P_Err_No;
         P_Pkg_NM := NVL(P_Pkg_Nm,'Ars_Api_Trns_Pkg.Update_Doc_Ref');
         Return;
      ELSE 
         P_Msg_Txt := NULL;
         P_ERR_NO :=NULL;
         P_Pkg_NM   := NULL;    
      End If;
   --####################--
   Exception When Others then
         P_Msg_Txt := 'Error in Update_Doc_Ref '||sqlerrm;
         P_ERR_NO  := 20401;
         P_Pkg_NM  :='Ars_Api_Trns_Pkg.Update_Doc_Ref'; 
  End  Update_Doc_Ref;                              
   --##-----------------------------------------------------------------------------------------------------##--
   PROCEDURE Insert_Installemnt_FBR (P_Doc_Type    Number,
                                  P_BillNo      Number,
                                  P_billdoctype Number,
                                  P_BillSer     Number,
                                  P_Billdate    Date,
                                  P_User_Id     Number,
                                  P_billcur     Varchar2,
                                  P_CashNo      Number,
                                  P_ccode       Varchar2,
                                  P_Typ         Varchar2 Default 'D',
                                  P_Msg_Txt                    Out Varchar2,
                                  P_ERR_NO                   Out Varchar2,
                                  P_Pkg_NM                     Out Varchar2) Is
  V_Msgs_No       Number := Null; 
  V_Sqlerrm       Varchar2 (4000) := Null; 
  V_Tbl_Instil    Varchar2 (2000);
  V_Tbl_Mst       Varchar2 (2000);                                 
BEGIN

       If P_Typ='D' Then
            Declare                
                Cursor c1 Is
               Select I_No, 
                I_Date, 
                I_Amt, 
                Installment_Br.Cheque_No, 
                Installment_Br.Cheque_Due_Date, 
                Installment_Br.C_Code, 
                A_Cy, 
                Installment_Br.Paid_Amt, 
                Adj_Amt, 
                Dr_No, 
                I_Py,
                Installment_Br.Cc_Code, 
                Installment_Br.Pj_No, 
                Installment_Br.Actv_No,
                Installment_Br.Brn_No, 
                Installment_Br.Brn_Year,
                Installment_Br.Cmp_No,
                Installment_Br.Brn_Usr,
                Ias_Bill_Mst_Br.a_code
                 From Ias_Bill_Mst_Br , Installment_Br
                where Ias_Bill_Mst_Br.bill_ser= Installment_Br.bill_ser 
                  and Installment_Br.Doc_type=4
                  and nvl(Ias_Bill_Mst_Br.bill_post,0)=0
                  and nvl(Ias_Bill_Mst_Br.Stand_By,0)=0
                  and Ias_Bill_Mst_Br.Bill_Ser = P_BillSer;                  
                Begin    
                     For J in c1 Loop                                    
                       Begin         
                              Insert Into Installment (  Doc_Type, 
                                                          Bill_Doc_Type, 
                                                          Bill_No, 
                                                          Bill_Ser, 
                                                          I_No, 
                                                          I_Date, 
                                                          I_Amt, 
                                                          Cheque_No, 
                                                          Cheque_Due_Date, 
                                                          C_Code, 
                                                          A_Cy, 
                                                          Paid_Amt, 
                                                          Adj_Amt, 
                                                          Dr_No, 
                                                          I_Py,
                                                          Cc_Code,
                                                          Pj_No,
                                                          Actv_No, 
                                                          Rcrd_No,
                                                          Brn_No, 
                                                          Brn_Year,
                                                          Cmp_No,
                                                           Brn_Usr,
                                                           a_code,
                                                           DR_TYP) 
                                         Values ( 4, 
                                                          P_billdoctype, 
                                                          P_BillNo, 
                                                          P_BillSer, 
                                                          J.I_No, 
                                                          J.I_Date, 
                                                          J.I_Amt, 
                                                          J.Cheque_No, 
                                                          J.Cheque_Due_Date, 
                                                          J.C_Code, 
                                                          J.A_Cy, 
                                                          J.Paid_Amt, 
                                                          J.Adj_Amt, 
                                                          J.Dr_No, 
                                                          J.I_Py, 
                                                          J.Cc_Code,
                                                          J.Pj_No,
                                                          J.Actv_No,
                                                          1,
                                                          J.Brn_No, 
                                                          J.Brn_Year,
                                                          J.Cmp_No,
                                                          J.Brn_Usr,
                                                          j.a_code,
                                                          1);
                       Exception
                               When No_Data_Found Then   
                                 Null;         
                          When Others Then 
                           P_Err_No := 20210;
                            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 1142)||Chr(10)||SqlErrM;
                            Goto Rtn_Rslt;                                                         
                      End;     
                 End Loop;    
                End;
        Else --------------------------------------------------------------------------------------    
             Declare                         
                Cursor c1 Is
               Select I_No, 
                I_Date, 
                Sum(I_Amt) I_Amt, 
                Installment_Br.Cheque_No, 
                Installment_Br.Cheque_Due_Date, 
                Installment_Br.C_Code, 
                A_Cy, 
                Sum(Installment_Br.Paid_Amt) Paid_Amt, 
                Sum(Adj_Amt) Adj_Amt, 
                Dr_No,                 
                I_Py, 
                Installment_Br.Cc_Code, 
                Installment_Br.Pj_No, 
                Installment_Br.Actv_No,
                Installment_Br.Brn_No, 
                Installment_Br.Brn_Year,
                Installment_Br.Cmp_No,
                Installment_Br.Brn_Usr,
                Ias_Bill_Mst_Br.a_code
                 From Ias_Bill_Mst_Br , Installment_Br
                where Ias_Bill_Mst_Br.bill_ser= Installment_Br.bill_ser 
                  and Installment_Br.Doc_type=4
                  and nvl(Ias_Bill_Mst_Br.bill_post,0)=0
                  and nvl(Ias_Bill_Mst_Br.Stand_By,0)=0                  
                  and Ias_Bill_Mst_Br.Bill_date=P_Billdate
                  and Ias_Bill_Mst_Br.ad_u_id=P_User_id 
                  and Ias_Bill_Mst_Br.bill_currency=P_billcur                  
                  and Nvl(Ias_Bill_Mst_Br.cash_no,0)=Nvl(P_CashNo,0)
                  and Nvl(Ias_Bill_Mst_Br.c_code,0)=Nvl(P_ccode,0)
                  Group By I_No,I_Date,Installment_Br.Cheque_No,Installment_Br.Cheque_Due_Date,Installment_Br.C_Code,A_Cy, 
                           Dr_No,I_Py,Installment_Br.Brn_No,Installment_Br.Brn_Year;
                Begin    
                     For J in c1 Loop                                                             
                       Begin         
                              Insert Into Installment (  Doc_Type, 
                                                          Bill_Doc_Type, 
                                                          Bill_No, 
                                                          Bill_Ser, 
                                                          I_No, 
                                                          I_Date, 
                                                          I_Amt, 
                                                          Cheque_No, 
                                                          Cheque_Due_Date, 
                                                          C_Code, 
                                                          A_Cy, 
                                                          Paid_Amt, 
                                                          Adj_Amt, 
                                                          Dr_No, 
                                                          Rcrd_No,
                                                          I_Py, 
                                                          Cc_Code,
                                                          Pj_No,
                                                          Actv_No, 
                                                          Brn_No, 
                                                          Brn_Year,
                                                          Cmp_No,
                                                          Brn_Usr,
                                                          a_code,
                                                          DR_TYP) 
                                         Values ( 4, 
                                                          P_billdoctype, 
                                                          P_BillNo, 
                                                          P_BillSer, 
                                                          J.I_No, 
                                                          J.I_Date, 
                                                          J.I_Amt, 
                                                          J.Cheque_No, 
                                                          J.Cheque_Due_Date, 
                                                          J.C_Code, 
                                                          J.A_Cy, 
                                                          J.Paid_Amt, 
                                                          J.Adj_Amt, 
                                                          J.Dr_No, 
                                                          J.I_Py, 
                                                          J.Cc_Code,
                                                          J.Pj_No,
                                                          J.Actv_No, 
                                                          1,
                                                          J.Brn_No, 
                                                          J.Brn_Year,
                                                          J.Cmp_No,
                                                         J.Brn_Usr,
                                                         j.a_code,
                                                         1); 
                                                          
                                                          
                      Exception
                          When No_Data_Found Then   
                                 Null;         
                          When Others Then        
                          P_Err_No := 20211;
                            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 1142)||Chr(10)||SqlErrM;
                            Goto Rtn_Rslt;
                      End;     
                 End Loop;    
                End;
End If;
 --####################--
     <<RTN_RSLT>>
      If P_Msg_Txt Is Not Null OR P_Err_No Is Not Null Then
         P_Msg_Txt := NVL(P_Msg_Txt,'Message Number Is Missing');
         P_ERR_NO :=P_Err_No;
         P_Pkg_NM := NVL(P_Pkg_Nm,'Ars_Api_Trns_Pkg.Insert_Installemnt_FBR');
         Return;
      ELSE 
         P_Msg_Txt := NULL;
         P_ERR_NO :=NULL;
         P_Pkg_NM   := NULL; 
      End If;
Exception When Others then
         P_Msg_Txt := 'Error in Insert_Installemnt_FBR '||sqlerrm;
         P_ERR_NO  := 20402;
         P_Pkg_NM  :='Ars_Api_Trns_Pkg.Insert_Installemnt_FBR';       
END Insert_Installemnt_FBR;
    --##-----------------------------------------------------------------------------------------------------##--
   Procedure Insrt_Other_Charges(    P_DOC_TYP                    IN IAS_POST_DTL.DOC_TYPE%TYPE
                                    ,P_Bill_Doc_Type              IN IAS_BILL_MST.Bill_Doc_Type%TYPE                DEFAULT NULL
                                    ,P_Bill_Type                  IN OTHER_CHARGES.Bill_Type%TYPE                   DEFAULT NULL
                                    ,P_SC_NO                      IN OTHER_CHARGES.SC_NO%TYPE                       DEFAULT NULL
                                    ,P_A_CODE                     IN OTHER_CHARGES.A_CODE%TYPE                      DEFAULT NULL
                                    ,P_CUR_CODE                   IN OTHER_CHARGES.A_CY%TYPE                        DEFAULT NULL
                                    ,P_AC_RATE                    IN OTHER_CHARGES.AC_RATE%TYPE                     DEFAULT NULL
                                    ,P_PER                        IN OTHER_CHARGES.PER%TYPE                         DEFAULT NULL
                                    ,P_AMT                        IN OTHER_CHARGES.AMT%TYPE                         DEFAULT NULL
                                    ,P_INV_ITEM                   IN OTHER_CHARGES.INV_ITEM%TYPE                    DEFAULT NULL
                                    ,P_RCRD_NO                    IN OTHER_CHARGES.RCRD_NO%TYPE                     DEFAULT NULL
                                    ,P_BILL_PY                    IN OTHER_CHARGES.BILL_PY%TYPE                     DEFAULT NULL
                                    ,P_VAT_AMT                    IN OTHER_CHARGES.VAT_AMT%TYPE                     DEFAULT NULL
                                    ,P_VAT_PER                    IN OTHER_CHARGES.VAT_PER%TYPE                     DEFAULT NULL
                                    ,P_SC_AMT                     IN OTHER_CHARGES.SC_AMT%TYPE                      DEFAULT NULL
                                    ,P_SC_AC_RATE                 IN OTHER_CHARGES.SC_AC_RATE%TYPE                  DEFAULT NULL
                                    ,P_SC_A_CY                    IN OTHER_CHARGES.SC_A_CY%TYPE                     DEFAULT NULL
                                    ,P_CC_CODE                    IN OTHER_CHARGES.CC_CODE%TYPE                     DEFAULT NULL
                                    ,P_PJ_NO                      IN OTHER_CHARGES.PJ_NO%TYPE                       DEFAULT NULL
                                    ,P_ACTV_NO                    IN OTHER_CHARGES.ACTV_NO%TYPE                     DEFAULT NULL                                     
                                    ,P_Msg_Txt                    Out Varchar2
                                    ,P_ERR_NO                   Out Varchar2
                                    ,P_Pkg_NM                     Out Varchar2) IS
  V_Cnt              Number;
  V_Msg_No  number;                                   
BEGIN
 NULL;
  ------------------------------------------------------------------
   If P_Cur_Code Is Null Then
      P_Err_No    := 20658;
      P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 31) || Chr(10) || ' OTHER_CHARGES P_CUR_CODE Is Null , Must Be Entered , ';
      Goto Rtn_Rslt;
   Else
      Gnr_Api_Pkg.Chk_Inpt_Data (P_Inpt_Typ     => 'CUR_CODE'
                                ,P_Sys_Typ      => 1
                                ,P_Doc_Type     => P_DOC_TYP
                                ,P_Inpt_Code1   => P_Cur_Code
                                ,P_Lng_Dflt     => G_Lng_no
                                ,P_Inpt_Nm      => G_Inpt_Nm
                                ,P_Msg_No       => V_Msg_No);

      If V_Msg_No Is Not Null Then
         P_Err_No    := 20659;
         P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No)|| Chr(10) || ' OTHER_CHARGES P_Cur_Code='||P_Cur_Code;
         Goto Rtn_Rslt;
      End If;
   End If; 
 ------------------------------------------------------------------
 If P_SC_A_CY Is Not  Null Then     
      Gnr_Api_Pkg.Chk_Inpt_Data (P_Inpt_Typ     => 'CUR_CODE'
                                ,P_Sys_Typ      => 1
                                ,P_Doc_Type     => P_DOC_TYP
                                ,P_Inpt_Code1   => P_SC_A_CY
                                ,P_Lng_Dflt     => G_Lng_no
                                ,P_Inpt_Nm      => G_Inpt_Nm
                                ,P_Msg_No       => V_Msg_No);

      If V_Msg_No Is Not Null Then
         P_Err_No    := 20660;
         P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No)|| Chr(10) || ' OTHER_CHARGES P_SC_A_CY='||P_SC_A_CY;
         Goto Rtn_Rslt;
      End If;
 End If;
 ------------------------------------------------------------------
 If P_SC_NO Is Not Null Then     
      Begin
       select 1 into v_cnt from SALES_CHARGES
           where SC_NO=P_SC_NO
           and rownum<=1;
     Exception when Others Then                 
         P_Err_No    := 20661;
         P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 348)|| Chr(10) || ' P_SC_NO='||P_SC_NO;
         Goto Rtn_Rslt;
     End;
 End If;
 ------------------------------------------------------------------
 If P_A_CODE Is Not Null Then        
             GNR_API_PKG.Chk_Inpt_Data (P_Inpt_Typ     => 'AC_CODE'
                                       ,P_SYS_TYP      =>1
                                       ,P_DOC_TYPE     => G_DOC_TYP
                                       ,P_Inpt_Code1   => P_A_CODE
                                       ,P_Lng_Dflt     => G_Lng_No
                                       ,P_Inpt_Nm      => G_Inpt_Nm
                                       ,P_Msg_No       => V_Msg_No);              

         If V_Msg_No Is Not Null Then
            P_Err_No := 20662;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No)|| Chr(10) || ' OTHER_CHARGES P_A_CODE='||P_A_CODE;
            Goto Rtn_Rslt;
         End If;
 End If;
 ------------------------------------------------------------------  
 If P_CC_CODE Is Not Null Then        
             GNR_API_PKG.Chk_Inpt_Data (P_Inpt_Typ     => 'CC_CODE'
                                       ,P_SYS_TYP      =>1
                                       ,P_DOC_TYPE     => G_DOC_TYP
                                       ,P_Inpt_Code1   => P_CC_CODE
                                       ,P_Lng_Dflt     => G_Lng_No
                                       ,P_Inpt_Nm      => G_Inpt_Nm
                                       ,P_Msg_No       => V_Msg_No);              

         If V_Msg_No Is Not Null Then
            P_Err_No := 20708;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No)|| Chr(10) || ' OTHER_CHARGES P_CC_CODE='||P_CC_CODE;
            Goto Rtn_Rslt;
         End If;
 End If;
  ------------------------------------------------------------------
 If P_PJ_NO Is Not Null Then        
             GNR_API_PKG.Chk_Inpt_Data (P_Inpt_Typ     => 'PJ_NO'
                                       ,P_SYS_TYP      =>1
                                       ,P_DOC_TYPE     => G_DOC_TYP
                                       ,P_Inpt_Code1   => P_PJ_NO
                                       ,P_Lng_Dflt     => G_Lng_No
                                       ,P_Inpt_Nm      => G_Inpt_Nm
                                       ,P_Msg_No       => V_Msg_No);              

         If V_Msg_No Is Not Null Then
            P_Err_No := 20709;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No)|| Chr(10) || ' OTHER_CHARGES P_PJ_NO='||P_PJ_NO;
            Goto Rtn_Rslt;
         End If;
 End If;
  ------------------------------------------------------------------
 If P_ACTV_NO Is Not Null Then        
             GNR_API_PKG.Chk_Inpt_Data (P_Inpt_Typ     => 'ACTV_NO'
                                       ,P_SYS_TYP      =>1
                                       ,P_DOC_TYPE     => G_DOC_TYP
                                       ,P_Inpt_Code1   => P_ACTV_NO
                                       ,P_Lng_Dflt     => G_Lng_No
                                       ,P_Inpt_Nm      => G_Inpt_Nm
                                       ,P_Msg_No       => V_Msg_No);              

         If V_Msg_No Is Not Null Then
            P_Err_No := 20710;
            P_Msg_Txt := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => V_Msg_No)|| Chr(10) || ' OTHER_CHARGES P_ACTV_NO='||P_ACTV_NO;
            Goto Rtn_Rslt;
         End If;
 End If;
 ------------------------------------------------------------------      
IF NVL(G_Pst_Typ,0)=2 AND NVL(P_DOC_TYP,0)IN (4,5)  THEN 
 Begin
   Delete from Other_Charges where Bill_Ser=G_DOC_Ser and Sc_No=P_Sc_No And Bill_Type=P_Bill_Type;
 Exception When  Others Then
   null;
 End ;
 Insert Into  Other_Charges(   Bill_No,
                               Doc_Date,
                               Bill_Ser,
                               Sc_No,
                               Bill_Type,
                               Bill_Doc_Type,                                                                            
                               A_Code,
                               A_Cy,
                               Ac_Rate,
                               Per,
                               Amt,
                               Inv_Item,
                               Rcrd_No,
                               Bill_Py,
                               External_Post,                                                                           
                               Vat_Amt,
                               Vat_Per,
                               Sc_Amt,
                               Sc_Ac_Rate,
                               Sc_A_Cy,
                               Cc_code,
                               Pj_no,
                               Actv_no,                               
                               Ad_Date,                              
                               Ad_U_Id,                               
                               Cmp_No,
                               Brn_No,
                               Brn_Year,
                               Brn_Usr)
     Values (  G_DOC_No,
               G_Doc_Date,
               G_DOC_Ser,
               P_Sc_No,
               P_Bill_Type,
               P_Bill_Doc_Type,                                                                            
               P_A_Code,
               P_CUR_CODE,
               P_Ac_Rate,
               P_Per,
               NVL(P_Amt,0),
               P_Inv_Item,
               P_Rcrd_No,
               P_Bill_Py,
               G_External_Post,                                                                           
               P_Vat_Amt,
               P_Vat_Per,
               P_Sc_Amt,
               DECODE(P_SC_AC_RATE,0,NULL,P_SC_AC_RATE),
               P_Sc_A_Cy, 
               P_Cc_code,
               P_Pj_no,
               P_Actv_no,               
               G_Ad_Date,               
               G_Ad_U_Id,               
               G_Cmp_No,
               G_Brn_No,
               G_Brn_Year,
               G_Brn_Usr);
ELSIF NVL(G_Pst_Typ,0)=1 AND NVL(P_DOC_TYP,0)IN (4,5) THEN
  Begin
   Delete from Other_Charges_Br where Bill_Ser=G_DOC_Ser and Sc_No=P_Sc_No And Bill_Type=P_Bill_Type;
 Exception When  Others Then
   null;
 End ; 
Insert Into  Other_Charges_BR( Bill_No,
                               Doc_Date,
                               Bill_Ser,
                               Sc_No,
                               Bill_Type,
                               Bill_Doc_Type,                                                                            
                               A_Code,
                               A_Cy,
                               Ac_Rate,
                               Per,
                               Amt,
                               Inv_Item,
                               Rcrd_No,
                               Bill_Py,
                               External_Post,                                                                           
                               Vat_Amt,
                               Vat_Per,
                               Sc_Amt,
                               Sc_Ac_Rate,
                               Sc_A_Cy,                               
                               Ad_Date,                              
                               Ad_U_Id,                               
                               Cmp_No,
                               Brn_No,
                               Brn_Year,
                               Brn_Usr)
     Values (  G_DOC_No,
               G_Doc_Date,
               G_DOC_Ser,
               P_Sc_No,
               P_Bill_Type,
               P_Bill_Doc_Type,                                                                             
               P_A_Code,
               P_CUR_CODE,
               P_Ac_Rate,
               P_Per,
               NVL(P_Amt,0),
               P_Inv_Item,
               P_Rcrd_No,
               P_Bill_Py,
               G_External_Post,                                                                           
               P_Vat_Amt,
               P_Vat_Per,
               P_Sc_Amt,
               DECODE(P_SC_AC_RATE,0,NULL,P_SC_AC_RATE),
               P_Sc_A_Cy,               
               G_Ad_Date,               
               G_Ad_U_Id,               
               G_Cmp_No,
               G_Brn_No,
               G_Brn_Year,
               G_Brn_Usr);  
  ELSIF NVL(P_DOC_TYP,0)IN (52,53,136) THEN 
   Begin
     Delete from OTHER_CHARGES_OTHRS where Bill_Ser=G_DOC_Ser and Sc_No=P_Sc_No And Bill_Type=P_Bill_Type;
 Exception When  Others Then
   null;
 End ;
  
Insert Into  OTHER_CHARGES_OTHRS( Bill_No,
                               Doc_Date,
                               Bill_Ser,
                               Sc_No,
                               Bill_Type,
                               Bill_Doc_Type,                                                                            
                               A_Code,
                               A_Cy,
                               Ac_Rate,
                               Per,
                               Amt,
                               Inv_Item,
                               Rcrd_No,
                               Bill_Py,
                               External_Post,                                                                           
