                                                       DR_CR_FLG,
                                                       CMP_NO,
                                                       BRN_NO,
                                                       BRN_YEAR,
                                                       BRN_USR)
                 Values (  G_DOC_TYP, 
                           G_DOC_NO, 
                           G_DOC_SER,
                           P_BILL_DOC_TYPE, 
                           P_DOC_JV_TYPE,
                           G_DOC_DATE, 
                           P_TAX_NO, 
                           P_CLC_TYP_NO,
                           P_AGNCY_NO, 
                           1, 
                           P_INPT_CODE, 
                           P_A_CODE, 
                           P_A_CY, 
                           P_AC_RATE, 
                           P_INPT_AMT, 
                           P_TAX_PRCNT,
                           P_TAX_AMT,
                           P_TAX_AMT_L,
                           P_CC_CODE,
                           P_PJ_NO,
                           P_ACTV_NO,
                           P_REF_NO,
                           P_RCRD_NO,
                           P_DOC_SEQUENCE,
                           G_DR_CR_FLG,
                           G_CMP_NO,
                           G_BRN_NO,
                           G_BRN_YEAR,
                           G_BRN_USR);
   ELSIF NVL(G_PST_TYP,0)=1 AND NVL(P_DOC_TYP,0) IN(4,5) THEN
   INSERT INTO GNR_TAX_INPT_MOVMNT_BR  (   DOC_TYPE, 
                                           DOC_NO, 
                                           DOC_SER,
                                           BILL_DOC_TYPE, 
                                           DOC_JV_TYPE,
                                           DOC_DATE, 
