                                           TAX_PRCNT,
                                           TAX_AMT,
                                           TAX_AMT_L,
                                           CC_CODE,
                                           PJ_NO,
                                           ACTV_NO,
                                           REF_NO,
                                           RCRD_NO,
                                           DOC_SEQUENCE,
                                           DR_CR_FLG,
                                           CMP_NO,
                                           BRN_NO,
                                           BRN_YEAR,
                                           BRN_USR)
                 Values (  G_DOC_TYP, 
                           G_DOC_NO, 
                           G_DOC_SER,
                           P_BILL_DOC_TYPE, 
                           P_DOC_JV_TYPE,
                           G_DOC_DATE, 
                           P_TAX_NO, 
                           P_CLC_TYP_NO,
                           P_AGNCY_NO, 
                           1, 
                           P_INPT_CODE, 
                           P_A_CODE, 
                           P_A_CY, 
                           P_AC_RATE, 
                           P_INPT_AMT, 
                           P_TAX_PRCNT,
                           P_TAX_AMT,
                           P_TAX_AMT_L,
