                           G_DR_CR_FLG,
                           G_CMP_NO,
                           G_BRN_NO,
                           G_BRN_YEAR,
                           G_BRN_USR);
   END IF;
ELSE
  NULL;
  END IF;                                      
--####################--
     <<RTN_RSLT>>
      If P_Msg_Txt Is Not Null OR P_Err_No Is Not Null Then        
            P_Msg_Txt  := NVL(P_Msg_Txt,'Message Number Is Missing');
            P_ERR_NO := P_Err_No ;
            P_Pkg_NM   :=NVL(P_Pkg_Nm,'Ars_Api_Trns_Pkg.INSRT_GNR_TAX_INPT_MOVMNT');
            Return;
      ELSE
         P_Msg_Txt  := NULL;
         P_ERR_NO    := NULL ;
         P_Pkg_NM   := NULL;     
      End If;
   --####################--
   Exception
      When Others Then
            P_Msg_Txt  := 'ERROR WHEN INSERT INSRT_GNR_TAX_INPT_MOVMNT' || Chr (10) || Sqlerrm;
            P_ERR_NO :=  20552;
            P_Pkg_NM   :=NVL(P_Pkg_Nm,'Ars_Api_Trns_Pkg.INSRT_GNR_TAX_INPT_MOVMNT');       
END  INSRT_GNR_TAX_INPT_MOVMNT; 
