Procedure Delete_Bill (P_Doc_Typ   In     Ias_Post_Mst.Doc_Type%Type
                      ,P_Doc_Ser   In     Sales_Order.Order_Ser%Type
                      ,P_Msg_Txt      Out Varchar2
                      ,P_Err_No       Out Varchar2
                      ,P_Pkg_Nm       Out Varchar2)
Is
Begin
   Begin
      Delete From Ias_Post_Mst
            Where Doc_Ser = P_doc_ser And Doc_Type = 4;
   Exception
      When No_Data_Found Then
         Null;
      When Others Then
         P_Err_No    := 20408;
         P_Msg_Txt   := 'ERROR WHEN DELTE FROM  IAS_POST_MST' || Chr(10) || Sqlerrm;
         Goto Rtn_Rslt;
   End;

   Begin
      Delete From Item_Movement
            Where Doc_Ser = P_doc_ser And Doc_Type = 1;
   Exception
      When No_Data_Found Then
         Null;
      When Others Then
         P_Err_No    := 20409;
         P_Msg_Txt   := 'ERROR WHEN DELTE FROM  item_movement' || Chr(10) || Sqlerrm;
         Goto Rtn_Rslt;
   End;

   Begin
      Delete From Sale_Cost
            Where Doc_Ser = P_doc_ser And BILL_TYPE = 4;
   Exception
      When No_Data_Found Then
         Null;
      When Others Then
         P_Err_No    := 20410;
         P_Msg_Txt   := 'ERROR WHEN DELTE FROM  sale_cost' || Chr(10) || Sqlerrm;
         Goto Rtn_Rslt;
   End;


   Begin
      Delete From Other_Charges
            Where Bill_Ser = P_doc_ser;
   Exception
      When No_Data_Found Then
         Null;
      When Others Then
         P_Err_No    := 20411;
         P_Msg_Txt   := 'ERROR WHEN DELTE FROM  OTHER_CHARGES' || Chr(10) || Sqlerrm;
         Goto Rtn_Rslt;
   End;
   Begin
      Delete From Other_Charges_Items
            Where Bill_Ser = P_doc_ser;
   Exception
      When No_Data_Found Then
         Null;
      When Others Then
         P_Err_No    := 20412;
         P_Msg_Txt   := 'ERROR WHEN DELTE FROM  OTHER_CHARGES_ITEMS' || Chr(10) || Sqlerrm;
         Goto Rtn_Rslt;
   End;
   Begin
      Delete From Gnr_Tax_Itm_Movmnt
            Where Doc_Ser = P_doc_ser And Doc_Type = 4;
   Exception
      When No_Data_Found Then
         Null;
      When Others Then
         P_Err_No    := 20413;
         P_Msg_Txt   := 'ERROR WHEN DELTE FROM  GNR_TAX_ITM_MOVMNT' || Chr(10) || Sqlerrm;
         Goto Rtn_Rslt;
   End;
   Begin
      Delete From Installment
            Where Bill_Ser = P_doc_ser;
   Exception
      When No_Data_Found Then
         Null;
      When Others Then
         P_Err_No    := 20414;
         P_Msg_Txt   := 'ERROR WHEN DELTE FROM  Installment' || Chr(10) || Sqlerrm;
         Goto Rtn_Rslt;
   End;   
   Begin
      Delete From DETAIL_OUT_BILLS
            Where Bill_Ser = P_doc_ser;
   Exception
      When No_Data_Found Then
         Null;
      When Others Then
         P_Err_No    := 20418;
         P_Msg_Txt   := 'ERROR WHEN DELTE FROM  DETAIL_OUT_BILLS' || Chr(10) || Sqlerrm;
         Goto Rtn_Rslt;
   End;
   
    Begin
      Delete From MASTER_OUT_BILLS
            Where Bill_Ser = P_doc_ser;
   Exception
      When No_Data_Found Then
         Null;
      When Others Then
         P_Err_No    := 20419;
         P_Msg_Txt   := 'ERROR WHEN DELTE FROM  MASTER_OUT_BILLS' || Chr(10) || Sqlerrm;
         Goto Rtn_Rslt;
   End;
   
    Begin
      Delete From Ars_Bill_Crdt_Crd
            Where doc_srl =P_doc_ser and doc_type=4;
   Exception
      When No_Data_Found Then
         Null;
      When Others Then
         P_Err_No    := 20414;
         P_Msg_Txt   := 'ERROR WHEN DELTE FROM  Ars_Bill_Crdt_Crd_br' || Chr(10) || Sqlerrm;
         Goto Rtn_Rslt;
   End;
   
   
    Begin
      Delete From Ias_Bill_Cpn
            Where Bill_ser =P_doc_ser;
   Exception
      When No_Data_Found Then
         Null;
      When Others Then
         P_Err_No    := 20414;
         P_Msg_Txt   := 'ERROR WHEN DELTE FROM  Ias_Bill_Cpn_Br' || Chr(10) || Sqlerrm;
         Goto Rtn_Rslt;
   End;


   Begin
      Delete From Ias_Bill_Dtl
            Where Bill_Ser = P_doc_ser;
   Exception
      When No_Data_Found Then
         Null;
      When Others Then
         P_Err_No    := 20415;
         P_Msg_Txt   := 'ERROR WHEN DELTE FROM  ias_bill_dtl' || Chr(10) || Sqlerrm;
         Goto Rtn_Rslt;
   End;

   Begin
      Delete From Ias_Bill_Mst
