      Return;
   Else
      P_Msg_Txt   := Null;
      P_Err_No    := Null;
      P_Pkg_Nm    := Null;
   End If;
Exception
   When Others Then
      P_Msg_Txt   := 'Error in DELETE_BILL ' || Sqlerrm;
      P_Err_No    := 20417;
      P_Pkg_Nm    := 'Ars_Api_Trns_Pkg.DELETE_BILL';
End Delete_Bill;
