Procedure Insrt_Cash_Custmr (P_Sys_No       In Number   Default Null
                            ,P_Bill_Doc_Type In IAS_BILL_MST.Bill_Doc_type%Type Default Null
                            ,P_Cust_Code    In Ias_Cash_Custmr.Cust_Code%Type Default Null
                            ,P_Cust_L_Nm    In Ias_Cash_Custmr.Cust_L_Nm%Type Default Null
                            ,P_Cust_F_Nm    In Ias_Cash_Custmr.Cust_F_Nm%Type Default Null
                            ,P_Rep_Code     In Ias_Cash_Custmr.Rep_Code%Type Default Null
                            ,P_Mobile_No    In Ias_Cash_Custmr.Mobile_No%Type Default Null
                            ,P_Tel_No       In Ias_Cash_Custmr.Tel_No%Type Default Null
                            ,P_E_Mail       In Ias_Cash_Custmr.E_Mail%Type Default Null
                            ,P_R_Code       In Ias_Cash_Custmr.R_Code%Type Default Null
                            ,P_City_No      In Ias_Cash_Custmr.City_No%Type Default Null
                            ,P_Address      In Ias_Cash_Custmr.Address%Type Default Null
                            ,P_C_Tax_Code   In Ias_Cash_Custmr.C_Tax_Code%Type Default Null
                            ,P_Msg_Txt                     Out Varchar2
                            ,P_ERR_NO                      Out Varchar2
                            ,P_Pkg_NM                      Out Varchar2)Is 
V_Cnt Number;                            
Begin

Return;
  If Nvl(P_Bill_Doc_Type,0)<>1 Then
     Return;
  End If;
  If Nvl(P_Sys_no,0)<>70 Then
     Return;
  End If;
  
  If P_Mobile_No Is Not Null Then
       Begin 
         select 1 Into V_Cnt From Ias_Cash_Custmr 
            where (Mobile_No=p_Mobile_No Or Cust_Code=p_Mobile_No)
            and rownum<=1;
      Exception When Others Then 
         V_cnt:=0;
      End ;
  
   If Nvl(V_Cnt,0)=0  Then
       If  P_Cust_L_Nm Is Not Null Then 
            Begin
               Insert Into Ias_Cash_Custmr
               ( Cust_Code,Cust_L_Nm,Cust_F_Nm,Rep_Code,Mobile_No,Tel_No,E_Mail,R_Code,City_No,Address,C_Tax_Code)
               Values( P_Mobile_No,P_Cust_L_Nm,P_Cust_F_Nm,P_Rep_Code,P_Mobile_No,P_Tel_No,P_E_Mail,P_R_Code,P_City_No,P_Address,P_C_Tax_Code);          
            Exception When Others Then 
             Null;
            End ;
       Else
         If  P_C_Tax_Code Is Not Null Then
           Update Ias_Cash_Custmr set  C_Tax_Code=P_C_Tax_Code
             Where Mobile_No=p_Mobile_No ;
         End If;       
       End If;                   
    End If;
  End If;
  
  Begin 
     select Cust_Code Into G_C_CODE_CSH From Ias_Cash_Custmr 
        where (Mobile_No=p_Mobile_No Or Cust_Code=p_Mobile_No)
        and rownum<=1;
  Exception When Others Then 
     G_C_CODE_CSH:=Null;
  End ;       
 --####################--
  <<RTN_RSLT>>
   If P_Msg_Txt Is Not Null OR P_Err_No Is Not Null Then
      P_Msg_Txt   := NVL(P_Msg_Txt,'Message Number Is Missing');
      P_Err_No    := P_Err_No;
      P_Pkg_Nm    := Nvl (P_Pkg_Nm, 'Ars_Api_Trns_Pkg.Insrt_Cash_Custmr');
      Return;
   Else
      P_Msg_Txt   := Null;
      P_Err_No    := Null;
      P_Pkg_Nm    := Null;
   End If;
Exception
   When Others Then
      P_Msg_Txt   := 'Error in Insrt_Cash_Custmr ' || Sqlerrm;
      P_Err_No    := 20417;
      P_Pkg_Nm    := 'Ars_Api_Trns_Pkg.Insrt_Cash_Custmr';                            
End  Insrt_Cash_Custmr;                            
--##-----------------------------------------------------------------------------------------------------##--
FUNCTION IS_USE_ETS_WEB_SRVC( P_BRN_NO       IN     NUMBER,
                              P_SYS_NO       IN     NUMBER) RETURN  NUMBER                                         
IS   
    V_SRVC_NO        NUMBER;
    V_ETS_SRVC_FLG   NUMBER(1) := 0;
    V_POS_REF_CODE   S_BRN.POS_REF_CODE%TYPE;        
BEGIN

    IF NVL(IAS_BRN_PKG.IS_BRN_USE_E_INVC(P_BRN_NO => P_BRN_NO), 0) = 0 THEN
        RETURN 0;
    END IF;

    SELECT NVL(POS_REF_CODE, '0')
      INTO V_POS_REF_CODE
      FROM S_BRN
     WHERE BRN_NO = P_BRN_NO
     AND ROWNUM<=1;

    BEGIN

        SELECT ETS_SRVC_FLG, SRVC_NO
          INTO V_ETS_SRVC_FLG, V_SRVC_NO
          FROM GNR_WEB_SRVC_MST
         WHERE NVL(ETS_SRVC_FLG, 0) = 1 AND SRVC_NO = V_POS_REF_CODE AND ROWNUM <= 1;
    EXCEPTION
        WHEN OTHERS THEN
            V_ETS_SRVC_FLG := 0;
    END;
   
   RETURN  V_ETS_SRVC_FLG;
EXCEPTION
    WHEN OTHERS THEN
       RETURN 0;
END IS_USE_ETS_WEB_SRVC;
--##-----------------------------------------------------------------------------------------------------##--
PROCEDURE SET_TAX_BILL_TYP(P_BILL_DOC_TYPE IN IAS_BILL_MST.BILL_DOC_TYPE%TYPE
                          ,P_C_CODE        IN CUSTOMER.C_CODE%TYPE
                          ,P_Use_Vat       IN NUMBER DEFAULT 0
                          ,P_C_TAX_CODE    IN OUT CUSTOMER.C_TAX_CODE%TYPE
                          ,P_TAX_BILL_TYP  IN OUT CUSTOMER.C_CLASS_VAT%TYPE                          
                          ) 
 IS  
        V_C_TAX_CODE CUSTOMER.C_TAX_CODE%TYPE := null;
        V_C_CLASS_VAT CUSTOMER.C_CLASS_VAT%TYPE := null;
 BEGIN
    
        If P_C_CODE IS NOT NULL  Then
        
               Begin
                  select  C_Tax_Code ,DECODE( NVL(C_CLASS_VAT,1),2,2,3,2,1) into V_C_TAX_CODE,V_C_CLASS_VAT 
                  from customer where c_code=P_C_Code and rownum<=1;
               Exception when others then             
                   Null;
               End;  
               
               If nvl(trim(P_C_TAX_CODE),'0')='0' Then
                  P_C_TAX_CODE:=V_C_TAX_CODE; 
               Else
                   V_C_TAX_CODE:=trim(P_C_TAX_CODE)  ;
                   P_C_TAX_CODE:=trim(P_C_TAX_CODE);      
               End If; 
                             
               P_TAX_BILL_TYP:= CASE WHEN nvl(trim(V_C_TAX_CODE),'0')='0' OR 
                                            V_C_CLASS_VAT = 1 THEN 1 ELSE 2 END;                                     
        Else
           P_C_TAX_CODE:=trim(P_C_TAX_CODE);
           P_TAX_BILL_TYP:=  CASE WHEN nvl(trim(P_C_TAX_CODE),'0')='0'  THEN 1 ELSE 2 END ;             
        End If;
        G_TAX_BILL_TYP:=P_TAX_BILL_TYP;
                                
EXCEPTION WHEN OTHERS THEN
  null;
END SET_TAX_BILL_TYP; 
--##-----------------------------------------------------------------------------------------------------##--
PROCEDURE SYNC_E_INVC_PRC( P_DOC_TYPE       IN     NUMBER,
                            P_BILL_TYPE      IN     NUMBER,
                            P_BRN_NO         IN     NUMBER,
                            P_Use_Vat        In     Number DEFAULT 0 ,
                            P_SYS_NO         IN     NUMBER,
                            P_DOC_SER        IN     NUMBER,
                            P_C_CODE         IN     VARCHAR2,                           
                            P_TAX_BILL_TYP   IN     NUMBER DEFAULT 1,    
                            P_OFFLINE_VLDT   IN     NUMBER DEFAULT 0,
                            P_DO_COMMIT      IN     NUMBER DEFAULT 0,
                            P_Tbl_Mst_Nm     IN     VARCHAR2,
                            P_Fld_Doc_Ser    IN     VARCHAR2,
                            P_DTS_ONLINE     IN     NUMBER DEFAULT 0,
                            P_COMMIT_FLG     IN     NUMBER DEFAULT 0, 
                            P_Pst_Typ        IN     NUMBER DEFAULT 1, --1 into br 2 into onyx                          
                            P_WEB_SRVC_UUID  OUT  IAS_BILL_MST.BILL_DOC_TYPE%TYPE,                          
                            P_WRNNG_TXT      OUT VARCHAR2,
                            P_Msg_Txt        Out Varchar2,
                            P_ERR_NO         Out Varchar2,
                            P_Pkg_NM         Out Varchar2)
IS
    V_START_DATE   DATE;
    V_END_DATE     DATE;
    V_USR          VARCHAR2(30);
    V_ERROR        VARCHAR2(4000);
    V_STATUS       VARCHAR2(4000);
    V_SRVC_NO      NUMBER;
    V_CNTRY_CODE   VARCHAR2(30);
    --V_USE_ASYNC_MODE   NUMBER := (CASE RMS_TAX_PKG.GET_TAX_BILL_TYP(P_BILL_TYPE => P_BILL_TYPE, P_C_CODE => P_C_CODE) WHEN 2 THEN 0 ELSE 1 END);
BEGIN
    
    IF NVL(P_Pst_Typ,0)<>2 THEN
      RETURN;
    END IF;
    ---------------------------------------------------------
    IF P_DOC_TYPE NOT In (4, 5) Then
       RETURN;
    END IF;
    ---------------------------------------------------------
    IF (Nvl(P_SYS_NO,0)=70  And nvl(P_DTS_ONLINE,0)=0 ) Or Nvl(P_SYS_NO,0)=185 
                     or (Nvl(P_SYS_NO,0) IN ( 61 , 85 )  And nvl(P_COMMIT_FLG,0)=0 )  Then -- (DTS Offline Or STN  )
        RETURN;
    END IF;
    ---------------------------------------------------------  
    IF NVL(IAS_BRN_PKG.IS_BRN_USE_E_INVC(P_BRN_NO => P_BRN_NO), 0) = 0 OR nvl(P_Use_Vat,0) = 0 THEN
        RETURN;
    END IF;
    
    ---------------------------------------------------------      
     IF NVL(G_SHO_TAX_SYNC,0)= 0 AND Nvl(P_SYS_NO,0) =67  THEN 
        RETURN;
     END IF; 
    ---------------------------------------------------------  
    BEGIN
        V_CNTRY_CODE := IAS_BRN_PKG.GET_BRN_CNTRY_CODE(P_BRN_NO);
    EXCEPTION
        WHEN OTHERS THEN
            V_CNTRY_CODE := NULL;
    END;
   ---------------------------------------------------------
    IF YS_TAX_PKG.GET_ETS_SRVC_FLG_FNC(P_BRN_NO => P_BRN_NO) = 1 AND UPPER(V_CNTRY_CODE) IN ('SAU','JOR','MYS') THEN

        EXECUTE IMMEDIATE 'BEGIN 
                                YS_JSON_PKG.SYNC_E_INVC_PRC(P_DOC_TYPE       => '||(CASE WHEN P_DOC_TYPE IS NULL THEN 'NULL' ELSE P_DOC_TYPE || '' END)||',
                                                            P_BILL_TYPE      => '||(CASE WHEN P_BILL_TYPE IS NULL THEN 'NULL' ELSE P_BILL_TYPE || '' END)||',
                                                            P_BRN_NO         => '||(CASE WHEN P_BRN_NO IS NULL THEN 'NULL' ELSE P_BRN_NO || '' END)||',
                                                            P_SYS_NO         => '||(CASE WHEN P_SYS_NO IS NULL THEN 'NULL' ELSE P_SYS_NO || '' END)||',
                                                            P_DOC_SER        => '||(CASE WHEN P_DOC_SER IS NULL THEN 'NULL' ELSE P_DOC_SER || '' END)||',
                                                            P_C_CODE         => '''||(CASE WHEN P_C_CODE IS NULL THEN 'NULL' ELSE P_C_CODE || '' END)||''',
                                                            P_ERR_TXT        => :V_ERROR,
                                                            P_WRNNG_TXT      => :V_STATUS,
                                                            P_TAX_BILL_TYP   => '||NVL(P_TAX_BILL_TYP,1)||',
                                                            P_OFFLINE_VLDT   => '||NVL(P_OFFLINE_VLDT,0)||'
                                                            );
                          END;'
            USING OUT V_ERROR, OUT V_STATUS;
            If V_ERROR Is Not Null Then
              P_ERR_NO :=20691;
              P_Msg_Txt:=V_ERROR;
              P_Pkg_NM  :='ARS_API_TRNS_PKG.SYNC_E_INVC_PRC';
              Return;
           
            End If;
                                    
            V_STATUS:=Replace(V_STATUS,'"',' ');
            V_STATUS:=Replace( V_STATUS,':',' ');
            V_STATUS:=Replace( V_STATUS,',',' ');
            V_STATUS:=Replace( V_STATUS,'''',' ');
            P_WRNNG_TXT:= V_STATUS;
            
           If Nvl(P_OFFLINE_VLDT,0)=0 then    
                  Begin
                    Execute Immediate ' Select  WEB_SRVC_UUID from '||P_Tbl_Mst_Nm||' 
                             where '||P_Fld_Doc_Ser||'='||P_DOC_SER||'
                               and rownum<=1  ' into P_WEB_SRVC_UUID;
                  Exception         
                     When Others Then
                       null;           
                  End;
                  
                  IF P_WEB_SRVC_UUID Is Null THEN
                       DBMS_LOCK.SLEEP(2);
                  END IF;
                  
                  Begin
                        Execute Immediate ' Select  WEB_SRVC_UUID from '||P_Tbl_Mst_Nm||' 
                                 where '||P_Fld_Doc_Ser||'='||P_DOC_SER||'
                                   and rownum<=1  ' into P_WEB_SRVC_UUID;
                   Exception         
                     When Others Then
                       null;           
                  End;       
           End If;   
          
                     
    END IF;
    
EXCEPTION
    WHEN OTHERS THEN
              P_ERR_NO :=20692;
              P_Msg_Txt:='Err In Sync_E_Invc_Prc  ' || CHR(10) || SQLERRM;
              P_Pkg_NM  :='ARS_API_TRNS_PKG.SYNC_E_INVC_PRC';       
END SYNC_E_INVC_PRC;
--##-----------------------------------------------------------------------------------------------------##--
 Procedure UPDATE_TAX_ITM_MOVMNT (P_Clc_Typ_No        In     Gnr_Tax_Itm_Movmnt.Clc_Typ_No%Type
                                           ,P_Doc_Typ           In     Gnr_Tax_Itm_Movmnt.Doc_Type%Type
                                           ,P_Doc_Ser           In     Gnr_Tax_Itm_Movmnt.Doc_Ser%Type
                                           ,P_Use_Vat           In     Number
                                           ,P_Doc_Due_Date      In     Ias_Bill_Mst.Bill_Due_Date%Type
                                           ,P_Tax_Due_Date      In     Ias_Bill_Mst.Bill_Date%Type
                                           ,P_Bill_Tax_Status   In     Ias_Bill_Mst_Extnd.Bill_Tax_Status%Type
                                           ,P_Tbl_Mvmnt_Nm      In     Varchar2
                                           ,P_Tbl_Mst_Nm        In     Varchar2
                                           ,P_Tbl_Dtl_Nm        In     Varchar2
                                           ,P_Fld_Doc_Ser       In     Varchar2
                                           ,P_Fld_Doc_Seq       In     Varchar2
                                           ,P_Lng_No            In     Number
                                           ,P_Msg_Txt              Out Varchar2
                                           ,P_Err_No               Out Varchar2
                                           ,P_Pkg_Nm               Out Varchar2)
Is
   V_Sql   Varchar2 (4000);
Begin
   If Nvl (P_Use_Vat, 0) = 0 Then
      Return;
   End If;
   If Nvl (P_Doc_Typ, 0) not in(4,5)  Then
      Return;
   End If;
   Begin
                    V_SQL :='UPDATE '||P_TBL_MVMNT_NM|| ' TX SET(
                                Tax_Typ_Code,
                                Vat_Cat_Code,
                                Tax_Prd_No,
                                PRC_BS_QTY,
                                PRC_DED_AMT,
                                ITM_NET_PRICE,
                                ITM_NET_QTY,
                                OTHR_AMT_ITM_DISC,
                                OTHR_AMT_ITM,
                                ITM_NET_AMT,
                                TAX_CUR_CODE,
                                TAX_CUR_RATE,
                                NET_TAX_AMT,
                                ITM_VAT_CAT_CODE,
                                ITM_VAT_EX_RSN_CODE,
                                ITM_VAT_EX_RSN_TXT,
                                TAX_DUE_DATE,
                                BILL_TAX_STATUS,
                                TAX_HAS_JRNL)=
            (Select Tc.Tax_Typ_Code
                  , Tc.Vat_Cat_Code
                  ,Ys_Tax_Pkg.Get_Tax_Prd (P_Doc_Date => TX.Doc_Date) Tax_Prd_No
                  ,1 Prc_Bs_Qty
                  , ( ( ( (Nvl (D.Dis_Amt_Mst, 0) + Nvl (D.Dis_Amt_Dtl, 0) + Nvl (D.Dis_Amt_Dtl2, 0) + Nvl (D.Dis_Amt_Dtl3, 0)) * (Nvl (D.I_Qty, 0) / Nvl ( (D.I_Qty + Nvl (D.Free_Qty, 0)), 1)))) + Nvl (D.Itm_Free_Qty_Amt, 0)) Prc_Ded_Amt
                  , (Nvl (D.I_Price, 0) - ( ( ( (Nvl (D.Dis_Amt_Mst, 0) + Nvl (D.Dis_Amt_Dtl, 0) + Nvl (D.Dis_Amt_Dtl2, 0) + Nvl (D.Dis_Amt_Dtl3, 0)) * (Nvl (D.I_Qty, 0) / Nvl ( (D.I_Qty + Nvl (D.Free_Qty, 0)), 1)))) + Nvl (D.Itm_Free_Qty_Amt, 0))) Itm_Net_Price
                  , (Nvl (D.I_Qty, 0) + Nvl (D.Free_Qty, 0)) Itm_Net_Qty
                  , (Nvl (D.Othr_Amt_Disc, 0) * (Nvl (D.I_Qty, 0) / Nvl ( (D.I_Qty + Nvl (D.Free_Qty, 0)), 1))) Othr_Amt_Itm_Disc
                  ,0 Othr_Amt_Itm      
                   , ( (Nvl (D.I_Price, 0) - ( ( ( (Nvl (D.Dis_Amt_Mst, 0) + Nvl (D.Dis_Amt_Dtl, 0) + Nvl (D.Dis_Amt_Dtl2, 0) + Nvl (D.Dis_Amt_Dtl3, 0) + Nvl (D.Othr_Amt_Disc, 0)) * (Nvl (D.I_Qty, 0) / Nvl ( (D.I_Qty + Nvl (D.Free_Qty, 0)), 1)))) + Nvl (D.Itm_Free_Qty_Amt, 0))) * (Nvl (D.I_Qty, 0) + Nvl (D.Free_Qty, 0))) Itm_Net_Amt
                  ,IAS_CMP_PKG.GET_TAX_CUR ( P_BRN_NO => m.BRN_NO) Tax_Curr
                  ,case when TX.A_CY= IAS_CMP_PKG.GET_TAX_CUR ( P_BRN_NO => m.BRN_NO)  then TX.AC_RATE else IAS_GEN_PKG.GET_CUR_RATE ( P_ACY => IAS_CMP_PKG.GET_TAX_CUR ( P_BRN_NO => m.BRN_NO) ) END Tax_Curr_Rate
                  , ( (Nvl (D.I_Price, 0) - ( ( ( (Nvl (D.Dis_Amt_Mst, 0) + Nvl (D.Dis_Amt_Dtl, 0) + Nvl (D.Dis_Amt_Dtl2, 0) + Nvl (D.Dis_Amt_Dtl3, 0) + Nvl (D.Othr_Amt_Disc, 0)) * (Nvl (D.I_Qty, 0) / Nvl ( (D.I_Qty + Nvl (D.Free_Qty, 0)), 1)))) + Nvl (D.Itm_Free_Qty_Amt, 0))) * (Nvl (D.I_Qty, 0) + Nvl (D.Free_Qty, 0))) * Nvl (TX.Tax_Prcnt, 0) / 100 Net_Tax_Amt
                  ,Decode (Ys_Tax_Pkg.CHK_TAX_STNDRD ( P_CLC_TYP_NO => TX.CLC_TYP_NO), 1, Ti.Vat_Cat_Code, Tc.Vat_Cat_Code) Itm_Vat_Cat_Code
                  ,TI.VAT_EXMPT_RSN_CODE ITM_VAT_EX_RSN_CODE
                 , TI.VAT_EXMPT_RSN_TXT ITM_VAT_EX_RSN_TXT
                  ,'''||P_TAX_DUE_DATE||'''  Tax_Due_Date
                  ,'''||P_BILL_TAX_STATUS||'''  Bill_Tax_Status
                  , (Case When '''||P_Doc_Due_Date||'''  Is Not Null And '''||P_Doc_Due_Date||'''  > TX.Doc_Date Then 1 Else 0 End) Tax_Has_Jrnl
              From  '||P_TBL_MST_NM|| ' M, '||P_TBL_DTL_NM||'  D,GNR_TAX_TYP_CLC_DTL TC,GNR_TAX_ITM TI
              where M.'||P_FLD_DOC_SER||'=D.'||P_FLD_DOC_SER|| '
              AND TX.DOC_SER=M.'||P_FLD_DOC_SER|| '
              AND TX.DOC_SEQUENCE='||P_FLD_DOC_SEQ||'
              AND TX.CLC_TYP_NO=tc.CLC_TYP_NO
              and TX.TAX_NO=tc.TAX_NO
              and TX.TAX_NO=ti.TAX_NO
              AND TI.TAX_NO     = TC.TAX_NO
               AND TX.I_CODE     =  TI.I_CODE
               AND D.I_CODE     =  TI.I_CODE
                AND TI.AGNCY_NO   = TX.AGNCY_NO)
            WHERE DOC_SER= '||P_DOC_SER;
            
            
             EXECUTE IMMEDIATE V_SQL;
   Exception
      When Others Then
         P_Err_No := 20690;
         P_Msg_Txt := Sqlerrm;
         Goto Rtn_Rslt;
   End;

  <<RTN_RSLT>>
   If P_Msg_Txt Is Not Null Or P_Err_No Is Not Null Then
      P_Msg_Txt := Nvl (P_Msg_Txt, 'Message Number Is Missing');
      P_Err_No := P_Err_No;
      P_Pkg_Nm := Nvl (P_Pkg_Nm, 'Ars_Api_Trns_Pkg.UPDATE_TAX_ITM_MOVMNT');
      Return;
   Else
      P_Msg_Txt := Null;
      P_Err_No := Null;
      P_Pkg_Nm := Null;
   End If;
--####################--
Exception
   When Others Then
      P_Msg_Txt := 'ERROR WHEN  UPDATE_TAX_ITM_MOVMNT' || Chr (10) || Sqlerrm;
      P_Err_No := 20212;
      P_Pkg_Nm := Nvl (P_Pkg_Nm, 'Ars_Api_Trns_Pkg.UPDATE_TAX_ITM_MOVMNT');
End UPDATE_TAX_ITM_MOVMNT;
--##-----------------------------------------------------------------------------------------------------#--
Function Is_Csh_Cstmr(p_c_code in varchar2) return number
Is
v_cnt number(1); 
Begin
  select 1 into v_cnt from customer
      where c_code=p_c_code
      and nvl(CSH_CST,0)=1
      and rownum<=1;
      return nvl(v_cnt,0);
Exception when others then
     return 0;
End Is_Csh_Cstmr;    
--##-----------------------------------------------------------------------------------------------------##--
Procedure Update_Si_Out_Qty(P_doc_Type number
                            ,P_Doc_No Number
                            ,P_Doc_Ser Number  )
Is 
   Bqty   Number := 0;
   Oqty   Number := 0;
   V_Cnt    Number := 0;
   Rtqty    Number := 0;
Begin
   --Check_Qty_In_Save;
   
    If Nvl(G_Use_Out_Bills,0)=0 Then
      Return;
    End If;
   If P_doc_type=4 Then
   Begin
      Select Nvl (Sum (Nvl (P_Qty, 0) + (Nvl (Free_Qty, 0) * Nvl (P_Size, 1))), 0)
        Into Bqty
        From Ias_Bill_Dtl
       Where Bill_No = P_doc_No
       And Bill_Ser = P_doc_Ser
       And Nvl (Service_Item, 0) = 0;

      Select Nvl (Sum (Nvl (P_Qty, 0) + (Nvl (Free_Qty, 0) * Nvl (P_Size, 1))), 0)
        Into Oqty
        From Detail_Out_Bills
       Where Bill_No = P_doc_No And Bill_Ser = P_doc_Ser;

      Begin
         Select Nvl (Sum (Nvl (P_Qty, 0) + (Nvl (Free_Qty, 0) * Nvl (P_Size, 1))), 0)
           Into Rtqty
           From Ias_Rt_Bill_Mst A, Ias_Rt_Bill_Dtl B
          Where A.Rt_Bill_Ser = B.Rt_Bill_Ser 
          And A.P_Year = 3 
          And B.Bill_Ser = P_Doc_SEr;      
      Exception
         When Others Then
            Rtqty := 0;
      End;
   Exception
      When Others Then
         Null;
   End;

       If Nvl (Bqty, 0) = (Nvl (Oqty, 0) + Nvl (Rtqty, 0)) Then --(2)
          Begin
             Update Ias_Bill_Mst
                Set Processed = 1
              Where Bill_No = P_doc_No And Bill_Ser = P_doc_Ser;
          Exception
             When Others Then
                Null;
          End;
       End If; 
  ----##-----------------------------------------------------------------------------------##--         
   Elsif P_doc_type=5 Then
   
      Update Ias_Bill_Dtl A               
             Set Out_Qty = (Nvl((Select Nvl(Sum(Nvl(I_Qty,0)),0) Iqty                        
                                                       From Detail_Out_Bills
                                                       Where Bill_Ser = A.Bill_Ser
                                                       And I_Code   = A.I_Code
                                                       And Rcrd_No  = A.Rcrd_No),0)
                                                  +
                                                  Nvl((Select Nvl(Sum(P_Qty),0)/Nvl(A.P_Size,1) Iqty From Ias_Rt_Bill_Mst M,Ias_Rt_Bill_Dtl D
                                                        Where M.Rt_Bill_Ser = D.Rt_Bill_Ser
                                                        And M.P_Year      =3
                                                        And D.Bill_Ser    = A.Bill_Ser
                                                        And D.I_Code      = A.I_Code
                                                        And D.Si_Rcrd_No  = A.Rcrd_No),0)),       
                      Out_Free_Qty = (Nvl((Select Nvl(Sum(Nvl(Free_Qty,0)),0) Fqty                        
                                                      From Detail_Out_Bills
                                                      Where Bill_Ser = A.Bill_Ser
                                                      And I_Code   = A.I_Code
                                                      And Rcrd_No  = A.Rcrd_No),0)
                                                +
                                                Nvl((Select  Nvl(Sum(Nvl(Free_Qty,0)*Nvl(P_Size,1)),0)/Nvl(A.P_Size,1) Fqty From Ias_Rt_Bill_Mst M,Ias_Rt_Bill_Dtl D
                                                      Where M.Rt_Bill_Ser = D.Rt_Bill_Ser
                                                      And M.P_Year      =3
                                                      And D.Bill_Ser    = A.Bill_Ser
                                                      And D.I_Code      = A.I_Code
                                                      And D.Si_Rcrd_No  = A.Rcrd_No),0)),
                      Not_Out_Qty =(Nvl((SELECT NVL (SUM (d.p_qty), 0) / NVL (a.p_size, 1) iqty
                                    FROM   ias_rt_bill_mst m,
                                           ias_rt_bill_dtl d
                                    WHERE  m.rt_bill_ser = d.rt_bill_ser
                                    AND    m.p_year = 3
                                    AND    d.bill_ser = a.bill_ser
                                    AND    d.i_code = a.i_code
                                    AND    d.si_rcrd_no = a.rcrd_no),0) ) , 
                       Not_Out_Free_Qty =(Nvl((SELECT  Nvl(Sum(Nvl(Free_Qty,0)*Nvl(P_Size,1)),0) /Nvl(A.P_Size,1)
                                    FROM   ias_rt_bill_mst m,
                                           ias_rt_bill_dtl d
                                    WHERE  m.rt_bill_ser = d.rt_bill_ser
                                    AND    m.p_year = 3
                                    AND    d.bill_ser = a.bill_ser
                                    AND    d.i_code = a.i_code
                                    AND    d.si_rcrd_no = a.rcrd_no),0) )                                                                                      
                    Where (Bill_Ser,I_Code,rcrd_no) In (Select Bill_Ser,I_Code,si_rcrd_no 
                                      From Ias_Rt_Bill_Dtl
                                        Where Rt_Bill_Ser =P_doc_ser);
       ------------------------------------------                                        
        Begin
          Update Ias_Bill_Mst a Set Processed = 1 
                 Where Bill_Ser In ( Select Bill_Ser
                                     From Ias_Rt_Bill_Dtl
                                      Where Rt_Bill_Ser =P_Doc_Ser)
                              And 0 = (Select Sum((Nvl(I_Qty,0)+Nvl(Free_Qty,0))-(Nvl(Out_Qty,0)+Nvl(Out_Free_Qty,0)))
                                                 From Ias_Bill_Dtl
                                                  Where Bill_Ser =a.Bill_Ser); 
        Exception 
                When Others Then
                null;
            End;                                                                                          
      ------------------------------------------
         Begin        
             Select nvl(Sum(nvl(i_qty,0)+nvl(free_qty,0)),0) Into bqty From Ias_Rt_Bill_Dtl
              Where rt_bill_no =P_Doc_No
                and rt_bill_ser=P_Doc_Ser
                and nvl(service_item,0)=0;
                        
             Select nvl(Sum(nvl(i_qty,0)+nvl(free_qty,0)),0) Into oqty From Ias_Ret_Bill_Dtl
              Where rt_bill_no =P_Doc_No
                and rt_bill_ser=P_Doc_Ser;        
            Exception 
                When Others Then
                null;
            End;                    
        --##-------------------------------------------------------------------------------------##--              
          If  nvl(bqty,0)= nvl(oqty,0)  Then --(2)                    
                   Begin
                      Update Ias_Rt_Bill_Mst Set Processed=1 
                       Where rt_bill_no =P_Doc_No
                         and rt_bill_ser=P_Doc_Ser;            
                   Exception when others then                   
                     null;
                   End;                                         
          End if;
          ------------------------------------------       
   End If; 
Exception when others Then 
    Null;
End Update_Si_Out_Qty;
--##-----------------------------------------------------------------------------------------------------##--
Procedure INSRT_ARCHIVES (   P_Doc_Typ    In     Ias_Post_Mst.Doc_Type%Type 
                            ,P_Doc_Ser    In     Ias_Post_Mst.doc_ser%Type   
                            ,P_FILE_NAME   In      Varchar2                    
                            ,P_Msg_Txt    Out Varchar2
                            ,P_ERR_NO   Out Varchar2
                            ,P_Pkg_Nm     Out Varchar2)
Is
V_cnt Number;
v_FULL_FILE_PATH  Varchar2(500);
v_FILE_UUID   Varchar2(500);
Begin

 Begin
         Select 1 Into V_Cnt 
           From Ias_Archives_Mst
            Where DOC_SER = P_DOC_Ser
             And RowNum   <= 1; 
    Exception When Others Then
       V_Cnt :=  0 ;
    End;

           IF NVL(V_Cnt,0)=0 THEN
                Begin 
                    ADM_INSRT_TRNS_PKG.INSRT_IAS_ARCHIVES_MST(  P_DOC_DATE        =>G_Doc_Date
                                                                ,P_DOC_DSC       =>G_Doc_Dsc
                                                                ,P_DOC_NOTE      =>NULL
                                                                ,P_DOC_TYP       =>P_Doc_Typ
                                                                ,P_DOC_NO        =>G_DOC_NO
                                                                ,P_DOC_SRL       =>G_DOC_SER
                                                                ,P_USR_NO        =>G_Ad_U_Id
                                                                ,P_BRN_NO        =>G_Brn_No
                                                                ,P_BRN_YEAR      =>G_Brn_Year
                                                                ,P_TRMNL_NM      =>G_Ad_Trmnl_Nm
                                                                ,P_LNG_NO        =>G_Lng_No);                                           
                  
                Exception
                   When Others Then
                      P_Msg_Txt := 'ERROR WHEN INSRT_IAS_ARCHIVES_MST'||sqlerrm;
                      P_ERR_NO  := 20714;
                    Goto Rtn_Rslt;
                End; 
           END IF; 
            --------------------------------------------------------------------
           BEGIN                                
                IF ADM_INSRT_TRNS_PKG.G_DOC_NO IS NULL THEN
                      P_Msg_Txt := 'ADM_INSRT_TRNS_PKG.G_Doc_No Is Null';
                      P_ERR_NO  := 20715;
                    Goto Rtn_Rslt;                 
                END IF;
              
                IF P_FILE_NAME IS NULL THEN
                       P_Msg_Txt := IAS_GEN_PKG.GET_MSG(G_LNG_NO,1601)||' '||IAS_GEN_PKG.GET_PROMPT (G_LNG_NO, 4983)|| 'ARCHIVES FILE_NAME ';
                       P_ERR_NO  := 20716;
                       Goto Rtn_Rslt;                  
                 
                END IF;
                ------------------------------------------------------
                ADM_INSRT_TRNS_PKG.INSRT_IAS_ARCHIVES_DTL( P_FILE_NAME  =>P_FILE_NAME,
                                                           P_FILE_SEQ   =>P_FILE_NAME, 
                                                           P_DOC_TYP   =>G_Doc_typ,
                                                           P_BRN_USR  =>G_BRN_USR  ,
                                                          --P_E_SIGN_FLG 
                                                          P_C_CODE      =>G_C_Code,
                                                          P_FULL_FILE_PATH =>v_FULL_FILE_PATH,
                                                          P_FILE_UUID        =>V_FILE_UUID);
                                              
           EXCEPTION WHEN OTHERS THEN
                P_Msg_Txt := 'ERROR WHEN  Into IAS_ARCHIVES_DTL'||sqlerrm;
                P_ERR_NO  := 20717;
                Goto Rtn_Rslt;               
           END  ;
          --------------------------------------------------------------------                    
  --####################--
  <<RTN_RSLT>>
   If P_Msg_Txt Is Not Null OR P_Err_No IS NOT NULL Then
      Rollback;
      P_Msg_Txt := NVL(P_Msg_Txt,'Message Number Is Missing');
      P_Err_No := P_Err_No;
      P_Pkg_Nm := Nvl (P_Pkg_Nm, 'Ars_Api_Trns_Pkg.INSRT_ARCHIVES');
      Return;
   End If;
--####################--

Exception
   When Others Then
      Rollback;
      P_Msg_Txt := 'Error When Insert Into INSRT_ARCHIVES , ' || Chr(10) || Sqlerrm;
      P_Err_No := 20718;
      P_Pkg_Nm := Nvl (P_Pkg_Nm, 'Ars_Api_Trns_Pkg.INSRT_ARCHIVES');
End INSRT_ARCHIVES;                         
--##-----------------------------------------------------------------------------------------------------##--
Procedure Updt_Bill_Mst_Extnd (  P_Doc_Typ    In     Ias_Post_Mst.Doc_Type%Type 
                                ,P_Doc_Ser    In     Ias_Post_Mst.doc_ser%Type                                                 
                                ,P_Msg_Txt    Out Varchar2
                                ,P_ERR_NO   Out Varchar2
                                ,P_Pkg_Nm     Out Varchar2)
Is
V_cnt Number;
V_CLC_TYP_NO_TAX_INPT IAS_BILL_MST_EXTND.CLC_TYP_NO_TAX_INPT%Type; 
V_VAT_INPT_CAT_CODE IAS_BILL_MST_EXTND.VAT_INPT_CAT_CODE%Type ;
V_Vat_Cat_Code                 VARCHAR2(100);
V_Tax_cur_code                 Ex_Rate.Cur_Code%Type;
V_TAX_CUR_RATE                 Ex_Rate.Cur_Rate%Type;
Begin

 
If P_Doc_Typ=4 and  G_Pst_Typ = 2 Then

   If Nvl(G_Use_Vat,0) = 1 And NVL(IAS_BRN_PKG.IS_BRN_USE_E_INVC(P_BRN_NO => G_Brn_No), 0)  = 1 
                                  And Nvl(Ias_Cmp_Pkg.IS_CMP_USE_E_INVOICE(    P_BRN_NO    =>G_Brn_No  ),0)=1 Then
          Begin
              Select S_Tax_Typ_List.Tax_Cat_Code                   
                      Into V_Vat_Cat_Code                           
                From   S_Tax_Typ_List,
                       S_Tax_Typ_Actv
                Where  Cntry_2_Ltr_Code = upper(gnr_e_invc_op.get_cntry_code_by_cmp(Ias_Brn_Pkg.GET_BRN_MAIN_CMP(G_Brn_no),15))
                  And    Vat_Sts = 1
                  And    S_Tax_Typ_Actv.Tax_Code = S_Tax_Typ_List.Tax_Code
                  And    S_Tax_Typ_Actv.Tax_Cat_Code = S_Tax_Typ_List.Tax_Cat_Code
                  And    Bitand (VAT_TYP_SI, Power (2, Ys_Tax_Pkg.GET_CLC_TAX_TYP (G_Clc_Typ_No_Tax))) =  Power (2, Ys_Tax_Pkg.GET_CLC_TAX_TYP (G_Clc_Typ_No_Tax))
                  And    UPPER(S_Tax_Typ_Actv.Tax_Code) = UPPER('VAT') 
                  and rownum<=1;
               
          Exception When no_data_found then
            V_Vat_Cat_Code:=null;
          when Others Then
               P_Err_No    := 20732;         
               P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 6498)||chr(10)||sqlerrm;
              Goto Rtn_Rslt;             
          End; 
          
          V_Tax_cur_code := Ias_cmp_pkg.Get_tax_cur ( P_brn_no => G_Brn_no);
          If V_Tax_cur_code Is Not Null Then
            V_Tax_cur_rate := Ias_gen_pkg.Get_cur_rate ( P_acy => V_Tax_cur_code );
          End if; 
          
          Begin
            select CLC_TYP_NO into V_CLC_TYP_NO_TAX_INPT  from GNR_TAX_INPT_MOVMNT
              where doc_ser=P_Doc_Ser and DOC_TYPE=P_Doc_Typ
              and rownum<=1;
          exception when others then
             V_CLC_TYP_NO_TAX_INPT:=NULL;
          End;
          
          If V_CLC_TYP_NO_TAX_INPT Is Not Null Then 
             If V_CLC_TYP_NO_TAX_INPT=G_Clc_Typ_No_Tax Then
                   V_VAT_INPT_CAT_CODE:=V_Vat_Cat_Code;
             Else
                  Begin
                      Select S_Tax_Typ_List.Tax_Cat_Code                   
                              Into V_VAT_INPT_CAT_CODE                           
                        From   S_Tax_Typ_List,
                               S_Tax_Typ_Actv
                        Where  Cntry_2_Ltr_Code = upper(gnr_e_invc_op.get_cntry_code_by_cmp(Ias_Brn_Pkg.GET_BRN_MAIN_CMP(G_Brn_no),15))
                          And    Vat_Sts = 1
                          And    S_Tax_Typ_Actv.Tax_Code = S_Tax_Typ_List.Tax_Code
                          And    S_Tax_Typ_Actv.Tax_Cat_Code = S_Tax_Typ_List.Tax_Cat_Code
                          And    Bitand (VAT_TYP_SI, Power (2, Ys_Tax_Pkg.GET_CLC_TAX_TYP (V_CLC_TYP_NO_TAX_INPT))) =  Power (2, Ys_Tax_Pkg.GET_CLC_TAX_TYP (V_CLC_TYP_NO_TAX_INPT))
                          And    UPPER(S_Tax_Typ_Actv.Tax_Code) = UPPER('VAT') 
                          and rownum<=1;
                       
                  Exception When no_data_found then
                    V_VAT_INPT_CAT_CODE:=null;
                  when Others Then
                      P_Err_No    := 20733;         
                      P_Msg_Txt   := Ias_Gen_Pkg.Get_Msg (P_Lng_No => G_Lng_No, P_Msg_No => 6498)||chr(10)||sqlerrm;
                      Goto Rtn_Rslt;             
                  End; 
              end if; 
          end if; 
          
                                    
        End If;                                  
   --##------------------------------------------------------------------------------------##--
     Begin
      Update IAS_BILL_MST_EXTND set                                              
                         VAT_CAT_CODE=V_Vat_Cat_Code
                        ,TAX_CUR_CODE=V_TAX_CUR_CODE
                        ,TAX_CUR_RATE =V_TAX_CUR_RATE   
                        ,TAX_DUE_DATE=G_TAX_DUE_DATE
                        ,CLC_TYP_NO_TAX_INPT=NVL(V_CLC_TYP_NO_TAX_INPT,G_Clc_Typ_No_Tax)
                        ,VAT_INPT_CAT_CODE=NVL(V_VAT_INPT_CAT_CODE,V_Vat_Cat_Code)
                        ,BILL_TAX_STATUS=G_BILL_TAX_STATUS
                        where BILL_SER=p_doc_ser;
   Exception When Others then 
    Null;
   End;                         
End If;
--------------------------------------------------------------------                    
  --####################--
  <<RTN_RSLT>>
   If P_Msg_Txt Is Not Null OR P_Err_No IS NOT NULL Then
      Rollback;
      P_Msg_Txt := NVL(P_Msg_Txt,'Message Number Is Missing');
      P_Err_No := P_Err_No;
      P_Pkg_Nm := Nvl (P_Pkg_Nm, 'Ars_Api_Trns_Pkg.Updt_Bill_Mst_Extnd');
      Return;
   End If;
--####################--

Exception
   When Others Then
      Rollback;
      P_Msg_Txt := 'Error When Insert Into Updt_Bill_Mst_Extnd , ' || Chr(10) || Sqlerrm;
      P_Err_No := 20734;
      P_Pkg_Nm := Nvl (P_Pkg_Nm, 'Ars_Api_Trns_Pkg.Updt_Bill_Mst_Extnd');
End Updt_Bill_Mst_Extnd;                         
--##-----------------------------------------------------------------------------------------------------##--

Procedure Chk_Insrt_Data(P_Doc_Typ    In     Ias_Post_Mst.Doc_Type%Type
                           ,P_Doc_Ser    In     Sales_Order.Order_Ser%Type                           
                           ,P_Msg_Txt    Out Varchar2
                          , P_ERR_NO   Out Varchar2
                           ,P_Pkg_Nm     Out Varchar2 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          -- 1 # POST FORM  TABLE BR -- 0 # OTHERS
                                                             )
Is
   V_Cnt                Number;
   V_Fnd                Number := 0;
   V_Amt                Number := 0;
   V_Msg_No             Number;
   --V_SQL             VARCHAR2(6000);
   V_Doc_Amt            Number;  
   V_Vat_Amt_Dtl        Number;
   V_Vat_Amt_Mst        Number;
   V_Fld_Disc           Varchar2(4000);   
   V_Sql                Varchar2(4000);
   V_Tbl_Mst_Nm         Varchar2(2000);
   V_Tbl_Dtl_Nm         Varchar2(2000);
   V_Tbl_Tax_Mvmnt_Nm   Varchar2(500);
   V_Py                 Number;
   V_Clc_Rtrn_Doc       Number;
   V_Typ_No             Number;
   V_Fld_Doc_Ser        Varchar2(500);
   V_Fld_Doc_No         Varchar2(500);   
   V_Bill_Doc_Type      Number;
   V_Fld_Doc_Seq        Varchar2(500);
   V_Fld_Mst_Amt        Varchar2(500);
   V_Tbl_Inpt_Nm        Varchar2(500); 
   V_Tbl_INPT_Mvmnt_Nm  Varchar2(500); 
   V_BILL_TYPE          NUMBER; 
   V_WRNNG_Txt          Varchar2(4000); 
Begin
   --##------------------------------------------------------------------------------------------------------##--
   If G_Pst_Typ Is Null Then
      P_Err_No := 20253;
      P_Msg_Txt :=  'PST_TYP IS NULL ';
      Goto Rtn_Rslt;
   Elsif G_Pst_Typ Not In (1, 2) Then
      P_Err_No := 20254;
      P_Msg_Txt :=  'Pst_Typ Must Be Equal 1 Or 2 ';
      Goto Rtn_Rslt;
   End If;
   --##------------------------------------------------------------------------------------------------------##--
   V_Fld_Disc := 'NVL(D.DIS_AMT_MST,0)+NVL(D.DIS_AMT_DTL,0)';

   If G_Clc_Tax_Dscnt2 = 1 Then
      V_Fld_Disc := V_Fld_Disc || '+NVL(D.DIS_AMT_DTL2,0)';
   End If;

   If G_Clc_Tax_Dscnt3 = 1 Then
      V_Fld_Disc := V_Fld_Disc || '+NVL(D.DIS_AMT_DTL3,0)';
   End If;

   V_Fld_Disc := '(' || V_Fld_Disc || '+NVL(D.OTHR_AMT_DISC,0))';
   --##------------------------------------------------------------------------------------------------------##--
   If G_Doc_Typ = 53 Then
      V_Clc_Rtrn_Doc :=     0;
      V_Tbl_Tax_Mvmnt_Nm := 'GNR_RQ_TAX_ITM_MOVMNT';
      V_Tbl_Mst_Nm :=       'SALES_ORDER';
      V_Tbl_Dtl_Nm :=       'ORDER_DETAIL';
      V_Fld_Doc_Ser :=      'ORDER_SER';
      V_Fld_Doc_Seq :=      'D.DOC_SEQ';
      V_Fld_Doc_No :=       'ORDER_NO';
      V_Fld_Mst_Amt :=      'ORDER_AMT';
      V_Tbl_Inpt_Nm :=      'OTHER_CHARGES_OTHRS';
      V_Tbl_INPT_Mvmnt_Nm:='GNR_TAX_INPT_MOVMNT';
      V_Typ_No :=           G_So_Type;
      V_Bill_Doc_Type :=    G_Bill_Doc_Type; 
      V_BILL_TYPE:=53    ;
   ELSIf G_Doc_Typ = 52 Then
      V_Clc_Rtrn_Doc :=     0;
      V_Tbl_Tax_Mvmnt_Nm := 'GNR_RQ_TAX_ITM_MOVMNT';
      V_Tbl_Mst_Nm :=       'QUOTATION';
      V_Tbl_Dtl_Nm :=       'QUOTATION_DETAIL';
      V_Fld_Doc_Ser :=      'QUOT_SER';
      V_Fld_Doc_Seq :=      'D.DOC_SEQUENCE';
      V_Fld_Doc_No :=       'QUOT_NO';
      V_Fld_Mst_Amt :=      'QUOT_AMT';
      V_Tbl_Inpt_Nm :=      'OTHER_CHARGES_OTHRS';
      V_Tbl_INPT_Mvmnt_Nm:='GNR_TAX_INPT_MOVMNT';
      V_Typ_No :=           G_QT_Type;
      V_Bill_Doc_Type :=    G_Bill_Doc_Type; 
      V_BILL_TYPE:=52    ;   
      
   ELSIf G_Doc_Typ = 136 Then
      V_Clc_Rtrn_Doc :=     0;
      V_Tbl_Tax_Mvmnt_Nm := 'GNR_RQ_TAX_ITM_MOVMNT';
      V_Tbl_Mst_Nm :=       'IAS_RT_BILL_MST_RQ';
      V_Tbl_Dtl_Nm :=       'IAS_RT_BILL_DTL_RQ';
      V_Fld_Doc_Ser :=      'RT_BILL_SER';
      V_Fld_Doc_Seq :=      'D.DOC_SEQUENCE';
      V_Fld_Doc_No :=       'RT_BILL_NO';
      V_Fld_Mst_Amt :=      'BILL_AMT';
      V_Tbl_Inpt_Nm :=      'OTHER_CHARGES_OTHRS';
      V_Tbl_INPT_Mvmnt_Nm:='GNR_TAX_INPT_MOVMNT';
      V_Typ_No :=           G_SR_Type;
      V_Bill_Doc_Type :=    G_RT_Bill_Doc_Type; 
      V_BILL_TYPE:=136    ; 
      
      If G_P_Year = 2 Or (G_P_Year = 1 And Nvl(G_Use_Billno_Rtsale_Py, 0) = 0) Then
         V_Clc_Rtrn_Doc := 0;
      Else
         V_Clc_Rtrn_Doc := 1;
      End If;   
     
   Elsif G_Doc_Typ = 4 Then
      If Nvl(G_Pst_Typ, 0) = 2 Then
         V_Tbl_Tax_Mvmnt_Nm := 'GNR_TAX_ITM_MOVMNT';
         V_Tbl_Mst_Nm :=       'IAS_BILL_MST';
         V_Tbl_Dtl_Nm :=       'IAS_BILL_DTL';
         V_Tbl_Inpt_Nm :=      'OTHER_CHARGES';
         V_Tbl_INPT_Mvmnt_Nm:='GNR_TAX_INPT_MOVMNT';
      Elsif Nvl(G_Pst_Typ, 0) = 1 Then
         V_Tbl_Tax_Mvmnt_Nm := 'GNR_TAX_ITM_MOVMNT_BR';
         V_Tbl_Mst_Nm :=       'IAS_BILL_MST_BR';
         V_Tbl_Dtl_Nm :=       'IAS_BILL_DTL_BR';
         V_Tbl_Inpt_Nm :=      'OTHER_CHARGES_BR';
         V_Tbl_INPT_Mvmnt_Nm:='GNR_TAX_INPT_MOVMNT_BR';
      End If;

      V_Fld_Doc_Ser :=    'BILL_SER';
      V_Fld_Doc_No :=     'BILL_NO';
      V_Fld_Mst_Amt :=    'BILL_AMT';
      V_Fld_Doc_Seq :=    'D.DOC_SEQUENCE';
      V_Clc_Rtrn_Doc :=   0;
      V_Typ_No :=         G_Si_Type;
      V_Bill_Doc_Type :=  G_Bill_Doc_Type;
      V_BILL_TYPE:=1;     
     
   Elsif G_Doc_Typ = 5 Then
      If Nvl(G_Pst_Typ, 0) = 2 Then
         V_Tbl_Tax_Mvmnt_Nm := 'GNR_TAX_ITM_MOVMNT';
         V_Tbl_Mst_Nm :=       'IAS_RT_BILL_MST';
         V_Tbl_Dtl_Nm :=       'IAS_RT_BILL_DTL';
         V_Tbl_Inpt_Nm :=      'OTHER_CHARGES';
         V_Tbl_INPT_Mvmnt_Nm:='GNR_TAX_INPT_MOVMNT';
      Elsif Nvl(G_Pst_Typ, 0) = 1 Then
         V_Tbl_Tax_Mvmnt_Nm := 'GNR_TAX_ITM_MOVMNT_BR';
         V_Tbl_Mst_Nm :=       'IAS_RT_BILL_MST_BR';
         V_Tbl_Dtl_Nm :=       'IAS_RT_BILL_DTL_BR';
         V_Tbl_Inpt_Nm :=      'OTHER_CHARGES_BR';
         V_Tbl_INPT_Mvmnt_Nm :='GNR_TAX_INPT_MOVMNT_BR';
      End If;

      V_Typ_No :=         G_Sr_Type;
      V_Bill_Doc_Type :=  G_Rt_Bill_Doc_Type;
      V_Fld_Doc_Ser :=    'RT_BILL_SER';
      V_Fld_Doc_No :=     'RT_BILL_NO';
      V_Fld_Mst_Amt :=    'BILL_AMT';
      V_Fld_Doc_Seq :=    'D.DOC_SEQUENCE'; 
      V_BILL_TYPE:=3;   

      If G_P_Year = 2 Or (G_P_Year = 1 And Nvl(G_Use_Billno_Rtsale_Py, 0) = 0) Then
         V_Clc_Rtrn_Doc := 0;
      Else
         V_Clc_Rtrn_Doc := 1;
      End If;
   End If;  
    G_Bill_Doc_Type:=V_Bill_Doc_Type; 
    G_Tbl_Mst_Nm  :=V_Tbl_Mst_Nm;
    G_Fld_Doc_Ser :=V_Fld_Doc_Ser ;   
   --##--------------------------------------------------------------------------------------------------------##--   
   If  Nvl(Ias_Brn_Pkg.Is_Brn_Use_E_Invc(P_Brn_No => G_Brn_No), 0)  = 1 
          And Nvl(Ias_Cmp_Pkg.Is_Cmp_Use_E_Invoice(    P_Brn_No    =>G_Brn_No  ),0)=1  And  G_Doc_Typ In(4,5) Then
         Begin
         Ars_Api_Chk_Pkg.Chk_Sale_Outlet (P_Sys_No    => G_SYS_NO,
                                          P_Cc_Code   => G_Cc_Code,
                                          P_Lang      => G_Lng_No,
                                          P_Msg_Txt   => P_Msg_Txt,
                                          P_Err_No    => P_Err_No,
                                          P_Pkg_Nm    => P_Pkg_Nm);
          Exception
             When Others Then
                     Null ;
          End;
     
        If P_Msg_Txt Is Not Null Then      
           Goto Rtn_Rslt;
        End If;
    End If;     
   --##--------------------------------------------------------------------------------------------------------##--   
   --## UPDATE DISC  
   Begin
        ARS_API_CHK_PKG.Updt_Bill_Disc_Prc( P_Doc_Typ             => G_Doc_Typ,
                                                 P_Pst_Typ             => G_Pst_Typ,
                                                 P_Doc_Ser             => G_Doc_Ser,
                                                 P_Use_Vat             => G_Use_Vat,
                                                 P_Bill_Doc_Type       =>G_Bill_Doc_Type,
                                                 P_Clc_Vat_Price_Typ   => G_Clc_Vat_Price_Typ,
                                                 P_Clc_Typ_No_Tax      => G_Clc_Typ_No_Tax,
                                                 P_CALC_TAX_AUTO_FLG   =>G_CALC_TAX_AUTO_FLG,
                                                 P_Fld_Doc_Ser         => V_Fld_Doc_Ser,
                                                 P_Tbl_Mvmnt_Nm        => V_Tbl_Tax_Mvmnt_Nm,
                                                 P_Tbl_Mst_Nm          => V_Tbl_Mst_Nm,
                                                 P_Tbl_Dtl_Nm          => V_Tbl_Dtl_Nm,
                                                 P_Fld_MST_AMT         => V_Fld_Mst_Amt,
                                                 P_DIFF_AMT            => G_DIFF_AMT,
                                                 P_Msg_Txt             => P_Msg_Txt,
                                                 P_ERR_NO              => P_Err_No,
                                                 P_Pkg_Nm              => P_Pkg_Nm);
   Exception
      When Others Then
         P_Err_No := 20255;
         P_Msg_Txt :=  'Err. Updt_Bill_Disc_Prc ' || Chr(10) || Sqlerrm;
         Goto Rtn_Rslt;
   End;

   If P_Msg_Txt Is Not Null Then      
      Goto Rtn_Rslt;
   End If;
   --##--------------------------------------------------------------------------------------------------------##--
   --## Calc_Other_Charges AUTO 
   IF   NVL(G_CALC_OTHER_CHRG,0)=1  Then 
     ARS_API_CHK_PKG.Calc_Other_Charges (P_Doc_Typ =>G_Doc_TYP
                             ,P_Bill_Doc_Type    =>V_Bill_Doc_Type
                             ,P_Doc_Ser          =>G_Doc_Ser
                             ,P_Doc_Date         =>G_Doc_Date
                             ,P_Brn_No           =>G_Brn_No
                             ,P_Use_Vat          =>G_Use_Vat
                             ,P_Cur_Code         =>G_Cur_Code
                             ,P_Cur_Rate         =>G_Cur_Rate
                             ,P_Clc_Typ_No_Tax   =>G_Clc_Typ_No_Tax
                             ,P_Fld_Doc_Ser      =>V_Fld_Doc_Ser
                             ,P_Fld_Mst_Amt      =>V_Fld_Mst_Amt                            
                             ,P_Tbl_Mst_Nm       =>V_Tbl_Mst_Nm                            
                             ,P_No_Of_Decimal    =>G_No_Of_Decimal_Ar
                             ,P_Lng_No           =>G_Lng_No
                             ,P_Msg_Txt          =>P_Msg_Txt
                             ,P_Err_No           =>P_Err_No
                             ,P_Pkg_Nm           =>P_Pkg_Nm);
          
                             
                             
       If P_Msg_Txt Is Not Null Then      
         Goto Rtn_Rslt;
        End If;
        
       If  Nvl(G_Use_Vat, 0) = 1 AND G_Clc_Typ_No_Tax Is Not Null  Then 
         BEGIN
          Ys_Tax_Pkg.Clc_Inpt_Tax_Aftr_Save (  P_Clc_Typ_No        => G_Clc_Typ_No_Tax              ,             
                                               P_Doc_Typ           => G_DOC_TYP                                         , -- Doc_Type In  Ias_Sys.Ias_Docjv_Type_Systems                                
                                               P_Doc_No            => G_DOC_NO                     ,             
                                               P_Doc_Ser           => G_DOC_SER                    ,             
                                               P_Bill_Doc_Typ      => V_Bill_Doc_Type               ,             
                                               P_Doc_Jv_Typ        => V_Typ_No                    ,             
                                               P_Doc_Date          => G_DOC_Date                   ,                                                                                            
                                               P_Doc_Due_Date      => G_Doc_Due_Date              ,             
                                               P_Tax_Due_Date      => G_Tax_Due_Date         ,
                                               P_Bill_tax_status   => Nvl(G_BILL_TAX_STATUS ,1)     ,
                                               P_Brn_No            => G_Brn_No                      ,            
                                               P_A_Cy              => G_Cur_Code               ,             
                                               P_Ac_Rate           => G_Cur_Rate                   ,
                                               P_Tbl_Inpt_Nm       => V_Tbl_Inpt_Nm                          ,             
                                               P_Tbl_Mst_Nm        => V_Tbl_Mst_Nm                           ,             
                                               P_Tbl_Dtl_Nm        => V_Tbl_Dtl_Nm                           ,             
                                               P_Fld_Doc_Ser       => V_Fld_Doc_Ser                                ,             
                                               P_FLD_DOC_AMT       => V_Fld_Mst_Amt                                ,
                                               P_Fld_Base_Amt      => CASE WHEN G_DOC_TYP IN(4,5) THEN 'SC_BASE_AMT' ELSE NULL END ,              
                                               P_Fld_Doc_Ser_Inpt  => 'M.BILL_SER'                             ,             
                                               P_Fld_Tax_A_Code    => 'TD.AC_CODE_AR'                           ,             
                                               P_Inpt_Typ          => 1                                         ,             
                                               P_Fld_Inpt_Code     => 'M.SC_NO'                                 ,             
                                               P_Fld_Inpt_Amt      => 'M.AMT'                                   ,
                                               P_Fld_Doc_Seq       => Null                                      ,
                                               P_Clc_Doc_Typ       => 1                                         ,-- CLC_DOC_TYP  1= SALES ,2 = PURCHASE ,
                                               P_Lng_No            => G_LNG_NO                                  ,
                                               P_DR_CR_FLG         =>G_DR_CR_FLG                      );                                 
            Exception When No_Data_Found Then 
              Null;
            When Others Then
                   P_Err_No := 20445;
                   P_Msg_Txt :=  'Err. WHEN Clc_Inpt_Tax_Aftr_Save' || Chr(10) || Sqlerrm;
                   Goto Rtn_Rslt;                                                 
            End;
         End If;                              
   END IF;
   --##--------------------------------------------------------------------------------------------------------##--
   --## Update_Other_Charges   
          ARS_API_CHK_PKG.Update_Other_Charges (
                                    P_Doc_Typ             =>G_Doc_TYP
                                   ,P_Doc_Ser             =>G_DOC_SER
                                   ,P_Use_Vat             =>G_Use_Vat
                                   ,P_Clc_Typ_No_Tax      =>G_Clc_Typ_No_Tax
                                   ,P_No_Of_Decimal       =>G_No_Of_Decimal_Ar
                                   ,P_Bill_Type           =>V_Bill_Type
                                   ,P_CALC_TAX_AUTO_FLG   =>G_CALC_TAX_AUTO_FLG
                                   ,P_Fld_Doc_Ser         =>V_Fld_Doc_Ser
                                   ,P_TBL_OTHER_CHRG_NM   =>V_Tbl_Inpt_Nm
                                   ,P_Tbl_INPT_Mvmnt_Nm   =>V_Tbl_INPT_Mvmnt_Nm                                  
                                   ,P_Tbl_Mst_Nm          => V_Tbl_Mst_Nm
                                   ,P_Tbl_Dtl_Nm          => V_Tbl_Dtl_Nm
                                   ,P_Fld_MST_AMT         => V_Fld_Mst_Amt
                                   ,P_DIFF_AMT            => G_DIFF_AMT
                                   ,P_Msg_Txt             => P_Msg_Txt
                                   ,P_ERR_NO              => P_Err_No
                                   ,P_Pkg_Nm              => P_Pkg_Nm);
               If P_Msg_Txt Is Not Null Then      
                  Goto Rtn_Rslt;
               End If;                                       
  --##--------------------------------------------------------------------------------------------------------##--                                
   -- set amt tax
   --##--------------------------------------------------------------------------------------------------------##--
   --## INSER ITAX_ITM_MOVMNT   
    If Nvl(G_Use_Vat, 0) = 1 AND G_Clc_Typ_No_Tax Is Not Null AND NVL(G_CALC_TAX_AUTO_FLG,0)=1 THEN          
         Begin
            Ys_Tax_Pkg.Clc_Itm_Tax_Aftr_Save(P_Clc_Typ_No          => G_Clc_Typ_No_Tax,
                                             P_Doc_Typ             => G_Doc_Typ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         -- Doc_Type In  Ias_Sys.Ias_Docjv_Type_Systems
                                             P_Doc_No              => G_Doc_No,
                                             P_Doc_Ser             => G_Doc_Ser,
                                             P_Bill_Doc_Typ        => V_Bill_Doc_Type,
                                             P_Doc_Jv_Typ          => V_Typ_No,
