                                             P_Fld_Stk_Cost        => 'NVL(D.STK_COST,0)',
                                             P_Fld_Doc_Seq         => V_Fld_Doc_Seq,
                                             P_Clc_Doc_Typ         => 1,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       -- CLC_DOC_TYP  1= SALES ,2 = PURCHASE ,
                                             P_Lng_No              => G_Lng_No,
