               Goto Rtn_Rslt;
        END;*/
   Elsif Nvl(G_Use_Vat, 0) = 1 AND G_Clc_Typ_No_Tax Is Not Null Then
     UPDATE_TAX_ITM_MOVMNT (P_Clc_Typ_No        =>G_Clc_Typ_No_Tax
