                           ,P_Tax_Due_Date      =>G_Tax_Due_Date
                           ,P_Bill_Tax_Status   =>Nvl(G_BILL_TAX_STATUS,1)
                           ,P_Tbl_Mvmnt_Nm     =>V_Tbl_Tax_Mvmnt_Nm
                           ,P_Tbl_Mst_Nm       =>V_Tbl_Mst_Nm
                           ,P_Tbl_Dtl_Nm        =>V_Tbl_Dtl_Nm
                           ,P_Fld_Doc_Ser      =>V_Fld_Doc_Ser
                           ,P_Fld_Doc_Seq      =>V_Fld_Doc_Seq
                           ,P_Lng_No           =>G_Lng_No
