   --##-----------------------------------------------------------------------------------------------------##--
   --## CHECK DOC AMT
    ARS_API_CHK_PKG.Chk_Amt_And_Itm_Tax(   P_Clc_Typ_No_Tax      => G_Clc_Typ_No_Tax,
                                           P_Use_Vat               => G_Use_Vat,
                                           P_CLC_TAX_FREE_QTY_FLG  =>G_CLC_TAX_FREE_QTY_FLG, 
                                           P_Calc_Vat_Amt_Type   => G_Calc_Vat_Amt_Type,
                                           P_CALC_TAX_AUTO_FLG   => G_CALC_TAX_AUTO_FLG,
                                           P_Doc_Typ             => G_Doc_Typ,
