   --##-----------------------------------------------------------------------------------------------------##--
     ARS_API_CHK_PKG.Chk_Credit_Limit(P_Chk_Crdt_Lmit   => G_CHK_CRDT_LMIT,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             --## 0 UNCHECKCredit_Limit  1- CHECK Credit_Limit
                                        P_Doc_Date        => G_Doc_Date,
