                                        P_Pkg_Nm          => P_Pkg_Nm);

   If P_Msg_Txt Is Not Null Then
      Goto Rtn_Rslt;
   End If;
   --##-----------------------------------------------------------------------------------------------------##--
   --##Check Limit Sales Amt and qty
   If G_DOC_TYP =4  Then
              IF (Nvl(G_SYS_NO,0)=70  And nvl(G_DTS_ONLINE,0)=0 ) --- DTS Offline
                Or Nvl(G_SYS_NO,0)=185                           ---STN
                or nvl(G_COMMIT_FLG,0)=0  Then -- Offline
               Null ;
             Else      
                     Ars_Gnr_Pkg.Chk_Cst_Sls_Lmt (P_Bill_Ser       =>G_Doc_Ser
                                                 ,P_Bill_Date      =>G_Doc_Date
                                                 ,P_C_Code         =>G_C_Code
                                                 ,P_No_Of_Decimal  =>G_No_Of_Decimal_Ar
                                                 ,P_User_No        =>G_Ad_U_Id             
                                                 ,P_Lng_No         =>G_Lng_No
                                                 ,P_Msg_Txt        =>P_Msg_Txt);
             If P_Msg_Txt Is Not Null Then
              P_Err_No:=20653;      
              Goto Rtn_Rslt;
             End If;                                       
     End If;                                  
   End If;
   --##-----------------------------------------------------------------------------------------------------##--
   --## UPDATE SALES MAN Comm
    If G_SHW_ITM_COMM_PER = 1 AND G_DOC_TYP IN(4,5) Then
    
      BEGIN 
          EXECUTE IMMEDIATE
          '  Update '||V_Tbl_DTL_Nm||'  
              Set Comm_Amt_Dtl= (Nvl(Comm_Per,0)*(i_price-Nvl(Dis_Amt_Mst,0)-Nvl(Dis_Amt_Dtl,0)-Nvl(Dis_Amt_Dtl2,0)-Nvl(Dis_Amt_Dtl3,0)))/100
            Where '||V_Fld_Doc_Ser||'='||G_Doc_Ser||'
              And Nvl(Comm_Per,0)<>0
              AND NVL(I_PRICE,0)>0 ' ;
      EXCEPTION WHEN NO_DATA_FOUND THEN
          NULL;
        WHEN OTHERS THEN
               P_Err_No := 20643;
               P_Msg_Txt :=  'Err. WHEN UPDATE '||V_Tbl_DTL_Nm||' Comm_Per' || Chr(10) || Sqlerrm;
               Goto Rtn_Rslt;
      END;
                           
      BEGIN
        EXECUTE IMMEDIATE
         ' Update '||V_Tbl_MST_Nm||'  Set Comm_Amt_Dtl=(Select Round(Nvl(Sum(I_Qty*nvl(comm_Amt_Dtl,0)),0),'||G_No_Of_Decimal_Ar||')
                                                   From '||V_Tbl_DTL_Nm||'
                                                  Where '||V_Fld_Doc_Ser||'='||G_Doc_Ser||')          
               Where '||V_Fld_Doc_Ser||'='||G_Doc_Ser||' ';
      EXCEPTION WHEN NO_DATA_FOUND THEN
         NULL;
      WHEN OTHERS THEN
           P_Err_No := 20644;
           P_Msg_Txt :=  'Err. WHEN UPDATE '||V_Tbl_MST_Nm||' Comm_Amt_Dtl' || Chr(10) || Sqlerrm;
           Goto Rtn_Rslt;
       END;  
   END IF;
 --##-----------------------------------------------------------------------------------------------------##--     
   --## Insrt_Apprvd_Lvl
     IF NVL(G_Use_Apprvd_Flg,0)=1 THEN
               Begin
                  Ys_Apprvd_Pkg.Insrt_Apprvd_Lvl (P_Doc_Typ    => G_DOC_TYP
                                                 ,P_Doc_Ser    => G_Doc_Ser
                                                 ,P_Doc_No     => G_Doc_No
                                                 ,P_Jv_Typ     => V_Typ_No
                                                 ,P_Doc_Date   => G_Doc_Date
                                                 ,P_Cmp_No     => G_Cmp_No
                                                 ,P_Brn_No     => G_Brn_No
                                                 ,P_Brn_Year   => G_Brn_Year
                                                 ,P_Brn_Usr    => G_Brn_Usr
                                                 ,P_Ad_U_id  =>g_ad_u_id   
                                                 ,P_Ad_Date =>g_ad_date );
               Exception
                  When Others Then
                      P_Err_No := 20258;
                      P_Msg_Txt :=  'Error In Insrt Apprvd Lvl '|| Sqlerrm;
                      P_Pkg_Nm  :=' Ys_Apprvd_Pkg.Insrt_Apprvd_Lvl';
                      Goto Rtn_Rslt;                   
               End; 
               IF G_SYS_NO=70 THEN
                  DECLARE
                    V_AUTO_APPRVD_QTN NUMBER(2):=0;
                    V_AUTO_APPRVD_SO  NUMBER(2):=0;
                   BEGIN
                           BEGIN 
                              EXECUTE IMMEDIATE 'SELECT AUTO_APPRVD_QTN, AUTO_APPRVD_SO FROM DTS_PARA 'INTO V_AUTO_APPRVD_QTN,V_AUTO_APPRVD_SO; 
                           EXCEPTION WHEN OTHERS THEN
                              P_Err_No := 20454;
                              P_Msg_Txt :=  'Error GET DTS_PARA '|| Sqlerrm;                      
                              Goto Rtn_Rslt;
                           END; 
                      IF (G_DOC_TYP=53 AND NVL(V_AUTO_APPRVD_SO,0)=1) OR (G_DOC_TYP=52 AND NVL(V_AUTO_APPRVD_QTN,0)=1) THEN
                         BEGIN
                                   Ys_Apprvd_Pkg.Auto_Apprvl_Lvl_Prc(   P_Doc_Typ      =>G_DOC_TYP, 
                                                                        P_Doc_Srl      =>G_Doc_Ser,
                                                                        P_Tbl_Nm       =>V_Tbl_Mst_Nm,
                                                                        P_Srl_Fld_Nm   =>V_Fld_Doc_Ser,
                                                                        P_Ad_U_Id      =>G_Ad_U_Id);
                         Exception When Others Then
                              P_Err_No := 20455;
                              P_Msg_Txt :=  'Error In Insrt Auto_Apprvl_Lvl_Prc '|| Sqlerrm;
                              P_Pkg_Nm  :=' Ys_Apprvd_Pkg.Auto_Apprvl_Lvl_Prc';
                              Goto Rtn_Rslt;
                         END;
                      END IF;
                   END;                                                                              
               END IF;
     END IF;             
   --##-----------------------------------------------------------------------------------------------------##--
       If G_Doc_Typ = 4 THEN
          Begin
                 Execute Immediate ' Update Ias_Reserve_Dtl a
                     Set Cp_Qty = ( Select Nvl(a.P_Qty,0) - Nvl(Sum(Nvl(P_Qty,0)+ (Nvl(Free_qty,0)*nvl(p_size,1))),0)
                                     From '||V_Tbl_DTL_Nm|| ' 
                                     Where Doc_Type_Ref       =  53
                                                           And Doc_No_Ref         =  a.Doc_No_Ref
                                                           And Doc_Ser_Ref        =  a.Doc_Ser_Ref         
                                                           And I_Code             =  a.I_Code 
                                                           And Nvl(Rcrd_No_Ref,0) =  Nvl(a.Rcrd_No,Nvl(Rcrd_No_Ref,0)))
                   Where Doc_Type_Ref = 53
                     And Doc_Ser_Ref In (Select Doc_Ser_Ref From '||V_Tbl_DTL_Nm||'  
                                                    where Bill_ser='||G_Doc_Ser|| '
                                                      and Doc_type_Ref=53) ';
          Exception when others then 
            Null;
          End; 
        End If; 
      --##-----------------------------------------------------------------------------------------------------##--      
      --## INSER INSTALLMENT
        IF G_Doc_Typ = 4 AND  NVL(G_Bill_Doc_Type,0)=4 THEN
           IF  NVL(G_INSRT_INSTALLMENT_FLG,0)=1 THEN  
              Begin
                 Insrt_Installment(P_Bill_Doc_Type   => G_Bill_Doc_Type,
                                   P_Doc_Ser         => G_DOC_Ser,
                                   P_Pymnt_Ac        => Null,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                   P_Ac_Dtl_Typ      => G_Ac_Dtl_Typ,
                                   P_No_Of_Decimal   => G_No_Of_Decimal_Ar,
                                   P_Pst_Typ         => G_Pst_Typ,
                                   P_Lng_No          => G_Lng_No,
                                   P_Msg_Txt         => P_Msg_Txt,
                                   P_ERR_NO        => P_Err_No,
                                   P_Pkg_NM           => P_Pkg_Nm);

                 If P_Msg_Txt Is Not Null Then           
                    Goto Rtn_Rslt;
                 End If;
              End;
           ELSIF  NVL(G_INSRT_INSTALLMENT_FLG,0)=2 THEN  
              Insert_Installemnt_FBR (P_Doc_Type    =>G_DOC_TYP,
                                      P_BillNo      =>G_DOC_NO,
                                      P_billdoctype =>G_Bill_Doc_Type,
                                      P_BillSer     =>G_DOC_Ser,
                                      P_Billdate    =>G_DOC_DATE,
                                      P_User_Id     =>G_AD_U_ID,
                                      P_billcur     =>G_CUR_CODE,
                                      P_CashNo      =>G_Cash_No,
                                      P_ccode       =>G_C_CODE,
                                      P_Typ         => 'D',
                                      P_Msg_Txt     => P_Msg_Txt,
                                      P_ERR_NO    => P_Err_No,
                                      P_Pkg_NM      => P_Pkg_Nm);
               If P_Msg_Txt Is Not Null Then           
                    Goto Rtn_Rslt;
               End If;
           END IF;                             
              
        END IF;      
   --##-------------------------------------------------------------------------------------##--
     If G_Pst_Typ = 2 And G_Doc_Typ In (4, 5) Then
         
          Begin
            Ars_insrt_Crdt_Crd_Prc (P_Doc_Type =>G_Doc_Typ, P_Doc_Ser=>G_Doc_Ser);
           Exception
             When No_Data_Found Then
                Null;
             When Others Then
                 Rollback;
                 P_Err_No := 20681;
                 P_Msg_Txt :=  'Error Insert Ars_Bill_Crdt_Crd '|| Sqlerrm;
                 P_Pkg_Nm  :='Ars_insrt_Crdt_Crd_Prc';
                 Goto Rtn_Rslt;           
          End; 
     End if; 
   --##------------------------------------------------------------------------------------##--
   If G_Doc_Typ = 4 And G_Pst_Typ = 2 Then      
      --## INSERT Out_Bills IF USE
      If Nvl(G_Use_Out_Bills, 0) = 1 AND NVL(G_INSRT_OUT_BILLS_FLG,0)=1 Then 
            
          If G_OUT_Ser Is Null Then
             P_Err_No := 20421;
             P_Msg_Txt:=  'G_OUT_Ser IS NULL ';
             Goto Rtn_Rslt;
          End If; 
                 
         Begin
            Ias_Insrt_Out_Bills_Pkg.Insrt_Out_Bills(P_Invs          => G_Invoicing_Serials,
                                                    P_Doc_Ser       => G_Doc_Ser,
                                                    P_Out_No        => G_Out_No,
                                                    P_Out_Ser       => G_Out_Ser,
                                                    P_Extrnl_Post   => G_External_Post,
                                                    P_Lang_No       => G_Lng_No,
                                                    P_Brn_No        => G_Brn_No);
         Exception
            When Others Then
                   P_Err_No := 20260;
                   P_Msg_Txt :=  'Err. When Insrt Into Out_Bills '|| Sqlerrm;
                   P_Pkg_Nm  :='Ias_Insrt_Out_Bills_Pkg.Insrt_Out_Bills';
                   Goto Rtn_Rslt;
          
         End;
         ---------------------------------------
         Update_Si_Out_Qty(P_doc_Type =>4
                            ,P_Doc_No =>G_Doc_Ser
                            ,P_Doc_Ser=>G_Doc_Ser  );
          ---------------------------------------                            
          Begin
             Ias_Post_In_Sav_Pkg.Post_Doc_In_Sav(G_Doc_Type    => 13,
                                                 G_Doc_Ser     => G_Out_Ser,
                                                 P_Jv_Type     => V_Bill_Doc_Type,
                                                 P_Doc_No      => G_Out_No,
                                                 P_Lang_No     => Nvl(G_Lng_No, 1),
                                                 P_User_No     => G_Ad_U_Id,
                                                 G_Post_Type   => 0);
          Exception
             When No_Data_Found Then
                Null;
             When Others Then
                 Rollback;
                 P_Err_No := 20420;
                 P_Msg_Txt :=  'Error When Updating Post In Out_Bills '|| Sqlerrm;
                 P_Pkg_Nm  :='Ias_Post_In_Sav_Pkg.Post_Doc_In_Sav';
                 Goto Rtn_Rslt;           
          End;

         Begin
            Update Item_Movement M
               Set Dis_Amt      = (Select Dis_Amt
                                     From Detail_Out_Bills D
                                    Where M.Out_Gr_Ser = D.Out_Ser
                                          And M.I_Code = D.I_Code
                                          And M.Doc_Sequence = D.Doc_Sequence)
             Where Doc_Ser = G_DOC_Ser;
         Exception
            When Others Then
               Null;
         End;          
      ELSE
         Begin
            Update Item_Movement M
               Set Dis_Amt      = (Select Dis_Amt
                                     From Ias_Bill_Dtl D
                                    Where M.Doc_Ser = D.Bill_Ser
                                          And M.I_Code = D.I_Code
                                          And M.Doc_Sequence = D.Doc_Sequence)
             Where Doc_Ser = G_Doc_Ser;
         Exception
            When Others Then
               Null;
         End;
      End If;
   --##-------------------------------------------------------------------------------------##--
   END IF;
   
   IF G_Doc_Typ = 5 And G_Pst_Typ = 2 Then
        IF Nvl(G_Use_Out_Bills, 0) = 1 AND NVL(G_INSRT_OUT_BILLS_FLG,0)=1 And nvl(G_P_Year,0)<>3 Then
          If G_Ret_Ser Is Null Then
             P_Err_No := 20261;
             P_Msg_Txt :=  'G_RET_SER IS NULL ';
             Goto Rtn_Rslt;
          End If;             
             --#########################--
               --THIS CODE BELUE  MUST BE RWRITE 
             --#######################--
          If G_P_Year = 0 Then
             V_Py := 2;
          Else
             V_Py := G_P_Year;
          End If;
          --##-------------------------------------------------------------------------------------##--     
          Begin
             Ias_Insrt_Out_Bills_Pkg.Insrt_Ret_Bills(P_Invs_Sr       => G_Invoicing_Serials_Sr,
                                                     P_Pyear         => V_Py,
                                                     P_Doc_Ser       => G_Doc_Ser,
                                                     P_Ret_No        => G_Ret_No,
                                                     P_Ret_Ser       => G_Ret_Ser,
                                                     P_Out_No        => Null, --V_Out_No              ,,
                                                     P_Out_Ser       => Null , --V_Out_Ser               ,
                                                     P_Extrnl_Post   => G_External_Post,
                                                     P_Lang_No       => G_Lng_No,
                                                     P_Brn_No        => G_Brn_No);
          Exception
             When Others Then
                   P_Err_No := 20263;
                   P_Msg_Txt :=  'Error When Insert Into Insrt_Ret_Bills Tables '|| Sqlerrm;
                   P_Pkg_Nm  :='Ias_Insrt_Out_Bills_Pkg.Insrt_Ret_Bills';
                   Goto Rtn_Rslt;           
          End;
           ---------------------------------------
            Update_Si_Out_Qty(P_doc_Type =>5
                            ,P_Doc_No =>G_Doc_Ser
                            ,P_Doc_Ser=>G_Doc_Ser  );
          ---------------------------------------  
          
          Begin
             Ias_Post_In_Sav_Pkg.Post_Doc_In_Sav(G_Doc_Type    => 14,
                                                 G_Doc_Ser     => G_Ret_Ser,
                                                 P_Jv_Type     => V_Bill_Doc_Type,
                                                 P_Doc_No      => G_Ret_No,
                                                 P_Lang_No     => Nvl(G_Lng_No, 1),
                                                 P_User_No     => G_Ad_U_Id,
                                                 G_Post_Type   => 0);
          Exception
             When No_Data_Found Then
                Null;
             When Others Then
                 Rollback;
                 P_Err_No := 20420;
                 P_Msg_Txt :=  'Error When Updating Post In Ret_Bills '|| Sqlerrm;
                 P_Pkg_Nm  :='Ias_Post_In_Sav_Pkg.Post_Doc_In_Sav';
                 Goto Rtn_Rslt;           
          End;

          Begin
             Update Gr_Detail M
                Set Dis_Amt      = (Select Dis_Amt
                                      From Ias_Ret_Bill_Dtl D
                                     Where M.G_Ser = D.Ret_Ser
                                           And M.I_Code = D.I_Code
                                           And M.Doc_Sequence = D.Doc_Sequence)
              Where G_Ser = G_Ret_Ser;
          Exception
             When Others Then
                Null;
          End;

          Begin
             Update Item_Movement M
                Set Dis_Amt      = (Select Dis_Amt
                                      From Ias_Ret_Bill_Dtl D
                                     Where M.Out_Gr_Ser = D.Ret_Ser
                                           And M.I_Code = D.I_Code
                                           And M.Doc_Sequence = D.Doc_Sequence)
              Where Doc_Ser = G_Doc_Ser;
          Exception
             When Others Then
                Null;
          End;
        ELSE
          Begin
             Update Gr_Detail M
                Set Dis_Amt      = (Select Dis_Amt
                                      From Ias_Rt_Bill_Dtl D
                                     Where M.Doc_Ser = D.Rt_Bill_Ser
                                           And M.I_Code = D.I_Code
                                           And M.Doc_Sequence = D.Doc_Sequence)
              Where Doc_Ser = G_Doc_Ser;
          Exception
             When Others Then
                Null;
          End;

          Begin
             Update Item_Movement M
                Set Dis_Amt      = (Select Dis_Amt
                                      From Ias_Rt_Bill_Dtl D
                                     Where M.Doc_Ser = D.Rt_Bill_Ser
                                           And M.I_Code = D.I_Code
                                           And M.Doc_Sequence = D.Doc_Sequence)
              Where Doc_Ser = G_Doc_Ser;
          Exception
             When Others Then
                Null;
          End;
        End If;
   End If;
   --##-------------------------------------------------------------------------------------##--
   --## PSTING
   If G_Pst_Typ = 2 And G_Doc_Typ In (4, 5) Then 
      
       Updt_Bill_Mst_Extnd (  P_Doc_Typ      =>G_doc_Typ
                                ,P_Doc_Ser   =>G_Doc_Ser                                               
                                ,P_Msg_Txt   =>P_Msg_Txt
                                ,P_ERR_NO    =>P_ERR_NO
                                ,P_Pkg_Nm    =>P_ERR_NO)  ;
       If P_Msg_Txt Is Not Null Then           
            Goto Rtn_Rslt;
       End If;                                       
        
      Begin
         Ias_Post_In_Sav_Pkg.Post_Doc_In_Sav(G_Doc_Type    => G_Doc_Typ,
                                             G_Doc_Ser     => G_Doc_Ser,
                                             P_Jv_Type     => V_Bill_Doc_Type,
                                             P_Doc_No      => G_Doc_No,
                                             P_Lang_No     => Nvl(G_Lng_No, 1),
                                             P_User_No     => G_Ad_U_Id,
                                             G_Post_Type   => 0);
      Exception
         When No_Data_Found Then
            Null;
         When Others Then
             Rollback;
             P_Err_No := 20264;
             P_Msg_Txt :=  'Error When Updating Post In Bills '|| Sqlerrm;
             P_Pkg_Nm  :='Ias_Post_In_Sav_Pkg.Post_Doc_In_Sav';
             Goto Rtn_Rslt;           
      End;
   --##----------------------------------------------------------------------------------------##--
      Ars_Api_Trns_Pkg.SYNC_E_INVC_PRC( P_DOC_TYPE      =>G_DOC_TYP,
                                        P_BILL_TYPE      =>V_BILL_DOC_TYPE,
                                        P_BRN_NO         =>G_BRN_NO,
                                        P_Use_Vat        =>G_Use_Vat,
                                        P_SYS_NO         =>G_SYS_NO,
                                        P_DOC_SER        =>G_DOC_SER,
                                        P_C_CODE         =>G_C_CODE,                           
                                        P_TAX_BILL_TYP   =>G_TAX_BILL_TYP,    
                                        P_OFFLINE_VLDT   =>1,
                                        P_DO_COMMIT      =>0, 
                                        P_Tbl_Mst_Nm     =>V_Tbl_Mst_Nm,
                                        P_Fld_Doc_Ser    =>V_Fld_Doc_Ser,                                        
                                        P_DTS_ONLINE     =>G_DTS_ONLINE,
                                        P_COMMIT_FLG     =>G_COMMIT_FLG, 
                                        P_Pst_Typ        =>G_Pst_Typ,
                                        P_WEB_SRVC_UUID  =>G_DOC_UUID,                             
                                        P_WRNNG_TXT      =>G_WRNNG_TXT,
                                        P_Msg_Txt        =>P_Msg_Txt,
                                        P_ERR_NO         =>P_ERR_NO,
                                        P_Pkg_NM         =>P_Pkg_NM);
          If  P_MSG_TXT Is Not Null Then             
              Goto Rtn_Rslt; 
          End If;                        
   --##----------------------------------------------------------------------------------------##--
   End If;  
  --##----------------------------------------------------------------------------------------##--
    If G_Sys_No=70 and G_C_Code Is Not Null Then
       Begin
         execute immediate '  Begin  DTS_GEN_PKG.EXECUTE_PLN(P_DOC_TYPE  =>'||G_Doc_Typ||'
                                                     ,P_DOC_SER   =>'||G_Doc_Ser||'
                                                     ,P_C_CODE    =>'''||G_C_Code||'''
                                                     ,P_REP_CODE  =>'''||G_rep_code||'''
                                                     ,P_DOC_DATE  =>'''||G_DOC_DATE||''' );
                                                     End ; ';
       Exception
         When Others Then
            Null;
       End;     
       
    End If;
  --##----------------------------------------------------------------------------------------##--
 
  --####################--

  <<RTN_RSLT>>
   If P_Msg_Txt Is Not Null OR P_Err_No Is Not Null Then
      Rollback;
      P_Msg_Txt :=  NVL(P_Msg_Txt,'Message Number Is Missing');
      P_ERR_NO := P_Err_No;
      P_Pkg_NM   :=NVL(P_Pkg_Nm,'Ars_Api_Trns_Pkg.Chk_Insrt_Data');
      Return;
   ELSE
       P_Msg_Txt := NULL;
       P_Err_No :=NULL;
       P_Pkg_NM   :=NULL;         
   End If;
--####################--
EXCEPTION WHEN OTHERS THEN 
     ROLLBACK;
     P_Msg_Txt := 'Error in Chk_Insrt_Data '||sqlerrm;
     P_ERR_NO  := 20387;
     P_Pkg_NM  :='Ars_Api_Trns_Pkg.Chk_Insrt_Data';    
End Chk_Insrt_Data;
--##-----------------------------------------------------------------------------------------------------##--
Function  Snd_Vrfct_Msg( P_Bill_Doc_Type  Ias_Bill_Mst.Bill_Doc_Type%Type         Default Null,
                                            P_C_Code         Ias_Bill_Mst.C_Code%Type                Default Null,
                                            P_C_Tel          Ias_Bill_Mst.C_Tel%Type                 Default Null, 
                                            P_Vrctn_Code     Number                                   Default Null ,
                                            P_Op_Type        Number  ,  --- 1 Send Verification  Code  2 Verification Code
                                            P_Lng_No         Number  Default    1 ,
                                            P_Cmp_No         Ias_Bill_Mst.Cmp_No%Type  Default Null  ,     
                                            P_Brn_No         Ias_Bill_Mst.Brn_No%Type  Default Null  ,
                                            P_Brn_Usr        Ias_Bill_Mst.Brn_Usr%Type  Default Null  ,
                                            P_Brn_Year       Ias_Bill_Mst.Brn_Year%Type  Default Null  ) Return Clob Is 
V_Msg_Txt                        Varchar2(500);
V_Snd_Vrfct_Msg_For_Crdt_Bill    Customer.Snd_Vrfct_Msg_For_Crdt_Bill%Type; 
V_C_Phone                        Customer.C_Phone%Type:=P_C_Tel; 
V_Json_Rslt                      Varchar2 (500):=  '{"_Result": { "_Errmsg": "@Errmsg","_Errno": @Errno } }';
Begin


  If  P_Op_Type  Is  Null Then
          V_Json_Rslt := Replace(V_Json_Rslt, '@Errno', '-1');
          V_Json_Rslt := Replace(V_Json_Rslt, '@Errmsg',Ias_Gen_Pkg.Get_Msg(Nvl(P_Lng_No,1),5289)||' P_Op_Type << >> 1 Send Verification  Code  2 Verification Code  ');
          Return V_Json_Rslt; 
  End If; 

  If  P_Op_Type  = 1  Then  
    
    If  P_C_Code  Is  Null Then
          V_Json_Rslt := Replace(V_Json_Rslt, '@Errno', '-1');
          V_Json_Rslt := Replace(V_Json_Rslt, '@Errmsg',Ias_Gen_Pkg.Get_Msg(Nvl(P_Lng_No,1),411)||' P_C_Code Is Null');
          Return V_Json_Rslt; 
    End If; 
    
    Begin
        Select Nvl(Snd_Vrfct_Msg_For_Crdt_Bill,0)
          Into V_Snd_Vrfct_Msg_For_Crdt_Bill
          From Customer
         Where C_Code = P_C_Code And Rownum <= 1;
    Exception
        When Others Then 
        V_Snd_Vrfct_Msg_For_Crdt_Bill :=0;  
     End; 
    
     If  P_Bill_Doc_Type  Is  Null Then
          V_Json_Rslt := Replace(V_Json_Rslt, '@Errno', '-1');
          V_Json_Rslt := Replace(V_Json_Rslt, '@Errmsg',Ias_Gen_Pkg.Get_Msg(Nvl(P_Lng_No,1),886)||' P_Bill_Doc_Type Is Null');
          Return V_Json_Rslt; 
     End If; 
 
     If  V_Snd_Vrfct_Msg_For_Crdt_Bill =0  Or (V_Snd_Vrfct_Msg_For_Crdt_Bill=1  And  P_Bill_Doc_Type  <> 4) Then 
      Return Null ;
     End If ;    

   If  V_C_Phone  Is Null Then 
    Begin
        Select  C_Phone
          Into  V_C_Phone
          From Customer
         Where C_Code = P_C_Code And Rownum <= 1;
    Exception
        When Others   Then 
          V_Json_Rslt := Replace(V_Json_Rslt, '@Errno', '-1');
          V_Json_Rslt := Replace(V_Json_Rslt, '@Errmsg',Ias_Gen_Pkg.Get_Msg(Nvl(P_Lng_No,1),2229)||' P_C_Phone Is Null');
          Return V_Json_Rslt;  
    End; 
   End If;
   
   If  P_Cmp_No  Is  Null Then
          V_Json_Rslt := Replace(V_Json_Rslt, '@Errno', '-1');
          V_Json_Rslt := Replace(V_Json_Rslt, '@Errmsg',' P_Cmp_No Is Null');
          Return V_Json_Rslt; 
    End If; 
    
    
    If  P_Brn_No  Is  Null Then
          V_Json_Rslt := Replace(V_Json_Rslt, '@Errno', '-1');
          V_Json_Rslt := Replace(V_Json_Rslt, '@Errmsg','P_Brn_No Is Null');
          Return V_Json_Rslt; 
    End If; 
     
    If  P_Brn_Usr  Is  Null Then
          V_Json_Rslt := Replace(V_Json_Rslt, '@Errno', '-1');
          V_Json_Rslt := Replace(V_Json_Rslt, '@Errmsg',' P_Brn_Usr Is Null');
          Return V_Json_Rslt; 
    End If; 
   
    If  P_Brn_Year  Is  Null Then
          V_Json_Rslt := Replace(V_Json_Rslt, '@Errno', '-1');
          V_Json_Rslt := Replace(V_Json_Rslt, '@Errmsg','P_Brn_Year Is Null');
          Return V_Json_Rslt; 
    End If; 
       
    
   
    If  V_Snd_Vrfct_Msg_For_Crdt_Bill =2  Or (V_Snd_Vrfct_Msg_For_Crdt_Bill=1  And  P_Bill_Doc_Type  = 4) Then 
        G_Vrctn_Code:= Trunc(Dbms_Random.Value(123456,5));
        V_Msg_Txt :=Ias_Gen_Pkg.Get_Msg(Nvl(P_Lng_No,1),7012)||' '||G_Vrctn_Code;
            Begin
                   Ias_Sms_Mail_Pkg.Insrt_Msg_Alrt_With_Save_Prc (    P_Lng_No           => Nvl(P_Lng_No,1) ,
                                                                      P_Msg_Mthd_Send    => 1                  ,
                                                                      P_Msg_Typ          => 45                 ,
                                                                      P_Msg_Txt          => V_Msg_Txt          ,
                                                                      P_Mobile_No        => V_C_Phone          ,
                                                                      P_E_Mail           => Null               ,
                                                                      P_Subjct_Mail      => Null               ,
                                                                      P_Attch_Email_File => Null               ,
                                                                      P_Doc_Typ          => Null               ,
                                                                      P_Doc_Srl          => Null               ,
                                                                      P_Ad_Date          =>  Sysdate           ,
                                                                      P_Cmp_No           =>P_Cmp_No            ,
                                                                      P_Brn_No           =>P_Brn_No            ,
                                                                      P_Brn_Usr          =>P_Brn_Usr           ,
                                                                      P_Brn_Year         =>P_Brn_Year          );
           Exception When Others Then    
                V_Json_Rslt := Replace(V_Json_Rslt, '@Errno', '-1');
                V_Json_Rslt := Replace(V_Json_Rslt, '@Errmsg',Sqlerrm);
           End;
        V_Json_Rslt := Replace(V_Json_Rslt, '@Errno', '0');
        V_Json_Rslt := Replace(V_Json_Rslt, '@Errmsg',V_Msg_Txt);
      
     Return V_Json_Rslt; 
  End If ;
   
  Elsif P_Op_Type =2  Then 
   
   If   P_Vrctn_Code Is Null Then 
     V_Json_Rslt := Replace(V_Json_Rslt, '@Errno', '-1');
     V_Json_Rslt := Replace(V_Json_Rslt, '@Errmsg',Ias_Gen_Pkg.Get_Msg(Nvl(P_Lng_No,1),5513)||' P_Vrctn_Code Is Null    ');
     Return V_Json_Rslt; 
   End If; 
   
   If   Nvl(P_Vrctn_Code,0) <>   Nvl(G_Vrctn_Code,0) Then
     V_Json_Rslt := Replace(V_Json_Rslt, '@Errno', '-1');
     V_Json_Rslt := Replace(V_Json_Rslt, '@Errmsg',Ias_Gen_Pkg.Get_Msg(Nvl(P_Lng_No,1),5505) );
     Return V_Json_Rslt; 
    Else 
     V_Json_Rslt := Replace(V_Json_Rslt, '@Errno', '1');
     V_Json_Rslt := Replace(V_Json_Rslt, '@Errmsg',Null );
     G_Vrctn_Code:=Null;
     Return V_Json_Rslt; 
   End If; 
  
  End If;  
   
  --##----------------------------------------------------------------------------##-- 
 Exception When  Others Then 
      Raise_Application_Error (-20752, 'Err Snd_Vrfct_Msg ' || Chr (10) || Sqlerrm);  
End Snd_Vrfct_Msg;  
